            }
        }
    }

    private bool TryNormalizePipeVariantAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        IReadOnlyCollection<Vector2Int> protectedAnchorCoordinates)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetLoadedBlock(coordinate, out Block block)
            || block == null
            || !(block.MapObject is Pipe installedPipe)
            || installedPipe == null
            || !installedPipe.gameObject.activeInHierarchy
            || !installedPipe.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int currentQuarterTurns))
        {
            return false;
        }

        if (anchorCoordinate != coordinate || IsProtectedAnchorCoordinate(anchorCoordinate, protectedAnchorCoordinates))
        {
            return false;
        }

        Pipe pipePrototype = installedPipe.StraightVariantPrefab != null
            ? installedPipe.StraightVariantPrefab
            : installedPipe;
        if (!TryResolvePipePlacementVariant(
                pipePrototype,
                anchorCoordinate,
                currentQuarterTurns,
                previewToIgnore,
                out MapObject desiredPrefab,
                out int desiredQuarterTurns)
            || !(desiredPrefab is Pipe desiredPipePrefab))
        {
            return false;
        }

        Quaternion desiredRotation = GetInstalledObjectRotation(desiredPipePrefab, desiredQuarterTurns);
        bool sameVariant = installedPipe.VariantKind == desiredPipePrefab.VariantKind;
        bool sameQuarterTurns = NormalizePlacementQuarterTurns(currentQuarterTurns) == NormalizePlacementQuarterTurns(desiredQuarterTurns);
        bool sameRotation = Mathf.Abs(Quaternion.Dot(installedPipe.transform.rotation, desiredRotation)) >= 0.9999f;
        if (sameVariant && sameQuarterTurns && sameRotation)
        {
            return false;
        }

        Vector3 desiredPosition = GetInstalledObjectWorldPosition(anchorCoordinate, desiredPipePrefab, desiredQuarterTurns);
        RemoveInstalledPipeVariantPreview(installedPipe);
        if (sameVariant)
        {
            installedPipe.transform.SetPositionAndRotation(desiredPosition, desiredRotation);
            block.SetMapObject(installedPipe);
            ConfigureInstalledObjectRuntime(installedPipe, anchorCoordinate, desiredQuarterTurns);
            RegisterInstalledObjectPersistence(installedPipe);
            return true;
        }

        MapObject replacementObject = CreateInstalledObjectInstance(desiredPipePrefab, terrain.transform, terrain);
        if (!(replacementObject is Pipe replacementPipe))
        {
            if (replacementObject is InstallationObject replacementInstallation)
            {
                ReleaseInstalledObjectInstance(replacementInstallation, desiredPipePrefab, terrain);
            }

            return false;
        }

        replacementPipe.transform.SetPositionAndRotation(desiredPosition, desiredRotation);
        replacementPipe.ApplyItemFilterMask(
            installedPipe.CaptureItemFilterMaskWords(),
            installedPipe.IsItemFilterMaskInitialized);
        block.SetMapObject(replacementPipe);
        ConfigureInstalledObjectRuntime(replacementPipe, anchorCoordinate, desiredQuarterTurns);
        RegisterInstalledObjectPersistence(replacementPipe);

        TryGetInstallationDefinition(installedPipe.ResolveItemId(), out ItemDefinition installedDefinition);
        ReleaseInstalledObjectInstance(
            installedPipe,
            ResolveInstallationSourcePrefab(
                installedDefinition,
                GetPipeVariantKind(installedPipe)),
            terrain);

        return true;
    }

    private bool TryGetEditableInstallationFromRaycast(
        Ray ray,
        float maxDistance,
        out InstallationObject installationObject,
        out Vector2Int anchorCoordinate)
    {
        installationObject = null;
        anchorCoordinate = Vector2Int.zero;

        int hitCount = Physics.RaycastNonAlloc(
            ray,
            pointerRaycastHits,
            Mathf.Max(0f, maxDistance),
            Physics.DefaultRaycastLayers,
            QueryTriggerInteraction.Ignore);
        if (hitCount <= 0)
        {
            return false;
        }

        InstallationObject bestInstallationObject = null;
        Vector2Int bestAnchorCoordinate = Vector2Int.zero;
        float bestDistance = float.PositiveInfinity;
        for (int i = 0; i < hitCount; i++)
        {
            RaycastHit hit = pointerRaycastHits[i];
            Collider hitCollider = hit.collider;
            if (hitCollider == null)
            {
                continue;
            }

            InstallationObject candidate = hitCollider.GetComponentInParent<InstallationObject>();
            if (candidate == null
                || !candidate.gameObject.activeInHierarchy
                || !candidate.TryGetPlacementRuntime(out Vector2Int candidateAnchorCoordinate, out _))
            {
                continue;
            }

            if (hit.distance >= bestDistance)
            {
                continue;
            }

            bestInstallationObject = candidate;
            bestAnchorCoordinate = candidateAnchorCoordinate;
            bestDistance = hit.distance;
        }

        if (bestInstallationObject == null)
        {
            return false;
        }

        installationObject = bestInstallationObject;
        anchorCoordinate = bestAnchorCoordinate;
        return true;
    }

    private bool TryGetConveyorPlacementOutputDirection(ConveyorBelt conveyorPrototype, int quarterTurns, out Vector2Int outputDirection)
    {
        outputDirection = Vector2Int.zero;
        if (conveyorPrototype == null)
        {
            return false;
        }

        return conveyorPrototype.TryGetOutputDirection(
            GetPlacementObjectRotation(conveyorPrototype, quarterTurns),
            out outputDirection);
    }

    private bool TryGetConveyorPlacementInputDirection(ConveyorBelt conveyorPrototype, int quarterTurns, out Vector2Int inputDirection)
    {
        inputDirection = Vector2Int.zero;
        if (conveyorPrototype == null)
        {
            return false;
        }

        return conveyorPrototype.TryGetInputDirection(
            GetPlacementObjectRotation(conveyorPrototype, quarterTurns),
            out inputDirection);
    }

    private bool TryGetConveyorPlacementQuarterTurnsForOutput(MapObject sourcePrefab, Vector2Int desiredOutputDirection, out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = 0;
        if (!(sourcePrefab is ConveyorBelt conveyorSource) || desiredOutputDirection == Vector2Int.zero)
        {
            return false;
        }

        for (int candidateQuarterTurns = 0; candidateQuarterTurns < 4; candidateQuarterTurns++)
        {
            if (!conveyorSource.TryGetOutputDirection(
                    GetPlacementObjectRotation(conveyorSource, candidateQuarterTurns),
                    out Vector2Int candidateOutputDirection))
            {
                continue;
            }

            if (candidateOutputDirection != desiredOutputDirection)
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool TryGetConveyorPlacementQuarterTurnsForInput(MapObject sourcePrefab, Vector2Int desiredInputDirection, out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = 0;
        if (!(sourcePrefab is ConveyorBelt conveyorSource) || desiredInputDirection == Vector2Int.zero)
        {
            return false;
        }

        for (int candidateQuarterTurns = 0; candidateQuarterTurns < 4; candidateQuarterTurns++)
        {
            if (!conveyorSource.TryGetInputDirection(
                    GetPlacementObjectRotation(conveyorSource, candidateQuarterTurns),
                    out Vector2Int candidateInputDirection))
            {
                continue;
            }

            if (candidateInputDirection != desiredInputDirection)
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool TryResolveConveyorEndpointAlignedQuarterTurns(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is ConveyorBelt conveyorPrototype))
        {
            return false;
        }

        ConveyorPreviewVariantMode previewVariantMode = previewToIgnore == activeInstallPreview
            ? installPreviewConveyorVariantMode
            : GetConveyorPreviewVariantMode(previewToIgnore);
        List<MapObject> candidateSources = new List<MapObject>(3);
        if (previewVariantMode == ConveyorPreviewVariantMode.Straight)
        {
            AddUniqueConveyorCandidateSource(candidateSources, conveyorPrototype.StraightVariantPrefab);
        }
        else
        {
            AddUniqueConveyorCandidateSource(candidateSources, conveyorPrototype.CornerVariantPrefab);
            AddUniqueConveyorCandidateSource(candidateSources, conveyorPrototype.ReverseCornerVariantPrefab);
            AddUniqueConveyorCandidateSource(candidateSources, conveyorPrototype.StraightVariantPrefab);
        }

        bool found = false;
        int bestScore = 0;
        int bestOffset = int.MaxValue;
        for (int i = 0; i < candidateSources.Count; i++)
        {
            if (!TryResolveConveyorEndpointAlignedQuarterTurnsForSource(
                    candidateSources[i],
                    anchorCoordinate,
                    previewToIgnore,
                    preferredQuarterTurns,
                    out int candidateQuarterTurns,
                    out int candidateScore))
            {
                continue;
            }

            int candidateOffset = GetQuarterTurnSearchOffset(preferredQuarterTurns, candidateQuarterTurns);
            if (found
                && (candidateScore < bestScore
                    || (candidateScore == bestScore && candidateOffset >= bestOffset)))
            {
                continue;
            }

            found = true;
            bestScore = candidateScore;
            bestOffset = candidateOffset;
            resolvedQuarterTurns = candidateQuarterTurns;
        }

        return found;
    }

    private bool TryResolveConveyorEndpointAlignedQuarterTurnsForSource(
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns,
        out int resolvedScore)
    {
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        resolvedScore = 0;
        if (!(sourcePrefab is ConveyorBelt conveyorSource))
        {
            return false;
        }

        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = (normalizedPreferredQuarterTurns + offset) % 4;
            Quaternion candidateRotation = GetPlacementObjectRotation(conveyorSource, candidateQuarterTurns);
            if (!conveyorSource.TryGetInputDirection(candidateRotation, out Vector2Int inputDirection)
                || !conveyorSource.TryGetOutputDirection(candidateRotation, out Vector2Int outputDirection))
            {
                continue;
            }

            int candidateScore = GetConveyorEndpointConnectionCandidateScore(
                anchorCoordinate,
                inputDirection,
                outputDirection,
                previewToIgnore);
            if (candidateScore <= 0)
            {
                continue;
            }

            if (resolvedScore > 0 && candidateScore <= resolvedScore)
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            resolvedScore = candidateScore;
            if (candidateScore >= 2)
            {
                return true;
            }
        }

        return resolvedScore > 0;
    }

    private int GetConveyorEndpointConnectionScore(
        Vector2Int anchorCoordinate,
        Vector2Int inputDirection,
        Vector2Int outputDirection,
        MapObject previewToIgnore)
    {
        int score = 0;
        if (inputDirection != Vector2Int.zero
            && TryGetConveyorPlacementDirectionsAtCoordinate(
                anchorCoordinate + inputDirection,
                previewToIgnore,
                out ConveyorBelt inputNeighborConveyor,
                out _,
                out Vector2Int neighborOutputDirection)
            && (neighborOutputDirection == -inputDirection
                || IsStraightConveyorSideSeamConnection(
                    inputNeighborConveyor,
                    inputDirection,
                    neighborOutputDirection)))
        {
            score++;
        }

        if (outputDirection != Vector2Int.zero
            && TryGetConveyorPlacementDirectionsAtCoordinate(
                anchorCoordinate + outputDirection,
                previewToIgnore,
                out ConveyorBelt outputNeighborConveyor,
                out Vector2Int neighborInputDirection,
                out Vector2Int outputNeighborOutputDirection)
            && (neighborInputDirection == -outputDirection
                || IsStraightConveyorSideSeamConnection(
                    outputNeighborConveyor,
                    outputDirection,
                    outputNeighborOutputDirection)))
        {
            score++;
        }

        return score;
    }

    private int GetConveyorEndpointConnectionCandidateScore(
        Vector2Int anchorCoordinate,
        Vector2Int inputDirection,
        Vector2Int outputDirection,
        MapObject previewToIgnore)
    {
        Vector2Int neighborOutputDirection = Vector2Int.zero;
        ConveyorBelt inputNeighborConveyor = null;
        bool inputHasConveyor = inputDirection != Vector2Int.zero
                                && TryGetConveyorPlacementDirectionsAtCoordinate(
                                    anchorCoordinate + inputDirection,
                                    previewToIgnore,
                                    out inputNeighborConveyor,
                                    out _,
                                    out neighborOutputDirection);
        bool inputConnected = inputHasConveyor && neighborOutputDirection == -inputDirection;
        bool inputSeamConnected = inputHasConveyor
                                  && !inputConnected
                                  && IsStraightConveyorSideSeamConnection(
                                      inputNeighborConveyor,
                                      inputDirection,
                                      neighborOutputDirection);

        Vector2Int neighborInputDirection = Vector2Int.zero;
        Vector2Int outputNeighborOutputDirection = Vector2Int.zero;
        ConveyorBelt outputNeighborConveyor = null;
        bool outputHasConveyor = outputDirection != Vector2Int.zero
                                 && TryGetConveyorPlacementDirectionsAtCoordinate(
                                     anchorCoordinate + outputDirection,
                                     previewToIgnore,
                                     out outputNeighborConveyor,
                                     out neighborInputDirection,
                                     out outputNeighborOutputDirection);
        bool outputConnected = outputHasConveyor && neighborInputDirection == -outputDirection;
        bool outputSeamConnected = outputHasConveyor
                                   && !outputConnected
                                   && IsStraightConveyorSideSeamConnection(
                                       outputNeighborConveyor,
                                       outputDirection,
                                       outputNeighborOutputDirection);

        return GetConveyorEndpointConnectionCandidateScore(
            inputConnected,
            outputConnected,
            inputHasConveyor,
            outputHasConveyor,
            inputSeamConnected,
            outputSeamConnected);
    }

    private static int GetConveyorEndpointConnectionCandidateScore(
        bool inputConnected,
        bool outputConnected,
        bool inputHasConveyor,
        bool outputHasConveyor,
        bool inputSeamConnected = false,
        bool outputSeamConnected = false)
    {
        int score = 0;
        score += inputConnected ? 4 : inputSeamConnected ? 3 : inputHasConveyor ? 0 : 0;
        score += outputConnected ? 2 : outputSeamConnected ? 1 : outputHasConveyor ? 0 : 0;
        return score;
    }

    private static bool IsStraightConveyorSideSeamConnection(
        ConveyorBelt conveyorBelt,
        Vector2Int endpointDirection,
        Vector2Int neighborFlowDirection)
    {
        return conveyorBelt != null
               && !conveyorBelt.IsCornerVariant
               && ConveyorBelt.IsPerpendicular(endpointDirection, neighborFlowDirection);
    }

    private static void AddUniqueConveyorCandidateSource(List<MapObject> candidateSources, MapObject candidateSource)
    {
        if (candidateSources == null || candidateSource == null)
        {
            return;
        }

        for (int i = 0; i < candidateSources.Count; i++)
        {
            if (candidateSources[i] == candidateSource)
            {
                return;
            }
        }

        candidateSources.Add(candidateSource);
    }

    private static int GetQuarterTurnSearchOffset(int preferredQuarterTurns, int candidateQuarterTurns)
    {
        int normalizedPreferredQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        int normalizedCandidateQuarterTurns = NormalizePlacementQuarterTurns(candidateQuarterTurns);
        return (normalizedCandidateQuarterTurns - normalizedPreferredQuarterTurns + 4) % 4;
    }

    private bool TryGetConveyorPlacementDirectionsAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out ConveyorBelt conveyorBelt,
        out Vector2Int inputDirection,
        out Vector2Int outputDirection)
    {
        return TryGetConveyorPlacementDirectionsAndSequenceAtCoordinate(
            coordinate,
            previewToIgnore,
            out conveyorBelt,
            out inputDirection,
            out outputDirection,
            out _);
    }

    private bool TryGetConveyorPlacementDirectionsAndSequenceAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out ConveyorBelt conveyorBelt,
        out Vector2Int inputDirection,
        out Vector2Int outputDirection,
        out long placementSequence)
    {
        conveyorBelt = null;
        inputDirection = Vector2Int.zero;
        outputDirection = Vector2Int.zero;
        placementSequence = 0;

        if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
            && preview != null
            && preview != previewToIgnore
            && preview is ConveyorBelt previewConveyor)
        {
            conveyorBelt = previewConveyor;
            placementSequence = installPreviewPlacementSequencesByPreview.TryGetValue(preview, out long previewSequence)
                ? previewSequence
                : 0;
            return previewConveyor.TryGetInputDirection(previewConveyor.transform.rotation, out inputDirection)
                && previewConveyor.TryGetOutputDirection(previewConveyor.transform.rotation, out outputDirection);
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        if (terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject is ConveyorBelt liveConveyor
            && liveConveyor != null
            && liveConveyor.gameObject.activeInHierarchy)
        {
            conveyorBelt = liveConveyor;
            placementSequence = liveConveyor.RuntimePlacementSequence;
            return liveConveyor.TryGetInputDirection(liveConveyor.transform.rotation, out inputDirection)
                && liveConveyor.TryGetOutputDirection(liveConveyor.transform.rotation, out outputDirection);
        }

        if (!terrain.TryGetInstallationStateAtCoordinate(coordinate, out BlockStateStore.InstallationSaveState savedState)
            || savedState == null
            || !TryGetInstallationDefinition(savedState, out ItemDefinition savedDefinition)
            || !(savedDefinition.mapObject is ConveyorBelt))
        {
            return false;
        }

        MapObject savedSourcePrefab = null;
        if (!IsBelt2F(savedDefinition.mapObject)
            && savedDefinition.mapObject is ConveyorBelt savedPrototype
            && savedState.conveyorVariantKind >= 0)
        {
            savedSourcePrefab = ResolveConveyorVariantPrefab(savedPrototype, savedState.conveyorVariantKind);
        }

        if (savedSourcePrefab == null)
        {
            savedSourcePrefab = ResolveInstalledObjectSourcePrefab(
                savedDefinition,
                savedState.anchorCoordinate,
                savedState.quarterTurns,
                null,
                ConveyorPreviewVariantMode.Corner);
        }
        if (!(savedSourcePrefab is ConveyorBelt savedConveyor))
        {
            return false;
        }

        conveyorBelt = savedConveyor;
        placementSequence = savedState.placementSequence;
        Quaternion savedRotation = GetPlacementObjectRotation(savedConveyor, savedState.quarterTurns);
        return savedConveyor.TryGetInputDirection(savedRotation, out inputDirection)
            && savedConveyor.TryGetOutputDirection(savedRotation, out outputDirection);
    }

    private void RefreshFencePreviewVariants(
        IReadOnlyList<Vector2Int> changedCoordinates = null,
        MapObject previewToIgnore = null,
        bool preserveActivePreviewQuarterTurns = false)
    {
        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is Wall))
        {
            return;
        }

        CleanupInstallPreviewReferences();
        if (installPreviewInstances.Count <= 0)
        {
            return;
        }

        HashSet<Vector2Int> affectedPreviewCoordinates = BuildFenceVariantRefreshCoordinates(changedCoordinates, true);
        int maxPassCount = Mathf.Max(1, installPreviewInstances.Count);
        for (int pass = 0; pass < maxPassCount; pass++)
        {
            bool anyChanged = false;
            List<MapObject> previews = new List<MapObject>(installPreviewInstances);
            for (int i = 0; i < previews.Count; i++)
            {
                MapObject preview = previews[i];
                if (!(preview is Wall)
                    || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
                {
                    continue;
                }

                if (affectedPreviewCoordinates != null && !affectedPreviewCoordinates.Contains(anchorCoordinate))
                {
                    continue;
                }

                if (RefreshSingleFencePreviewVariant(
                        preview,
                        anchorCoordinate,
                        previewToIgnore,
                        preserveActivePreviewQuarterTurns && preview == activeInstallPreview))
                {
                    anyChanged = true;
                }
            }

            if (!anyChanged)
            {
                break;
            }
        }
    }

    private static HashSet<Vector2Int> BuildFenceVariantRefreshCoordinates(
        IReadOnlyList<Vector2Int> changedCoordinates,
        bool includeSelf)
    {
        if (changedCoordinates == null || changedCoordinates.Count <= 0)
        {
            return null;
        }

        HashSet<Vector2Int> coordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < changedCoordinates.Count; i++)
        {
            Vector2Int coordinate = changedCoordinates[i];
            if (includeSelf)
            {
                coordinates.Add(coordinate);
            }

            coordinates.Add(coordinate + Vector2Int.up);
            coordinates.Add(coordinate + Vector2Int.right);
            coordinates.Add(coordinate + Vector2Int.down);
            coordinates.Add(coordinate + Vector2Int.left);
        }

        return coordinates.Count > 0 ? coordinates : null;
    }

    private void RefreshPipePreviewVariants(
        IReadOnlyList<Vector2Int> changedCoordinates = null,
        MapObject previewToIgnore = null)
    {
        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is Pipe))
        {
            return;
        }

        CleanupInstallPreviewReferences();
        if (installPreviewInstances.Count <= 0)
        {
            return;
        }

        HashSet<Vector2Int> affectedPreviewCoordinates = BuildPipeVariantRefreshCoordinates(changedCoordinates, true, previewToIgnore);
        int maxPassCount = Mathf.Max(1, installPreviewInstances.Count);
        for (int pass = 0; pass < maxPassCount; pass++)
        {
            bool anyChanged = false;
            List<MapObject> previews = new List<MapObject>(installPreviewInstances);
            for (int i = 0; i < previews.Count; i++)
            {
                MapObject preview = previews[i];
                if (!(preview is Pipe)
                    || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
                {
                    continue;
                }

                if (affectedPreviewCoordinates != null && !affectedPreviewCoordinates.Contains(anchorCoordinate))
                {
                    continue;
                }

                if (RefreshSinglePipePreviewVariant(preview, anchorCoordinate, previewToIgnore))
                {
                    anyChanged = true;
                }
            }

            if (!anyChanged)
            {
                break;
            }
        }
    }

    private static bool ContainsCoordinate(IReadOnlyCollection<Vector2Int> coordinates, Vector2Int coordinate)
    {
        if (coordinates == null)
        {
            return false;
        }

        foreach (Vector2Int candidate in coordinates)
        {
            if (candidate == coordinate)
            {
                return true;
            }
        }

        return false;
    }

    private void RefreshInstalledFenceVariantPreviews(
        IReadOnlyList<Vector2Int> changedCoordinates = null,
        MapObject previewToIgnore = null)
    {
        CleanupInstalledFenceVariantPreviewReferences();
        if (IsEditingInstallation()
            || activeInstallDefinition == null
            || !(activeInstallDefinition.mapObject is Wall fencePrototype)
            || installPreviewInstances.Count <= 0)
        {
            RemoveInstalledFenceVariantPreviews(null);
            return;
        }

        HashSet<Vector2Int> affectedCoordinates = BuildFenceVariantRefreshCoordinates(changedCoordinates, true)
                                                 ?? BuildInstalledFenceVariantPreviewRefreshCoordinates();
        if (affectedCoordinates == null || affectedCoordinates.Count <= 0)
        {
            RemoveInstalledFenceVariantPreviews(null);
            return;
        }

        Dictionary<Wall, InstalledFenceVariantPreviewPlan> desiredPreviewsByFence =
            new Dictionary<Wall, InstalledFenceVariantPreviewPlan>();
        foreach (Vector2Int coordinate in affectedCoordinates)
        {
            if (TryResolveInstalledFenceVariantPreview(
                    coordinate,
                    fencePrototype,
                    previewToIgnore,
                    out InstalledFenceVariantPreviewPlan plan)
                && plan != null
                && plan.installedFence != null)
            {
                desiredPreviewsByFence[plan.installedFence] = plan;
            }
        }

        List<Wall> existingPreviewOwners = new List<Wall>(installedFenceVariantPreviews.Keys);
        for (int i = 0; i < existingPreviewOwners.Count; i++)
        {
            Wall installedFence = existingPreviewOwners[i];
            if (installedFence == null)
            {
                RemoveInstalledFenceVariantPreview(installedFence);
                continue;
            }

            if (!installedFence.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _)
                || !affectedCoordinates.Contains(anchorCoordinate))
            {
                continue;
            }

            if (!desiredPreviewsByFence.TryGetValue(installedFence, out InstalledFenceVariantPreviewPlan plan))
            {
                RemoveInstalledFenceVariantPreview(installedFence);
                continue;
            }

            UpdateInstalledFenceVariantPreview(plan);
            desiredPreviewsByFence.Remove(installedFence);
        }

        foreach (InstalledFenceVariantPreviewPlan plan in desiredPreviewsByFence.Values)
        {
            UpdateInstalledFenceVariantPreview(plan);
        }
    }

    private HashSet<Vector2Int> BuildInstalledFenceVariantPreviewRefreshCoordinates()
    {
        HashSet<Vector2Int> coordinates = new HashSet<Vector2Int>();
        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (!(preview is Wall)
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
            {
                continue;
            }

            AddFenceVariantRefreshCoordinates(coordinates, anchorCoordinate, true);
        }

        List<Wall> existingPreviewOwners = new List<Wall>(installedFenceVariantPreviews.Keys);
        for (int i = 0; i < existingPreviewOwners.Count; i++)
        {
            Wall installedFence = existingPreviewOwners[i];
            if (installedFence == null
                || !installedFence.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _))
            {
                continue;
            }

            coordinates.Add(anchorCoordinate);
        }

        return coordinates.Count > 0 ? coordinates : null;
    }

    private static void AddFenceVariantRefreshCoordinates(HashSet<Vector2Int> coordinates, Vector2Int coordinate, bool includeSelf)
    {
        if (coordinates == null)
        {
            return;
        }

        if (includeSelf)
        {
            coordinates.Add(coordinate);
        }

        coordinates.Add(coordinate + Vector2Int.up);
        coordinates.Add(coordinate + Vector2Int.right);
        coordinates.Add(coordinate + Vector2Int.down);
        coordinates.Add(coordinate + Vector2Int.left);
    }

    private void AddPipeConnectorVariantRefreshCoordinatesForWorldCoordinate(
        HashSet<Vector2Int> coordinates,
        Vector2Int coordinate,
        bool includeSelf,
        MapObject previewToIgnore = null)
    {
        AddFenceVariantRefreshCoordinates(coordinates, coordinate, includeSelf);
        if (coordinates == null)
        {
            return;
        }

        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out PlacementSnapshot previewSnapshot)
            && previewSnapshot?.mapObject != null
            && IsPipeConnectorObject(previewSnapshot.mapObject))
        {
            AddPipeConnectorVariantRefreshCoordinates(
                coordinates,
                previewSnapshot.anchorCoordinate,
                previewSnapshot.mapObject,
                previewSnapshot.quarterTurns,
                true);
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain != null
            && terrain.TryGetLoadedBlock(coordinate, out Block block)
            && block != null
            && block.MapObject != null
            && IsPipeConnectorObject(block.MapObject)
            && block.MapObject is InstallationObject installationObject
            && installationObject.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int quarterTurns))
        {
            AddPipeConnectorVariantRefreshCoordinates(
                coordinates,
                anchorCoordinate,
                block.MapObject,
                quarterTurns,
                true);
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot)
            && savedSnapshot?.mapObject != null
            && IsPipeConnectorObject(savedSnapshot.mapObject))
        {
            AddPipeConnectorVariantRefreshCoordinates(
                coordinates,
                savedSnapshot.anchorCoordinate,
                savedSnapshot.mapObject,
                savedSnapshot.quarterTurns,
                true);
        }
    }

    private void AddPipeConnectorVariantRefreshCoordinates(
        HashSet<Vector2Int> coordinates,
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        bool includeSelf)
    {
        AddFenceVariantRefreshCoordinates(coordinates, anchorCoordinate, includeSelf);
        if (coordinates == null || footprintSource == null)
        {
            return;
        }

        List<Vector2Int> footprintCoordinates = GetFootprintCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        for (int i = 0; i < footprintCoordinates.Count; i++)
        {
            AddFenceVariantRefreshCoordinates(coordinates, footprintCoordinates[i], true);
        }

        if (!TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null)
        {
            return;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int pipeAreaCoordinate))
            {
                continue;
            }

            AddFenceVariantRefreshCoordinates(coordinates, pipeAreaCoordinate, true);
        }
    }

    private bool TryResolveInstalledFenceVariantPreview(
        Vector2Int coordinate,
        Wall fencePrototype,
        MapObject previewToIgnore,
        out InstalledFenceVariantPreviewPlan plan)
    {
        plan = null;
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetLoadedBlock(coordinate, out Block block)
            || block == null
            || !(block.MapObject is Wall installedFence)
            || installedFence == null
            || !installedFence.gameObject.activeInHierarchy
            || !installedFence.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int currentQuarterTurns)
            || anchorCoordinate != coordinate)
        {
            return false;
        }

        Wall sourcePrototype = installedFence.StraightVariantPrefab != null
            ? installedFence.StraightVariantPrefab
            : fencePrototype != null && fencePrototype.StraightVariantPrefab != null
                ? fencePrototype.StraightVariantPrefab
                : fencePrototype != null
                    ? fencePrototype
                    : installedFence;
        if (!TryResolveFencePlacementVariant(
                sourcePrototype,
                anchorCoordinate,
                currentQuarterTurns,
                previewToIgnore,
                out MapObject desiredPrefab,
                out int desiredQuarterTurns)
            || !(desiredPrefab is Wall desiredFencePrefab))
        {
            return false;
        }

        Quaternion desiredRotation = GetInstalledObjectRotation(desiredFencePrefab, desiredQuarterTurns);
        Vector3 desiredFinalPosition = GetInstalledObjectWorldPosition(anchorCoordinate, desiredFencePrefab, desiredQuarterTurns);
        bool sameVariant = installedFence.VariantKind == desiredFencePrefab.VariantKind;
        bool sameRotation = Mathf.Abs(Quaternion.Dot(installedFence.transform.rotation, desiredRotation)) >= 0.9999f;
        bool samePosition = (installedFence.transform.position - desiredFinalPosition).sqrMagnitude <= 0.0001f;
        if (sameVariant && sameRotation && samePosition)
        {
            return false;
        }

        plan = new InstalledFenceVariantPreviewPlan
        {
            installedFence = installedFence,
            sourcePrefab = desiredFencePrefab,
            quarterTurns = NormalizePlacementQuarterTurns(desiredQuarterTurns),
            position = GetInstalledObjectWorldPosition(anchorCoordinate, desiredFencePrefab, desiredQuarterTurns),
            rotation = desiredRotation
        };
        return true;
    }

    private void UpdateInstalledFenceVariantPreview(InstalledFenceVariantPreviewPlan plan)
    {
        if (plan == null
            || plan.installedFence == null
            || plan.sourcePrefab == null)
        {
            return;
        }

        Wall installedFence = plan.installedFence;
        installedFenceVariantPreviews.TryGetValue(installedFence, out MapObject preview);
        installedFenceVariantPreviewSourcePrefabs.TryGetValue(installedFence, out MapObject currentSourcePrefab);
        bool requiresReplacement = preview == null
                                   || currentSourcePrefab != plan.sourcePrefab
                                   || RequiresFencePreviewReplacement(preview, plan.sourcePrefab);
        if (requiresReplacement)
        {
            DestroyInstallPreviewObject(preview);
            preview = Instantiate(plan.sourcePrefab);
            if (preview == null)
            {
                RemoveInstalledFenceVariantPreview(installedFence);
                return;
            }

            preview.name = $"{plan.sourcePrefab.name}_InstalledBlueprint";
            ConfigureInstallPreview(preview);
            installedFenceVariantPreviews[installedFence] = preview;
            installedFenceVariantPreviewSourcePrefabs[installedFence] = plan.sourcePrefab;
        }

        HideInstalledObjectForVariantPreview(installedFence, installedFencePreviewRendererStates);
        preview.transform.SetPositionAndRotation(plan.position, plan.rotation);
        if (preview is InstallationObject previewInstallation)
        {
            previewInstallation.RefreshInstalledDirectionFromCurrentTransform();
        }
    }

    private void RemoveInstalledFenceVariantPreviews(IReadOnlyCollection<Vector2Int> allowedCoordinates)
    {
        List<Wall> installedFences = new List<Wall>(installedFenceVariantPreviews.Keys);
        for (int i = 0; i < installedFences.Count; i++)
        {
            Wall installedFence = installedFences[i];
            if (installedFence != null
                && allowedCoordinates != null
                && installedFence.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _)
                && ContainsCoordinate(allowedCoordinates, anchorCoordinate))
            {
                continue;
            }

            RemoveInstalledFenceVariantPreview(installedFence);
        }
    }

    private void RemoveInstalledFenceVariantPreview(Wall installedFence)
    {
        if (ReferenceEquals(installedFence, null))
        {
            return;
        }

        installedFenceVariantPreviews.TryGetValue(installedFence, out MapObject preview);
        DestroyInstallPreviewObject(preview);
        installedFenceVariantPreviews.Remove(installedFence);
        installedFenceVariantPreviewSourcePrefabs.Remove(installedFence);
        RestoreInstalledObjectPreviewRenderers(installedFence, installedFencePreviewRendererStates);
    }

    private void CleanupInstalledFenceVariantPreviewReferences()
    {
        CopyWallKeys(installedFenceVariantPreviews, cleanupWallScratch);
        for (int i = 0; i < cleanupWallScratch.Count; i++)
        {
            Wall installedFence = cleanupWallScratch[i];
            installedFenceVariantPreviews.TryGetValue(installedFence, out MapObject preview);
            bool ownerMissing = installedFence == null;
            bool ownerInactive = !ownerMissing && !installedFence.gameObject.activeInHierarchy;
            if (ownerMissing || ownerInactive || preview == null)
            {
                RemoveInstalledFenceVariantPreview(installedFence);
            }
        }

        CopyWallKeys(installedFencePreviewRendererStates, cleanupWallScratch);
        for (int i = 0; i < cleanupWallScratch.Count; i++)
        {
            Wall installedFence = cleanupWallScratch[i];
            if (installedFence == null || !installedFenceVariantPreviews.ContainsKey(installedFence))
            {
                RestoreInstalledObjectPreviewRenderers(installedFence, installedFencePreviewRendererStates);
            }
        }

        cleanupWallScratch.Clear();
    }

    private void RefreshInstalledPipeVariantPreviews(
        IReadOnlyList<Vector2Int> changedCoordinates = null,
        MapObject previewToIgnore = null,
        IReadOnlyCollection<Vector2Int> protectedAnchorCoordinates = null)
    {
        CleanupInstalledPipeVariantPreviewReferences();
        if (IsEditingInstallation()
            || activeInstallDefinition == null
            || !IsPipeConnectorObject(activeInstallDefinition.mapObject)
            || installPreviewInstances.Count <= 0)
        {
            RemoveInstalledPipeVariantPreviews(null);
            return;
        }

        Pipe pipePrototype = activeInstallDefinition.mapObject as Pipe;

        HashSet<Vector2Int> affectedCoordinates = BuildPipeVariantRefreshCoordinates(changedCoordinates, true, previewToIgnore)
                                                 ?? BuildInstalledPipeVariantPreviewRefreshCoordinates();
        if (affectedCoordinates == null || affectedCoordinates.Count <= 0)
        {
            RemoveInstalledPipeVariantPreviews(null);
            return;
        }

        AddInstalledPipeVariantPreviewOwnerCoordinates(affectedCoordinates);

        Dictionary<Pipe, InstalledPipeVariantPreviewPlan> desiredPreviewsByPipe =
            new Dictionary<Pipe, InstalledPipeVariantPreviewPlan>();
        foreach (Vector2Int coordinate in affectedCoordinates)
        {
            if (TryResolveInstalledPipeVariantPreview(
                    coordinate,
                    pipePrototype,
                    previewToIgnore,
                    protectedAnchorCoordinates,
                    out InstalledPipeVariantPreviewPlan plan)
                && plan != null
                && plan.installedPipe != null)
            {
                desiredPreviewsByPipe[plan.installedPipe] = plan;
            }
        }

        List<Pipe> existingPreviewOwners = new List<Pipe>(installedPipeVariantPreviews.Keys);
        for (int i = 0; i < existingPreviewOwners.Count; i++)
        {
            Pipe installedPipe = existingPreviewOwners[i];
            if (installedPipe == null)
            {
                RemoveInstalledPipeVariantPreview(installedPipe);
                continue;
            }

            if (!installedPipe.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _)
                || !affectedCoordinates.Contains(anchorCoordinate))
            {
                continue;
            }

            if (!desiredPreviewsByPipe.TryGetValue(installedPipe, out InstalledPipeVariantPreviewPlan plan))
            {
                RemoveInstalledPipeVariantPreview(installedPipe);
                continue;
            }

            UpdateInstalledPipeVariantPreview(plan);
            desiredPreviewsByPipe.Remove(installedPipe);
        }

        foreach (InstalledPipeVariantPreviewPlan plan in desiredPreviewsByPipe.Values)
        {
            UpdateInstalledPipeVariantPreview(plan);
        }

        RestorePipeRenderersWithoutRenderableVariantPreview();
    }

    private HashSet<Vector2Int> BuildInstalledPipeVariantPreviewRefreshCoordinates()
    {
        HashSet<Vector2Int> coordinates = new HashSet<Vector2Int>();
        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (!IsPipeConnectorObject(preview)
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
            {
                continue;
            }

            MapObject footprintSource = ResolveInstallPreviewFootprintSource(preview) ?? preview;
            AddPipeConnectorVariantRefreshCoordinates(
                coordinates,
                anchorCoordinate,
                footprintSource,
                GetPreviewQuarterTurns(preview),
                true);
        }

        AddInstalledPipeVariantPreviewOwnerCoordinates(coordinates);

        return coordinates.Count > 0 ? coordinates : null;
    }

    private HashSet<Vector2Int> BuildPipeVariantRefreshCoordinates(
        IReadOnlyList<Vector2Int> changedCoordinates,
        bool includeSelf,
        MapObject previewToIgnore)
    {
        if (changedCoordinates == null || changedCoordinates.Count <= 0)
        {
            return null;
        }

        HashSet<Vector2Int> coordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < changedCoordinates.Count; i++)
        {
            AddPipeConnectorVariantRefreshCoordinatesForWorldCoordinate(
                coordinates,
                changedCoordinates[i],
                includeSelf,
                previewToIgnore);
        }

        return coordinates.Count > 0 ? coordinates : null;
    }

    private void AddInstalledPipeVariantPreviewOwnerCoordinates(HashSet<Vector2Int> coordinates)
    {
        if (coordinates == null)
        {
            return;
        }

        List<Pipe> existingPreviewOwners = new List<Pipe>(installedPipeVariantPreviews.Keys);
        for (int i = 0; i < existingPreviewOwners.Count; i++)
        {
            Pipe installedPipe = existingPreviewOwners[i];
            if (installedPipe == null
                || !installedPipe.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _))
            {
                continue;
            }

            coordinates.Add(anchorCoordinate);
        }
    }

    private bool TryResolveInstalledPipeVariantPreview(
        Vector2Int coordinate,
        Pipe pipePrototype,
        MapObject previewToIgnore,
        IReadOnlyCollection<Vector2Int> protectedAnchorCoordinates,
        out InstalledPipeVariantPreviewPlan plan)
    {
        plan = null;
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetLoadedBlock(coordinate, out Block block)
            || block == null
            || !(block.MapObject is Pipe installedPipe)
            || installedPipe == null
            || !installedPipe.gameObject.activeInHierarchy
            || !installedPipe.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int currentQuarterTurns)
            || anchorCoordinate != coordinate)
        {
            return false;
        }

        if (IsProtectedAnchorCoordinate(anchorCoordinate, protectedAnchorCoordinates))
        {
            return false;
        }

        Pipe sourcePrototype = installedPipe.StraightVariantPrefab != null
            ? installedPipe.StraightVariantPrefab
            : pipePrototype != null && pipePrototype.StraightVariantPrefab != null
                ? pipePrototype.StraightVariantPrefab
                : pipePrototype != null
                    ? pipePrototype
                    : installedPipe;
        if (!TryResolvePipePlacementVariant(
                sourcePrototype,
                anchorCoordinate,
                currentQuarterTurns,
                previewToIgnore,
                out MapObject desiredPrefab,
                out int desiredQuarterTurns)
            || !(desiredPrefab is Pipe desiredPipePrefab))
        {
            return false;
        }

        Quaternion desiredRotation = GetInstalledObjectRotation(desiredPipePrefab, desiredQuarterTurns);
        Vector3 desiredFinalPosition = GetInstalledObjectWorldPosition(anchorCoordinate, desiredPipePrefab, desiredQuarterTurns);
        bool sameVariant = installedPipe.VariantKind == desiredPipePrefab.VariantKind;
        bool sameRotation = Mathf.Abs(Quaternion.Dot(installedPipe.transform.rotation, desiredRotation)) >= 0.9999f;
        bool samePosition = (installedPipe.transform.position - desiredFinalPosition).sqrMagnitude <= 0.0001f;
        if (sameVariant && sameRotation && samePosition)
        {
            return false;
        }

        plan = new InstalledPipeVariantPreviewPlan
        {
            installedPipe = installedPipe,
            sourcePrefab = desiredPipePrefab,
            quarterTurns = NormalizePlacementQuarterTurns(desiredQuarterTurns),
            position = GetInstalledObjectWorldPosition(anchorCoordinate, desiredPipePrefab, desiredQuarterTurns),
            rotation = desiredRotation
        };
        return true;
    }

    private void UpdateInstalledPipeVariantPreview(InstalledPipeVariantPreviewPlan plan)
    {
        if (plan == null
            || plan.installedPipe == null
            || plan.sourcePrefab == null)
        {
            return;
        }

        Pipe installedPipe = plan.installedPipe;
        installedPipeVariantPreviews.TryGetValue(installedPipe, out MapObject preview);
        installedPipeVariantPreviewSourcePrefabs.TryGetValue(installedPipe, out MapObject currentSourcePrefab);
        bool requiresReplacement = preview == null
                                   || currentSourcePrefab != plan.sourcePrefab
                                   || RequiresPipePreviewReplacement(preview, plan.sourcePrefab);
        if (requiresReplacement)
        {
            MapObject previousPreview = preview;
            MapObject replacementPreview = Instantiate(plan.sourcePrefab);
            if (replacementPreview == null)
            {
                RemoveInstalledPipeVariantPreview(installedPipe);
                return;
            }

            replacementPreview.name = $"{plan.sourcePrefab.name}_InstalledBlueprint";
            ConfigureInstallPreview(replacementPreview);
            replacementPreview.transform.SetPositionAndRotation(plan.position, plan.rotation);
            if (replacementPreview is InstallationObject replacementInstallation)
            {
                replacementInstallation.RefreshInstalledDirectionFromCurrentTransform();
            }

            installedPipeVariantPreviews[installedPipe] = replacementPreview;
            installedPipeVariantPreviewSourcePrefabs[installedPipe] = plan.sourcePrefab;
            HideInstalledPipeForVariantPreview(installedPipe, replacementPreview);
            DestroyInstallPreviewObject(previousPreview);
            return;
        }

        preview.transform.SetPositionAndRotation(plan.position, plan.rotation);
        if (preview is InstallationObject previewInstallation)
        {
            previewInstallation.RefreshInstalledDirectionFromCurrentTransform();
        }

        HideInstalledPipeForVariantPreview(installedPipe, preview);
    }

    private void RemoveInstalledPipeVariantPreviews(IReadOnlyCollection<Vector2Int> allowedCoordinates)
    {
        List<Pipe> installedPipes = new List<Pipe>(installedPipeVariantPreviews.Keys);
        for (int i = 0; i < installedPipes.Count; i++)
        {
            Pipe installedPipe = installedPipes[i];
            if (installedPipe != null
                && allowedCoordinates != null
                && installedPipe.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _)
                && ContainsCoordinate(allowedCoordinates, anchorCoordinate))
            {
                continue;
            }

            RemoveInstalledPipeVariantPreview(installedPipe);
        }
    }

    private void RemoveInstalledPipeVariantPreview(Pipe installedPipe)
    {
        if (ReferenceEquals(installedPipe, null))
        {
            return;
        }

        installedPipeVariantPreviews.TryGetValue(installedPipe, out MapObject preview);
        installedPipeVariantPreviews.Remove(installedPipe);
        installedPipeVariantPreviewSourcePrefabs.Remove(installedPipe);
        RestoreInstalledObjectPreviewRenderers(installedPipe, installedPipePreviewRendererStates);
        DestroyInstallPreviewObject(preview);
    }

    private void CleanupInstalledPipeVariantPreviewReferences()
    {
        CopyPipeKeys(installedPipeVariantPreviews, cleanupPipeScratch);
        for (int i = 0; i < cleanupPipeScratch.Count; i++)
        {
            Pipe installedPipe = cleanupPipeScratch[i];
            installedPipeVariantPreviews.TryGetValue(installedPipe, out MapObject preview);
            bool ownerMissing = installedPipe == null;
            bool ownerInactive = !ownerMissing && !installedPipe.gameObject.activeInHierarchy;
            if (ownerMissing || ownerInactive || preview == null)
            {
                RemoveInstalledPipeVariantPreview(installedPipe);
            }
        }

        CopyPipeKeys(installedPipePreviewRendererStates, cleanupPipeScratch);
        for (int i = 0; i < cleanupPipeScratch.Count; i++)
        {
            Pipe installedPipe = cleanupPipeScratch[i];
            if (installedPipe == null || !installedPipeVariantPreviews.ContainsKey(installedPipe))
            {
                RestoreInstalledObjectPreviewRenderers(installedPipe, installedPipePreviewRendererStates);
            }
        }

        cleanupPipeScratch.Clear();
    }

    private void HideInstalledPipeForVariantPreview(Pipe installedPipe, MapObject preview)
    {
        if (HasRenderableVariantPreview(preview))
        {
            HideInstalledObjectForVariantPreview(installedPipe, installedPipePreviewRendererStates);
            return;
        }

        RestoreInstalledObjectPreviewRenderers(installedPipe, installedPipePreviewRendererStates);
    }

    private void RestorePipeRenderersWithoutRenderableVariantPreview()
    {
        CopyPipeKeys(installedPipePreviewRendererStates, cleanupPipeScratch);
        for (int i = 0; i < cleanupPipeScratch.Count; i++)
        {
            Pipe installedPipe = cleanupPipeScratch[i];
            bool hasRenderablePreview = installedPipe != null
                                        && installedPipeVariantPreviews.TryGetValue(installedPipe, out MapObject preview)
                                        && HasRenderableVariantPreview(preview);
            if (!hasRenderablePreview)
            {
                RestoreInstalledObjectPreviewRenderers(installedPipe, installedPipePreviewRendererStates);
            }
        }

        cleanupPipeScratch.Clear();
    }

    private static bool HasRenderableVariantPreview(MapObject preview)
    {
        if (preview == null || !preview.gameObject.activeInHierarchy)
        {
            return false;
        }

        Renderer[] renderers = preview.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer != null && renderer.enabled && renderer.gameObject.activeInHierarchy)
            {
                return true;
            }
        }

        return false;
    }

    private static void CopyWallKeys<TValue>(Dictionary<Wall, TValue> dictionary, List<Wall> target)
    {
        target.Clear();
        if (dictionary == null || dictionary.Count <= 0)
        {
            return;
        }

        foreach (KeyValuePair<Wall, TValue> entry in dictionary)
        {
            target.Add(entry.Key);
        }
    }

    private static void CopyPipeKeys<TValue>(Dictionary<Pipe, TValue> dictionary, List<Pipe> target)
    {
        target.Clear();
        if (dictionary == null || dictionary.Count <= 0)
        {
            return;
        }

        foreach (KeyValuePair<Pipe, TValue> entry in dictionary)
        {
            target.Add(entry.Key);
        }
    }

    private static void HideInstalledObjectForVariantPreview<TInstallation>(
        TInstallation installedObject,
        Dictionary<TInstallation, List<RendererVisibilityState>> rendererStatesByObject)
        where TInstallation : MapObject
    {
        if (installedObject == null
            || rendererStatesByObject == null
            || rendererStatesByObject.ContainsKey(installedObject))
        {
            return;
        }

        Renderer[] renderers = installedObject.GetComponentsInChildren<Renderer>(true);
        List<RendererVisibilityState> rendererStates = new List<RendererVisibilityState>();
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer == null)
            {
                continue;
            }

            rendererStates.Add(new RendererVisibilityState
            {
                renderer = renderer,
                enabled = renderer.enabled
            });
            renderer.enabled = false;
        }

        rendererStatesByObject[installedObject] = rendererStates;
    }

    private static void RestoreInstalledObjectPreviewRenderers<TInstallation>(
        TInstallation installedObject,
        Dictionary<TInstallation, List<RendererVisibilityState>> rendererStatesByObject)
        where TInstallation : MapObject
    {
        if (ReferenceEquals(installedObject, null)
            || rendererStatesByObject == null
            || !rendererStatesByObject.TryGetValue(installedObject, out List<RendererVisibilityState> rendererStates))
        {
            return;
        }

        for (int i = 0; i < rendererStates.Count; i++)
        {
            RendererVisibilityState rendererState = rendererStates[i];
            if (rendererState == null || rendererState.renderer == null)
            {
                continue;
            }

            rendererState.renderer.enabled = rendererState.enabled;
        }

        rendererStatesByObject.Remove(installedObject);
    }

    private void DestroyInstallPreviewObject(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        UnregisterUtilityPolePreviewWire(preview);
        SetInstallPreviewSelectionVisual(preview, false);
        ReleaseBlueprintPreviewMaterials(preview);
        preview.gameObject.SetActive(false);
        if (Application.isPlaying)
        {
            Destroy(preview.gameObject);
        }
        else
        {
            DestroyImmediate(preview.gameObject);
        }
    }

    private static void ReleaseBlueprintPreviewMaterials(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        Renderer[] renderers = preview.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer == null)
            {
                continue;
            }

            Material[] materials = renderer.sharedMaterials;
            if (materials == null)
            {
                continue;
            }

            for (int materialIndex = 0; materialIndex < materials.Length; materialIndex++)
            {
                Material material = materials[materialIndex];
                if (!IsRuntimeBlueprintPreviewMaterial(material))
                {
                    continue;
                }

                materials[materialIndex] = null;
                if (Application.isPlaying)
                {
                    runtimeBlueprintPreviewMaterials.Remove(material);
                    Destroy(material);
                }
                else
                {
                    runtimeBlueprintPreviewMaterials.Remove(material);
                    DestroyImmediate(material);
                }
            }

            renderer.sharedMaterials = materials;
        }
    }

    private static bool IsRuntimeBlueprintPreviewMaterial(Material material)
    {
        if (material == null)
        {
            return false;
        }

        if (runtimeBlueprintPreviewMaterials.Contains(material))
        {
            return true;
        }

        return (material.hideFlags & HideFlags.DontSave) != 0
               && material.name.EndsWith(BlueprintPreviewRuntimeMaterialSuffix);
    }

    private void RefreshActiveFencePreviewVariant(bool preserveActivePreviewQuarterTurns = false)
    {
        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is Wall))
        {
            return;
        }

        if (activeInstallPreview == null || !TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
        {
            return;
        }

        RefreshSingleFencePreviewVariant(
            activeInstallPreview,
            anchorCoordinate,
            null,
            preserveActivePreviewQuarterTurns);
    }

    private void RefreshActivePipePreviewVariant()
    {
        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is Pipe))
        {
            return;
        }

        if (activeInstallPreview == null || !TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
        {
