    }

    private List<Vector3> GetRectGridBlockWorldPositions(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        InputOutputModule.RectGridBlockType blockType)
    {
        return GetRectGridBlockWorldPositions(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            new[] { blockType });
    }

    private List<Vector3> GetRectGridBlockWorldPositions(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes)
    {
        List<Vector3> worldPositions = new List<Vector3>();
        if (!TryGetRectGridBlockCoordinates(anchorCoordinate, footprintSource, quarterTurns, blockTypes, out List<Vector2Int> coordinates))
        {
            return worldPositions;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        float fallbackY = terrain != null ? terrain.transform.position.y : 0f;

        for (int i = 0; i < coordinates.Count; i++)
        {
            worldPositions.Add(GetAreaMarkerWorldPosition(coordinates[i], terrain, fallbackY));
        }

        return worldPositions;
    }

    private void FillRectGridBlockWorldPositions(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes,
        List<Vector3> worldPositions)
    {
        if (worldPositions == null)
        {
            return;
        }

        worldPositions.Clear();
        if (!TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        float fallbackY = terrain != null ? terrain.transform.position.y : 0f;
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(footprintSource, quarterTurns);
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (placement.blockType == InputOutputModule.RectGridBlockType.None
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight
                || (blockTypes != null && !RectGridBlockTypeListContains(blockTypes, placement.blockType)))
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int rotatedOffset = RotateFootprintOffset(localOffset, normalizedQuarterTurns);
            worldPositions.Add(GetAreaMarkerWorldPosition(anchorCoordinate + rotatedOffset, terrain, fallbackY));
        }
    }

    private Vector3 GetAreaMarkerWorldPosition(Vector2Int coordinate)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        float fallbackY = terrain != null ? terrain.transform.position.y : 0f;
        return GetAreaMarkerWorldPosition(coordinate, terrain, fallbackY);
    }

    private static Vector3 GetAreaMarkerWorldPosition(
        Vector2Int coordinate,
        TerrainGenerator terrain,
        float fallbackY)
    {
        if (terrain != null && terrain.TryGetLoadedBlock(coordinate, out Block block) && block != null)
        {
            Vector3 markerPosition = block.transform.position;
            if (TryGetMiningResourceMarkerSurfaceY(block, out float markerSurfaceY))
            {
                markerPosition.y = Mathf.Max(markerPosition.y, markerSurfaceY);
            }

            return markerPosition;
        }

        return new Vector3(coordinate.x, fallbackY, coordinate.y);
    }

    private static bool TryGetMiningResourceMarkerSurfaceY(Block block, out float surfaceY)
    {
        surfaceY = 0f;
        Resource resource = block != null ? block.Resource : null;
        if (resource == null || resource.ResolvedHarvestMode != Resource.HarvestMode.Mining)
        {
            return false;
        }

        int resourceInstanceId = resource.GetInstanceID();
        if (ResourceMarkerSurfaceYCache.TryGetValue(resourceInstanceId, out surfaceY))
        {
            return true;
        }

        ResourceRendererScratch.Clear();
        resource.GetComponentsInChildren(true, ResourceRendererScratch);
        bool foundRenderer = false;
        Bounds bounds = default;
        for (int i = 0; i < ResourceRendererScratch.Count; i++)
        {
            Renderer rendererComponent = ResourceRendererScratch[i];
            if (rendererComponent == null)
            {
                continue;
            }

            if (!foundRenderer)
            {
                bounds = rendererComponent.bounds;
                foundRenderer = true;
                continue;
            }

            bounds.Encapsulate(rendererComponent.bounds);
        }

        ResourceRendererScratch.Clear();

        surfaceY = foundRenderer
            ? bounds.max.y
            : Mathf.Max(block.transform.position.y, resource.transform.position.y);
        ResourceMarkerSurfaceYCache[resourceInstanceId] = surfaceY;
        return true;
    }

    private bool TryBuildRectGridPlacementCells(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes,
        List<RectGridPlacementCell> cells)
    {
        if (cells == null)
        {
            return false;
        }

        cells.Clear();
        if (!TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(footprintSource, quarterTurns);
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (placement.blockType == InputOutputModule.RectGridBlockType.None
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight
                || (blockTypes != null && !RectGridBlockTypeListContains(blockTypes, placement.blockType)))
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int rotatedOffset = RotateFootprintOffset(localOffset, normalizedQuarterTurns);
            cells.Add(new RectGridPlacementCell(
                placement,
                placement.blockType,
                localOffset,
                rotatedOffset,
                anchorCoordinate + rotatedOffset));
        }

        return cells.Count > 0;
    }

    private bool TryGetRectGridBlockCoordinates(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        InputOutputModule.RectGridBlockType blockType,
        out List<Vector2Int> coordinates)
    {
        return TryGetRectGridBlockCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            new[] { blockType },
            out coordinates);
    }

    private bool TryGetRectGridBlockCoordinates(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes,
        out List<Vector2Int> coordinates)
    {
        coordinates = new List<Vector2Int>();
        List<RectGridPlacementCell> cells = new List<RectGridPlacementCell>();
        if (!TryBuildRectGridPlacementCells(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                blockTypes,
                cells))
        {
            return false;
        }

        for (int i = 0; i < cells.Count; i++)
        {
            coordinates.Add(cells[i].coordinate);
        }

        return coordinates.Count > 0;
    }

    private bool TryGetRectGridBlockLocalOffsets(
        MapObject footprintSource,
        int quarterTurns,
        InputOutputModule.RectGridBlockType blockType,
        out List<Vector2Int> localOffsets)
    {
        return TryGetRectGridBlockLocalOffsets(
            footprintSource,
            quarterTurns,
            new[] { blockType },
            out localOffsets);
    }

    private bool TryGetRectGridBlockLocalOffsets(
        MapObject footprintSource,
        int quarterTurns,
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes,
        out List<Vector2Int> localOffsets)
    {
        localOffsets = new List<Vector2Int>();
        List<RectGridPlacementCell> cells = new List<RectGridPlacementCell>();
        if (!TryBuildRectGridPlacementCells(
                Vector2Int.zero,
                footprintSource,
                quarterTurns,
                blockTypes,
                cells))
        {
            return false;
        }

        for (int i = 0; i < cells.Count; i++)
        {
            localOffsets.Add(cells[i].rotatedOffset);
        }

        return localOffsets.Count > 0;
    }

    private static bool RectGridBlockTypeListContains(
        IReadOnlyList<InputOutputModule.RectGridBlockType> blockTypes,
        InputOutputModule.RectGridBlockType blockType)
    {
        if (blockTypes == null)
        {
            return false;
        }

        for (int i = 0; i < blockTypes.Count; i++)
        {
            if (blockTypes[i] == blockType)
            {
                return true;
            }
        }

        return false;
    }

    private void BeginInstallPreview(ItemDefinition definition)
    {
        ClearInstallPreview();
        InvalidateInstallPreviewMoveCache();

        activeInstallDefinition = definition;
        activeInstallPreview = null;
        activeInstallBaseRotation = definition.mapObject != null ? definition.mapObject.transform.rotation : Quaternion.identity;
        installPreviewQuarterTurns = IsFenceDoorDefinition(definition)
            ? GetPreferredFenceDoorStandaloneQuarterTurns(definition, null)
            : GetPreferredInstallPreviewQuarterTurns(definition, null);
        waitForPointerReleaseAfterPreviewSpawn = true;
        InvalidateInstallGrid();
        GameManager.Instance?.SetInstallationPlacementActive(true);
        RefreshInstallOrEditWorkableRangeVisualRequest();
    }

    private void BeginRailloadInstallPreview(ItemDefinition definition)
    {
        ClearInstallPreview();
        InvalidateInstallPreviewMoveCache();

        activeInstallDefinition = definition;
        activeInstallPreview = null;
        activeInstallBaseRotation = definition != null && definition.mapObject != null
            ? definition.mapObject.transform.rotation
            : Quaternion.identity;
        installPreviewQuarterTurns = 0;
        waitForPointerReleaseAfterPreviewSpawn = true;
        InvalidateInstallGrid();
        GameManager.Instance?.SetInstallationPlacementActive(true);
        ResolveRailloadInstallationController().Begin(this, definition);
        RefreshInstallOrEditWorkableRangeVisualRequest();
    }

    private RailloadInstallationController ResolveRailloadInstallationController()
    {
        if (railloadInstallationController != null)
        {
            return railloadInstallationController;
        }

        railloadInstallationController = GetComponent<RailloadInstallationController>();
        if (railloadInstallationController == null)
        {
            railloadInstallationController = gameObject.AddComponent<RailloadInstallationController>();
        }

        railloadInstallationController.Initialize(this);
        return railloadInstallationController;
    }

    private bool IsRailloadInstallationModeActive()
    {
        return railloadInstallationController != null && railloadInstallationController.IsActive;
    }

    private MapObject CreateInstallPreviewInstance(ItemDefinition definition)
    {
        if (definition == null || definition.mapObject == null)
        {
            return null;
        }

        MapObject sourcePrefab = definition.mapObject;
        if (definition.mapObject is ConveyorBelt conveyorPrototype)
        {
            sourcePrefab = conveyorPrototype.StraightVariantPrefab != null
                ? conveyorPrototype.StraightVariantPrefab
                : definition.mapObject;
        }
        else if (definition.mapObject is Wall fencePrototype)
        {
            sourcePrefab = fencePrototype.StraightVariantPrefab != null
                ? fencePrototype.StraightVariantPrefab
                : definition.mapObject;
        }
        else if (definition.mapObject is Pipe pipePrototype)
        {
            sourcePrefab = pipePrototype.StraightVariantPrefab != null
                ? pipePrototype.StraightVariantPrefab
                : definition.mapObject;
        }

        return CreateInstallPreviewInstance(sourcePrefab, definition.mapObject);
    }

    private MapObject CreateInstallPreviewInstance(MapObject sourcePrefab, MapObject nameSourcePrefab)
    {
        if (sourcePrefab == null)
        {
            return null;
        }

        MapObject preview = Instantiate(sourcePrefab);
        if (preview == null)
        {
            return null;
        }

        string previewName = nameSourcePrefab != null ? nameSourcePrefab.name : sourcePrefab.name;
        preview.name = $"{previewName}_Blueprint";
        ConfigureInstallPreview(preview);
        installPreviewSourcePrefabsByPreview[preview] = sourcePrefab;
        return preview;
    }

    private void ConfigureInstallPreview(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        ApplyConveyorVariantSharedInstallationSettings(preview);
        ApplyPipeVariantSharedMapObjectSettings(preview);

        MonoBehaviour[] behaviours = preview.GetComponentsInChildren<MonoBehaviour>(true);
        for (int i = 0; i < behaviours.Length; i++)
        {
            MonoBehaviour behaviour = behaviours[i];
            if (behaviour == null)
            {
                continue;
            }

            behaviour.enabled = false;
        }

        Collider[] colliders = preview.GetComponentsInChildren<Collider>(true);
        for (int i = 0; i < colliders.Length; i++)
        {
            if (colliders[i] != null)
            {
                colliders[i].enabled = false;
            }
        }

        Rigidbody[] rigidbodies = preview.GetComponentsInChildren<Rigidbody>(true);
        for (int i = 0; i < rigidbodies.Length; i++)
        {
            Rigidbody body = rigidbodies[i];
            if (body == null)
            {
                continue;
            }

            body.isKinematic = true;
            body.detectCollisions = false;
        }

        if (installPreviewPropertyBlock == null)
        {
            installPreviewPropertyBlock = new MaterialPropertyBlock();
        }

        Renderer[] renderers = preview.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            Renderer renderer = renderers[i];
            if (renderer == null)
            {
                continue;
            }

            renderer.shadowCastingMode = ShadowCastingMode.Off;
            renderer.receiveShadows = false;
            Color previewTint = ResolveInstallPreviewTint(preview);
            ApplyBlueprintPreviewMaterial(renderer, previewTint);

            Material sharedMaterial = renderer.sharedMaterial;
            if (sharedMaterial == null)
            {
                continue;
            }

            installPreviewPropertyBlock.Clear();
            renderer.GetPropertyBlock(installPreviewPropertyBlock);
            bool hasColorProperty = false;

            if (TryApplyBlueprintPreviewProperties(sharedMaterial, installPreviewPropertyBlock, previewTint))
            {
                hasColorProperty = true;
            }
            else if (sharedMaterial.HasProperty(BaseColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(BaseColorPropertyId, previewTint);
                hasColorProperty = true;
            }
            else if (sharedMaterial.HasProperty(ColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(ColorPropertyId, previewTint);
                hasColorProperty = true;
            }

            if (sharedMaterial.HasProperty(EmissionColorPropertyId))
            {
                installPreviewPropertyBlock.SetColor(EmissionColorPropertyId, previewTint * 0.35f);
                hasColorProperty = true;
            }

            if (hasColorProperty)
            {
                renderer.SetPropertyBlock(installPreviewPropertyBlock);
            }
        }

        SetInstallPreviewSelectionVisual(preview, false);
    }

    private static void ApplyBlueprintPreviewMaterial(Renderer renderer, Color previewTint)
    {
        if (renderer == null
            || renderer.GetComponentInParent<WorkableObjectRangeVisual>() != null)
        {
            return;
        }

        Material[] sourceMaterials = renderer.sharedMaterials;
        if (sourceMaterials == null || sourceMaterials.Length == 0)
        {
            return;
        }

        Material[] previewMaterials = new Material[sourceMaterials.Length];
        for (int i = 0; i < previewMaterials.Length; i++)
        {
            previewMaterials[i] = CreateBlueprintPreviewMaterial(sourceMaterials[i], previewTint);
        }

        renderer.sharedMaterials = previewMaterials;
    }

    private static Material CreateBlueprintPreviewMaterial(Material sourceMaterial, Color previewTint)
    {
        if (sourceMaterial == null)
        {
            return null;
        }

        Material material = new Material(sourceMaterial)
        {
            name = $"{sourceMaterial.name}{BlueprintPreviewRuntimeMaterialSuffix}",
            hideFlags = HideFlags.DontSave
        };

        runtimeBlueprintPreviewMaterials.Add(material);
        ConfigureBlueprintPreviewMaterial(material, previewTint);
        return material;
    }

    private static void ConfigureBlueprintPreviewMaterial(Material material, Color previewTint)
    {
        if (material == null)
        {
            return;
        }

        SetBlueprintPreviewMaterialProperties(material, previewTint);
        material.SetOverrideTag("RenderType", "Transparent");
        material.renderQueue = (int)RenderQueue.Transparent;
        material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");

        if (material.HasProperty(SurfacePropertyId))
        {
            material.SetFloat(SurfacePropertyId, 1f);
        }

        if (material.HasProperty(SrcBlendPropertyId))
        {
            material.SetFloat(SrcBlendPropertyId, (float)BlendMode.SrcAlpha);
        }

        if (material.HasProperty(DstBlendPropertyId))
        {
            material.SetFloat(DstBlendPropertyId, (float)BlendMode.OneMinusSrcAlpha);
        }

        if (material.HasProperty(SrcBlendAlphaPropertyId))
        {
            material.SetFloat(SrcBlendAlphaPropertyId, (float)BlendMode.One);
        }

        if (material.HasProperty(DstBlendAlphaPropertyId))
        {
            material.SetFloat(DstBlendAlphaPropertyId, (float)BlendMode.OneMinusSrcAlpha);
        }

        if (material.HasProperty(ZWritePropertyId))
        {
            material.SetFloat(ZWritePropertyId, 1f);
        }
    }

    private static void SetBlueprintPreviewMaterialProperties(Material material, Color previewTint)
    {
        if (material == null)
        {
            return;
        }

        if (material.HasProperty(BlueprintPreviewPropertyId))
        {
            material.SetFloat(BlueprintPreviewPropertyId, 1f);
        }

        if (material.HasProperty(BlueprintTintPropertyId))
        {
            material.SetColor(BlueprintTintPropertyId, GetBlueprintPreviewTintColor(previewTint));
        }

        if (material.HasProperty(BlueprintBrightnessPropertyId))
        {
            material.SetFloat(BlueprintBrightnessPropertyId, BlueprintPreviewBrightness);
        }

        if (material.HasProperty(BlueprintMinBrightnessPropertyId))
        {
            material.SetFloat(BlueprintMinBrightnessPropertyId, BlueprintPreviewMinBrightness);
        }

        if (material.HasProperty(BlueprintContrastPropertyId))
        {
            material.SetFloat(BlueprintContrastPropertyId, BlueprintPreviewContrast);
        }

        if (material.HasProperty(BlueprintAlphaPropertyId))
        {
            material.SetFloat(BlueprintAlphaPropertyId, Mathf.Max(previewTint.a, BlueprintPreviewAlpha));
        }

        if (material.HasProperty(BlueprintRimColorPropertyId))
        {
            material.SetColor(BlueprintRimColorPropertyId, GetBlueprintPreviewRimColor(previewTint));
        }

        if (material.HasProperty(BlueprintRimStrengthPropertyId))
        {
            material.SetFloat(BlueprintRimStrengthPropertyId, BlueprintPreviewRimStrength);
        }

        if (material.HasProperty(BlueprintRimPowerPropertyId))
        {
            material.SetFloat(BlueprintRimPowerPropertyId, BlueprintPreviewRimPower);
        }
    }

    private static bool TryApplyBlueprintPreviewProperties(
        Material material,
        MaterialPropertyBlock propertyBlock,
        Color previewTint)
    {
        if (material == null || propertyBlock == null)
        {
            return false;
        }

        bool applied = false;
        if (material.HasProperty(BlueprintPreviewPropertyId))
        {
            propertyBlock.SetFloat(BlueprintPreviewPropertyId, 1f);
            applied = true;
        }

        if (material.HasProperty(BlueprintTintPropertyId))
        {
            propertyBlock.SetColor(BlueprintTintPropertyId, GetBlueprintPreviewTintColor(previewTint));
            applied = true;
        }

        if (material.HasProperty(BlueprintBrightnessPropertyId))
        {
            propertyBlock.SetFloat(BlueprintBrightnessPropertyId, BlueprintPreviewBrightness);
            applied = true;
        }

        if (material.HasProperty(BlueprintMinBrightnessPropertyId))
        {
            propertyBlock.SetFloat(BlueprintMinBrightnessPropertyId, BlueprintPreviewMinBrightness);
            applied = true;
        }

        if (material.HasProperty(BlueprintContrastPropertyId))
        {
            propertyBlock.SetFloat(BlueprintContrastPropertyId, BlueprintPreviewContrast);
            applied = true;
        }

        if (material.HasProperty(BlueprintAlphaPropertyId))
        {
            propertyBlock.SetFloat(BlueprintAlphaPropertyId, Mathf.Max(previewTint.a, BlueprintPreviewAlpha));
            applied = true;
        }

        if (material.HasProperty(BlueprintRimColorPropertyId))
        {
            propertyBlock.SetColor(BlueprintRimColorPropertyId, GetBlueprintPreviewRimColor(previewTint));
            applied = true;
        }

        if (material.HasProperty(BlueprintRimStrengthPropertyId))
        {
            propertyBlock.SetFloat(BlueprintRimStrengthPropertyId, BlueprintPreviewRimStrength);
            applied = true;
        }

        if (material.HasProperty(BlueprintRimPowerPropertyId))
        {
            propertyBlock.SetFloat(BlueprintRimPowerPropertyId, BlueprintPreviewRimPower);
            applied = true;
        }

        return applied;
    }

    private static Color GetBlueprintPreviewTintColor(Color previewTint)
    {
        return new Color(previewTint.r, previewTint.g, previewTint.b, 1f);
    }

    private static Color GetBlueprintPreviewRimColor(Color previewTint)
    {
        return new Color(0.03f, 0.12f, 0.52f, 1f);
    }

    private void TryMoveInstallPreview(Vector2 pointerPosition, bool preserveRotation = false)
    {
        if (activeInstallPreview == null)
        {
            return;
        }

        Vector3? railReferenceWorldPosition = null;
        if (TryGetInstallPreviewRailReferenceWorldPosition(pointerPosition, out Vector3 worldPoint))
        {
            railReferenceWorldPosition = worldPoint;
        }

        if (TryGetPlacementPointerBlock(pointerPosition, out Block block))
        {
            MoveInstallPreviewToBlock(block, preserveRotation, railReferenceWorldPosition);
        }
    }

    private bool TryGetInstallPreviewRailReferenceWorldPosition(
        Vector2 pointerPosition,
        out Vector3 worldPosition)
    {
        worldPosition = Vector3.zero;
        Camera targetCamera = ResolveInstallPreviewCamera();
        return targetCamera != null
               && TryGetGroundPlanePoint(targetCamera.ScreenPointToRay(pointerPosition), out worldPosition);
    }

    private bool MoveInstallPreviewToBlock(
        Block block,
        bool preserveRotation = false,
        Vector3? railReferenceWorldPosition = null)
    {
        if (activeInstallPreview == null || block == null)
        {
            return false;
        }

        if (TryUseCachedInstallPreviewMove(block, preserveRotation, out bool cachedMoveResult))
        {
            return cachedMoveResult;
        }

        int preferredQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        bool allowWaterPumpAutoRotation = IsWaterPumpPreview(activeInstallPreview);
        bool preserveRotationForTarget = preserveRotation && !allowWaterPumpAutoRotation;
        bool useSimpleRectGridTarget =
            TryResolveInstallPreviewFootprintSourceForPlacement(activeInstallPreview, out MapObject moveFootprintSource)
            && CanUseSimpleRectGridInstallGridCheck(moveFootprintSource);
        Block anchorBlock;
        int resolvedQuarterTurns;
        bool hasPlacementTarget = IsTrainSource(moveFootprintSource)
            ? TryResolveTrainInstallPreviewTarget(
                block,
                moveFootprintSource,
                preferredQuarterTurns,
                railReferenceWorldPosition,
                out anchorBlock,
                out resolvedQuarterTurns)
            : useSimpleRectGridTarget
            ? TryResolveSimpleRectGridInstallPreviewTargetFast(
                block,
                moveFootprintSource,
                activeInstallPreview,
                preferredQuarterTurns,
                preserveRotationForTarget,
                out anchorBlock,
                out resolvedQuarterTurns)
            : preserveRotationForTarget
                ? TryResolveFixedRotationInstallPreviewTarget(
                    block,
                    activeInstallPreview,
                    preferredQuarterTurns,
                    out anchorBlock,
                    out resolvedQuarterTurns)
                : TryResolvePlaceableInstallPreviewTarget(
                    block,
                    activeInstallPreview,
                    preferredQuarterTurns,
                    false,
                    out anchorBlock,
                    out resolvedQuarterTurns);
        if (!hasPlacementTarget)
        {
            CacheInstallPreviewMoveResult(block, false, preserveRotation);
            return false;
        }

        MapObject waterPumpRotationSource = ResolveInstallPreviewFootprintSource(activeInstallPreview)
                                            ?? (activeInstallDefinition != null ? activeInstallDefinition.mapObject : null)
                                            ?? activeInstallPreview;
        if ((!preserveRotation || allowWaterPumpAutoRotation)
            && TryResolveWaterPumpOutwardQuarterTurns(
                anchorBlock.Coordinate,
                waterPumpRotationSource,
                resolvedQuarterTurns,
                out int waterPumpQuarterTurns))
        {
            resolvedQuarterTurns = waterPumpQuarterTurns;
        }

        MapObject activePlacementSourceForMove = ResolveInstallPreviewPlacementSource(activeInstallPreview)
                                             ?? moveFootprintSource;
        if (!IsTrainSource(activePlacementSourceForMove)
            && TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int currentAnchorCoordinate)
            && currentAnchorCoordinate == anchorBlock.Coordinate
            && GetPreviewQuarterTurns(activeInstallPreview) == resolvedQuarterTurns)
        {
            CacheInstallPreviewMoveResult(block, true, preserveRotation);
            return true;
        }

        SetInstallPreviewQuarterTurns(activeInstallPreview, resolvedQuarterTurns);

        Vector2Int previousAnchorCoordinate = Vector2Int.zero;
        bool hadPreviousAnchorCoordinate = TryGetPreviewAnchorCoordinate(activeInstallPreview, out previousAnchorCoordinate);

        installPreviewAnchorCoordinates[activeInstallPreview] = anchorBlock.Coordinate;
        if (hadPreviousAnchorCoordinate && previousAnchorCoordinate != anchorBlock.Coordinate)
        {
            straightFirstConveyorPreviews.Remove(activeInstallPreview);
        }

        RefreshActiveConveyorPreviewVariant();
        RefreshActiveFencePreviewVariant(true);
        RefreshActivePipePreviewVariant();
        MapObject placementSource = ResolveInstallPreviewPlacementSource(activeInstallPreview);
        Vector3 targetPosition = ResolvePlacementWorldPosition(
            anchorBlock,
            placementSource,
            installPreviewQuarterTurns,
            railReferenceWorldPosition);
        if (IsTrainSource(placementSource) && railReferenceWorldPosition.HasValue)
        {
            installPreviewRailReferenceWorldPositions[activeInstallPreview] = railReferenceWorldPosition.Value;
        }
        else
        {
            installPreviewRailReferenceWorldPositions.Remove(activeInstallPreview);
        }

        activeInstallPreview.transform.position = targetPosition;
        activeInstallPreview.transform.rotation = GetInstallPreviewRotation();
        if (activeInstallPreview is InstallationObject movedInstallationPreview)
        {
            movedInstallationPreview.RefreshInstalledDirectionFromCurrentTransform();
        }

        RefreshPreviewRangeVisualsIfNeeded(activeInstallPreview);
        RefreshUtilityPolePreviewWires();
        RefreshInstallPreviewAreaMarkers(activeInstallPreview);
        RefreshFencePreviewVariantsAroundActivePreview(
            hadPreviousAnchorCoordinate ? previousAnchorCoordinate : (Vector2Int?)null,
            true);
        RefreshPipePreviewVariantsAroundActivePreview(
            hadPreviousAnchorCoordinate ? previousAnchorCoordinate : (Vector2Int?)null);
        RefreshTrainInstallPreviewTints();
        RememberBlueprintRotationForPreview(activeInstallDefinition, activeInstallPreview, installPreviewQuarterTurns);
        InvalidateInstallGridPreview();
        CacheInstallPreviewMoveResult(block, true, preserveRotation);
        return true;
    }

    private bool IsWaterPumpPreview(MapObject preview)
    {
        if (preview == null)
        {
            return false;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(preview)
                                    ?? (activeInstallDefinition != null ? activeInstallDefinition.mapObject : null)
                                    ?? preview;
        return IsWaterPumpSource(footprintSource);
    }

    private bool TryResolveTrainInstallPreviewTarget(
        Block block,
        MapObject footprintSource,
        int preferredQuarterTurns,
        Vector3? railReferenceWorldPosition,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = block;
        resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            preferredQuarterTurns);
        if (block == null || !IsTrainSource(footprintSource))
        {
            return false;
        }

        Vector3 referencePosition = railReferenceWorldPosition ?? block.transform.position;
        return TryResolveTrainRailPlacementPose(
            footprintSource,
            block.Coordinate,
            resolvedQuarterTurns,
            referencePosition,
            out _,
            out _);
    }

    private bool TryGetPointerBlock(out Block block)
    {
        block = null;
        return TryGetPrimaryPointerPosition(out Vector2 pointerPosition) && TryGetPointerBlock(pointerPosition, out block);
    }

    private bool TryGetPointerBlock(Vector2 pointerPosition, out Block block)
    {
        block = null;

        Camera targetCamera = ResolveInstallPreviewCamera();
        if (targetCamera == null)
        {
            return false;
        }

        Ray ray = targetCamera.ScreenPointToRay(pointerPosition);
        int hitCount = Physics.RaycastNonAlloc(
            ray,
            pointerRaycastHits,
            512f,
            Physics.DefaultRaycastLayers,
            QueryTriggerInteraction.Ignore);
        if (hitCount > 0)
        {
            Block nearestBlock = null;
            float nearestDistance = float.PositiveInfinity;
            for (int i = 0; i < hitCount; i++)
            {
                RaycastHit hit = pointerRaycastHits[i];
                Block hitBlock = hit.collider != null ? hit.collider.GetComponentInParent<Block>() : null;
                if (hitBlock != null && hit.distance < nearestDistance)
                {
                    nearestBlock = hitBlock;
                    nearestDistance = hit.distance;
                }
            }

            if (nearestBlock != null)
            {
                block = nearestBlock;
                return true;
            }
        }

        return TryGetBlockFromGroundPlane(ray, out block);
    }

    public bool TryGetPlacementPointerBlock(out Block block)
    {
        block = null;
        return TryGetPrimaryPointerPosition(out Vector2 pointerPosition)
               && TryGetPlacementPointerBlock(pointerPosition, out block);
    }

    public bool TryGetPlacementPointerBlock(Vector2 pointerPosition, out Block block)
    {
        block = null;
        Camera targetCamera = ResolveInstallPreviewCamera();
        if (targetCamera == null)
        {
            return false;
        }

        Ray ray = targetCamera.ScreenPointToRay(pointerPosition);
        return TryGetBlockFromGroundPlane(ray, out block)
               || TryGetPointerBlock(pointerPosition, out block);
    }

    private Camera ResolveInstallPreviewCamera()
    {
        if (installPreviewCamera != null)
        {
            return installPreviewCamera;
        }

        installPreviewCamera = Camera.main;
        if (installPreviewCamera != null)
        {
            return installPreviewCamera;
        }

        PlayerCamera playerCamera = FindObjectOfType<PlayerCamera>();
        if (playerCamera != null)
        {
            installPreviewCamera = playerCamera.GetComponent<Camera>();
        }

        if (installPreviewCamera == null)
        {
            installPreviewCamera = FindObjectOfType<Camera>();
        }

        return installPreviewCamera;
    }

    private TerrainGenerator ResolveInstallPreviewTerrain()
    {
        if (installPreviewTerrain == null)
        {
            installPreviewTerrain = TerrainGenerator.ResolveActive();
        }

        return installPreviewTerrain;
    }

    private void UpdateInstallGrid()
    {
        bool showFullGrid = IsInstallGridModeActive();
        bool showConveyorDebugOnly = !showFullGrid
            && GameManager.Instance != null
            && GameManager.Instance.DebugConveyorInstallGridEnds;
        if (!showFullGrid && !showConveyorDebugOnly)
        {
            SetInstallGridVisible(false);
            ResetInstallGridRefreshState();
            return;
        }

        if (showFullGrid != installGridLastShowFullGrid
            || showConveyorDebugOnly != installGridLastShowConveyorDebugOnly)
        {
            installGridDirty = true;
            installGridPreviewDirty = true;
            installGridLastShowFullGrid = showFullGrid;
            installGridLastShowConveyorDebugOnly = showConveyorDebugOnly;
        }

        EnsureInstallGridResources();
        bool wasVisible = installGridObject != null && installGridObject.activeSelf;
        SetInstallGridVisible(true);
        if (!wasVisible)
        {
            installGridDirty = true;
            installGridPreviewDirty = true;
        }

        if (HaveInstallGridBoundsChanged())
        {
            installGridDirty = true;
        }

        if (HaveInstallGridPreviewStateChanged())
        {
            installGridPreviewDirty = true;
        }

        if (installGridDirty)
        {
            RebuildInstallGridMesh();
            installGridDirty = false;
        }

        if (installGridPreviewDirty)
        {
            RebuildInstallGridPreviewMesh();
            installGridPreviewDirty = false;
        }
    }

    private void ResetInstallGridRefreshState()
    {
        installGridDirty = true;
        installGridPreviewDirty = true;
        installGridBoundsInitialized = false;
        installGridLastShowFullGrid = false;
        installGridLastShowConveyorDebugOnly = false;
        installGridLastHadPreviewOverlay = false;
        installGridLastPreviewAnchorCoordinate = Vector2Int.zero;
        installGridLastPreviewQuarterTurns = 0;
        installGridLastPreview = null;
    }

    private bool HaveInstallGridBoundsChanged()
    {
        if (!TryGetInstallGridEffectiveBounds(out Vector2Int minCoordinate, out Vector2Int maxCoordinate))
        {
            return installGridBoundsInitialized;
        }

        return !installGridBoundsInitialized
               || installGridMinCoordinate != minCoordinate
               || installGridMaxCoordinate != maxCoordinate;
    }

    private bool HaveInstallGridPreviewStateChanged()
    {
        Vector2Int anchorCoordinate = Vector2Int.zero;
        bool hasPreviewOverlay = IsInstallGridModeActive()
                                 && activeInstallPreview != null
                                 && TryGetPreviewAnchorCoordinate(activeInstallPreview, out anchorCoordinate);
        int quarterTurns = hasPreviewOverlay ? GetPreviewAreaQuarterTurns(activeInstallPreview) : 0;
        bool changed = installGridLastHadPreviewOverlay != hasPreviewOverlay
                       || installGridLastPreview != activeInstallPreview
                       || (hasPreviewOverlay && installGridLastPreviewAnchorCoordinate != anchorCoordinate)
                       || (hasPreviewOverlay && installGridLastPreviewQuarterTurns != quarterTurns);

        installGridLastHadPreviewOverlay = hasPreviewOverlay;
        installGridLastPreview = activeInstallPreview;
        installGridLastPreviewAnchorCoordinate = hasPreviewOverlay ? anchorCoordinate : Vector2Int.zero;
        installGridLastPreviewQuarterTurns = quarterTurns;
        return changed;
    }

    private bool TryGetInstallGridEffectiveBounds(out Vector2Int minCoordinate, out Vector2Int maxCoordinate)
    {
        minCoordinate = Vector2Int.zero;
        maxCoordinate = Vector2Int.zero;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || !terrain.TryGetLoadedBlockBounds(out Vector2Int loadedMin, out Vector2Int loadedMax))
        {
            return false;
        }

        minCoordinate = loadedMin;
        maxCoordinate = loadedMax;
        if (!TryGetInstallGridViewportBounds(terrain, out Vector2Int viewportMin, out Vector2Int viewportMax))
        {
            ClampInstallGridEffectiveBounds(
                loadedMin,
                loadedMax,
                ResolveInstallGridFocusCoordinate(minCoordinate, maxCoordinate, true),
                ref minCoordinate,
                ref maxCoordinate);
            return true;
        }

        minCoordinate = new Vector2Int(
            Mathf.Max(loadedMin.x, viewportMin.x),
            Mathf.Max(loadedMin.y, viewportMin.y));
        maxCoordinate = new Vector2Int(
            Mathf.Min(loadedMax.x, viewportMax.x),
            Mathf.Min(loadedMax.y, viewportMax.y));
        if (minCoordinate.x > maxCoordinate.x || minCoordinate.y > maxCoordinate.y)
        {
            return false;
        }

        ClampInstallGridEffectiveBounds(
            loadedMin,
            loadedMax,
            ResolveInstallGridFocusCoordinate(minCoordinate, maxCoordinate, false),
            ref minCoordinate,
            ref maxCoordinate);
        return true;
    }

    private void ClampInstallGridEffectiveBounds(
        Vector2Int loadedMin,
        Vector2Int loadedMax,
        Vector2Int focusCoordinate,
        ref Vector2Int minCoordinate,
        ref Vector2Int maxCoordinate)
    {
        if (minCoordinate.x > maxCoordinate.x || minCoordinate.y > maxCoordinate.y)
        {
            return;
        }

        ClampInstallGridAxis(
            minCoordinate.x,
            maxCoordinate.x,
            focusCoordinate.x,
            out int clampedMinX,
            out int clampedMaxX);
        ClampInstallGridAxis(
            minCoordinate.y,
            maxCoordinate.y,
            focusCoordinate.y,
            out int clampedMinY,
            out int clampedMaxY);

        minCoordinate = new Vector2Int(
            Mathf.Max(loadedMin.x, clampedMinX),
            Mathf.Max(loadedMin.y, clampedMinY));
        maxCoordinate = new Vector2Int(
            Mathf.Min(loadedMax.x, clampedMaxX),
            Mathf.Min(loadedMax.y, clampedMaxY));
    }

    private Vector2Int ResolveInstallGridFocusCoordinate(
        Vector2Int minCoordinate,
        Vector2Int maxCoordinate,
        bool allowPreviewFocus)
    {
        if (allowPreviewFocus
            && activeInstallPreview != null
            && TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
        {
            return anchorCoordinate;
        }

        if (allowPreviewFocus && selectedEditableInstallation != null)
        {
            return selectedEditableAnchorCoordinate;
        }

        return new Vector2Int(
            (minCoordinate.x + maxCoordinate.x) / 2,
            (minCoordinate.y + maxCoordinate.y) / 2);
    }

    private static void ClampInstallGridAxis(
        int currentMin,
        int currentMax,
        int focus,
        out int clampedMin,
        out int clampedMax)
    {
        int size = currentMax - currentMin + 1;
        if (size <= InstallGridMaxVisibleCellsPerAxis)
        {
            clampedMin = currentMin;
            clampedMax = currentMax;
            return;
        }

        int clampedSize = Mathf.Min(size, InstallGridMaxVisibleCellsPerAxis);
        int clampedFocus = Mathf.Clamp(focus, currentMin, currentMax);
        clampedMin = clampedFocus - clampedSize / 2;
        clampedMax = clampedMin + clampedSize - 1;
        if (clampedMin < currentMin)
        {
            clampedMax += currentMin - clampedMin;
            clampedMin = currentMin;
        }

        if (clampedMax > currentMax)
        {
            clampedMin -= clampedMax - currentMax;
            clampedMax = currentMax;
        }
    }

    private bool TryGetInstallGridViewportBounds(
        TerrainGenerator terrain,
        out Vector2Int minCoordinate,
        out Vector2Int maxCoordinate)
    {
        minCoordinate = Vector2Int.zero;
        maxCoordinate = Vector2Int.zero;
        Camera targetCamera = ResolveInstallPreviewCamera();
        if (targetCamera == null || terrain == null)
        {
            return false;
        }

        Plane groundPlane = new Plane(Vector3.up, new Vector3(0f, terrain.transform.position.y, 0f));
        float minX = float.PositiveInfinity;
        float maxX = float.NegativeInfinity;
        float minZ = float.PositiveInfinity;
        float maxZ = float.NegativeInfinity;
        int hitCount = 0;

        for (int y = 0; y <= 1; y++)
        {
            for (int x = 0; x <= 1; x++)
            {
                Ray ray = targetCamera.ViewportPointToRay(new Vector3(x, y, 0f));
                if (!groundPlane.Raycast(ray, out float enter))
                {
                    continue;
                }

                Vector3 point = ray.GetPoint(enter);
                minX = Mathf.Min(minX, point.x);
                maxX = Mathf.Max(maxX, point.x);
                minZ = Mathf.Min(minZ, point.z);
                maxZ = Mathf.Max(maxZ, point.z);
                hitCount++;
            }
        }

        if (hitCount <= 0)
        {
            return false;
        }

        minCoordinate = new Vector2Int(
            Mathf.FloorToInt(minX - 1f) - InstallGridViewportPaddingCells,
            Mathf.FloorToInt(minZ - 1f) - InstallGridViewportPaddingCells);
        maxCoordinate = new Vector2Int(
            Mathf.CeilToInt(maxX + 1f) + InstallGridViewportPaddingCells,
            Mathf.CeilToInt(maxZ + 1f) + InstallGridViewportPaddingCells);
        return true;
    }

    private void EnsureInstallGridResources()
    {
        if (installGridObject == null)
        {
            installGridObject = new GameObject("InstallationGridOverlay");
            installGridObject.hideFlags = HideFlags.DontSave;
            installGridObject.transform.SetPositionAndRotation(Vector3.zero, Quaternion.identity);
            installGridMeshFilter = installGridObject.AddComponent<MeshFilter>();
            installGridMeshRenderer = installGridObject.AddComponent<MeshRenderer>();
        }

        if (installGridPreviewObject == null)
        {
            installGridPreviewObject = new GameObject("InstallationGridPreviewOverlay");
            installGridPreviewObject.hideFlags = HideFlags.DontSave;
            installGridPreviewObject.transform.SetParent(installGridObject.transform, false);
            installGridPreviewObject.transform.localPosition = Vector3.zero;
            installGridPreviewObject.transform.localRotation = Quaternion.identity;
            installGridPreviewMeshFilter = installGridPreviewObject.AddComponent<MeshFilter>();
            installGridPreviewMeshRenderer = installGridPreviewObject.AddComponent<MeshRenderer>();
        }
        else if (installGridObject != null && installGridPreviewObject.transform.parent != installGridObject.transform)
        {
            installGridPreviewObject.transform.SetParent(installGridObject.transform, false);
        }

        if (installGridMesh == null)
        {
            installGridMesh = new Mesh
            {
                name = "InstallationGridOverlayMesh",
                hideFlags = HideFlags.DontSave
            };
            installGridMesh.MarkDynamic();
        }

        if (installGridPreviewMesh == null)
        {
            installGridPreviewMesh = new Mesh
            {
                name = "InstallationGridPreviewOverlayMesh",
                hideFlags = HideFlags.DontSave
            };
            installGridPreviewMesh.MarkDynamic();
        }

        if (installGridMeshFilter != null && installGridMeshFilter.sharedMesh != installGridMesh)
        {
            installGridMeshFilter.sharedMesh = installGridMesh;
        }

        if (installGridPreviewMeshFilter != null && installGridPreviewMeshFilter.sharedMesh != installGridPreviewMesh)
        {
            installGridPreviewMeshFilter.sharedMesh = installGridPreviewMesh;
        }

        if (installGridMaterial == null)
        {
            Shader shader = Shader.Find(InstallGridOverlayShaderName);
            if (shader == null)
            {
                shader = Shader.Find("Sprites/Default");
            }
            if (shader == null)
            {
                shader = Shader.Find("Unlit/Color");
            }
            if (shader == null)
            {
                shader = Shader.Find("Universal Render Pipeline/Unlit");
            }

            if (shader != null)
            {
                installGridMaterial = new Material(shader)
                {
                    name = "InstallationGridOverlayMaterial",
                    hideFlags = HideFlags.DontSave
                };
            }
        }

        if (installGridMaterial != null)
        {
            ApplyGridMaterialColor(installGridMaterial);
        }

        if (installGridMeshRenderer != null)
        {
            installGridMeshRenderer.sharedMaterial = installGridMaterial;
            installGridMeshRenderer.sortingOrder = 5000;
            installGridMeshRenderer.shadowCastingMode = ShadowCastingMode.Off;
            installGridMeshRenderer.receiveShadows = false;
            installGridMeshRenderer.lightProbeUsage = LightProbeUsage.Off;
            installGridMeshRenderer.reflectionProbeUsage = ReflectionProbeUsage.Off;
        }

        if (installGridPreviewMeshRenderer != null)
        {
            installGridPreviewMeshRenderer.sharedMaterial = installGridMaterial;
            installGridPreviewMeshRenderer.sortingOrder = 5001;
            installGridPreviewMeshRenderer.shadowCastingMode = ShadowCastingMode.Off;
            installGridPreviewMeshRenderer.receiveShadows = false;
            installGridPreviewMeshRenderer.lightProbeUsage = LightProbeUsage.Off;
            installGridPreviewMeshRenderer.reflectionProbeUsage = ReflectionProbeUsage.Off;
        }
    }

    private void RebuildInstallGridMesh()
    {
        EnsureInstallGridResources();

        if (installGridMesh == null)
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || !TryGetInstallGridEffectiveBounds(out Vector2Int minCoordinate, out Vector2Int maxCoordinate))
        {
            installGridMesh.Clear();
            installGridBoundsInitialized = false;
            return;
        }

        installGridMinCoordinate = minCoordinate;
        installGridMaxCoordinate = maxCoordinate;
        installGridBoundsInitialized = true;

        bool showFullGrid = IsInstallGridModeActive();
        bool showConveyorDebugOnly = !showFullGrid
            && GameManager.Instance != null
            && GameManager.Instance.DebugConveyorInstallGridEnds;

        float lineY = terrain.transform.position.y + installGridVerticalOffset;
        float fillY = lineY - 0.002f;
        float conveyorDebugArrowY = lineY + ConveyorDebugArrowWorldLift;
        float minX = minCoordinate.x - 0.5f;
        float maxX = maxCoordinate.x + 0.5f;
        float minZ = minCoordinate.y - 0.5f;
        float maxZ = maxCoordinate.y + 0.5f;

        List<Vector3> vertices = installGridVertices;
        List<int> triangles = installGridTriangles;
        List<Color> colors = installGridColors;
        vertices.Clear();
        triangles.Clear();
        colors.Clear();

        if (showFullGrid && activeInstallDefinition != null && activeInstallDefinition.mapObject != null)
        {
            MapObject activeGridSource = activeInstallDefinition.mapObject;
            bool useFastBoilerGridCheck = IsBoilerSource(activeGridSource);
            bool useFastSteamGeneratorGridCheck = IsSteamGeneratorSource(activeGridSource);
            for (int z = minCoordinate.y; z <= maxCoordinate.y; z++)
            {
                for (int x = minCoordinate.x; x <= maxCoordinate.x; x++)
                {
                    Vector2Int coordinate = new Vector2Int(x, z);
                    if (!terrain.TryGetLoadedBlock(coordinate, out Block block) || block == null)
                    {
                        continue;
                    }

                    if (CanPlaceActiveDefinitionFromGridCoordinate(
                            block,
                            useFastBoilerGridCheck,
                            useFastSteamGeneratorGridCheck))
                    {
                        continue;
                    }

                    AddGridCellQuad(
                        vertices,
                        triangles,
                        colors,
                        coordinate,
                        fillY,
                        installGridBlockedFillColor);
                }
            }
        }

        if (showConveyorDebugOnly)
        {
            AddInstalledConveyorDebugEnds(vertices, triangles, colors, minCoordinate, maxCoordinate, conveyorDebugArrowY);
        }

        if (showFullGrid)
        {
            for (int x = minCoordinate.x; x <= maxCoordinate.x + 1; x++)
            {
                float lineX = x - 0.5f;
                AddGridLineQuad(
                    vertices,
                    triangles,
                    colors,
                    new Vector3(lineX, lineY, minZ),
                    new Vector3(lineX, lineY, maxZ),
                    installGridColor);
            }

            for (int z = minCoordinate.y; z <= maxCoordinate.y + 1; z++)
            {
                float lineZ = z - 0.5f;
                AddGridLineQuad(
                    vertices,
                    triangles,
                    colors,
                    new Vector3(minX, lineY, lineZ),
                    new Vector3(maxX, lineY, lineZ),
                    installGridColor);
            }
        }

        installGridMesh.Clear();
        installGridMesh.SetVertices(vertices);
        installGridMesh.SetTriangles(triangles, 0, true);
        installGridMesh.SetColors(colors);
        installGridMesh.RecalculateBounds();
    }

    private void RebuildInstallGridPreviewMesh()
    {
        EnsureInstallGridResources();

        if (installGridPreviewMesh == null)
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || !IsInstallGridModeActive())
        {
            installGridPreviewMesh.Clear();
            return;
        }

        float lineY = terrain.transform.position.y + installGridVerticalOffset + 0.001f;
        float fillY = lineY - 0.002f;
        List<Vector3> vertices = installGridVertices;
        List<int> triangles = installGridTriangles;
        List<Color> colors = installGridColors;
        vertices.Clear();
        triangles.Clear();
        colors.Clear();

        AddInstallPreviewFootprintFill(vertices, triangles, colors, fillY);
        AddInstallPreviewFootprintOutline(vertices, triangles, colors, lineY + 0.001f);

        installGridPreviewMesh.Clear();
        if (vertices.Count <= 0)
        {
            return;
        }

        installGridPreviewMesh.SetVertices(vertices);
        installGridPreviewMesh.SetTriangles(triangles, 0, true);
        installGridPreviewMesh.SetColors(colors);
        installGridPreviewMesh.RecalculateBounds();
    }

    private bool CanPlaceActiveDefinitionFromGridCoordinate(
        Block block,
        bool useFastBoilerGridCheck = false,
        bool useFastSteamGeneratorGridCheck = false)
    {
        if (block == null || activeInstallDefinition == null || activeInstallDefinition.mapObject == null)
        {
            return false;
        }

        MapObject footprintSource = activeInstallDefinition.mapObject;
        if (useFastBoilerGridCheck)
        {
            return CanPlaceBoilerFromGridCoordinateFast(block, footprintSource);
        }

        if (useFastSteamGeneratorGridCheck)
        {
            return CanPlaceSteamGeneratorFromGridCoordinateFast(block, footprintSource);
        }

        if (!IsBelt2F(footprintSource))
        {
            if (footprintSource is Pipe pipePrototype)
            {
                return CanPlacePipeFromGridCoordinate(block, pipePrototype);
            }

            if (IsBoilerSource(footprintSource) && IsExactPumpOutputCoordinateForPlacement(block.Coordinate))
            {
                return true;
            }

            if (IsWaterPumpSource(footprintSource))
            {
                int preferredQuarterTurns = activeInstallPreview != null
                    ? GetPreviewQuarterTurns(activeInstallPreview)
                    : GetPreferredInstallPreviewQuarterTurns(activeInstallDefinition, null);
                return TryResolvePlaceableInstallPreviewTarget(
                    block,
                    activeInstallPreview,
                    preferredQuarterTurns,
                    false,
                    out _,
                    out _);
            }

            if (HasMultiCellMapSize(footprintSource))
            {
                int preferredQuarterTurns = activeInstallPreview != null
                    ? GetPreviewQuarterTurns(activeInstallPreview)
                    : GetPreferredInstallPreviewQuarterTurns(activeInstallDefinition, null);
                if (CanUseSimpleRectGridInstallGridCheck(footprintSource))
                {
                    return CanPlaceSimpleRectGridFromGridCoordinateFast(
                        block,
                        footprintSource,
                        preferredQuarterTurns,
                        activeInstallPreview);
                }

                return TryResolvePlaceableInstallPreviewTarget(
                    block,
                    activeInstallPreview,
                    preferredQuarterTurns,
                    false,
                    out _,
                    out _);
            }

            return CanPlacePreviewOnTargetBlockType(block, footprintSource);
        }

        return CanPlaceBelt2FGridTargetBlock(block, footprintSource);
    }

    private bool CanUseSimpleRectGridInstallGridCheck(MapObject footprintSource)
    {
        if (footprintSource == null
            || IsBelt2F(footprintSource)
            || IsWaterPumpSource(footprintSource)
            || IsBoilerSource(footprintSource)
            || IsSteamGeneratorSource(footprintSource)
            || footprintSource is Pipe
            || footprintSource is Pump
            || footprintSource is Wall)
        {
            return false;
        }

        if (footprintSource is InstallationObject installationObject && installationObject.CanStoreFluid)
        {
            return false;
        }

        return TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
               && inputOutputModule.LayoutType == InputOutputModule.SlotLayoutType.RectGrid
               && inputOutputModule.RectGridPlacements != null
               && inputOutputModule.RectGridPlacements.Count > 0;
    }

    private bool CanPlaceSimpleRectGridFromGridCoordinateFast(
        Block clickedBlock,
        MapObject footprintSource,
        int preferredQuarterTurns,
        MapObject previewToIgnore)
    {
        if (clickedBlock == null
            || footprintSource == null
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        int candidateCount = UsesTwoStateInstallPreviewRotation(previewToIgnore)
            ? 2
            : GetPlacementRotationCandidateCount(footprintSource);
        int baseQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                baseQuarterTurns + offset);
            for (int i = 0; i < placements.Count; i++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[i];
                if (placement.blockType == InputOutputModule.RectGridBlockType.None
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (CanPlaceSimpleRectGridAtAnchorFast(
                        terrain,
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore,
                        placements,
                        rectGridWidth,
                        rectGridHeight,
                        objectAnchorCell))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryResolveSimpleRectGridInstallPreviewTargetFast(
        Block clickedBlock,
        MapObject footprintSource,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool preserveRotation,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || footprintSource == null
            || !CanUseSimpleRectGridInstallGridCheck(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        int candidateCount = preserveRotation
            ? 1
            : UsesTwoStateInstallPreviewRotation(previewToIgnore)
                ? 2
                : GetPlacementRotationCandidateCount(footprintSource);
        int baseQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                baseQuarterTurns + offset);
            for (int i = 0; i < placements.Count; i++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[i];
                if (placement.blockType == InputOutputModule.RectGridBlockType.None
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || !CanPlaceSimpleRectGridAtAnchorFast(
                        terrain,
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore,
                        placements,
                        rectGridWidth,
                        rectGridHeight,
                        objectAnchorCell))
                {
                    continue;
                }

                anchorBlock = candidateAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool CanPlaceSimpleRectGridAtAnchorFast(
        TerrainGenerator terrain,
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore,
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements,
        int rectGridWidth,
        int rectGridHeight,
        Vector2Int objectAnchorCell)
    {
        if (terrain == null || footprintSource == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        if (PlacementHasNormalInputOutputAreaPipeOverlap(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore))
        {
            return false;
        }

        bool checkedAnyPlacement = false;
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (placement.blockType == InputOutputModule.RectGridBlockType.None
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight)
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int coordinate = anchorCoordinate + RotateFootprintOffset(localOffset, quarterTurns);
            if (!terrain.TryGetLoadedBlock(coordinate, out Block footprintBlock)
                || footprintBlock == null)
            {
                return false;
            }

            if (!CanPlacePreviewOnTargetBlockType(
                    footprintBlock,
                    footprintSource,
                    placement.blockType,
                    anchorCoordinate,
                    quarterTurns,
                    previewToIgnore))
            {
                return false;
            }

            if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject existingPreview)
                && existingPreview != null
                && existingPreview != previewToIgnore
                && !CanOverlapCompatibleInstallPreview(
                    coordinate,
                    footprintSource,
                    placement.blockType,
                    anchorCoordinate,
                    quarterTurns,
                    existingPreview))
            {
                return false;
            }

            checkedAnyPlacement = true;
        }

        return checkedAnyPlacement;
    }

    private bool CanPlaceBoilerFromGridCoordinateFast(Block block, MapObject footprintSource)
    {
        if (block == null || !TryResolveInstallationObject(footprintSource, out InstallationObject installationObject))
        {
            return false;
        }

        InstallationMapFilter allowedFilter = ResolvePlacementMapFilter(footprintSource, installationObject);
        if (!CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block);

        return occupyingObject == null
               || occupyingObject is Pump
               || IsFluidStoragePlacementObject(occupyingObject);
    }

    private bool CanPlaceSteamGeneratorFromGridCoordinateFast(Block block, MapObject footprintSource)
    {
        if (block == null || !TryResolveInstallationObject(footprintSource, out InstallationObject installationObject))
        {
            return false;
        }

        InstallationMapFilter allowedFilter = ResolvePlacementMapFilter(footprintSource, installationObject);
        if (!CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block);
        if (occupyingObject == null
            || occupyingObject is BoxObject
            || IsResourceAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        return occupyingObject is Pipe
               || IsBoilerSource(occupyingObject)
               || IsSteamGeneratorSource(occupyingObject);
    }

    private bool CanPlacePipeFromGridCoordinate(Block block, Pipe pipePrototype)
    {
        if (block == null || pipePrototype == null)
        {
            return false;
        }

        InstallationMapFilter allowedFilter = ResolvePlacementMapFilter(pipePrototype, pipePrototype);
        if (!CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        if (CoordinateHasBoilerEnergyInputBlockForPlacement(block.Coordinate, null))
        {
            return false;
        }

        bool isInputOutputAreaBlock =
            InputOutputModuleEnergyAreaController.CoordinateIsEnergyArea(block.Coordinate)
            || InputOutputModuleItemAreaController.CoordinateIsItemArea(block.Coordinate)
            || InputOutputModuleOutputAreaController.CoordinateIsOutputArea(block.Coordinate)
            || InputOutputModule.CoordinateIsRuntimeInputOutputAreaBlock(block.Coordinate);
        bool isRuntimePipeAreaBlock = InputOutputModule.CoordinateAllowsRuntimePipeBlock(block.Coordinate);
        if (isInputOutputAreaBlock && !isRuntimePipeAreaBlock)
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block);

        if (IsResourceAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (IsRailloadAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (CanPlacePassthroughOnBelt2FBridgeCenter(
                block,
                pipePrototype,
                occupyingObject,
                0))
        {
            return true;
        }

        return occupyingObject == null;
    }

    private void AddInstallPreviewFootprintFill(List<Vector3> vertices, List<int> triangles, List<Color> colors, float fillY)
    {
        CleanupInstallPreviewReferences();

        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null
                || preview != activeInstallPreview
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
            {
                continue;
            }

            int quarterTurns = GetPreviewAreaQuarterTurns(preview);
            bool isBlockedPreview = false;
            if (ResolveInstallPreviewTerrain() != null
                && ResolveInstallPreviewTerrain().TryGetLoadedBlock(anchorCoordinate, out Block anchorBlock)
                && anchorBlock != null)
            {
                isBlockedPreview = !CanPlacePreviewOnBlock(anchorBlock, preview, quarterTurns);
            }

            Color previewFillColor = isBlockedPreview
                ? installGridBlockedFillColor
                : GetInstallPreviewFootprintFillColor(preview);
            List<Vector2Int> occupiedCoordinates = GetInstallPreviewAreaDisplayCoordinates(
                preview,
                anchorCoordinate,
                quarterTurns);
            for (int coordinateIndex = 0; coordinateIndex < occupiedCoordinates.Count; coordinateIndex++)
            {
                Vector2Int coordinate = occupiedCoordinates[coordinateIndex];
                AddGridCellQuad(
                    vertices,
                    triangles,
                    colors,
                    coordinate,
                    fillY,
                    previewFillColor);
            }
        }
    }

    private Color GetInstallPreviewFootprintFillColor(MapObject preview)
    {
        Color color = ResolveInstallPreviewTint(preview);
        color.a = Mathf.Min(color.a, InstallPreviewFootprintFillAlpha);
        return color;
    }

    private void AddInstallPreviewFootprintOutline(List<Vector3> vertices, List<int> triangles, List<Color> colors, float lineY)
    {
        CleanupInstallPreviewReferences();

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null
                || preview != activeInstallPreview
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
            {
                continue;
            }

            int quarterTurns = GetPreviewAreaQuarterTurns(preview);
            bool isBlockedPreview = false;
            if (terrain != null
                && terrain.TryGetLoadedBlock(anchorCoordinate, out Block anchorBlock)
                && anchorBlock != null)
            {
                isBlockedPreview = !CanPlacePreviewOnBlock(anchorBlock, preview, quarterTurns);
            }

            Color previewLineColor = isBlockedPreview ? installGridBlockedLineColor : installGridColor;
            List<Vector2Int> occupiedCoordinates = GetInstallPreviewAreaDisplayCoordinates(
                preview,
                anchorCoordinate,
                quarterTurns);
            for (int coordinateIndex = 0; coordinateIndex < occupiedCoordinates.Count; coordinateIndex++)
            {
                Vector2Int coordinate = occupiedCoordinates[coordinateIndex];
                AddGridCellOutline(
                    vertices,
                    triangles,
                    colors,
                    coordinate,
                    lineY,
                    previewLineColor);
            }
        }
    }

    private void AddGridCellOutline(List<Vector3> vertices, List<int> triangles, List<Color> colors, Vector2Int coordinate, float y, Color color)
    {
        AddGridEdgeLine(vertices, triangles, colors, coordinate, Vector2Int.up, y, color);
        AddGridEdgeLine(vertices, triangles, colors, coordinate, Vector2Int.right, y, color);
        AddGridEdgeLine(vertices, triangles, colors, coordinate, Vector2Int.down, y, color);
        AddGridEdgeLine(vertices, triangles, colors, coordinate, Vector2Int.left, y, color);
    }

    private void AddInstalledConveyorDebugEnds(List<Vector3> vertices, List<int> triangles, List<Color> colors, Vector2Int minCoordinate, Vector2Int maxCoordinate, float lineY)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return;
        }

        HashSet<Vector2Int> drawnAnchors = new HashSet<Vector2Int>();
        for (int z = minCoordinate.y; z <= maxCoordinate.y; z++)
        {
            for (int x = minCoordinate.x; x <= maxCoordinate.x; x++)
            {
                Vector2Int coordinate = new Vector2Int(x, z);
                if (!terrain.TryGetLoadedBlock(coordinate, out Block block)
                    || block == null
                    || !(block.MapObject is ConveyorBelt conveyor)
                    || conveyor == null
                    || !conveyor.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out _)
                    || !drawnAnchors.Add(anchorCoordinate))
                {
                    continue;
                }

                Quaternion rotation = conveyor.transform.rotation;
                if (!conveyor.TryGetOutputDirection(rotation, out Vector2Int outputDirection))
                {
                    continue;
                }

                if (!conveyor.TryGetInputDirection(rotation, out Vector2Int inputDirection))
                {
                    inputDirection = -outputDirection;
                }

                AddConveyorFlowArrow(vertices, triangles, colors, anchorCoordinate, inputDirection, outputDirection, lineY + 0.001f, installGridConveyorEndDebugColor);
            }
        }
    }

    private void AddConveyorFlowArrow(
        List<Vector3> vertices,
        List<int> triangles,
        List<Color> colors,
        Vector2Int anchorCoordinate,
        Vector2Int inputDirection,
        Vector2Int outputDirection,
        float y,
        Color color)
    {
        if (inputDirection == Vector2Int.zero || outputDirection == Vector2Int.zero)
        {
            return;
        }

        Vector3 center = new Vector3(anchorCoordinate.x, y, anchorCoordinate.y);
        Vector3 inputPoint = center + DirectionToWorld(inputDirection) * installGridConveyorArrowInset;
        Vector3 outputPoint = center + DirectionToWorld(outputDirection) * installGridConveyorArrowInset;

        if (inputDirection == -outputDirection)
        {
            AddGridLineQuad(vertices, triangles, colors, inputPoint, outputPoint, color);
            AddArrowHead(vertices, triangles, colors, Vector3.Lerp(inputPoint, outputPoint, 0.45f), (outputPoint - inputPoint).normalized, color);
            AddArrowHead(vertices, triangles, colors, Vector3.Lerp(inputPoint, outputPoint, 0.75f), (outputPoint - inputPoint).normalized, color);
            return;
        }

        AddGridLineQuad(vertices, triangles, colors, inputPoint, center, color);
        AddGridLineQuad(vertices, triangles, colors, center, outputPoint, color);
        AddArrowHead(vertices, triangles, colors, Vector3.Lerp(inputPoint, center, 0.68f), (center - inputPoint).normalized, color);
        AddArrowHead(vertices, triangles, colors, Vector3.Lerp(center, outputPoint, 0.68f), (outputPoint - center).normalized, color);
    }

    private void AddArrowHead(
        List<Vector3> vertices,
        List<int> triangles,
        List<Color> colors,
        Vector3 center,
        Vector3 direction,
        Color color)
    {
        if (direction.sqrMagnitude <= 0.0001f)
        {
            return;
        }

        Vector3 normalizedDirection = direction.normalized;
        Vector3 tip = center + normalizedDirection * (installGridConveyorArrowHeadLength * 0.5f);
        Vector3 baseCenter = center - normalizedDirection * (installGridConveyorArrowHeadLength * 0.5f);
        Vector3 perpendicular = Vector3.Cross(Vector3.up, normalizedDirection) * (installGridConveyorArrowHeadWidth * 0.5f);
        int startIndex = vertices.Count;

        vertices.Add(tip);
        vertices.Add(baseCenter + perpendicular);
        vertices.Add(baseCenter - perpendicular);

        colors.Add(color);
        colors.Add(color);
        colors.Add(color);

        triangles.Add(startIndex);
        triangles.Add(startIndex + 1);
        triangles.Add(startIndex + 2);
    }

    private static Vector3 DirectionToWorld(Vector2Int direction)
    {
        return new Vector3(direction.x, 0f, direction.y).normalized;
    }

    private Quaternion wasActivePreviewRotation(MapObject preview)
    {
        if (preview == null)
        {
            return Quaternion.identity;
        }

        if (preview == activeInstallPreview)
        {
            return GetInstallPreviewRotation();
        }

        int quarterTurns = GetPreviewQuarterTurns(preview);
        MapObject rotationSource = ResolveInstallPreviewRotationSource(preview);
        Quaternion previewBaseRotation = installPreviewBaseRotationsByPreview.TryGetValue(preview, out Quaternion storedBaseRotation)
            ? storedBaseRotation
            : (rotationSource != null ? rotationSource.transform.rotation : preview.transform.rotation);
        if (TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
        {
            Vector3 railReferencePosition = installPreviewRailReferenceWorldPositions.TryGetValue(
                preview,
                out Vector3 storedRailReferencePosition)
                ? storedRailReferencePosition
                : preview.transform.position;
            return ResolvePlacementObjectRotation(
                previewBaseRotation,
                rotationSource,
                anchorCoordinate,
                quarterTurns,
                railReferencePosition);
        }

        return GetPlacementObjectRotation(previewBaseRotation, rotationSource, quarterTurns);
    }

    private void AddGridEdgeLine(List<Vector3> vertices, List<int> triangles, List<Color> colors, Vector2Int coordinate, Vector2Int direction, float y, Color color)
    {
        if (direction == Vector2Int.zero)
        {
            return;
        }

        float minX = coordinate.x - 0.5f;
        float maxX = coordinate.x + 0.5f;
        float minZ = coordinate.y - 0.5f;
        float maxZ = coordinate.y + 0.5f;

        Vector3 start;
        Vector3 end;

        if (direction == Vector2Int.up)
        {
            start = new Vector3(minX, y, maxZ);
            end = new Vector3(maxX, y, maxZ);
        }
        else if (direction == Vector2Int.down)
        {
            start = new Vector3(minX, y, minZ);
            end = new Vector3(maxX, y, minZ);
        }
        else if (direction == Vector2Int.left)
        {
            start = new Vector3(minX, y, minZ);
            end = new Vector3(minX, y, maxZ);
        }
        else if (direction == Vector2Int.right)
        {
            start = new Vector3(maxX, y, minZ);
            end = new Vector3(maxX, y, maxZ);
        }
        else
        {
            return;
        }

        AddGridLineQuad(vertices, triangles, colors, start, end, color);
    }

    private void AddGridLineQuad(List<Vector3> vertices, List<int> triangles, List<Color> colors, Vector3 start, Vector3 end, Color color)
    {
        Vector3 direction = end - start;
        if (direction.sqrMagnitude <= 0.0001f)
        {
            return;
        }

        Vector3 perpendicular = Vector3.Cross(Vector3.up, direction.normalized) * (installGridLineWidth * 0.5f);
        int startIndex = vertices.Count;

        vertices.Add(start - perpendicular);
        vertices.Add(start + perpendicular);
        vertices.Add(end + perpendicular);
        vertices.Add(end - perpendicular);

        colors.Add(color);
        colors.Add(color);
        colors.Add(color);
        colors.Add(color);

        triangles.Add(startIndex);
        triangles.Add(startIndex + 1);
        triangles.Add(startIndex + 2);
        triangles.Add(startIndex);
        triangles.Add(startIndex + 2);
        triangles.Add(startIndex + 3);
    }

    private static void AddGridCellQuad(List<Vector3> vertices, List<int> triangles, List<Color> colors, Vector2Int coordinate, float y, Color color)
    {
        float minX = coordinate.x - 0.5f;
        float maxX = coordinate.x + 0.5f;
        float minZ = coordinate.y - 0.5f;
        float maxZ = coordinate.y + 0.5f;
        int startIndex = vertices.Count;

        vertices.Add(new Vector3(minX, y, minZ));
        vertices.Add(new Vector3(minX, y, maxZ));
        vertices.Add(new Vector3(maxX, y, maxZ));
        vertices.Add(new Vector3(maxX, y, minZ));

        colors.Add(color);
        colors.Add(color);
        colors.Add(color);
        colors.Add(color);

        triangles.Add(startIndex);
        triangles.Add(startIndex + 1);
        triangles.Add(startIndex + 2);
        triangles.Add(startIndex);
        triangles.Add(startIndex + 2);
        triangles.Add(startIndex + 3);
    }

    private void ApplyGridMaterialColor(Material material)
    {
        if (material == null)
        {
            return;
        }

        if (material.HasProperty(BaseColorPropertyId))
        {
            material.SetColor(BaseColorPropertyId, installGridColor);
        }

        if (material.HasProperty(ColorPropertyId))
        {
            material.SetColor(ColorPropertyId, installGridColor);
        }
    }

    private void SetInstallGridVisible(bool isVisible)
    {
        if (installGridObject == null)
        {
            if (!isVisible)
            {
                return;
            }

            EnsureInstallGridResources();
        }

        if (installGridObject != null && installGridObject.activeSelf != isVisible)
        {
            installGridObject.SetActive(isVisible);
        }

        if (installGridPreviewObject != null && installGridPreviewObject.activeSelf != isVisible)
        {
            installGridPreviewObject.SetActive(isVisible);
        }
    }

    private void ReleaseInstallGridResources()
    {
        if (Application.isPlaying)
        {
            if (installGridObject != null)
            {
                Destroy(installGridObject);
            }

            if (installGridMesh != null)
            {
                Destroy(installGridMesh);
            }

            if (installGridPreviewMesh != null)
            {
                Destroy(installGridPreviewMesh);
            }

            if (installGridMaterial != null)
            {
                Destroy(installGridMaterial);
            }
        }
        else
        {
            if (installGridObject != null)
            {
                DestroyImmediate(installGridObject);
            }

            if (installGridMesh != null)
            {
                DestroyImmediate(installGridMesh);
            }

            if (installGridPreviewMesh != null)
            {
                DestroyImmediate(installGridPreviewMesh);
            }

            if (installGridMaterial != null)
            {
                DestroyImmediate(installGridMaterial);
            }
        }

        installGridObject = null;
        installGridMeshFilter = null;
        installGridMeshRenderer = null;
        installGridMesh = null;
        installGridPreviewObject = null;
        installGridPreviewMeshFilter = null;
        installGridPreviewMeshRenderer = null;
        installGridPreviewMesh = null;
        installGridMaterial = null;
    }

    private bool TryGetBlockFromGroundPlane(Ray ray, out Block block)
    {
        block = null;

        if (!TryGetGroundPlanePoint(ray, out Vector3 worldPoint))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        Vector2Int coordinate = new Vector2Int(
            Mathf.RoundToInt(worldPoint.x),
            Mathf.RoundToInt(worldPoint.z));

        return terrain.TryGetLoadedBlock(coordinate, out block) && block != null;
    }

    private bool TryGetGroundPlanePoint(Ray ray, out Vector3 worldPoint)
    {
        worldPoint = Vector3.zero;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        Plane groundPlane = new Plane(Vector3.up, new Vector3(0f, terrain.transform.position.y, 0f));
        if (!groundPlane.Raycast(ray, out float enter))
        {
            return false;
        }

        worldPoint = ray.GetPoint(enter);
        return true;
    }

    private void UpdateInstallPreviewPointerInput()
    {
        if (Input.touchCount > 0)
        {
            Touch touch = Input.GetTouch(0);
            switch (touch.phase)
            {
                case TouchPhase.Began:
                    BeginPreviewPointerTracking(touch.position, IsPointerOverBlockingUi(touch.position));
                    break;
                case TouchPhase.Moved:
                case TouchPhase.Stationary:
                    EnsurePreviewPointerTracking(touch.position);
                    ContinuePreviewPointerTracking(touch.position);
                    break;
                case TouchPhase.Ended:
                    EndPreviewPointerTracking(touch.position, false);
                    break;
                case TouchPhase.Canceled:
                    EndPreviewPointerTracking(touch.position, true);
                    break;
            }

            return;
        }

        if (Input.GetMouseButtonDown(0))
        {
            BeginPreviewPointerTracking(Input.mousePosition, IsPointerOverBlockingUi(Input.mousePosition));
        }
        else if (Input.GetMouseButton(0))
        {
            EnsurePreviewPointerTracking(Input.mousePosition);
        }

        if (Input.GetMouseButton(0))
        {
            ContinuePreviewPointerTracking(Input.mousePosition);
        }

        if (Input.GetMouseButtonUp(0))
        {
            EndPreviewPointerTracking(Input.mousePosition, false);
        }
    }

    private void BeginPreviewPointerTracking(Vector2 pointerPosition, bool startedOverUi)
    {
        isPreviewPointerTracking = true;
        previewPointerDragged = false;
        previewPointerStartedOverUi = startedOverUi;
        previewPointerStartPosition = pointerPosition;
        previewPointerOriginPreview = null;

        if (startedOverUi)
        {
            return;
        }

        if (!TryGetPointerBlock(pointerPosition, out Block pointerBlock) || pointerBlock == null)
        {
            return;
        }

        if (!TryGetInstallPreviewAtBlock(pointerBlock, out MapObject originPreview) || originPreview == null)
        {
            return;
        }

        previewPointerOriginPreview = originPreview;
        if (originPreview != activeInstallPreview)
        {
            SelectInstallPreview(originPreview);
        }
    }

    private void EnsurePreviewPointerTracking(Vector2 pointerPosition)
    {
        if (isPreviewPointerTracking)
        {
            return;
        }

        BeginPreviewPointerTracking(pointerPosition, IsPointerOverBlockingUi(pointerPosition));
    }

    private void ContinuePreviewPointerTracking(Vector2 pointerPosition)
    {
        if (!isPreviewPointerTracking || previewPointerStartedOverUi)
        {
            return;
        }

        if (!previewPointerDragged)
        {
            float threshold = Mathf.Max(1f, installRotateTapThreshold);
            previewPointerDragged = Vector2.Distance(previewPointerStartPosition, pointerPosition) >= threshold;
        }

        if (previewPointerDragged && (IsEditingInstallation() || previewPointerOriginPreview != null))
        {
            TryHandleInstallPreviewDrag(pointerPosition);
        }
    }

    private void EndPreviewPointerTracking(Vector2 pointerPosition, bool wasCanceled)
    {
        if (!isPreviewPointerTracking)
        {
            return;
        }

        if (!wasCanceled && !previewPointerStartedOverUi)
        {
            if (IsEditingInstallation())
            {
                if (previewPointerDragged)
                {
                    TryMoveInstallPreview(pointerPosition, true);
                }
                else
                {
                    HandleInstallationEditClick(pointerPosition);
                }

                ResetPreviewPointerTracking();
                return;
            }

            if (previewPointerDragged)
            {
                if (previewPointerOriginPreview != null)
                {
                    TryHandleInstallPreviewDrag(pointerPosition);
                }
            }
            else
            {
                HandleInstallPreviewClick(pointerPosition);
            }
        }

        ResetPreviewPointerTracking();
    }

    private void TryHandleInstallPreviewDrag(Vector2 pointerPosition)
    {
        if (IsEditingInstallation())
        {
            TryMoveInstallPreview(pointerPosition, true);
            return;
        }

        if (previewPointerOriginPreview != null
            && previewPointerOriginPreview != activeInstallPreview)
        {
            SelectInstallPreview(previewPointerOriginPreview);
        }

        TryMoveInstallPreview(pointerPosition, true);
    }

    private void HandleInstallationEditClick(Vector2 pointerPosition)
    {
        if (!TryGetEditableInstallationAtPointer(pointerPosition, out InstallationObject installationObject, out Vector2Int anchorCoordinate)
            || installationObject == null)
        {
            return;
        }

        if (activeInstallationEditSession != null
            && installationObject == activeInstallationEditSession.originalInstallation)
        {
            return;
        }

        if (!TryCommitActiveInstallationEditPreview())
        {
            CancelInstallationEdit();
        }
        if (!BeginInstallationEdit(installationObject))
        {
            SelectEditableInstallation(installationObject, anchorCoordinate);
        }
    }

    private bool TryCommitActiveInstallationEditPreview()
    {
        InstallationEditSession editSession = activeInstallationEditSession;
        if (editSession == null)
        {
            return false;
        }

        CleanupInstallPreviewReferences();
        if (activeInstallPreview == null || !TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
        {
            return false;
        }

        Quaternion previewRotation = activeInstallPreview.transform.rotation;
        Vector3 previewPosition = activeInstallPreview.transform.position;
        int quarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        int conveyorVariantKind = GetInstallationVariantKind(activeInstallPreview);
        if (!CanRestoreEditedInstallationAt(
                editSession,
                anchorCoordinate,
                quarterTurns,
                conveyorVariantKind,
                activeInstallPreview))
        {
            InvalidateInstallGrid();
            return false;
        }

        activeInstallationEditSession = null;
        RestoreEditedInstallation(
            editSession,
            anchorCoordinate,
            quarterTurns,
            conveyorVariantKind,
            previewRotation,
            previewPosition);
        ClearInstallPreview();
        return true;
    }

    private void ResetPreviewPointerTracking()
    {
        isPreviewPointerTracking = false;
        previewPointerDragged = false;
        previewPointerStartedOverUi = false;
        previewPointerStartPosition = Vector2.zero;
        previewPointerOriginPreview = null;
    }

    private void RotateInstallPreviewClockwise()
    {
        if (activeInstallPreview == null)
        {
            return;
        }

        InvalidateInstallPreviewMoveCache();

        int previousQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        Block anchorBlock = null;
        bool hasAnchorBlock = TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate)
                            && ResolveInstallPreviewTerrain() != null
                            && ResolveInstallPreviewTerrain().TryGetLoadedBlock(anchorCoordinate, out anchorBlock);
        Vector2Int previousAnchorCoordinate = anchorCoordinate;
        bool shouldReanchorRotatedMultiCellPreview = false;

        if (IsActiveBelt2FPreview())
        {
            if (!TryRotateBelt2FPreviewAroundBridgeCenter(
                    hasAnchorBlock,
                    anchorCoordinate,
                    out anchorBlock,
                    out anchorCoordinate,
                    out int resolvedQuarterTurns))
            {
                return;
            }

            hasAnchorBlock = anchorBlock != null;
            installPreviewQuarterTurns = resolvedQuarterTurns;
        }
        else if (activeInstallDefinition != null && activeInstallDefinition.mapObject is ConveyorBelt conveyorBelt)
        {
            int logicalQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);

            bool useCornerVariant = installPreviewConveyorVariantMode == ConveyorPreviewVariantMode.Corner
                || (activeInstallPreview is ConveyorBelt previewConveyor && previewConveyor.IsCornerVariant);
            if (hasAnchorBlock)
            {
                if (!TryFindNextConveyorPreviewRotation(
                        conveyorBelt,
                        anchorCoordinate,
                        activeInstallPreview,
                        logicalQuarterTurns,
                        useCornerVariant,
                        out logicalQuarterTurns,
                        out ConveyorPreviewVariantMode resolvedVariantMode,
                        out MapObject resolvedVariantPrefab,
                        out int resolvedSequenceIndex))
                {
                    return;
                }

                installPreviewQuarterTurns = logicalQuarterTurns;
                installPreviewConveyorVariantMode = resolvedVariantMode;
                installPreviewConveyorRotationSequenceIndexesByPreview[activeInstallPreview] = resolvedSequenceIndex;
                if (resolvedVariantPrefab != null)
                {
                    installPreviewSourcePrefabsByPreview[activeInstallPreview] = resolvedVariantPrefab;
                }

                ApplyConveyorPreviewVariant(
                    activeInstallPreview,
                    resolvedVariantPrefab,
                    anchorCoordinate,
                    logicalQuarterTurns);
            }
            else
            {
                if (!TryFindNextConveyorPreviewRotation(
                        conveyorBelt,
                        null,
                        activeInstallPreview,
                        logicalQuarterTurns,
                        useCornerVariant,
                        out logicalQuarterTurns,
                        out ConveyorPreviewVariantMode resolvedVariantMode,
                        out MapObject resolvedVariantPrefab,
                        out int resolvedSequenceIndex))
                {
                    return;
                }

                installPreviewQuarterTurns = logicalQuarterTurns;
                installPreviewConveyorVariantMode = resolvedVariantMode;
                installPreviewConveyorRotationSequenceIndexesByPreview[activeInstallPreview] = resolvedSequenceIndex;
                if (resolvedVariantPrefab != null)
                {
                    installPreviewSourcePrefabsByPreview[activeInstallPreview] = resolvedVariantPrefab;
                }
            }
        }
        else if (TryRotateWaterPumpPreviewAtShore(
                     hasAnchorBlock,
                     anchorBlock,
                     anchorCoordinate,
                     out int waterPumpQuarterTurns))
        {
            installPreviewQuarterTurns = waterPumpQuarterTurns;
        }
        else if (TryRotateSteamGeneratorPreviewInPlaceOnStraightPipe(
                     hasAnchorBlock,
                     anchorCoordinate,
                     out _,
                     out anchorBlock,
                     out anchorCoordinate,
                     out int steamGeneratorQuarterTurns))
        {
            hasAnchorBlock = anchorBlock != null;
            installPreviewQuarterTurns = steamGeneratorQuarterTurns;
        }
        else
        {
            int nextQuarterTurns = GetNextInstallPreviewQuarterTurns(
                activeInstallPreview,
                installPreviewQuarterTurns);
            bool shouldRememberFenceDoorStandaloneQuarterTurns =
                ShouldRememberFenceDoorStandaloneQuarterTurns(
                    activeInstallPreview,
                    hasAnchorBlock,
                    anchorCoordinate);
            if (shouldRememberFenceDoorStandaloneQuarterTurns)
            {
                installPreviewFenceDoorStandaloneQuarterTurnsByPreview[activeInstallPreview] =
                    NormalizePlacementQuarterTurnsForObject(activeInstallPreview, nextQuarterTurns);
            }

            installPreviewQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                activeInstallPreview,
                nextQuarterTurns);
            shouldReanchorRotatedMultiCellPreview = hasAnchorBlock
                                                   && !IsTrainSource(ResolveInstallPreviewPlacementSource(activeInstallPreview));
        }

        if (shouldReanchorRotatedMultiCellPreview
            && hasAnchorBlock
            && ShouldKeepInstallPreviewAnchorOnRotation(activeInstallPreview, anchorCoordinate))
        {
            shouldReanchorRotatedMultiCellPreview = false;
        }

        if (shouldReanchorRotatedMultiCellPreview
            && hasAnchorBlock
            && TryResolveRotatedMultiCellInstallPreviewAnchor(
                activeInstallPreview,
                previousAnchorCoordinate,
                previousQuarterTurns,
                installPreviewQuarterTurns,
                out Block reanchoredBlock,
                out Vector2Int reanchoredCoordinate))
        {
            anchorBlock = reanchoredBlock;
            anchorCoordinate = reanchoredCoordinate;
        }

        if (hasAnchorBlock
            && BoilerPlacementRotationCandidateIsBlockedForActivePreview(
                anchorBlock,
                anchorCoordinate,
                installPreviewQuarterTurns)
            && !TryFindBoilerRotationSkippingPlacementConflicts(
                activeInstallPreview,
                previousAnchorCoordinate,
                previousQuarterTurns,
                installPreviewQuarterTurns,
                out anchorBlock,
                out anchorCoordinate,
                out installPreviewQuarterTurns))
        {
            installPreviewQuarterTurns = previousQuarterTurns;
            return;
        }

        installPreviewQuarterTurnsByPreview[activeInstallPreview] = installPreviewQuarterTurns;
        if (hasAnchorBlock)
        {
            installPreviewAnchorCoordinates[activeInstallPreview] = anchorCoordinate;
        }

        if (ShouldRememberFenceDoorStandaloneQuarterTurns(activeInstallPreview, hasAnchorBlock, anchorCoordinate))
        {
            installPreviewFenceDoorStandaloneQuarterTurnsByPreview[activeInstallPreview] =
                NormalizePlacementQuarterTurnsForObject(activeInstallPreview, installPreviewQuarterTurns);
        }

        if (!(activeInstallDefinition != null && activeInstallDefinition.mapObject is ConveyorBelt))
        {
            RefreshActiveConveyorPreviewVariant();
        }
        RefreshActiveFencePreviewVariant(true);
        RefreshActivePipePreviewVariant();
        activeInstallPreview.transform.rotation = GetInstallPreviewRotation();
        if (activeInstallPreview is InstallationObject rotatedInstallationPreview)
        {
            rotatedInstallationPreview.RefreshInstalledDirectionFromCurrentTransform();
        }

        if (hasAnchorBlock)
        {
            MapObject placementSource = ResolveInstallPreviewPlacementSource(activeInstallPreview);
            if (!IsTrainSource(placementSource))
            {
                activeInstallPreview.transform.position = ResolvePlacementWorldPosition(
                    anchorBlock,
                    placementSource,
                    installPreviewQuarterTurns,
                    activeInstallPreview.transform.position);
            }
        }

        if (!hasAnchorBlock || previousAnchorCoordinate != anchorCoordinate)
        {
            RefreshPreviewRangeVisualsIfNeeded(activeInstallPreview);
        }
        RefreshUtilityPolePreviewWires();
        RefreshInstallPreviewAreaMarkers(activeInstallPreview);
        RememberBlueprintRotationForPreview(activeInstallDefinition, activeInstallPreview, installPreviewQuarterTurns);
        RefreshFencePreviewVariantsAroundActivePreview(
            hasAnchorBlock ? anchorCoordinate : (Vector2Int?)null,
            true);
        RefreshPipePreviewVariantsAroundActivePreview(
            hasAnchorBlock ? anchorCoordinate : (Vector2Int?)null);
        InvalidateInstallGridPreview();
    }

    private bool TryRotateWaterPumpPreviewAtShore(
        bool hasAnchorBlock,
        Block anchorBlock,
        Vector2Int anchorCoordinate,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        if (!hasAnchorBlock
            || anchorBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(activeInstallPreview, out MapObject footprintSource)
            || !IsWaterPumpSource(footprintSource))
        {
            return false;
        }

        int preferredQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            resolvedQuarterTurns + 1);
        if (TryResolveWaterPumpOutwardQuarterTurns(
                anchorCoordinate,
                footprintSource,
                preferredQuarterTurns,
                out int waterPumpQuarterTurns)
            && CanPlacePreviewOnBlock(anchorBlock, activeInstallPreview, waterPumpQuarterTurns))
        {
            resolvedQuarterTurns = waterPumpQuarterTurns;
        }

        return true;
    }

    private bool BoilerPlacementRotationCandidateIsBlockedForActivePreview(
        Block anchorBlock,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        return TryResolveInstallPreviewFootprintSourceForPlacement(
                   activeInstallPreview,
                   out MapObject footprintSource)
               && IsBoilerSource(footprintSource)
               && !CanUseBoilerPlacementRotationCandidate(
                   anchorBlock,
                   anchorCoordinate,
                   activeInstallPreview,
                   footprintSource,
                   quarterTurns);
    }

    private bool CanUseBoilerPlacementRotationCandidate(
        Block anchorBlock,
        Vector2Int anchorCoordinate,
        MapObject preview,
        MapObject footprintSource,
        int quarterTurns)
    {
        return anchorBlock != null
               && !PlacementHasBoilerPlacementRotationConflict(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns,
                   preview)
               && CanPlacePreviewOnBlock(anchorBlock, preview, quarterTurns);
    }

    private bool PlacementHasBoilerPlacementRotationConflict(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject preview)
    {
        return PlacementHasBoilerEnergyInputPipeConflict(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns,
                   preview)
               || PlacementHasBoilerPumpOutputDirectionMismatch(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns);
    }

    private bool TryFindBoilerRotationSkippingPlacementConflicts(
        MapObject preview,
        Vector2Int previousAnchorCoordinate,
        int previousQuarterTurns,
        int startQuarterTurns,
        out Block resolvedAnchorBlock,
        out Vector2Int resolvedAnchorCoordinate,
        out int resolvedQuarterTurns)
    {
        resolvedAnchorBlock = null;
        resolvedAnchorCoordinate = previousAnchorCoordinate;
        resolvedQuarterTurns = startQuarterTurns;

        if (!TryResolveInstallPreviewFootprintSourceForPlacement(preview, out MapObject footprintSource)
            || !IsBoilerSource(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        bool keepPumpOutputAnchor = IsExactPumpOutputCoordinateForPlacement(previousAnchorCoordinate);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                preview,
                startQuarterTurns + offset);
            Vector2Int candidateAnchorCoordinate = previousAnchorCoordinate;
            Block candidateAnchorBlock = null;

            if (!keepPumpOutputAnchor
                && TryResolveRotatedMultiCellInstallPreviewAnchor(
                    preview,
                    previousAnchorCoordinate,
                    previousQuarterTurns,
                    candidateQuarterTurns,
                    out Block reanchoredBlock,
                    out Vector2Int reanchoredCoordinate))
            {
                candidateAnchorBlock = reanchoredBlock;
                candidateAnchorCoordinate = reanchoredCoordinate;
            }
            else if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out candidateAnchorBlock)
                     || candidateAnchorBlock == null)
            {
                continue;
            }

            if (!CanUseBoilerPlacementRotationCandidate(
                    candidateAnchorBlock,
                    candidateAnchorCoordinate,
                    preview,
                    footprintSource,
                    candidateQuarterTurns))
            {
                continue;
            }

            resolvedAnchorBlock = candidateAnchorBlock;
            resolvedAnchorCoordinate = candidateAnchorCoordinate;
            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool ShouldKeepInstallPreviewAnchorOnRotation(MapObject preview, Vector2Int anchorCoordinate)
    {
        if (!TryResolveInstallPreviewFootprintSourceForPlacement(preview, out MapObject footprintSource))
        {
            return false;
        }

        // Vehicles and some rect-grid objects should rotate in place instead of
        // preserving footprint centroid by moving the anchor between grid cells.
        return IsTrainSource(footprintSource)
               || IsSteamGeneratorSource(footprintSource)
               || (IsBoilerSource(footprintSource)
                   && IsExactPumpOutputCoordinateForPlacement(anchorCoordinate));
    }

    private bool TryResolveRotatedMultiCellInstallPreviewAnchor(
        MapObject preview,
        Vector2Int currentAnchorCoordinate,
        int previousQuarterTurns,
        int targetQuarterTurns,
        out Block resolvedAnchorBlock,
        out Vector2Int resolvedAnchorCoordinate)
    {
        resolvedAnchorBlock = null;
        resolvedAnchorCoordinate = currentAnchorCoordinate;

        MapObject footprintSource = ResolveInstallPreviewPlacementSource(preview);
        if (footprintSource == null
            || !HasMultiCellPlacementFootprint(footprintSource)
            || IsBelt2F(footprintSource))
        {
            return false;
        }

        int normalizedPreviousQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            previousQuarterTurns);
        int normalizedTargetQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            targetQuarterTurns);
        if (normalizedPreviousQuarterTurns == normalizedTargetQuarterTurns)
        {
            return false;
        }

        if (RectGridObjectCoordinatesMatchAtSameAnchor(
                footprintSource,
                currentAnchorCoordinate,
                normalizedPreviousQuarterTurns,
                normalizedTargetQuarterTurns))
        {
            return false;
        }

        List<Vector2Int> previousOffsets = GetFootprintLocalOffsets(
            footprintSource,
            normalizedPreviousQuarterTurns);
        List<Vector2Int> targetOffsets = GetFootprintLocalOffsets(
            footprintSource,
            normalizedTargetQuarterTurns);
        if (previousOffsets.Count <= 1 || targetOffsets.Count <= 1)
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        Vector2 previousAverageOffset = GetAverageLocalOffset(previousOffsets);
        Vector2 targetAverageOffset = GetAverageLocalOffset(targetOffsets);
        Vector2 desiredCenter = new Vector2(currentAnchorCoordinate.x, currentAnchorCoordinate.y) + previousAverageOffset;
        Vector2 idealAnchor = desiredCenter - targetAverageOffset;

        HashSet<Vector2Int> previousCoordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < previousOffsets.Count; i++)
        {
            previousCoordinates.Add(currentAnchorCoordinate + previousOffsets[i]);
        }

        List<Vector2Int> candidates = new List<Vector2Int>();
        HashSet<Vector2Int> candidateSet = new HashSet<Vector2Int>();
        void AddCandidate(Vector2Int candidate)
        {
            if (candidateSet.Add(candidate))
            {
                candidates.Add(candidate);
            }
        }

        int roundedX = RoundGridCoordinate(idealAnchor.x);
        int roundedY = RoundGridCoordinate(idealAnchor.y);
        AddCandidate(new Vector2Int(roundedX, roundedY));

        int floorX = Mathf.FloorToInt(idealAnchor.x);
        int ceilX = Mathf.CeilToInt(idealAnchor.x);
        int floorY = Mathf.FloorToInt(idealAnchor.y);
        int ceilY = Mathf.CeilToInt(idealAnchor.y);
        AddCandidate(new Vector2Int(floorX, floorY));
        AddCandidate(new Vector2Int(ceilX, floorY));
        AddCandidate(new Vector2Int(floorX, ceilY));
        AddCandidate(new Vector2Int(ceilX, ceilY));
        AddCandidate(currentAnchorCoordinate);

        for (int previousIndex = 0; previousIndex < previousOffsets.Count; previousIndex++)
        {
            Vector2Int previousCoordinate = currentAnchorCoordinate + previousOffsets[previousIndex];
            for (int targetIndex = 0; targetIndex < targetOffsets.Count; targetIndex++)
            {
                AddCandidate(previousCoordinate - targetOffsets[targetIndex]);
            }
        }

        Vector2Int bestCoordinate = currentAnchorCoordinate;
        Block bestBlock = null;
        float bestCenterDistance = float.MaxValue;
        int bestOverlap = -1;
        for (int i = 0; i < candidates.Count; i++)
        {
            Vector2Int candidateCoordinate = candidates[i];
            if (!terrain.TryGetLoadedBlock(candidateCoordinate, out Block candidateBlock)
                || candidateBlock == null
                || !CanPlacePreviewOnBlock(candidateBlock, preview, normalizedTargetQuarterTurns))
            {
                continue;
            }

            Vector2 candidateCenter =
                new Vector2(candidateCoordinate.x, candidateCoordinate.y) + targetAverageOffset;
            float centerDistance = (candidateCenter - desiredCenter).sqrMagnitude;
            int overlap = CountRotatedFootprintOverlap(
                candidateCoordinate,
                targetOffsets,
                previousCoordinates);
            if (centerDistance > bestCenterDistance + 0.0001f
                || (Mathf.Abs(centerDistance - bestCenterDistance) <= 0.0001f
                    && overlap <= bestOverlap))
            {
                continue;
            }

            bestCenterDistance = centerDistance;
            bestOverlap = overlap;
            bestCoordinate = candidateCoordinate;
            bestBlock = candidateBlock;
        }

        if (bestBlock == null || bestCoordinate == currentAnchorCoordinate)
        {
            return false;
        }

        resolvedAnchorBlock = bestBlock;
        resolvedAnchorCoordinate = bestCoordinate;
        return true;
    }

    private bool RectGridObjectCoordinatesMatchAtSameAnchor(
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        int previousQuarterTurns,
        int targetQuarterTurns)
    {
        return TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
               && inputOutputModule.RectGridPlacements != null
               && TryGetRectGridFootprintSettings(
                   footprintSource,
                   out _,
                   out _,
                   out Vector2Int objectAnchorCell)
               && RectGridObjectCoordinatesMatch(
                   inputOutputModule.RectGridPlacements,
                   objectAnchorCell,
                   anchorCoordinate,
                   previousQuarterTurns,
                   anchorCoordinate,
                   targetQuarterTurns);
    }

    private static Vector2 GetAverageLocalOffset(IReadOnlyList<Vector2Int> offsets)
    {
        if (offsets == null || offsets.Count <= 0)
        {
            return Vector2.zero;
        }

        Vector2 averageOffset = Vector2.zero;
        for (int i = 0; i < offsets.Count; i++)
        {
            averageOffset += offsets[i];
        }

        return averageOffset / offsets.Count;
    }

    private static int CountRotatedFootprintOverlap(
        Vector2Int anchorCoordinate,
        IReadOnlyList<Vector2Int> localOffsets,
        ISet<Vector2Int> previousCoordinates)
    {
        if (localOffsets == null || previousCoordinates == null || previousCoordinates.Count <= 0)
        {
            return 0;
        }

        int overlap = 0;
        for (int i = 0; i < localOffsets.Count; i++)
        {
            if (previousCoordinates.Contains(anchorCoordinate + localOffsets[i]))
            {
                overlap++;
            }
        }

        return overlap;
    }

    private static int RoundGridCoordinate(float value)
    {
        return Mathf.FloorToInt(value + 0.5f);
    }

    private bool TryRotateSteamGeneratorPreviewInPlaceOnStraightPipe(
        bool hasAnchorBlock,
        Vector2Int anchorCoordinate,
        out bool handled,
        out Block resolvedAnchorBlock,
        out Vector2Int resolvedAnchorCoordinate,
        out int resolvedQuarterTurns)
    {
        handled = false;
        resolvedAnchorBlock = null;
        resolvedAnchorCoordinate = anchorCoordinate;
        resolvedQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        if (!hasAnchorBlock
            || activeInstallPreview == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(activeInstallPreview, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        if (!TryGetRectGridFootprintSettings(
                footprintSource,
                out _,
                out _,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        int currentQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        int targetQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            currentQuarterTurns + 2);
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    currentQuarterTurns,
                    placement,
                    out Vector2Int pipeCoordinate)
                || !TryGetPipePlacementAtCoordinate(
                    pipeCoordinate,
                    out Pipe pipe,
                    out Quaternion pipeRotation)
                || !TryGetStraightPipeAxis(pipe, pipeRotation, out _))
            {
                continue;
            }

            handled = true;

            for (int targetPlacementIndex = 0; targetPlacementIndex < placements.Count; targetPlacementIndex++)
            {
                InputOutputModule.RectGridBlockPlacement targetPlacement = placements[targetPlacementIndex];
                if (!InputOutputModule.AllowsPipeAreaInteraction(targetPlacement.blockType))
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    targetPlacement.x - objectAnchorCell.x,
                    targetPlacement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    pipeCoordinate - RotateFootprintOffset(localOffset, targetQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || !RectGridObjectCoordinatesMatch(
                        placements,
                        objectAnchorCell,
                        anchorCoordinate,
                        currentQuarterTurns,
                        candidateAnchorCoordinate,
                        targetQuarterTurns))
                {
                    continue;
                }

                resolvedAnchorBlock = candidateAnchorBlock;
                resolvedAnchorCoordinate = candidateAnchorCoordinate;
                resolvedQuarterTurns = targetQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private static bool RectGridObjectCoordinatesMatch(
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements,
        Vector2Int objectAnchorCell,
        Vector2Int firstAnchorCoordinate,
        int firstQuarterTurns,
        Vector2Int secondAnchorCoordinate,
        int secondQuarterTurns)
    {
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        int firstObjectCount = 0;
        int secondObjectCount = 0;
        for (int i = 0; i < placements.Count; i++)
        {
            if (placements[i].blockType == InputOutputModule.RectGridBlockType.Object)
            {
                firstObjectCount++;
                secondObjectCount++;
            }
        }

        if (firstObjectCount <= 0 || firstObjectCount != secondObjectCount)
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement firstPlacement = placements[i];
            if (firstPlacement.blockType != InputOutputModule.RectGridBlockType.Object)
            {
                continue;
            }

            Vector2Int firstOffset = new Vector2Int(
                firstPlacement.x - objectAnchorCell.x,
                firstPlacement.y - objectAnchorCell.y);
            Vector2Int firstCoordinate =
                firstAnchorCoordinate + RotateFootprintOffset(firstOffset, firstQuarterTurns);
            bool foundMatchingSecondCoordinate = false;
            for (int j = 0; j < placements.Count; j++)
            {
                InputOutputModule.RectGridBlockPlacement secondPlacement = placements[j];
                if (secondPlacement.blockType != InputOutputModule.RectGridBlockType.Object)
                {
                    continue;
                }

                Vector2Int secondOffset = new Vector2Int(
                    secondPlacement.x - objectAnchorCell.x,
                    secondPlacement.y - objectAnchorCell.y);
                Vector2Int secondCoordinate =
                    secondAnchorCoordinate + RotateFootprintOffset(secondOffset, secondQuarterTurns);
                if (secondCoordinate != firstCoordinate)
                {
                    continue;
                }

                foundMatchingSecondCoordinate = true;
                break;
            }

            if (!foundMatchingSecondCoordinate)
            {
                return false;
            }
        }

        return true;
    }

    private bool IsActiveBelt2FPreview()
    {
        if (activeInstallPreview == null)
        {
            return false;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(activeInstallPreview)
                                    ?? (activeInstallDefinition != null ? activeInstallDefinition.mapObject : null)
                                    ?? activeInstallPreview;
        return IsBelt2F(footprintSource);
    }

    private bool TryRotateBelt2FPreviewAroundBridgeCenter(
        bool hasAnchorBlock,
        Vector2Int currentAnchorCoordinate,
        out Block rotatedAnchorBlock,
        out Vector2Int rotatedAnchorCoordinate,
        out int rotatedQuarterTurns)
    {
        rotatedAnchorBlock = null;
        rotatedAnchorCoordinate = currentAnchorCoordinate;
        rotatedQuarterTurns = GetNextInstallPreviewQuarterTurns(activeInstallPreview, installPreviewQuarterTurns);

        if (!hasAnchorBlock)
        {
            return true;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(activeInstallPreview)
                                    ?? (activeInstallDefinition != null ? activeInstallDefinition.mapObject : null)
                                    ?? activeInstallPreview;
        if (!IsBelt2F(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        Vector2Int bridgeCenterCoordinate = GetBelt2FBridgeCenterCoordinate(
            currentAnchorCoordinate,
            footprintSource,
            GetPreviewQuarterTurns(activeInstallPreview));

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        int startQuarterTurns = GetNextInstallPreviewQuarterTurns(activeInstallPreview, installPreviewQuarterTurns);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                activeInstallPreview,
                startQuarterTurns + offset);
            Vector2Int candidateAnchorCoordinate =
                bridgeCenterCoordinate - GetBelt2FBridgeCenterOffset(footprintSource, candidateQuarterTurns);
            if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                || candidateAnchorBlock == null
                || !CanPlacePreviewOnBlock(candidateAnchorBlock, activeInstallPreview, candidateQuarterTurns))
            {
                continue;
            }

            rotatedAnchorBlock = candidateAnchorBlock;
            rotatedAnchorCoordinate = candidateAnchorCoordinate;
            rotatedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        rotatedAnchorBlock = null;
        rotatedAnchorCoordinate = currentAnchorCoordinate;
        rotatedQuarterTurns = GetPreviewQuarterTurns(activeInstallPreview);
        return false;
    }

    private bool TryFindNextConveyorPreviewRotation(
        ConveyorBelt conveyorPrototype,
        Vector2Int? anchorCoordinate,
        MapObject previewToIgnore,
        int currentStraightQuarterTurns,
        bool currentUsesCornerVariant,
        out int resolvedQuarterTurns,
        out ConveyorPreviewVariantMode resolvedVariantMode,
        out MapObject resolvedVariantPrefab,
        out int resolvedSequenceIndex)
    {
        int normalizedCurrentQuarterTurns = NormalizePlacementQuarterTurns(currentStraightQuarterTurns);
        resolvedQuarterTurns = normalizedCurrentQuarterTurns;
        resolvedVariantMode = currentUsesCornerVariant
            ? ConveyorPreviewVariantMode.Corner
            : ConveyorPreviewVariantMode.Straight;
        resolvedVariantPrefab = null;
        resolvedSequenceIndex = 0;

        if (conveyorPrototype == null)
        {
            return false;
        }

        int currentSequenceIndex = previewToIgnore != null
            && installPreviewConveyorRotationSequenceIndexesByPreview.TryGetValue(
                previewToIgnore,
                out int storedSequenceIndex)
                ? NormalizeConveyorRotationSequenceIndex(storedSequenceIndex)
                : GetConveyorRotationSequenceIndex(
                    conveyorPrototype,
                    previewToIgnore,
                    normalizedCurrentQuarterTurns,
                    currentUsesCornerVariant);

        for (int offset = 1; offset <= ConveyorRotationSequenceCount; offset++)
        {
            int candidateSequenceIndex = NormalizeConveyorRotationSequenceIndex(currentSequenceIndex + offset);
            if (!TryGetConveyorRotationSequenceCandidate(
                    conveyorPrototype,
                    candidateSequenceIndex,
                    out int candidateQuarterTurns,
                    out ConveyorPreviewVariantMode candidateVariantMode,
                    out MapObject candidateVariantPrefab)
                || candidateVariantPrefab == null)
            {
                continue;
            }

            if (candidateVariantMode == ConveyorPreviewVariantMode.Corner
                && anchorCoordinate.HasValue
                && !CanUseConveyorCornerRotationCandidate(
                    anchorCoordinate.Value,
                    candidateVariantPrefab,
                    candidateQuarterTurns,
                    previewToIgnore))
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            resolvedVariantMode = candidateVariantMode;
            resolvedVariantPrefab = candidateVariantPrefab;
            resolvedSequenceIndex = candidateSequenceIndex;
            return true;
        }

        return false;
    }

    private int GetConveyorRotationSequenceIndex(
        ConveyorBelt conveyorPrototype,
        MapObject preview,
        int currentStraightQuarterTurns,
        bool currentUsesCornerVariant)
    {
        int normalizedCurrentQuarterTurns = NormalizePlacementQuarterTurns(currentStraightQuarterTurns);
        if (currentUsesCornerVariant
            && preview is ConveyorBelt previewConveyor
            && previewConveyor.IsCornerVariant)
        {
            int outputQuarterTurns = normalizedCurrentQuarterTurns;
            if (TryGetConveyorStraightQuarterTurnsFromPreview(preview, conveyorPrototype, out int resolvedOutputQuarterTurns))
            {
                outputQuarterTurns = NormalizePlacementQuarterTurns(resolvedOutputQuarterTurns);
            }

            int cornerSequenceBaseIndex = ((outputQuarterTurns + 3) % 4) * 3;
            return cornerSequenceBaseIndex + (previewConveyor.IsReverseCornerVariant ? 2 : 1);
        }

        return normalizedCurrentQuarterTurns * 3;
    }

    private static int NormalizeConveyorRotationSequenceIndex(int sequenceIndex)
    {
        return ((sequenceIndex % ConveyorRotationSequenceCount) + ConveyorRotationSequenceCount) % ConveyorRotationSequenceCount;
    }

    private bool TryGetConveyorRotationSequenceCandidate(
        ConveyorBelt conveyorPrototype,
        int candidateSequenceIndex,
        out int candidateQuarterTurns,
        out ConveyorPreviewVariantMode candidateVariantMode,
        out MapObject candidateVariantPrefab)
    {
        candidateQuarterTurns = 0;
        candidateVariantMode = ConveyorPreviewVariantMode.Straight;
        candidateVariantPrefab = null;
        if (conveyorPrototype == null)
        {
            return false;
        }

        int normalizedSequenceIndex = NormalizeConveyorRotationSequenceIndex(candidateSequenceIndex);
        int straightQuarterTurns = normalizedSequenceIndex / 3;
        int sequenceStep = normalizedSequenceIndex % 3;
        if (sequenceStep == 0)
        {
            candidateQuarterTurns = straightQuarterTurns;
            candidateVariantPrefab = ResolveConveyorVariantPrefab(conveyorPrototype, 0) ?? conveyorPrototype;
            return candidateVariantPrefab is ConveyorBelt straightConveyor && !straightConveyor.IsCornerVariant;
        }

        if (conveyorPrototype.CornerVariantPrefab == null
            && conveyorPrototype.ReverseCornerVariantPrefab == null)
        {
            return false;
        }

        candidateQuarterTurns = (straightQuarterTurns + 1) % 4;
        candidateVariantMode = ConveyorPreviewVariantMode.Corner;
        candidateVariantPrefab = ResolveConveyorVariantPrefab(conveyorPrototype, sequenceStep == 1 ? 1 : 2);
        return candidateVariantPrefab is ConveyorBelt resolvedCornerConveyor
            && resolvedCornerConveyor.IsCornerVariant
            && resolvedCornerConveyor.IsReverseCornerVariant == (sequenceStep == 2);
    }

    private bool CanUseConveyorCornerRotationCandidate(
        Vector2Int anchorCoordinate,
        MapObject candidateVariantPrefab,
        int candidateQuarterTurns,
        MapObject previewToIgnore)
    {
        if (!(candidateVariantPrefab is ConveyorBelt candidateConveyor)
            || !candidateConveyor.IsCornerVariant)
        {
            return false;
        }

        Quaternion candidateRotation = GetPlacementObjectRotation(candidateConveyor, candidateQuarterTurns);
        if (!candidateConveyor.TryGetInputDirection(candidateRotation, out Vector2Int inputDirection)
            || !candidateConveyor.TryGetOutputDirection(candidateRotation, out Vector2Int outputDirection))
        {
            return false;
        }

        bool hasConnectedEndpoint = false;
        Vector2Int[] sideDirections =
        {
            Vector2Int.up,
            Vector2Int.right,
            Vector2Int.down,
            Vector2Int.left
        };

        for (int i = 0; i < sideDirections.Length; i++)
        {
            Vector2Int sideDirection = sideDirections[i];
            if (!TryGetConveyorPlacementDirectionsAtCoordinate(
                    anchorCoordinate + sideDirection,
                    previewToIgnore,
                    out ConveyorBelt conveyorBelt,
                    out Vector2Int neighborInputDirection,
                    out Vector2Int neighborOutputDirection))
            {
                continue;
            }

            if (sideDirection == inputDirection)
            {
                if (neighborOutputDirection == -sideDirection
                    || IsStraightConveyorSideSeamConnection(
                        conveyorBelt,
                        sideDirection,
                        neighborOutputDirection))
                {
                    hasConnectedEndpoint = true;
                    continue;
                }

                return false;
            }

            if (sideDirection == outputDirection)
            {
                if (neighborInputDirection == -sideDirection
                    || IsStraightConveyorSideSeamConnection(
                        conveyorBelt,
                        sideDirection,
                        neighborOutputDirection))
                {
                    hasConnectedEndpoint = true;
                    continue;
                }

                return false;
            }
        }

        return hasConnectedEndpoint;
    }

    private bool TryResolveActiveConveyorCornerPromotion(
        ConveyorBelt conveyorPrototype,
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore,
        out MapObject resolvedPrefab,
        out int resolvedQuarterTurns)
    {
        resolvedPrefab = sourcePrefab;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(quarterTurns);
        if (conveyorPrototype == null
            || straightFirstConveyorPreviews.Contains(previewToIgnore)
            || IsBelt2F(conveyorPrototype)
            || !(sourcePrefab is ConveyorBelt sourceConveyor)
            || sourceConveyor.IsCornerVariant)
        {
            return false;
        }

        if (!TryResolveConveyorCornerPlacementPrefab(
                conveyorPrototype,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore,
                out MapObject cornerPrefab,
                out int cornerQuarterTurns,
                false,
                false))
        {
            return false;
        }

        if (!(cornerPrefab is ConveyorBelt cornerConveyor)
            || !cornerConveyor.IsCornerVariant
            || !TryGetConveyorEndpointConnectionScoreForSource(
                cornerConveyor,
                anchorCoordinate,
                cornerQuarterTurns,
                previewToIgnore,
                out int cornerConnectionScore)
            || cornerConnectionScore <= 0)
        {
            return false;
        }

        int straightConnectionScore = GetConveyorEndpointConnectionScore(
            anchorCoordinate,
            sourceConveyor,
            quarterTurns,
            previewToIgnore);
        if (cornerConnectionScore < 2 || cornerConnectionScore <= straightConnectionScore)
        {
            return false;
        }

        resolvedPrefab = cornerPrefab;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(cornerQuarterTurns);
        return true;
    }

    private bool TryGetConveyorEndpointConnectionScoreForSource(
        ConveyorBelt conveyorSource,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore,
        out int connectionScore)
    {
        connectionScore = 0;
        if (conveyorSource == null)
        {
            return false;
        }

        Quaternion sourceRotation = GetPlacementObjectRotation(conveyorSource, quarterTurns);
        if (!conveyorSource.TryGetInputDirection(sourceRotation, out Vector2Int inputDirection)
            || !conveyorSource.TryGetOutputDirection(sourceRotation, out Vector2Int outputDirection))
        {
            return false;
        }

        connectionScore = GetConveyorEndpointConnectionScore(
            anchorCoordinate,
            inputDirection,
            outputDirection,
            previewToIgnore);
        return true;
    }

    private int GetConveyorEndpointConnectionScore(
        Vector2Int anchorCoordinate,
        ConveyorBelt conveyorSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (conveyorSource == null)
        {
            return 0;
        }

        Quaternion sourceRotation = GetPlacementObjectRotation(conveyorSource, quarterTurns);
        if (!conveyorSource.TryGetInputDirection(sourceRotation, out Vector2Int inputDirection)
            || !conveyorSource.TryGetOutputDirection(sourceRotation, out Vector2Int outputDirection))
        {
            return 0;
        }

        return GetConveyorEndpointConnectionScore(
            anchorCoordinate,
            inputDirection,
            outputDirection,
            previewToIgnore);
    }

    private MapObject ResolveConveyorPreviewSourceForAnchor(
        ConveyorBelt conveyorPrototype,
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (IsBelt2F(conveyorPrototype))
        {
            return sourcePrefab != null ? sourcePrefab : conveyorPrototype;
        }

        if (conveyorPrototype == null || !(sourcePrefab is ConveyorBelt sourceConveyor) || !sourceConveyor.IsCornerVariant)
        {
            return sourcePrefab;
        }

        if (CanUseConveyorCornerRotationCandidate(
                anchorCoordinate,
                sourcePrefab,
                quarterTurns,
                previewToIgnore))
        {
            return sourcePrefab;
        }

        return ResolveConveyorVariantPrefab(conveyorPrototype, 0) ?? conveyorPrototype;
    }

    private bool IsSameConveyorPreviewState(MapObject preview, MapObject candidatePrefab, int candidateQuarterTurns)
    {
        if (!(preview is ConveyorBelt previewConveyor)
            || !(candidatePrefab is ConveyorBelt candidateConveyor))
        {
            return false;
        }

        if (previewConveyor.IsCornerVariant != candidateConveyor.IsCornerVariant
            || previewConveyor.IsReverseCornerVariant != candidateConveyor.IsReverseCornerVariant)
        {
            return false;
        }

        Quaternion candidateRotation = GetPlacementObjectRotation(candidateConveyor, candidateQuarterTurns);
        return Mathf.Abs(Quaternion.Dot(preview.transform.rotation, candidateRotation)) >= 0.9999f;
    }

    private bool TryGetConveyorStraightQuarterTurnsFromPreview(MapObject preview, ConveyorBelt conveyorPrototype, out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = installPreviewQuarterTurns;
        if (!(preview is ConveyorBelt previewConveyor) || conveyorPrototype == null)
        {
            return false;
        }

        if (!previewConveyor.TryGetOutputDirection(preview.transform.rotation, out Vector2Int outputDirection))
        {
            return false;
        }

        ConveyorBelt straightPrefab = conveyorPrototype.StraightVariantPrefab != null
            ? conveyorPrototype.StraightVariantPrefab
            : conveyorPrototype;
        return TryGetConveyorPlacementQuarterTurnsForOutput(straightPrefab, outputDirection, out resolvedQuarterTurns);
    }

    private Quaternion GetInstallPreviewRotation()
    {
        if (activeInstallPreview != null)
        {
            MapObject rotationSource = ResolveInstallPreviewRotationSource(activeInstallPreview);
            Quaternion previewBaseRotation = installPreviewBaseRotationsByPreview.TryGetValue(activeInstallPreview, out Quaternion storedBaseRotation)
                ? storedBaseRotation
                : (rotationSource != null ? rotationSource.transform.rotation : activeInstallPreview.transform.rotation);
            if (TryGetPreviewAnchorCoordinate(activeInstallPreview, out Vector2Int anchorCoordinate))
            {
                Vector3 railReferencePosition = installPreviewRailReferenceWorldPositions.TryGetValue(
                    activeInstallPreview,
                    out Vector3 storedRailReferencePosition)
                    ? storedRailReferencePosition
                    : activeInstallPreview.transform.position;
                return ResolvePlacementObjectRotation(
                    previewBaseRotation,
                    rotationSource,
                    anchorCoordinate,
                    installPreviewQuarterTurns,
                    railReferencePosition);
            }

            return GetPlacementObjectRotation(previewBaseRotation, rotationSource, installPreviewQuarterTurns);
        }

        if (activeInstallDefinition != null && activeInstallDefinition.mapObject != null)
        {
            return GetPlacementObjectRotation(activeInstallBaseRotation, activeInstallDefinition.mapObject, installPreviewQuarterTurns);
        }

        return Quaternion.identity;
    }

    private void HandleInstallPreviewClick(Vector2 pointerPosition)
    {
        if (!TryGetPointerBlock(pointerPosition, out Block clickedBlock) || clickedBlock == null)
        {
            return;
        }

        Vector3? railReferenceWorldPosition = TryGetInstallPreviewRailReferenceWorldPosition(
            pointerPosition,
            out Vector3 pointerWorldPosition)
            ? pointerWorldPosition
            : null;

        if (TryGetInstallPreviewAtBlock(clickedBlock, out MapObject clickedPreview) && clickedPreview != null)
        {
            if (IsPreviewObjectCell(clickedPreview, clickedBlock))
            {
                RemoveInstallPreview(clickedPreview);
                return;
            }

            if (CanCreateAdditionalPreview()
                && CoordinateHasInputOutputAreaForPlacement(clickedBlock.Coordinate, null)
                && TryCreateAndPlaceInstallPreview(clickedBlock, clickedPreview, railReferenceWorldPosition))
            {
                return;
            }

            SelectInstallPreview(clickedPreview);
            return;
        }

        if (CanCreateAdditionalPreview())
        {
            TryCreateAndPlaceInstallPreview(clickedBlock, null, railReferenceWorldPosition);
        }
    }

    private void SelectInstallPreview(MapObject preview)
    {
        SelectInstallPreview(preview, true, true);
    }

    private void SelectInstallPreview(MapObject preview, bool refreshDependentVisuals, bool invalidateGrid)
    {
        if (preview == null)
        {
            return;
        }

        InvalidateInstallPreviewMoveCache();
        activeInstallPreview = preview;
        installPreviewQuarterTurns = GetPreviewQuarterTurns(preview);
        installPreviewConveyorVariantMode = GetConveyorPreviewVariantMode(preview);
        activeInstallPreview.transform.rotation = GetInstallPreviewRotation();
        if (activeInstallPreview is InstallationObject selectedInstallationPreview)
        {
            selectedInstallationPreview.RefreshInstalledDirectionFromCurrentTransform();
        }

        if (refreshDependentVisuals)
        {
            RefreshInstallPreviewSelectionVisuals();
            RefreshInstallPreviewAreaMarkers(activeInstallPreview);
            RefreshInstallOrEditWorkableRangeVisualRequest();
        }

        if (invalidateGrid)
        {
            InvalidateInstallGridPreview();
        }
    }

    private int GetPreviewQuarterTurns(MapObject preview)
    {
        if (preview == null)
        {
            return 0;
        }

        if (installPreviewQuarterTurnsByPreview.TryGetValue(preview, out int storedQuarterTurns))
        {
            return NormalizePlacementQuarterTurnsForObject(
                ResolveInstallPreviewRotationSource(preview),
                storedQuarterTurns);
        }

        if (preview == activeInstallPreview)
        {
            return NormalizePlacementQuarterTurnsForObject(
                ResolveInstallPreviewRotationSource(preview),
                installPreviewQuarterTurns);
        }

        return 0;
    }

    private int GetPreviewAreaQuarterTurns(MapObject preview)
    {
        if (preview == null)
        {
            return 0;
        }

        MapObject placementSource = ResolveInstallPreviewPlacementSource(preview);
        if (installPreviewQuarterTurnsByPreview.TryGetValue(preview, out int storedQuarterTurns))
        {
            return NormalizePlacementQuarterTurnsForObject(
                placementSource,
                storedQuarterTurns);
        }

        if (preview == activeInstallPreview)
        {
            return NormalizePlacementQuarterTurnsForObject(placementSource, installPreviewQuarterTurns);
        }

        if (TryResolvePlacementQuarterTurnsFromRotation(
                placementSource,
                preview.transform.rotation,
                out int transformQuarterTurns))
        {
            return NormalizePlacementQuarterTurnsForObject(
                placementSource,
                transformQuarterTurns);
        }

        return 0;
    }

    private void SetInstallPreviewQuarterTurns(MapObject preview, int quarterTurns)
    {
        if (preview == null)
        {
            return;
        }

        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            ResolveInstallPreviewRotationSource(preview),
            quarterTurns);
        installPreviewQuarterTurnsByPreview[preview] = normalizedQuarterTurns;
        if (preview == activeInstallPreview)
        {
            installPreviewQuarterTurns = normalizedQuarterTurns;
        }
    }

    private MapObject ResolveInstallPreviewRotationSource(MapObject preview)
    {
        if (preview != null
            && installPreviewSourcePrefabsByPreview.TryGetValue(preview, out MapObject sourcePrefab)
            && sourcePrefab != null)
        {
            return sourcePrefab;
        }

        return preview;
    }

    private static int NormalizePlacementQuarterTurns(int quarterTurns)
    {
        return ((quarterTurns % 4) + 4) % 4;
    }

    private static bool UsesTwoStateWallRotation(MapObject sourcePrefab)
    {
        return sourcePrefab is Wall wall && wall.VariantKind == FenceVariantKind.Straight;
    }

    private static bool UsesTwoStateUtilityPoleRotation(MapObject sourcePrefab)
    {
        return sourcePrefab is UtilityPole;
    }

    private static bool UsesTwoStatePlacementRotation(MapObject sourcePrefab)
    {
        return UsesTwoStateWallRotation(sourcePrefab)
               || UsesTwoStateUtilityPoleRotation(sourcePrefab);
    }

    private static int GetPlacementRotationCandidateCount(MapObject sourcePrefab)
    {
        return UsesTwoStatePlacementRotation(sourcePrefab) ? 2 : 4;
    }

    private static int NormalizePlacementQuarterTurnsForObject(MapObject sourcePrefab, int quarterTurns)
    {
        int normalizedQuarterTurns = NormalizePlacementQuarterTurns(quarterTurns);
        return UsesTwoStatePlacementRotation(sourcePrefab)
            ? normalizedQuarterTurns % 2
            : normalizedQuarterTurns;
    }

    private static int ResolveTwoStateQuarterTurnsFromRotation(
        MapObject sourcePrefab,
        Quaternion worldRotation,
        int fallbackQuarterTurns)
    {
        int bestQuarterTurns = -1;
        float bestDot = -1f;
        Quaternion baseRotation = sourcePrefab != null
            ? sourcePrefab.transform.rotation
            : Quaternion.identity;

        for (int candidateQuarterTurns = 0; candidateQuarterTurns < 4; candidateQuarterTurns++)
        {
            Quaternion candidateRotation = baseRotation * Quaternion.Euler(0f, candidateQuarterTurns * 90f, 0f);
            float dot = Mathf.Abs(Quaternion.Dot(candidateRotation, worldRotation));
            if (dot > bestDot)
            {
                bestDot = dot;
                bestQuarterTurns = candidateQuarterTurns;
            }
        }

        if (bestQuarterTurns >= 0 && bestDot >= PlacementRotationNearestDotThreshold)
        {
            return bestQuarterTurns % 2;
        }

        return NormalizePlacementQuarterTurns(fallbackQuarterTurns) % 2;
    }

    private int GetNextInstallPreviewQuarterTurns(MapObject preview, int currentQuarterTurns)
    {
        if (UsesTwoStateInstallPreviewRotation(preview))
        {
            return NormalizeInstallPreviewQuarterTurns(preview, currentQuarterTurns) == 0 ? 1 : 0;
        }

        return NormalizePlacementQuarterTurns(currentQuarterTurns + 1);
    }

    private bool UsesTwoStateInstallPreviewRotation(MapObject preview)
    {
        return activeInstallDefinition != null
               && (activeInstallDefinition.mapObject is Wall
                   || UsesTwoStateUtilityPoleRotation(activeInstallDefinition.mapObject))
               || UsesTwoStatePlacementRotation(preview);
    }

    private int NormalizeInstallPreviewQuarterTurns(MapObject preview, int quarterTurns)
    {
        return UsesTwoStateInstallPreviewRotation(preview)
            ? NormalizePlacementQuarterTurns(quarterTurns) % 2
            : NormalizePlacementQuarterTurnsForObject(preview, quarterTurns);
    }

    private void RememberLastBlueprintRotation(ItemDefinition definition, int quarterTurns)
    {
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            definition != null ? definition.mapObject : null,
            quarterTurns);
        lastBlueprintQuarterTurns = normalizedQuarterTurns;
        hasLastBlueprintQuarterTurns = true;

        if (definition != null && definition.id >= 0)
        {
            lastBlueprintQuarterTurnsByItemId[definition.id] = normalizedQuarterTurns;
        }
    }

    private void RememberBlueprintRotationForPreview(ItemDefinition definition, MapObject preview, int quarterTurns)
    {
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            preview != null ? preview : definition != null ? definition.mapObject : null,
            quarterTurns);
        if (IsFenceDoorDefinition(definition))
        {
            if (preview is FenceDoor)
            {
                if (TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate)
                    && HasFenceNeighborConnections(anchorCoordinate, preview, true))
                {
                    return;
                }

                installPreviewFenceDoorStandaloneQuarterTurnsByPreview[preview] = normalizedQuarterTurns;
            }
        }

        RememberLastBlueprintRotation(definition, normalizedQuarterTurns);
    }

    private bool HasFenceNeighborConnections(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        bool allowPotentialConnections)
    {
        List<Vector2Int> neighborDirections = GetFenceNeighborConnectionDirections(
            anchorCoordinate,
            previewToIgnore,
            allowPotentialConnections);
        return CountFenceNeighborDirections(neighborDirections) > 0;
    }

    private void RememberLastInstalledRotation(ItemDefinition definition, int quarterTurns)
    {
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            definition != null ? definition.mapObject : null,
            quarterTurns);
        lastInstalledQuarterTurns = normalizedQuarterTurns;
        hasLastInstalledQuarterTurns = true;

        if (definition != null && definition.id >= 0)
        {
            lastInstalledQuarterTurnsByItemId[definition.id] = normalizedQuarterTurns;
        }
    }

    private int GetPreferredInstallPreviewQuarterTurns(ItemDefinition definition, MapObject sourcePreview)
    {
        if (sourcePreview != null)
        {
            return GetPreviewQuarterTurns(sourcePreview);
        }

        if (TryGetRememberedBlueprintRotation(definition, out int blueprintQuarterTurns))
        {
            return blueprintQuarterTurns;
        }

        if (activeInstallPreview != null && installPreviewInstances.Contains(activeInstallPreview))
        {
            return GetPreviewQuarterTurns(activeInstallPreview);
        }

        return TryGetRememberedInstallRotation(definition, out int rememberedQuarterTurns)
            ? rememberedQuarterTurns
            : 0;
    }

    private int GetPreferredFenceDoorStandaloneQuarterTurns(ItemDefinition definition, MapObject sourcePreview)
    {
        if (sourcePreview != null)
        {
            return GetFenceDoorStandaloneQuarterTurns(sourcePreview, GetPreviewQuarterTurns(sourcePreview));
        }

        if (definition != null
            && definition.id >= 0
            && lastBlueprintQuarterTurnsByItemId.TryGetValue(definition.id, out int blueprintQuarterTurns))
        {
            return NormalizePlacementQuarterTurnsForObject(definition.mapObject, blueprintQuarterTurns);
        }

        if (definition != null
            && definition.id >= 0
            && lastInstalledQuarterTurnsByItemId.TryGetValue(definition.id, out int installedQuarterTurns))
        {
            return NormalizePlacementQuarterTurnsForObject(definition.mapObject, installedQuarterTurns);
        }

        return 0;
    }

    private static bool IsFenceDoorDefinition(ItemDefinition definition)
    {
        return definition != null && definition.mapObject is FenceDoor;
    }

    private bool HasRememberedInstallRotation(ItemDefinition definition)
    {
        return TryGetRememberedInstallRotation(definition, out _);
    }

    private bool HasRememberedBlueprintRotation(ItemDefinition definition)
    {
        return TryGetRememberedBlueprintRotation(definition, out _);
    }

    private bool TryGetRememberedBlueprintRotation(ItemDefinition definition, out int quarterTurns)
    {
        quarterTurns = 0;
        if (definition != null
            && definition.id >= 0
            && lastBlueprintQuarterTurnsByItemId.TryGetValue(definition.id, out int itemQuarterTurns))
        {
            quarterTurns = NormalizePlacementQuarterTurnsForObject(definition.mapObject, itemQuarterTurns);
            return true;
        }

        if (!hasLastBlueprintQuarterTurns)
        {
            return false;
        }

        quarterTurns = NormalizePlacementQuarterTurnsForObject(definition != null ? definition.mapObject : null, lastBlueprintQuarterTurns);
        return true;
    }

    private bool TryGetRememberedInstallRotation(ItemDefinition definition, out int quarterTurns)
    {
        quarterTurns = 0;
        if (definition != null
            && definition.id >= 0
            && lastInstalledQuarterTurnsByItemId.TryGetValue(definition.id, out int itemQuarterTurns))
        {
            quarterTurns = NormalizePlacementQuarterTurnsForObject(definition.mapObject, itemQuarterTurns);
            return true;
        }

        if (!hasLastInstalledQuarterTurns)
        {
            return false;
        }

        quarterTurns = NormalizePlacementQuarterTurnsForObject(definition != null ? definition.mapObject : null, lastInstalledQuarterTurns);
        return true;
    }

    private bool TryResolvePlacementQuarterTurnsFromRotation(MapObject sourcePrefab, Quaternion worldRotation, out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = 0;
        if (sourcePrefab == null)
        {
            return false;
        }

        if (UsesTwoStatePlacementRotation(sourcePrefab))
        {
            resolvedQuarterTurns = ResolveTwoStateQuarterTurnsFromRotation(
                sourcePrefab,
                worldRotation,
                resolvedQuarterTurns);
            return true;
        }

        int candidateCount = GetPlacementRotationCandidateCount(sourcePrefab);
        int bestQuarterTurns = -1;
        float bestDot = -1f;
        for (int candidateQuarterTurns = 0; candidateQuarterTurns < candidateCount; candidateQuarterTurns++)
        {
            Quaternion candidateRotation = GetPlacementObjectRotation(sourcePrefab, candidateQuarterTurns);
            float dot = Mathf.Abs(Quaternion.Dot(candidateRotation, worldRotation));
            if (dot >= PlacementRotationExactDotThreshold)
            {
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }

            if (dot > bestDot)
            {
                bestDot = dot;
                bestQuarterTurns = candidateQuarterTurns;
            }
        }

        if (bestQuarterTurns >= 0 && bestDot >= PlacementRotationNearestDotThreshold)
        {
            resolvedQuarterTurns = bestQuarterTurns;
            return true;
        }

        return false;
    }

    private bool CanCreateAdditionalPreview()
    {
        if (IsEditingInstallation())
        {
            return false;
        }

        int itemId = activeInstallDefinition != null ? activeInstallDefinition.id : -1;
        int availableItemCount = GetAvailableInstallItemCount(itemId);
        return GetInstallPreviewCount() < availableItemCount;
    }

    public int GetAvailableInstallItemCount(int itemId = -1)
    {
        if (IsEditingInstallation())
        {
            return 1;
        }

        if (itemId < 0 && activeInstallDefinition != null)
        {
            itemId = activeInstallDefinition.id;
        }

        return GetCurrentInstallItemCount() + GetReservedInstallPreviewItemCount(itemId);
    }

    private int GetCurrentInstallItemCount()
    {
        if (IsEditingInstallation())
        {
            return 1;
        }

        int itemId = activeInstallDefinition != null ? activeInstallDefinition.id : -1;
        PlayerBag handBag = GetPlayerHandBag();
        if (itemId < 0 && handBag != null)
        {
            itemId = handBag.GetSlotItemId(0);
        }

        if (itemId < 0)
        {
            return 0;
        }

        int totalCount = 0;
        if (handBag != null && handBag.GetSlotItemId(0) == itemId)
        {
            totalCount += handBag.GetSlotCount(0);
        }

        PlayerBag inventoryBag = GetPlayerInventoryBag();
        if (inventoryBag != null && inventoryBag != handBag)
        {
            totalCount += inventoryBag.GetTotalItemCount(itemId);
        }

        return totalCount;
    }

    public int RemoveInstallItemsFromPlayer(int itemId, int requestedCount)
    {
        if (itemId < 0 || requestedCount <= 0)
        {
            return 0;
        }

        int removedCount = 0;
        Player player = GameManager.Instance != null ? GameManager.Instance.Player : null;
        PlayerBag handBag = player != null ? player.GetHandBag() : GetPlayerHandBag();
        PlayerBag inventoryBag = player != null ? player.GetBag() : GetPlayerInventoryBag();
        if (inventoryBag != null && inventoryBag != handBag)
        {
            removedCount += inventoryBag.RemoveItems(itemId, requestedCount);
        }

        int remainingCount = requestedCount - removedCount;
        if (remainingCount > 0 && handBag != null)
        {
            removedCount += handBag.RemoveItems(itemId, remainingCount);
            handBag.RefreshExternalStackCounts();
        }

        player?.UpdateCarryState();
        return removedCount;
    }

    private int GetInstallPreviewCount()
    {
        CleanupInstallPreviewReferences();
        return installPreviewInstances.Count;
    }

    private void RegisterInstallPreview(MapObject preview, int quarterTurns)
    {
        if (preview == null)
        {
            return;
        }

        InvalidateInstallPreviewMoveCache();
        CleanupInstallPreviewReferences();
        if (!installPreviewInstances.Contains(preview))
        {
            installPreviewInstances.Add(preview);
        }

        MapObject rotationSource = ResolveInstallPreviewRotationSource(preview);
        int normalizedQuarterTurns = NormalizePlacementQuarterTurnsForObject(rotationSource, quarterTurns);
        installPreviewQuarterTurnsByPreview[preview] = normalizedQuarterTurns;
        if (preview is FenceDoor)
        {
            installPreviewFenceDoorStandaloneQuarterTurnsByPreview[preview] = normalizedQuarterTurns;
        }

        installPreviewBaseRotationsByPreview[preview] = rotationSource != null
            ? rotationSource.transform.rotation
            : preview.transform.rotation;
        if (!installPreviewPlacementSequencesByPreview.ContainsKey(preview))
        {
            installPreviewPlacementSequencesByPreview[preview] = InstallationObject.ClaimNextPlacementSequence();
        }
        installPreviewConveyorVariantMode = GetConveyorPreviewVariantMode(preview);
    }

    private void CleanupInstallPreviewReferences()
    {
        for (int i = installPreviewInstances.Count - 1; i >= 0; i--)
        {
            if (installPreviewInstances[i] != null)
            {
                continue;
            }

            installPreviewInstances.RemoveAt(i);
        }

        RemoveMissingPreviewKeys(installPreviewQuarterTurnsByPreview);
        RemoveMissingPreviewKeys(installPreviewAnchorCoordinates);
        RemoveMissingPreviewKeys(installPreviewFenceDoorStandaloneQuarterTurnsByPreview);
        RemoveMissingPreviewKeys(installPreviewBaseRotationsByPreview);
        RemoveMissingPreviewKeys(installPreviewSourcePrefabsByPreview);
        RemoveMissingPreviewKeys(installPreviewRailReferenceWorldPositions);
        RemoveMissingPreviewKeys(installPreviewPlacementSequencesByPreview);
        RemoveMissingPreviewKeys(installPreviewConveyorRotationSequenceIndexesByPreview);
        RemoveMissingPreviewItemReservations();
        RemoveMissingStraightFirstConveyorPreviews();

        CleanupInstalledFenceVariantPreviewReferences();
    }

    private void RemoveMissingPreviewKeys<TValue>(Dictionary<MapObject, TValue> dictionary)
    {
        if (dictionary == null || dictionary.Count <= 0)
        {
            return;
        }

        cleanupMapObjectScratch.Clear();
        foreach (KeyValuePair<MapObject, TValue> entry in dictionary)
        {
            if (entry.Key == null)
            {
                cleanupMapObjectScratch.Add(entry.Key);
            }
        }

        for (int i = 0; i < cleanupMapObjectScratch.Count; i++)
        {
            dictionary.Remove(cleanupMapObjectScratch[i]);
        }

        cleanupMapObjectScratch.Clear();
    }

    private void RemoveMissingStraightFirstConveyorPreviews()
    {
        if (straightFirstConveyorPreviews.Count <= 0)
        {
            return;
        }

        cleanupMapObjectScratch.Clear();
        foreach (MapObject preview in straightFirstConveyorPreviews)
        {
            if (preview == null || !installPreviewInstances.Contains(preview))
            {
                cleanupMapObjectScratch.Add(preview);
            }
        }

        for (int i = 0; i < cleanupMapObjectScratch.Count; i++)
        {
            straightFirstConveyorPreviews.Remove(cleanupMapObjectScratch[i]);
        }

        cleanupMapObjectScratch.Clear();
    }

    private void RemoveMissingPreviewItemReservations()
    {
        if (installPreviewItemReservationsByPreview.Count <= 0)
        {
            return;
        }

        cleanupMapObjectScratch.Clear();
        foreach (KeyValuePair<MapObject, InstallPreviewItemReservation> entry in installPreviewItemReservationsByPreview)
        {
            if (entry.Key != null)
            {
                continue;
            }

            RefundInstallPreviewReservation(entry.Value);
            cleanupMapObjectScratch.Add(entry.Key);
        }

        for (int i = 0; i < cleanupMapObjectScratch.Count; i++)
        {
            installPreviewItemReservationsByPreview.Remove(cleanupMapObjectScratch[i]);
        }

        cleanupMapObjectScratch.Clear();
    }

    private bool TryCreateAndPlaceInstallPreview(
        Block block,
        MapObject sourcePreview,
        Vector3? railReferenceWorldPosition = null)
    {
        if (block == null || activeInstallDefinition == null || !CanCreateAdditionalPreview())
        {
            return false;
        }

        int quarterTurns = IsFenceDoorDefinition(activeInstallDefinition)
            ? GetPreferredFenceDoorStandaloneQuarterTurns(activeInstallDefinition, sourcePreview)
            : GetPreferredInstallPreviewQuarterTurns(activeInstallDefinition, sourcePreview);
        if (sourcePreview == null && activeInstallDefinition.mapObject is ConveyorBelt conveyorPrototype)
        {
            if (!HasRememberedBlueprintRotation(activeInstallDefinition)
                && !HasRememberedInstallRotation(activeInstallDefinition)
                && activeInstallPreview == null)
            {
                TryResolveInitialConveyorPreviewQuarterTurns(block.Coordinate, conveyorPrototype, out quarterTurns);
            }
        }

        Block anchorBlock;
        bool resolvedTarget;
        if (IsTrainSource(activeInstallDefinition.mapObject))
        {
            resolvedTarget = TryResolveTrainInstallPreviewTarget(
                block,
                activeInstallDefinition.mapObject,
                quarterTurns,
                railReferenceWorldPosition,
                out anchorBlock,
                out quarterTurns);
        }
        else
        {
            resolvedTarget = TryResolvePlaceableInstallPreviewTarget(
                block,
                sourcePreview,
                quarterTurns,
                sourcePreview != null,
                out anchorBlock,
                out quarterTurns);
        }

        if (!resolvedTarget)
        {
            return false;
        }

        if (!TryReserveInstallPreviewItem(activeInstallDefinition, out InstallPreviewItemReservation reservation))
        {
            return false;
        }

        MapObject preview = CreateInstallPreviewInstance(activeInstallDefinition);
        if (preview == null)
        {
            RefundInstallPreviewReservation(reservation);
            return false;
        }

        installPreviewItemReservationsByPreview[preview] = reservation;
        RegisterInstallPreview(preview, quarterTurns);
        if (sourcePreview == null
            && activeInstallDefinition.mapObject is ConveyorBelt
            && !IsBelt2F(activeInstallDefinition.mapObject))
        {
            straightFirstConveyorPreviews.Add(preview);
        }

        SelectInstallPreview(preview);
        if (sourcePreview != null)
        {
            installPreviewConveyorVariantMode = GetConveyorPreviewVariantMode(sourcePreview);
            if (sourcePreview is ConveyorBelt)
            {
                MapObject sourcePrefab = ResolveInstallPreviewFootprintSource(sourcePreview);
                if (sourcePrefab != null)
                {
                    installPreviewSourcePrefabsByPreview[preview] = sourcePrefab;
                }
            }

            RefreshActiveConveyorPreviewVariant();
        }

        if (sourcePreview != null)
        {
            bool placed = ApplyResolvedInstallPreviewPlacement(anchorBlock, quarterTurns);
            if (placed && sourcePreview is ConveyorBelt)
            {
                straightFirstConveyorPreviews.Remove(sourcePreview);
                if (TryGetPreviewAnchorCoordinate(sourcePreview, out Vector2Int sourceAnchorCoordinate))
                {
                    RefreshSingleConveyorPreviewVariant(
                        sourcePreview,
                        sourceAnchorCoordinate,
                        activeInstallPreview);
                    RefreshAllInstallPreviewConveyorEndpointVisuals();
                }
            }

            return placed;
        }

        Block initialPreviewBlock = IsBelt2F(activeInstallDefinition.mapObject) ? block : anchorBlock;
        if (MoveInstallPreviewToBlock(initialPreviewBlock, false, railReferenceWorldPosition))
        {
            return true;
        }

        RemoveInstallPreview(preview);
        return false;
    }

    private bool ApplyResolvedInstallPreviewPlacement(Block anchorBlock, int resolvedQuarterTurns)
    {
        if (activeInstallPreview == null || anchorBlock == null)
        {
            return false;
        }

        installPreviewQuarterTurns = NormalizePlacementQuarterTurnsForObject(activeInstallPreview, resolvedQuarterTurns);
        installPreviewQuarterTurnsByPreview[activeInstallPreview] = installPreviewQuarterTurns;
        installPreviewAnchorCoordinates[activeInstallPreview] = anchorBlock.Coordinate;

        RefreshActiveConveyorPreviewVariant();
        RefreshActiveFencePreviewVariant(true);
        RefreshActivePipePreviewVariant();

        MapObject placementSource = ResolveInstallPreviewPlacementSource(activeInstallPreview);
        activeInstallPreview.transform.position = ResolvePlacementWorldPosition(
            anchorBlock,
            placementSource,
            installPreviewQuarterTurns);
        activeInstallPreview.transform.rotation = GetInstallPreviewRotation();
        if (activeInstallPreview is InstallationObject movedInstallationPreview)
        {
            movedInstallationPreview.RefreshInstalledDirectionFromCurrentTransform();
        }

        RefreshPreviewRangeVisualsIfNeeded(activeInstallPreview);
        RefreshUtilityPolePreviewWires();
        RefreshInstallPreviewAreaMarkers(activeInstallPreview);
        RefreshFencePreviewVariantsAroundActivePreview(null, true);
        RefreshPipePreviewVariantsAroundActivePreview(null);
        RefreshTrainInstallPreviewTints();
        RememberBlueprintRotationForPreview(activeInstallDefinition, activeInstallPreview, installPreviewQuarterTurns);
        InvalidateInstallGridPreview();
        return true;
    }

    private void RemoveInstallPreview(MapObject preview)
    {
        if (preview == null)
        {
            return;
        }

        InvalidateInstallPreviewMoveCache();
        RefundInstallPreviewReservation(preview);

        Vector2Int removedFenceAnchorCoordinate = Vector2Int.zero;
        bool hadRemovedFenceAnchorCoordinate = preview is Wall
            && TryGetPreviewAnchorCoordinate(preview, out removedFenceAnchorCoordinate);
        Vector2Int removedPipeAnchorCoordinate = Vector2Int.zero;
        bool hadRemovedPipeAnchorCoordinate = preview is Pipe
            && TryGetPreviewAnchorCoordinate(preview, out removedPipeAnchorCoordinate);
        bool removedConveyorPreview = preview is ConveyorBelt;

        installPreviewInstances.Remove(preview);
        installPreviewQuarterTurnsByPreview.Remove(preview);
        installPreviewFenceDoorStandaloneQuarterTurnsByPreview.Remove(preview);
        installPreviewBaseRotationsByPreview.Remove(preview);
        installPreviewSourcePrefabsByPreview.Remove(preview);
        installPreviewRailReferenceWorldPositions.Remove(preview);
        installPreviewPlacementSequencesByPreview.Remove(preview);
        installPreviewConveyorRotationSequenceIndexesByPreview.Remove(preview);
        installPreviewAnchorCoordinates.Remove(preview);
        installPreviewItemReservationsByPreview.Remove(preview);
        straightFirstConveyorPreviews.Remove(preview);

        if (activeInstallPreview == preview)
        {
            activeInstallPreview = null;
            installPreviewQuarterTurns = 0;
        }

        DestroyInstallPreviewObject(preview);

        EnsureValidActiveInstallPreview();
        RefreshInstallOrEditWorkableRangeVisualRequest();
        RefreshActiveConveyorPreviewVariant();
        if (removedConveyorPreview)
        {
            RefreshAllInstallPreviewConveyorEndpointVisuals();
        }

        if (hadRemovedFenceAnchorCoordinate)
        {
            RefreshActiveFencePreviewVariant();
            RefreshFencePreviewVariants();
            RefreshInstalledFenceVariantPreviews();
        }
        else if (hadRemovedPipeAnchorCoordinate)
        {
            RefreshActivePipePreviewVariant();
            RefreshPipePreviewVariants();
            RefreshInstalledPipeVariantPreviews();
        }
        else
        {
            RefreshActiveFencePreviewVariant();
            RefreshInstalledFenceVariantPreviews();
            RefreshActivePipePreviewVariant();
            RefreshPipePreviewVariants();
            RefreshInstalledPipeVariantPreviews();
        }

        InvalidateInstallGrid();
        RefreshTrainInstallPreviewTints();
    }

    private void RemovePlacedInstallPreviews(IReadOnlyList<MapObject> placedPreviews)
    {
        if (placedPreviews == null || placedPreviews.Count <= 0)
        {
            return;
        }

        InvalidateInstallPreviewMoveCache();
        for (int i = 0; i < placedPreviews.Count; i++)
        {
            MapObject preview = placedPreviews[i];
            if (preview == null)
            {
                continue;
            }

            installPreviewInstances.Remove(preview);
            installPreviewQuarterTurnsByPreview.Remove(preview);
            installPreviewFenceDoorStandaloneQuarterTurnsByPreview.Remove(preview);
            installPreviewBaseRotationsByPreview.Remove(preview);
            installPreviewSourcePrefabsByPreview.Remove(preview);
            installPreviewRailReferenceWorldPositions.Remove(preview);
            installPreviewPlacementSequencesByPreview.Remove(preview);
            installPreviewConveyorRotationSequenceIndexesByPreview.Remove(preview);
            installPreviewAnchorCoordinates.Remove(preview);
            installPreviewItemReservationsByPreview.Remove(preview);
            straightFirstConveyorPreviews.Remove(preview);
            if (activeInstallPreview == preview)
            {
                activeInstallPreview = null;
                installPreviewQuarterTurns = 0;
            }

            DestroyInstallPreviewObject(preview);
        }

        EnsureValidActiveInstallPreview();
        RefreshInstallOrEditWorkableRangeVisualRequest();
        if (installPreviewInstances.Count <= 0)
        {
            ClearInstallPreview();
            return;
        }

        InvalidateInstallGrid();
        RefreshTrainInstallPreviewTints();
    }

    private void EnsureValidActiveInstallPreview()
    {
        if (activeInstallPreview != null)
        {
            return;
        }

        CleanupInstallPreviewReferences();
        if (installPreviewInstances.Count <= 0)
        {
            installPreviewQuarterTurns = 0;
            return;
        }

        SelectInstallPreview(installPreviewInstances[installPreviewInstances.Count - 1]);
    }

    private bool IsInstallationModeActive()
    {
        return GameManager.Instance != null
               && GameManager.Instance.InstallationPlacementActive
               && activeInstallDefinition != null;
    }

    private bool IsInstallGridModeActive()
    {
        return IsInstallationModeActive() || mapEditModeActive;
    }

    private void InvalidateInstallGrid()
    {
        installGridDirty = true;
        installGridPreviewDirty = true;
    }

    private void InvalidateInstallGridPreview()
    {
        installGridPreviewDirty = true;
    }

    private void InvalidateInstallPreviewMoveCache()
    {
        cachedInstallPreviewMovePreview = null;
        cachedInstallPreviewMoveBlock = null;
        cachedInstallPreviewMoveQuarterTurns = 0;
        cachedInstallPreviewMovePreviewCount = 0;
        cachedInstallPreviewMovePreserveRotation = false;
        cachedInstallPreviewMoveResult = false;
    }

    private bool TryUseCachedInstallPreviewMove(Block block, bool preserveRotation, out bool result)
    {
        result = false;
        if (ShouldBypassInstallPreviewMoveCacheForRailAlignment())
        {
            return false;
        }

        if (activeInstallPreview == null
            || block == null
            || cachedInstallPreviewMovePreview != activeInstallPreview
            || cachedInstallPreviewMoveBlock != block
            || cachedInstallPreviewMoveQuarterTurns != installPreviewQuarterTurns
            || cachedInstallPreviewMovePreviewCount != installPreviewInstances.Count
            || cachedInstallPreviewMovePreserveRotation != preserveRotation)
        {
            return false;
        }

        result = cachedInstallPreviewMoveResult;
        return true;
    }

    private bool ShouldBypassInstallPreviewMoveCacheForRailAlignment()
    {
        MapObject rotationSource = activeInstallPreview != null
            ? ResolveInstallPreviewRotationSource(activeInstallPreview)
            : activeInstallDefinition != null
                ? activeInstallDefinition.mapObject
                : null;
        return IsTrainSource(rotationSource);
    }

    private void CacheInstallPreviewMoveResult(Block block, bool result, bool preserveRotation)
    {
        if (activeInstallPreview == null || block == null)
        {
            InvalidateInstallPreviewMoveCache();
            return;
        }

        cachedInstallPreviewMovePreview = activeInstallPreview;
        cachedInstallPreviewMoveBlock = block;
        cachedInstallPreviewMoveQuarterTurns = installPreviewQuarterTurns;
        cachedInstallPreviewMovePreviewCount = installPreviewInstances.Count;
        cachedInstallPreviewMovePreserveRotation = preserveRotation;
        cachedInstallPreviewMoveResult = result;
    }

    private bool TryGetInstallPreviewAtBlock(Block block, out MapObject preview)
    {
        preview = null;
        if (block == null)
        {
            return false;
        }

        return TryGetInstallPreviewAtCoordinate(block.Coordinate, out preview);
    }

    private bool TryGetBlockForPreview(MapObject preview, out Block block)
    {
        block = null;
        if (preview == null)
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        if (!TryGetPreviewAnchorCoordinate(preview, out Vector2Int coordinate))
        {
            return false;
        }

        return terrain.TryGetLoadedBlock(coordinate, out block) && block != null;
    }

    private bool CanPlacePreviewOnBlock(
        Block block,
        MapObject previewToIgnore = null,
        int? quarterTurnsOverride = null,
        bool includeIgnoredPreviewAsConnector = false)
    {
        if (block == null)
        {
            return false;
        }

        int quarterTurns = quarterTurnsOverride ?? (previewToIgnore != null ? GetPreviewQuarterTurns(previewToIgnore) : installPreviewQuarterTurns);
        MapObject footprintSource = previewToIgnore != null
            ? previewToIgnore
            : (activeInstallDefinition != null ? activeInstallDefinition.mapObject : null);
        if (activeInstallDefinition != null && IsBelt2F(activeInstallDefinition.mapObject))
        {
            footprintSource = activeInstallDefinition.mapObject;
        }
        else if (activeInstallDefinition != null && activeInstallDefinition.mapObject is ConveyorBelt)
        {
            ConveyorPreviewVariantMode previewVariantMode = previewToIgnore == activeInstallPreview
                ? installPreviewConveyorVariantMode
                : GetConveyorPreviewVariantMode(previewToIgnore);
            footprintSource = ResolveInstalledObjectSourcePrefab(
                                  activeInstallDefinition,
                                  block.Coordinate,
                                  quarterTurns,
                                  previewToIgnore,
                                  previewVariantMode)
                              ?? footprintSource;
        }
        else if (activeInstallDefinition != null
                 && activeInstallDefinition.mapObject is Wall fencePrototype
                 && TryResolveFencePlacementVariant(
                     fencePrototype,
                     block.Coordinate,
                     quarterTurns,
                     previewToIgnore,
                     out MapObject fenceSourcePrefab,
                     out int fenceQuarterTurns))
        {
            footprintSource = fenceSourcePrefab ?? footprintSource;
            quarterTurns = fenceQuarterTurns;
        }
        else if (activeInstallDefinition != null
                 && activeInstallDefinition.mapObject is Pipe pipePrototype)
        {
            footprintSource = ResolveInstallPreviewFootprintSource(previewToIgnore)
                              ?? pipePrototype.StraightVariantPrefab
                              ?? footprintSource;
        }

        if (footprintSource == null)
        {
            return false;
        }

        if (IsTrainSource(footprintSource))
        {
            Vector3 referencePosition = previewToIgnore != null
                ? previewToIgnore.transform.position
                : block.transform.position;
            if (previewToIgnore != null
                && installPreviewRailReferenceWorldPositions.TryGetValue(previewToIgnore, out Vector3 storedRailReferencePosition))
            {
                referencePosition = storedRailReferencePosition;
            }

            return TryResolveTrainRailPlacementPose(
                footprintSource,
                block.Coordinate,
                quarterTurns,
                referencePosition,
                out _,
                out _);
        }

        if (!TryGetFootprintBlocks(
                block.Coordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore,
                out _,
                false,
                includeIgnoredPreviewAsConnector))
        {
            return !IsBelt2F(footprintSource)
                   && CanPlaceStraightConveyorPreviewOnBlock(block, previewToIgnore, quarterTurns);
        }

        if (IsBoilerSource(footprintSource)
            && IsExactPumpOutputCoordinateForPlacement(block.Coordinate)
            && TryGetBoilerPumpOutputDirectionMatch(
                footprintSource,
                block.Coordinate,
                quarterTurns,
                out bool pumpOutputDirectionMatches))
        {
            return pumpOutputDirectionMatches;
        }

        if (!CanProposedFluidStoragePipeAreaConnectionsMatchExisting(
                block.Coordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore,
                includeIgnoredPreviewAsConnector))
        {
            return false;
        }

        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is ConveyorBelt conveyorPrototype))
        {
            return true;
        }

        ConveyorBelt cornerConveyor = footprintSource is ConveyorBelt footprintConveyor && footprintConveyor.IsCornerVariant
            ? footprintConveyor
            : null;

        if (cornerConveyor == null)
        {
            return conveyorPrototype != null;
        }

        return true;
    }

    private bool CanPlaceStraightConveyorPreviewOnBlock(Block block, MapObject previewToIgnore, int quarterTurns)
    {
        if (block == null
            || !CanUseStraightConveyorFallback(previewToIgnore)
            || !TryResolveStraightConveyorPlacementSource(out MapObject sourcePrefab))
        {
            return false;
        }

        return TryGetFootprintBlocks(
            block.Coordinate,
            sourcePrefab,
            NormalizePlacementQuarterTurns(quarterTurns),
            previewToIgnore,
            out _);
    }

    private bool CanUseStraightConveyorFallback(MapObject preview)
    {
        if (activeInstallDefinition == null
            || !(activeInstallDefinition.mapObject is ConveyorBelt)
            || IsBelt2F(activeInstallDefinition.mapObject))
        {
            return false;
        }

        if (preview == null)
        {
            return true;
        }

        if (preview == activeInstallPreview && installPreviewConveyorVariantMode == ConveyorPreviewVariantMode.Straight)
        {
            return true;
        }

        return preview is ConveyorBelt conveyorPreview && !conveyorPreview.IsCornerVariant;
    }

    private bool TryResolveStraightConveyorPlacementSource(out MapObject sourcePrefab)
    {
        sourcePrefab = null;
        if (activeInstallDefinition == null || !(activeInstallDefinition.mapObject is ConveyorBelt conveyorPrototype))
        {
            return false;
        }

        sourcePrefab = ResolveConveyorVariantPrefab(conveyorPrototype, 0) ?? conveyorPrototype;
        return sourcePrefab is ConveyorBelt straightConveyor && !straightConveyor.IsCornerVariant;
    }

    private bool TryFindPlaceableInstallPreviewQuarterTurns(
        Block block,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (block == null)
        {
            return false;
        }

        if (TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject waterPumpFootprintSource)
            && TryResolveWaterPumpOutwardQuarterTurns(
                block.Coordinate,
                waterPumpFootprintSource,
                resolvedQuarterTurns,
                out int waterPumpQuarterTurns)
            && CanPlacePreviewOnBlock(block, previewToIgnore, waterPumpQuarterTurns))
        {
            resolvedQuarterTurns = waterPumpQuarterTurns;
            return true;
        }

        if (IsConveyorInstallPreview(previewToIgnore)
            && TryResolveConveyorEndpointAlignedQuarterTurns(
                block.Coordinate,
                previewToIgnore,
                resolvedQuarterTurns,
                out int endpointAlignedQuarterTurns))
        {
            if (CanPlacePreviewOnBlock(block, previewToIgnore, endpointAlignedQuarterTurns)
                || CanPlaceStraightConveyorPreviewOnBlock(block, previewToIgnore, endpointAlignedQuarterTurns))
            {
                resolvedQuarterTurns = endpointAlignedQuarterTurns;
                return true;
            }
        }

        if (activeInstallDefinition != null
            && activeInstallDefinition.mapObject is Wall fencePrototype
            && TryResolveFencePlacementVariant(
                fencePrototype,
                block.Coordinate,
                resolvedQuarterTurns,
                previewToIgnore,
                out _,
                out int fenceResolvedQuarterTurns)
            && CanPlacePreviewOnBlock(block, previewToIgnore, fenceResolvedQuarterTurns))
        {
            resolvedQuarterTurns = fenceResolvedQuarterTurns;
            return true;
        }

        if (TryResolveSteamGeneratorPipeAlignedQuarterTurns(
                block,
                previewToIgnore,
                resolvedQuarterTurns,
                out int steamGeneratorPipeQuarterTurns))
        {
            resolvedQuarterTurns = steamGeneratorPipeQuarterTurns;
            return true;
        }

        if (CanUseBoilerEnergyInputRotationCandidate(block.Coordinate, previewToIgnore, resolvedQuarterTurns)
            && CanPlacePreviewOnBlock(block, previewToIgnore, resolvedQuarterTurns))
        {
            return true;
        }

        if (CanUseBoilerEnergyInputRotationCandidate(block.Coordinate, previewToIgnore, resolvedQuarterTurns)
            && CanPlaceDisconnectedFluidStoragePreviewOnBlock(
                block,
                previewToIgnore,
                resolvedQuarterTurns))
        {
            return true;
        }

        if (IsConveyorInstallPreview(previewToIgnore))
        {
            if (CanPlaceStraightConveyorPreviewOnBlock(block, previewToIgnore, resolvedQuarterTurns))
            {
                return true;
            }

            return false;
        }

        int candidateCount = UsesTwoStateInstallPreviewRotation(previewToIgnore)
            ? 2
            : GetPlacementRotationCandidateCount(previewToIgnore);
        for (int offset = 1; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                resolvedQuarterTurns + offset);
            if (!CanUseBoilerEnergyInputRotationCandidate(block.Coordinate, previewToIgnore, candidateQuarterTurns)
                || (!CanPlacePreviewOnBlock(block, previewToIgnore, candidateQuarterTurns)
                && !CanPlaceDisconnectedFluidStoragePreviewOnBlock(
                    block,
                    previewToIgnore,
                    candidateQuarterTurns)))
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool CanPlaceDisconnectedFluidStoragePreviewOnBlock(
        Block block,
        MapObject previewToIgnore,
        int quarterTurns)
    {
        if (block == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !TryResolveInstallationObject(footprintSource, out InstallationObject installationObject)
            || installationObject is Pipe
            || installationObject is Pump
            || !installationObject.CanStoreFluid
            || PlacementHasExternalFluidConnector(
                block.Coordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore))
        {
            return false;
        }

        return TryGetFootprintBlocks(
            block.Coordinate,
            footprintSource,
            quarterTurns,
            previewToIgnore,
            out _);
    }

    private bool PlacementHasExternalFluidConnector(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (footprintSource == null
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int pipeAreaCoordinate))
            {
                continue;
            }

            if (CoordinateHasExternalFluidConnector(pipeAreaCoordinate, previewToIgnore))
            {
                return true;
            }

            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                if (CoordinateHasExternalFluidConnector(
                        pipeAreaCoordinate + PipeCardinalDirections[directionIndex],
                        previewToIgnore))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool CoordinateHasExternalFluidConnector(Vector2Int coordinate, MapObject previewToIgnore)
    {
        if (TryGetPipePlacementAtCoordinate(coordinate, out _, out _))
        {
            return true;
        }

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);
        bool hasConnector = false;
        for (int i = 0; i < pipeAreaBlockCandidateScratchA.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipeAreaBlockCandidateScratchA[i];
            if (IsIgnoredFluidConnectorSnapshot(candidate.snapshot, previewToIgnore))
            {
                continue;
            }

            hasConnector = true;
            break;
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return hasConnector;
    }

    private bool IsIgnoredFluidConnectorSnapshot(PlacementSnapshot snapshot, MapObject previewToIgnore)
    {
        if (snapshot == null || snapshot.mapObject == null)
        {
            return true;
        }

        if (SnapshotBelongsToMapObject(snapshot, previewToIgnore))
        {
            return true;
        }

        InstallationObject originalInstallation = activeInstallationEditSession != null
            ? activeInstallationEditSession.originalInstallation
            : null;
        return SnapshotBelongsToMapObject(snapshot, originalInstallation);
    }

    private static bool SnapshotBelongsToMapObject(PlacementSnapshot snapshot, MapObject mapObject)
    {
        if (snapshot == null || snapshot.mapObject == null || mapObject == null)
        {
            return false;
        }

        if (snapshot.mapObject == mapObject)
        {
            return true;
        }

        Transform snapshotTransform = snapshot.mapObject.transform;
        Transform mapObjectTransform = mapObject.transform;
        if (snapshotTransform == null || mapObjectTransform == null)
        {
            return false;
        }

        return snapshotTransform == mapObjectTransform
               || snapshotTransform.IsChildOf(mapObjectTransform)
               || mapObjectTransform.IsChildOf(snapshotTransform);
    }

    private bool TryGetAdjacentBoilerInitialQuarterTurns(
        Vector2Int targetCoordinate,
        MapObject previewToIgnore,
        out int quarterTurns)
    {
        quarterTurns = 0;
        if (!TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsBoilerSource(footprintSource))
        {
            return false;
        }

        if (!TryGetNearbyBoilerPlacementQuarterTurns(
                targetCoordinate,
                previewToIgnore,
                out int nearbyBoilerQuarterTurns))
        {
            return false;
        }

        quarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            nearbyBoilerQuarterTurns);
        return true;
    }

    private bool TryGetNearbyBoilerPlacementQuarterTurns(
        Vector2Int targetCoordinate,
        MapObject previewToIgnore,
        out int quarterTurns)
    {
        if (TryGetBoilerPipePassPlacementQuarterTurnsAtCoordinate(
                targetCoordinate,
                previewToIgnore,
                out quarterTurns)
            || TryGetBoilerObjectPlacementQuarterTurnsAtCoordinate(
                targetCoordinate,
                previewToIgnore,
                out quarterTurns))
        {
            return true;
        }

        for (int distance = 1; distance <= 2; distance++)
        {
            for (int i = 0; i < PipeCardinalDirections.Length; i++)
            {
                Vector2Int direction = PipeCardinalDirections[i];
                Vector2Int probeCoordinate = new Vector2Int(
                    targetCoordinate.x + direction.x * distance,
                    targetCoordinate.y + direction.y * distance);

                if (TryGetBoilerObjectPlacementQuarterTurnsAtCoordinate(
                        probeCoordinate,
                        previewToIgnore,
                        out quarterTurns)
                    || TryGetBoilerPipePassPlacementQuarterTurnsAtCoordinate(
                        probeCoordinate,
                        previewToIgnore,
                        out quarterTurns))
                {
                    return true;
                }
            }
        }

        quarterTurns = 0;
        return false;
    }

    private bool TryGetBoilerObjectPlacementQuarterTurnsAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out int quarterTurns)
    {
        quarterTurns = 0;
        if (!TryGetBoilerObjectPlacementSnapshotAtCoordinate(
                coordinate,
                previewToIgnore,
                out PlacementSnapshot snapshot))
        {
            return false;
        }

        quarterTurns = snapshot.quarterTurns;
        return true;
    }

    private bool TryGetBoilerObjectPlacementSnapshotAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out PlacementSnapshot snapshot)
    {
        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out snapshot)
            && IsBoilerObjectSnapshotAtCoordinate(snapshot, coordinate))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out snapshot)
            && IsBoilerObjectSnapshotAtCoordinate(snapshot, coordinate))
        {
            return true;
        }

        if (TryGetRuntimeGridPlacementSnapshot(coordinate, out snapshot)
            && IsBoilerObjectSnapshotAtCoordinate(snapshot, coordinate))
        {
            return true;
        }

        if (TryGetRuntimeAreaPlacementSnapshot(coordinate, out snapshot)
            && IsBoilerObjectSnapshotAtCoordinate(snapshot, coordinate))
        {
            return true;
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out snapshot)
            && IsBoilerObjectSnapshotAtCoordinate(snapshot, coordinate))
        {
            return true;
        }

        snapshot = null;
        return false;
    }

    private bool IsBoilerObjectSnapshotAtCoordinate(PlacementSnapshot snapshot, Vector2Int coordinate)
    {
        return snapshot != null
               && IsBoilerSource(snapshot.mapObject)
               && SnapshotHasRectGridObjectBlock(snapshot, coordinate);
    }

    private bool TryGetBoilerPipePassPlacementQuarterTurnsAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out int quarterTurns)
    {
        quarterTurns = 0;
        pipeAreaBlockCandidateScratchB.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchB);

        for (int i = 0; i < pipeAreaBlockCandidateScratchB.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipeAreaBlockCandidateScratchB[i];
            if (candidate.snapshot == null
                || !IsBoilerSource(candidate.snapshot.mapObject)
                || !IsPipePassBlockType(candidate.blockType))
            {
                continue;
            }

            quarterTurns = candidate.snapshot.quarterTurns;
            pipeAreaBlockCandidateScratchB.Clear();
            return true;
        }

        pipeAreaBlockCandidateScratchB.Clear();
        return false;
    }

    private bool TryResolveFixedRotationInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = clickedBlock;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource))
        {
            return false;
        }

        if (IsBelt2F(footprintSource))
        {
            TerrainGenerator terrain = ResolveInstallPreviewTerrain();
            Vector2Int bridgeCenterOffset = GetBelt2FBridgeCenterOffset(footprintSource, resolvedQuarterTurns);
            Vector2Int candidateAnchorCoordinate = clickedBlock.Coordinate - bridgeCenterOffset;
            if (terrain != null
                && terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                && candidateAnchorBlock != null
                && CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, resolvedQuarterTurns))
            {
                anchorBlock = candidateAnchorBlock;
                return true;
            }

            return false;
        }

        if (TryResolveFixedRotationSteamGeneratorChainTarget(
                clickedBlock,
                previewToIgnore,
                resolvedQuarterTurns,
                out anchorBlock))
        {
            return true;
        }

        if (TryResolveBoilerPipeConnectionInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                resolvedQuarterTurns,
                false,
                false,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (CanPlacePreviewOnBlock(clickedBlock, previewToIgnore, resolvedQuarterTurns))
        {
            anchorBlock = clickedBlock;
            return true;
        }

        if (TryFindFixedRotationItemAreaOverlapInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                resolvedQuarterTurns,
                out anchorBlock))
        {
            return true;
        }

        return TryFindFixedRotationMultiCellInstallPreviewTarget(
            clickedBlock,
            previewToIgnore,
            resolvedQuarterTurns,
            out anchorBlock);
    }

    private bool TryResolveFixedRotationSteamGeneratorChainTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int quarterTurns,
        out Block anchorBlock)
    {
        anchorBlock = null;
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out _))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        int searchRadius = Mathf.Max(4, Mathf.Max(rectGridWidth, rectGridHeight) + 1);
        int bestScore = int.MaxValue;
        Block bestAnchorBlock = null;
        for (int z = -searchRadius; z <= searchRadius; z++)
        {
            for (int x = -searchRadius; x <= searchRadius; x++)
            {
                Vector2Int connectorCoordinate = clickedBlock.Coordinate + new Vector2Int(x, z);
                pipeAreaBlockCandidateScratchC.Clear();
                CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
                    connectorCoordinate,
                    previewToIgnore,
                    pipeAreaBlockCandidateScratchC);

                for (int candidateIndex = 0; candidateIndex < pipeAreaBlockCandidateScratchC.Count; candidateIndex++)
                {
                    PipeAreaBlockCandidate existingCandidate = pipeAreaBlockCandidateScratchC[candidateIndex];
                    if (!TryResolveFixedRotationSteamGeneratorChainCandidate(
                            clickedBlock.Coordinate,
                            connectorCoordinate,
                            existingCandidate,
                            footprintSource,
                            terrain,
                            previewToIgnore,
                            quarterTurns,
                            out Block candidateAnchorBlock))
                    {
                        continue;
                    }

                    int score = Mathf.Abs(connectorCoordinate.x - clickedBlock.Coordinate.x)
                        + Mathf.Abs(connectorCoordinate.y - clickedBlock.Coordinate.y);
                    if (bestAnchorBlock != null && score >= bestScore)
                    {
                        continue;
                    }

                    bestScore = score;
                    bestAnchorBlock = candidateAnchorBlock;
                }
            }
        }

        pipeAreaBlockCandidateScratchC.Clear();
        anchorBlock = bestAnchorBlock;
        return anchorBlock != null;
    }

    private bool TryResolveFixedRotationSteamGeneratorChainCandidate(
        Vector2Int clickedCoordinate,
        Vector2Int connectorCoordinate,
        PipeAreaBlockCandidate existingCandidate,
        MapObject footprintSource,
        TerrainGenerator terrain,
        MapObject previewToIgnore,
        int quarterTurns,
        out Block anchorBlock)
    {
        anchorBlock = null;
        if (existingCandidate.snapshot == null
            || !IsSteamGeneratorSource(existingCandidate.snapshot.mapObject)
            || !TryGetSteamGeneratorPipePassTailDirection(
                connectorCoordinate,
                existingCandidate,
                out Vector2Int existingTailDirection)
            || !TryGetSteamGeneratorBodyDirectionFromCenter(
                footprintSource,
                quarterTurns,
                out Vector2Int proposedTailDirection)
            || proposedTailDirection != existingTailDirection)
        {
            return false;
        }

        Vector2Int candidateAnchorCoordinate = connectorCoordinate;
        if (!SteamGeneratorChainPlacementContainsCoordinate(
                clickedCoordinate,
                candidateAnchorCoordinate,
                footprintSource,
                quarterTurns)
            || !terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
            || candidateAnchorBlock == null
            || !CanPlacePreviewOnBlock(
                candidateAnchorBlock,
                previewToIgnore,
                quarterTurns,
                true))
        {
            return false;
        }

        anchorBlock = candidateAnchorBlock;
        return true;
    }

    private bool TryFindFixedRotationItemAreaOverlapInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int quarterTurns,
        out Block anchorBlock)
    {
        anchorBlock = null;
        if (clickedBlock == null
            || !CoordinateHasInputOutputAreaForPlacement(clickedBlock.Coordinate, null)
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            bool canUsePlacementForAreaOverlap = IsRectGridAreaBlockType(placement.blockType)
                || CanUseObjectPlacementForFluidStorageAreaOverlap(
                    footprintSource,
                    placement.blockType,
                    clickedBlock.Coordinate);
            if (!canUsePlacementForAreaOverlap
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight)
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int candidateAnchorCoordinate =
                clickedBlock.Coordinate - RotateFootprintOffset(localOffset, quarterTurns);
            if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                || candidateAnchorBlock == null
                || PlacementHasBoilerEnergyInputPipeConflict(
                    candidateAnchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    previewToIgnore)
                || PlacementHasNormalInputOutputAreaPipeOverlap(
                    candidateAnchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    previewToIgnore)
                || !CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, quarterTurns))
            {
                continue;
            }

            anchorBlock = candidateAnchorBlock;
            return true;
        }

        return false;
    }

    private bool TryFindFixedRotationMultiCellInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int quarterTurns,
        out Block anchorBlock)
    {
        anchorBlock = null;
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !HasMultiCellMapSize(footprintSource)
            || IsBelt2F(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        List<Vector2Int> localOffsets = GetFootprintLocalOffsets(footprintSource, quarterTurns);
        for (int i = 0; i < localOffsets.Count; i++)
        {
            Vector2Int localOffset = localOffsets[i];
            if (localOffset == Vector2Int.zero)
            {
                continue;
            }

            Vector2Int candidateAnchorCoordinate = clickedBlock.Coordinate - localOffset;
            if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                || candidateAnchorBlock == null
                || PlacementHasBoilerEnergyInputPipeConflict(
                    candidateAnchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    previewToIgnore)
                || PlacementHasNormalInputOutputAreaPipeOverlap(
                    candidateAnchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    previewToIgnore)
                || !CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, quarterTurns))
            {
                continue;
            }

            anchorBlock = candidateAnchorBlock;
            return true;
        }

        return false;
    }

    private bool TryResolvePlaceableInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = clickedBlock;
        resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null)
        {
            return false;
        }

        if (TryGetAdjacentBoilerInitialQuarterTurns(
                clickedBlock.Coordinate,
                previewToIgnore,
                out int adjacentBoilerQuarterTurns))
        {
            preferredQuarterTurns = adjacentBoilerQuarterTurns;
            resolvedQuarterTurns = adjacentBoilerQuarterTurns;
        }

        if (TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            && IsBelt2F(footprintSource))
        {
            return TryResolveBelt2FBridgeCenterInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                out anchorBlock,
                out resolvedQuarterTurns);
        }

        if (TryResolveBelt2FBridgeCenterInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveSteamGeneratorOnBoilerOutputInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveSteamGeneratorOnPipePassInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveSteamGeneratorOnPipeInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveSteamGeneratorBesidePipeInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveSteamGeneratorChainInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveBoilerOnSteamGeneratorInputInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveBoilerOnPumpOutputInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveBoilerPipeConnectionInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                true,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (TryResolveBoilerOnBoilerPipePassInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                includeIgnoredPreviewAsConnector,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        if (includeIgnoredPreviewAsConnector
            && CoordinateHasInputOutputAreaForPlacement(clickedBlock.Coordinate, null))
        {
            return TryFindPlaceableItemAreaOverlapInstallPreviewTarget(
                clickedBlock,
                null,
                preferredQuarterTurns,
                out anchorBlock,
                out resolvedQuarterTurns);
        }

        bool isMultiCellPreview =
            TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject previewFootprintSource)
            && HasMultiCellMapSize(previewFootprintSource)
            && !IsBelt2F(previewFootprintSource);

        if (TryFindPlaceableInstallPreviewQuarterTurns(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                out resolvedQuarterTurns))
        {
            anchorBlock = clickedBlock;
            return true;
        }

        if (isMultiCellPreview)
        {
            if (TryFindPlaceableItemAreaOverlapInstallPreviewTarget(
                    clickedBlock,
                    previewToIgnore,
                    preferredQuarterTurns,
                    out anchorBlock,
                    out resolvedQuarterTurns))
            {
                return true;
            }

            if (TryFindPlaceableMultiCellInstallPreviewTarget(
                    clickedBlock,
                    previewToIgnore,
                    preferredQuarterTurns,
                    out anchorBlock,
                    out resolvedQuarterTurns))
            {
                return true;
            }
        }

        if (TryFindPlaceableItemAreaOverlapInstallPreviewTarget(
                clickedBlock,
                previewToIgnore,
                preferredQuarterTurns,
                out anchorBlock,
                out resolvedQuarterTurns))
        {
            return true;
        }

        return !isMultiCellPreview
               && TryFindPlaceableMultiCellInstallPreviewTarget(
                   clickedBlock,
                   previewToIgnore,
                   preferredQuarterTurns,
                   out anchorBlock,
                   out resolvedQuarterTurns);
    }

    private bool TryResolveBelt2FBridgeCenterInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsBelt2F(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                resolvedQuarterTurns + offset);
            Vector2Int bridgeCenterOffset = GetBelt2FBridgeCenterOffset(footprintSource, candidateQuarterTurns);
            Vector2Int candidateAnchorCoordinate = clickedBlock.Coordinate - bridgeCenterOffset;
            if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                || candidateAnchorBlock == null
                || !CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, candidateQuarterTurns))
            {
                continue;
            }

            anchorBlock = candidateAnchorBlock;
            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool TryResolveSteamGeneratorChainInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out _))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        int searchRadius = Mathf.Max(4, Mathf.Max(rectGridWidth, rectGridHeight) + 1);
        bool foundCandidate = false;
        int bestScore = int.MaxValue;
        Block bestAnchorBlock = null;
        int bestQuarterTurns = resolvedQuarterTurns;
        for (int z = -searchRadius; z <= searchRadius; z++)
        {
            for (int x = -searchRadius; x <= searchRadius; x++)
            {
                Vector2Int connectorCoordinate = clickedBlock.Coordinate + new Vector2Int(x, z);
                pipeAreaBlockCandidateScratchC.Clear();
                CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
                    connectorCoordinate,
                    connectorPreviewToIgnore,
                    pipeAreaBlockCandidateScratchC);

                for (int candidateIndex = 0; candidateIndex < pipeAreaBlockCandidateScratchC.Count; candidateIndex++)
                {
                    PipeAreaBlockCandidate existingCandidate = pipeAreaBlockCandidateScratchC[candidateIndex];
                    if (!TryResolveSteamGeneratorStraightChainCandidate(
                            clickedBlock.Coordinate,
                            connectorCoordinate,
                            existingCandidate,
                            footprintSource,
                            terrain,
                            previewToIgnore,
                            out Block candidateAnchorBlock,
                            out int candidateQuarterTurns))
                    {
                        continue;
                    }

                    int score = Mathf.Abs(connectorCoordinate.x - clickedBlock.Coordinate.x)
                        + Mathf.Abs(connectorCoordinate.y - clickedBlock.Coordinate.y);
                    if (!foundCandidate || score < bestScore)
                    {
                        foundCandidate = true;
                        bestScore = score;
                        bestAnchorBlock = candidateAnchorBlock;
                        bestQuarterTurns = candidateQuarterTurns;
                    }
                }
            }
        }

        pipeAreaBlockCandidateScratchC.Clear();
        if (!foundCandidate)
        {
            return false;
        }

        anchorBlock = bestAnchorBlock;
        resolvedQuarterTurns = bestQuarterTurns;
        return anchorBlock != null;
    }

    private bool TryResolveSteamGeneratorStraightChainCandidate(
        Vector2Int clickedCoordinate,
        Vector2Int connectorCoordinate,
        PipeAreaBlockCandidate existingCandidate,
        MapObject footprintSource,
        TerrainGenerator terrain,
        MapObject previewToIgnore,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = 0;
        if (existingCandidate.snapshot == null
            || !IsSteamGeneratorSource(existingCandidate.snapshot.mapObject)
            || !IsPipePassBlockType(existingCandidate.blockType)
            || terrain == null)
        {
            return false;
        }

        resolvedQuarterTurns = NormalizePlacementQuarterTurnsForObject(
            footprintSource,
            existingCandidate.snapshot.quarterTurns);

        if (!TryGetPipeAreaObjectDirection(
                connectorCoordinate,
                existingCandidate,
                out Vector2Int pipePassObjectDirection))
        {
            return false;
        }

        Vector2Int existingTailDirection = -pipePassObjectDirection;
        if (existingTailDirection == Vector2Int.zero
            || !TryGetSteamGeneratorBodyDirectionFromCenter(
                footprintSource,
                resolvedQuarterTurns,
                out Vector2Int proposedTailDirection)
            || proposedTailDirection != existingTailDirection)
        {
            return false;
        }

        Vector2Int candidateAnchorCoordinate = connectorCoordinate;
        if (!SteamGeneratorChainPlacementContainsCoordinate(
                clickedCoordinate,
                candidateAnchorCoordinate,
                footprintSource,
                resolvedQuarterTurns)
            || !terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
            || candidateAnchorBlock == null)
        {
            return false;
        }

        if (!CanPlacePreviewOnBlock(
                candidateAnchorBlock,
                previewToIgnore,
                resolvedQuarterTurns,
                true))
        {
            return false;
        }

        anchorBlock = candidateAnchorBlock;
        return true;
    }

    private bool SteamGeneratorChainPlacementContainsCoordinate(
        Vector2Int coordinate,
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        if (coordinate == anchorCoordinate)
        {
            return true;
        }

        List<Vector2Int> visualCoordinates = GetPlacementVisualCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        for (int i = 0; i < visualCoordinates.Count; i++)
        {
            if (visualCoordinates[i] == coordinate)
            {
                return true;
            }
        }

        return TryGetRectGridFootprintBlockType(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            coordinate,
            out InputOutputModule.RectGridBlockType blockType)
            && blockType != InputOutputModule.RectGridBlockType.None;
    }

    private bool TryResolveSteamGeneratorOnBoilerOutputInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                footprintSource,
                preferredQuarterTurns + offset);

            for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
                if (placement.blockType != InputOutputModule.RectGridBlockType.Object
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || !TryGetSteamGeneratorDirectBoilerOutputPlacement(
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        connectorPreviewToIgnore,
                        out _,
                        out _)
                    || !CanPlacePreviewOnBlock(
                        candidateAnchorBlock,
                        previewToIgnore,
                        candidateQuarterTurns,
                        includeIgnoredPreviewAsConnector))
                {
                    continue;
                }

                anchorBlock = candidateAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool TryResolveSteamGeneratorOnPipePassInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        List<PipeAreaBlockCandidate> pipePassCandidates =
            CollectPipePassCandidatesAtCoordinate(clickedBlock.Coordinate, connectorPreviewToIgnore);
        if (pipePassCandidates.Count <= 0)
        {
            return false;
        }

        if (!TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int passIndex = 0; passIndex < pipePassCandidates.Count; passIndex++)
        {
            PipeAreaBlockCandidate pipePassCandidate = pipePassCandidates[passIndex];
            if (pipePassCandidate.snapshot != null
                && IsSteamGeneratorSource(pipePassCandidate.snapshot.mapObject))
            {
                continue;
            }

            if (!TryGetPipeAreaObjectDirection(
                    clickedBlock.Coordinate,
                    pipePassCandidate,
                    out Vector2Int pipePassObjectDirection))
            {
                continue;
            }

            Vector2Int requiredInputDirection = -pipePassObjectDirection;
            for (int offset = 0; offset < candidateCount; offset++)
            {
                int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                    footprintSource,
                    preferredQuarterTurns + offset);
                if (!TryGetSteamGeneratorBodyDirectionFromCenter(
                        footprintSource,
                        candidateQuarterTurns,
                        out Vector2Int adjacentBodyDirection)
                    || adjacentBodyDirection != requiredInputDirection)
                {
                    continue;
                }

                for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
                {
                    InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
                    if (!InputOutputModule.IsInputItemBlockType(placement.blockType)
                        || placement.x < 0
                        || placement.x >= rectGridWidth
                        || placement.y < 0
                        || placement.y >= rectGridHeight)
                    {
                        continue;
                    }

                    Vector2Int localOffset = new Vector2Int(
                        placement.x - objectAnchorCell.x,
                        placement.y - objectAnchorCell.y);
                    Vector2Int candidateAnchorCoordinate =
                        clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                    if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                        || candidateAnchorBlock == null)
                    {
                        continue;
                    }

                    PlacementSnapshot proposedSnapshot = new PlacementSnapshot
                    {
                        mapObject = footprintSource,
                        rotation = GetPlacementObjectRotation(footprintSource, candidateQuarterTurns),
                        anchorCoordinate = candidateAnchorCoordinate,
                        quarterTurns = candidateQuarterTurns
                    };
                    PipeAreaBlockCandidate proposedInputCandidate =
                        new PipeAreaBlockCandidate(proposedSnapshot, placement.blockType);
                    if (!CanPipeAreaBlockCandidatesConnect(
                            clickedBlock.Coordinate,
                            pipePassCandidate,
                            clickedBlock.Coordinate,
                            proposedInputCandidate)
                        || !CanPlacePreviewOnBlock(
                            candidateAnchorBlock,
                            previewToIgnore,
                            candidateQuarterTurns,
                            includeIgnoredPreviewAsConnector))
                    {
                        continue;
                    }

                    anchorBlock = candidateAnchorBlock;
                    resolvedQuarterTurns = candidateQuarterTurns;
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryResolveSteamGeneratorOnPipeInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(clickedBlock);

        if (!TryGetPipePlacementAtBlock(clickedBlock, occupyingObject, out Pipe pipe, out Quaternion pipeRotation))
        {
            return false;
        }

        if (!TryGetStraightPipeAxis(pipe, pipeRotation, out Vector2Int pipeAxisDirection))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                footprintSource,
                preferredQuarterTurns + offset);
            if (!TryGetSteamGeneratorBodyDirectionFromCenter(
                    footprintSource,
                    candidateQuarterTurns,
                    out Vector2Int bodyDirection)
                || !DirectionsShareAxis(bodyDirection, pipeAxisDirection))
            {
                continue;
            }

            for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
                if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || !SteamGeneratorPipeAreaDirectionMatchesPipe(
                        footprintSource,
                        inputOutputModule,
                        candidateAnchorCoordinate,
                        candidateQuarterTurns,
                        clickedBlock.Coordinate,
                        pipeAxisDirection)
                    || !CanPlacePreviewOnBlock(
                        candidateAnchorBlock,
                        previewToIgnore,
                        candidateQuarterTurns,
                        includeIgnoredPreviewAsConnector))
                {
                    continue;
                }

                anchorBlock = candidateAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool TryResolveSteamGeneratorBesidePipeInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        const int maxSteamGeneratorCenterPipeProbeDistance = 2;
        for (int distance = 1; distance <= maxSteamGeneratorCenterPipeProbeDistance; distance++)
        {
            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                Vector2Int directionToPipe = PipeCardinalDirections[directionIndex];
                Vector2Int pipeCoordinate = clickedBlock.Coordinate
                    + new Vector2Int(directionToPipe.x * distance, directionToPipe.y * distance);
                if (!terrain.TryGetLoadedBlock(pipeCoordinate, out Block pipeBlock)
                    || pipeBlock == null)
                {
                    continue;
                }

                MapObject occupyingObject = GetOccupyingObjectForPlacement(pipeBlock);

                if (!TryGetPipePlacementAtBlock(pipeBlock, occupyingObject, out Pipe pipe, out Quaternion pipeRotation)
                    || !TryGetStraightPipeAxis(pipe, pipeRotation, out Vector2Int pipeAxisDirection)
                    || !DirectionsShareAxis(pipeAxisDirection, directionToPipe)
                    || !TryResolveSteamGeneratorCenterAtPipeCoordinate(
                        terrain,
                        footprintSource,
                        inputOutputModule,
                        placements,
                        rectGridWidth,
                        rectGridHeight,
                        objectAnchorCell,
                        clickedBlock,
                        pipeCoordinate,
                        pipeAxisDirection,
                        previewToIgnore,
                        preferredQuarterTurns,
                        includeIgnoredPreviewAsConnector,
                        out anchorBlock,
                        out resolvedQuarterTurns))
                {
                    continue;
                }

                return true;
            }
        }

        return false;
    }

    private bool TryResolveSteamGeneratorCenterAtPipeCoordinate(
        TerrainGenerator terrain,
        MapObject footprintSource,
        InputOutputModule inputOutputModule,
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements,
        int rectGridWidth,
        int rectGridHeight,
        Vector2Int objectAnchorCell,
        Block centerBlock,
        Vector2Int pipeCoordinate,
        Vector2Int pipeAxisDirection,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (terrain == null
            || footprintSource == null
            || inputOutputModule == null
            || placements == null
            || placements.Count <= 0
            || centerBlock == null
            || pipeAxisDirection == Vector2Int.zero)
        {
            return false;
        }

        Vector2Int centerToPipe = pipeCoordinate - centerBlock.Coordinate;
        if (!TryGetCardinalDirectionAndDistance(
                centerToPipe,
                out Vector2Int directionToPipe,
                out int pipeDistance)
            || pipeDistance > 2
            || !DirectionsShareAxis(directionToPipe, pipeAxisDirection))
        {
            return false;
        }

        Vector2Int requiredBodyDirection = pipeDistance == 1
            ? -directionToPipe
            : directionToPipe;
        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                footprintSource,
                preferredQuarterTurns + offset);
            if (!TryGetSteamGeneratorBodyDirectionFromCenter(
                    footprintSource,
                    candidateQuarterTurns,
                    out Vector2Int bodyDirection)
                || bodyDirection != requiredBodyDirection)
            {
                continue;
            }

            for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
                if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidatePipeCoordinate =
                    centerBlock.Coordinate + RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (candidatePipeCoordinate != pipeCoordinate
                    || !PlacementHasRectGridObjectCoordinate(
                        centerBlock.Coordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        centerBlock.Coordinate)
                    || !CanPlacePreviewOnBlock(
                        centerBlock,
                        previewToIgnore,
                        candidateQuarterTurns,
                        includeIgnoredPreviewAsConnector))
                {
                    continue;
                }

                anchorBlock = centerBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private static bool TryGetCardinalDirectionAndDistance(
        Vector2Int offset,
        out Vector2Int direction,
        out int distance)
    {
        direction = Vector2Int.zero;
        distance = Mathf.Abs(offset.x) + Mathf.Abs(offset.y);
        if (distance <= 0 || (offset.x != 0 && offset.y != 0))
        {
            return false;
        }

        direction = offset.x != 0
            ? new Vector2Int(offset.x > 0 ? 1 : -1, 0)
            : new Vector2Int(0, offset.y > 0 ? 1 : -1);
        return true;
    }

    private bool PlacementHasRectGridObjectCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        Vector2Int coordinate)
    {
        return TryGetRectGridFootprintBlockType(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns,
                   coordinate,
                   out InputOutputModule.RectGridBlockType blockType)
               && blockType == InputOutputModule.RectGridBlockType.Object;
    }

    private bool TryResolveBoilerOnSteamGeneratorInputInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsBoilerSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out _))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        if (terrain.TryGetLoadedBlock(clickedBlock.Coordinate, out Block clickedAnchorBlock)
            && clickedAnchorBlock != null)
        {
            for (int offset = 0; offset < candidateCount; offset++)
            {
                int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                    footprintSource,
                    preferredQuarterTurns + offset);
                if (!CanBoilerDirectSteamGeneratorInputConnection(
                        clickedBlock.Coordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        connectorPreviewToIgnore)
                    || PlacementHasBoilerEnergyInputPipeConflict(
                        clickedBlock.Coordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        connectorPreviewToIgnore)
                    || !CanPlacePreviewOnBlock(
                        clickedAnchorBlock,
                        previewToIgnore,
                        candidateQuarterTurns,
                        includeIgnoredPreviewAsConnector))
                {
                    continue;
                }

                anchorBlock = clickedAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        int bestScore = int.MaxValue;
        Block bestAnchorBlock = null;
        int bestQuarterTurns = resolvedQuarterTurns;
        bool foundCandidate = false;
        int searchRadius = 2;
        for (int z = -searchRadius; z <= searchRadius; z++)
        {
            for (int x = -searchRadius; x <= searchRadius; x++)
            {
                Vector2Int connectorCoordinate = clickedBlock.Coordinate + new Vector2Int(x, z);
                pipeAreaBlockCandidateScratchC.Clear();
                CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
                    connectorCoordinate,
                    connectorPreviewToIgnore,
                    pipeAreaBlockCandidateScratchC);

                for (int existingIndex = 0; existingIndex < pipeAreaBlockCandidateScratchC.Count; existingIndex++)
                {
                    PipeAreaBlockCandidate existingInputCandidate = pipeAreaBlockCandidateScratchC[existingIndex];
                    if (existingInputCandidate.snapshot == null
                        || !IsSteamGeneratorSource(existingInputCandidate.snapshot.mapObject)
                        || !InputOutputModule.IsInputItemBlockType(existingInputCandidate.blockType)
                        || !TryGetSteamGeneratorBodyDirectionFromCenter(
                            existingInputCandidate.snapshot.mapObject,
                            existingInputCandidate.snapshot.quarterTurns,
                            out Vector2Int steamBodyDirection)
                        || steamBodyDirection == Vector2Int.zero
                        || connectorCoordinate != existingInputCandidate.snapshot.anchorCoordinate - steamBodyDirection)
                    {
                        continue;
                    }

                    for (int offset = 0; offset < candidateCount; offset++)
                    {
                        int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                            footprintSource,
                            preferredQuarterTurns + offset);

                        Vector2Int candidateAnchorCoordinate = connectorCoordinate;
                        if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                            || candidateAnchorBlock == null)
                        {
                            continue;
                        }

                        if (!CanBoilerDirectSteamGeneratorInputConnection(
                                candidateAnchorCoordinate,
                                footprintSource,
                                candidateQuarterTurns,
                                previewToIgnore)
                            || PlacementHasBoilerEnergyInputPipeConflict(
                                candidateAnchorCoordinate,
                                footprintSource,
                                candidateQuarterTurns,
                                previewToIgnore)
                            || !CanPlacePreviewOnBlock(
                                candidateAnchorBlock,
                                previewToIgnore,
                                candidateQuarterTurns,
                                includeIgnoredPreviewAsConnector))
                        {
                            continue;
                        }

                        int score = Mathf.Abs(x) + Mathf.Abs(z);
                        if (!foundCandidate || score < bestScore)
                        {
                            foundCandidate = true;
                            bestScore = score;
                            bestAnchorBlock = candidateAnchorBlock;
                            bestQuarterTurns = candidateQuarterTurns;
                        }
                    }
                }
            }
        }

        pipeAreaBlockCandidateScratchC.Clear();
        if (!foundCandidate)
        {
            return false;
        }

        anchorBlock = bestAnchorBlock;
        resolvedQuarterTurns = bestQuarterTurns;
        return anchorBlock != null;
    }

    private bool TryResolveBoilerOnPumpOutputInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsBoilerSource(footprintSource)
            || !TryGetExactPumpOutputDirectionForPlacement(
                clickedBlock.Coordinate,
                out Vector2Int pumpOutputDirection)
            || pumpOutputDirection == Vector2Int.zero
            || !TryGetRectGridFootprintSettings(footprintSource, out _, out _, out _))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        // CRITICAL: Pump -> Boiler is an adjacent fluid-direction connection, not a
        // PipeOutput/PipePass same-cell overlap. The Boiler Object/anchor is allowed on
        // the pump OutputArea so the two machines are visually flush. Do not "fix"
        // this by separating the machines; only the pump-side Boiler PipePass direction
        // is allowed to constrain rotation.
        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                preferredQuarterTurns + offset);
            if (!BoilerPumpSidePipePassMatchesOutputDirection(
                    footprintSource,
                    clickedBlock.Coordinate,
                    clickedBlock.Coordinate,
                    candidateQuarterTurns,
                    pumpOutputDirection)
                || !CanPlacePreviewOnBlock(
                    clickedBlock,
                    previewToIgnore,
                    candidateQuarterTurns))
            {
                continue;
            }

            anchorBlock = clickedBlock;
            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool TryResolveBoilerOnBoilerPipePassInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsBoilerSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        if (!HasBoilerPipePassAtCoordinate(clickedBlock.Coordinate, connectorPreviewToIgnore))
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                footprintSource,
                preferredQuarterTurns + offset);
            for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
                if (placement.blockType != InputOutputModule.RectGridBlockType.Object
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || PlacementHasBoilerEnergyInputPipeConflict(
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore)
                    || !CanPlacePreviewOnBlock(
                        candidateAnchorBlock,
                        previewToIgnore,
                        candidateQuarterTurns,
                        includeIgnoredPreviewAsConnector))
                {
                    continue;
                }

                anchorBlock = candidateAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool TryResolveBoilerPipeConnectionInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        bool includeIgnoredPreviewAsConnector,
        bool allowRotationSearch,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsBoilerSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        int candidateCount = allowRotationSearch ? GetPlacementRotationCandidateCount(footprintSource) : 1;
        bool foundCandidate = false;
        int bestScore = int.MaxValue;
        Block bestAnchorBlock = null;
        int bestQuarterTurns = resolvedQuarterTurns;
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                footprintSource,
                preferredQuarterTurns + (allowRotationSearch ? offset : 0));

            TryConsiderBoilerPipeConnectionAnchor(
                clickedBlock,
                footprintSource,
                candidateQuarterTurns,
                previewToIgnore,
                connectorPreviewToIgnore,
                includeIgnoredPreviewAsConnector,
                0,
                ref foundCandidate,
                ref bestScore,
                ref bestAnchorBlock,
                ref bestQuarterTurns);

            TryConsiderBoilerPipeFlushConnectionAnchors(
                clickedBlock,
                terrain,
                footprintSource,
                candidateQuarterTurns,
                previewToIgnore,
                connectorPreviewToIgnore,
                includeIgnoredPreviewAsConnector,
                ref foundCandidate,
                ref bestScore,
                ref bestAnchorBlock,
                ref bestQuarterTurns);

            for (int placementIndex = 0; placementIndex < placements.Count; placementIndex++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[placementIndex];
                if (!IsPipePassBlockType(placement.blockType)
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(
                    placement.x - objectAnchorCell.x,
                    placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null)
                {
                    continue;
                }

                TryConsiderBoilerPipeConnectionAnchor(
                    candidateAnchorBlock,
                    footprintSource,
                    candidateQuarterTurns,
                    previewToIgnore,
                    connectorPreviewToIgnore,
                    includeIgnoredPreviewAsConnector,
                    1 + Mathf.Abs(localOffset.x) + Mathf.Abs(localOffset.y),
                    ref foundCandidate,
                    ref bestScore,
                    ref bestAnchorBlock,
                    ref bestQuarterTurns);
            }
        }

        if (!foundCandidate)
        {
            return false;
        }

        anchorBlock = bestAnchorBlock;
        resolvedQuarterTurns = bestQuarterTurns;
        return anchorBlock != null;
    }

    private void TryConsiderBoilerPipeFlushConnectionAnchors(
        Block clickedBlock,
        TerrainGenerator terrain,
        MapObject footprintSource,
        int candidateQuarterTurns,
        MapObject previewToIgnore,
        MapObject connectorPreviewToIgnore,
        bool includeIgnoredPreviewAsConnector,
        ref bool foundCandidate,
        ref int bestScore,
        ref Block bestAnchorBlock,
        ref int bestQuarterTurns)
    {
        if (clickedBlock == null || terrain == null || !IsBoilerSource(footprintSource))
        {
            return;
        }

        for (int pipeSearchIndex = 0; pipeSearchIndex <= PipeCardinalDirections.Length; pipeSearchIndex++)
        {
            Vector2Int pipeCoordinate = pipeSearchIndex == 0
                ? clickedBlock.Coordinate
                : clickedBlock.Coordinate + PipeCardinalDirections[pipeSearchIndex - 1];
            if (!TryGetPipePlacementAtCoordinate(pipeCoordinate, connectorPreviewToIgnore, out _, out _))
            {
                continue;
            }

            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                Vector2Int directionFromPipeToBody = PipeCardinalDirections[directionIndex];
                Vector2Int candidateAnchorCoordinate = pipeCoordinate + directionFromPipeToBody;
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || !TryGetBoilerPipePassDirectionAtCoordinate(
                        footprintSource,
                        candidateAnchorCoordinate,
                        candidateQuarterTurns,
                        pipeCoordinate,
                        out Vector2Int pipePassDirection)
                    || pipePassDirection != directionFromPipeToBody)
                {
                    continue;
                }

                int score = 1
                    + Mathf.Abs(candidateAnchorCoordinate.x - clickedBlock.Coordinate.x)
                    + Mathf.Abs(candidateAnchorCoordinate.y - clickedBlock.Coordinate.y);
                TryConsiderBoilerPipeConnectionAnchor(
                    candidateAnchorBlock,
                    footprintSource,
                    candidateQuarterTurns,
                    previewToIgnore,
                    connectorPreviewToIgnore,
                    includeIgnoredPreviewAsConnector,
                    score,
                    ref foundCandidate,
                    ref bestScore,
                    ref bestAnchorBlock,
                    ref bestQuarterTurns);
            }
        }
    }

    private void TryConsiderBoilerPipeConnectionAnchor(
        Block candidateAnchorBlock,
        MapObject footprintSource,
        int candidateQuarterTurns,
        MapObject previewToIgnore,
        MapObject connectorPreviewToIgnore,
        bool includeIgnoredPreviewAsConnector,
        int score,
        ref bool foundCandidate,
        ref int bestScore,
        ref Block bestAnchorBlock,
        ref int bestQuarterTurns)
    {
        if (candidateAnchorBlock == null
            || !PlacementHasRectGridObjectCoordinate(
                candidateAnchorBlock.Coordinate,
                footprintSource,
                candidateQuarterTurns,
                candidateAnchorBlock.Coordinate)
            || PlacementHasBoilerEnergyInputPipeConflict(
                candidateAnchorBlock.Coordinate,
                footprintSource,
                candidateQuarterTurns,
                previewToIgnore)
            || !BoilerPlacementHasCompatiblePipePassPipeConnection(
                candidateAnchorBlock.Coordinate,
                footprintSource,
                candidateQuarterTurns,
                connectorPreviewToIgnore)
            || !CanPlacePreviewOnBlock(
                candidateAnchorBlock,
                previewToIgnore,
                candidateQuarterTurns,
                includeIgnoredPreviewAsConnector))
        {
            return;
        }

        if (foundCandidate && score >= bestScore)
        {
            return;
        }

        foundCandidate = true;
        bestScore = score;
        bestAnchorBlock = candidateAnchorBlock;
        bestQuarterTurns = candidateQuarterTurns;
    }

    private bool BoilerPlacementHasCompatiblePipePassPipeConnection(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!IsPipePassBlockType(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int pipePassCoordinate))
            {
                continue;
            }

            PipeAreaBlockCandidate proposedCandidate =
                new PipeAreaBlockCandidate(proposedSnapshot, placement.blockType);
            if (BoilerPipePassCanConnectPipeAtCoordinate(
                pipePassCoordinate,
                proposedCandidate,
                previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private bool BoilerPipePassCanConnectPipeAtCoordinate(
        Vector2Int pipePassCoordinate,
        PipeAreaBlockCandidate proposedCandidate,
        MapObject previewToIgnore)
    {
        List<Vector2Int> requiredPipeDirections = new List<Vector2Int>(4);
        if (!TryGetPipePlacementAtCoordinate(
                pipePassCoordinate,
                previewToIgnore,
                out Pipe pipe,
                out Quaternion pipeRotation))
        {
            return false;
        }

        if (!TryGetProposedPipeAreaPipeConnectionDirections(
                pipePassCoordinate,
                proposedCandidate,
                pipePassCoordinate,
                requiredPipeDirections))
        {
            return false;
        }

        for (int directionIndex = 0; directionIndex < requiredPipeDirections.Count; directionIndex++)
        {
            Vector2Int requiredDirection = requiredPipeDirections[directionIndex];
            if (requiredDirection == Vector2Int.zero)
            {
                continue;
            }

            if (TryResolvePipeVariantForForcedConnection(
                    pipePassCoordinate,
                    pipe,
                    pipeRotation,
                    requiredDirection,
                    out Pipe resolvedPipe,
                    out Quaternion resolvedPipeRotation)
                && PipeAreaCandidateFluidMatchesPipeNetwork(
                    pipePassCoordinate,
                    resolvedPipe,
                    resolvedPipeRotation,
                    pipePassCoordinate,
                    proposedCandidate,
                    previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private List<PipeAreaBlockCandidate> CollectPipePassCandidatesAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore)
    {
        List<PipeAreaBlockCandidate> pipePassCandidates = new List<PipeAreaBlockCandidate>(2);
        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);

        for (int i = 0; i < pipeAreaBlockCandidateScratchA.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipeAreaBlockCandidateScratchA[i];
            if (IsPipePassBlockType(candidate.blockType))
            {
                pipePassCandidates.Add(candidate);
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return pipePassCandidates;
    }

    private bool HasBoilerPipePassAtCoordinate(Vector2Int coordinate, MapObject previewToIgnore)
    {
        List<PipeAreaBlockCandidate> pipePassCandidates = CollectPipePassCandidatesAtCoordinate(
            coordinate,
            previewToIgnore);
        for (int i = 0; i < pipePassCandidates.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipePassCandidates[i];
            if (candidate.snapshot != null && IsBoilerSource(candidate.snapshot.mapObject))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryFindPlaceableItemAreaOverlapInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        if (clickedBlock == null
            || !CoordinateHasInputOutputAreaForPlacement(clickedBlock.Coordinate, null)
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !TryGetRectGridFootprintSettings(footprintSource, out int rectGridWidth, out int rectGridHeight, out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        for (int offset = 0; offset < 4; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(preferredQuarterTurns + offset);
            for (int i = 0; i < placements.Count; i++)
            {
                InputOutputModule.RectGridBlockPlacement placement = placements[i];
                bool canUsePlacementForAreaOverlap = IsRectGridAreaBlockType(placement.blockType)
                    || CanUseObjectPlacementForFluidStorageAreaOverlap(
                        footprintSource,
                        placement.blockType,
                        clickedBlock.Coordinate);
                if (!canUsePlacementForAreaOverlap
                    || placement.x < 0
                    || placement.x >= rectGridWidth
                    || placement.y < 0
                    || placement.y >= rectGridHeight)
                {
                    continue;
                }

                Vector2Int localOffset = new Vector2Int(placement.x - objectAnchorCell.x, placement.y - objectAnchorCell.y);
                Vector2Int candidateAnchorCoordinate =
                    clickedBlock.Coordinate - RotateFootprintOffset(localOffset, candidateQuarterTurns);
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || PlacementHasBoilerEnergyInputPipeConflict(
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore)
                    || PlacementHasNormalInputOutputAreaPipeOverlap(
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore)
                    || !CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, candidateQuarterTurns))
                {
                    continue;
                }

                anchorBlock = candidateAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool TryFindPlaceableMultiCellInstallPreviewTarget(
        Block clickedBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out Block anchorBlock,
        out int resolvedQuarterTurns)
    {
        anchorBlock = null;
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (clickedBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !HasMultiCellMapSize(footprintSource)
            || IsBelt2F(footprintSource))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        int candidateCount = UsesTwoStateInstallPreviewRotation(previewToIgnore)
            ? 2
            : GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizeInstallPreviewQuarterTurns(
                previewToIgnore,
                resolvedQuarterTurns + offset);
            List<Vector2Int> localOffsets = GetFootprintLocalOffsets(footprintSource, candidateQuarterTurns);
            if (localOffsets.Count <= 1)
            {
                continue;
            }

            for (int i = 0; i < localOffsets.Count; i++)
            {
                Vector2Int localOffset = localOffsets[i];
                if (localOffset == Vector2Int.zero)
                {
                    continue;
                }

                Vector2Int candidateAnchorCoordinate = clickedBlock.Coordinate - localOffset;
                if (!terrain.TryGetLoadedBlock(candidateAnchorCoordinate, out Block candidateAnchorBlock)
                    || candidateAnchorBlock == null
                    || PlacementHasBoilerEnergyInputPipeConflict(
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore)
                    || PlacementHasNormalInputOutputAreaPipeOverlap(
                        candidateAnchorCoordinate,
                        footprintSource,
                        candidateQuarterTurns,
                        previewToIgnore)
                    || !CanPlacePreviewOnBlock(candidateAnchorBlock, previewToIgnore, candidateQuarterTurns))
                {
                    continue;
                }

                anchorBlock = candidateAnchorBlock;
                resolvedQuarterTurns = candidateQuarterTurns;
                return true;
            }
        }

        return false;
    }

    private bool TryResolveInstallPreviewFootprintSourceForPlacement(MapObject previewToIgnore, out MapObject footprintSource)
    {
        footprintSource = null;
        if (previewToIgnore != null)
        {
            footprintSource = ResolveInstallPreviewFootprintSource(previewToIgnore) ?? previewToIgnore;
            return footprintSource != null;
        }

        footprintSource = activeInstallDefinition != null ? activeInstallDefinition.mapObject : null;
        return footprintSource != null;
    }

    private bool PlacementHasNormalInputOutputAreaPipeOverlap(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (footprintSource == null
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!IsNormalInputOutputAreaBlockType(placement.blockType)
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight)
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int coordinate = anchorCoordinate + RotateFootprintOffset(localOffset, quarterTurns);
            if (!terrain.TryGetLoadedBlock(coordinate, out Block block) || block == null)
            {
                continue;
            }

            MapObject occupyingObject = GetOccupyingObjectForPlacement(block, previewToIgnore);

            if (TryGetPipePlacementAtBlock(block, occupyingObject, out _, out _))
            {
                return true;
            }

            if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject existingPreview)
                && existingPreview != null
                && existingPreview != previewToIgnore
                && IsPipePlacementSource(existingPreview))
            {
                return true;
            }
        }

        return false;
    }

    private bool PlacementHasBoilerEnergyInputPipeConflict(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || !TryGetRectGridFootprintSettings(
                footprintSource,
                out int rectGridWidth,
                out int rectGridHeight,
                out Vector2Int objectAnchorCell)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.IsInputEnergyBlockType(placement.blockType)
                || placement.x < 0
                || placement.x >= rectGridWidth
                || placement.y < 0
                || placement.y >= rectGridHeight)
            {
                continue;
            }

            Vector2Int localOffset = new Vector2Int(
                placement.x - objectAnchorCell.x,
                placement.y - objectAnchorCell.y);
            Vector2Int energyCoordinate = anchorCoordinate + RotateFootprintOffset(localOffset, quarterTurns);
            if (TryGetPipePlacementAtCoordinate(energyCoordinate, previewToIgnore, out _, out _)
                || BoilerEnergyInputHasIncomingPipeConnection(energyCoordinate, previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private bool CanUseBoilerEnergyInputRotationCandidate(
        Vector2Int anchorCoordinate,
        MapObject previewToIgnore,
        int quarterTurns)
    {
        return !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
               || !IsBoilerSource(footprintSource)
               || !PlacementHasBoilerEnergyInputPipeConflict(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns,
                   previewToIgnore);
    }

    private bool BoilerEnergyInputHasIncomingPipeConnection(Vector2Int energyCoordinate, MapObject previewToIgnore)
    {
        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionToPipe = PipeCardinalDirections[i];
            Vector2Int pipeCoordinate = energyCoordinate + directionToPipe;
            Vector2Int directionToEnergyInput = -directionToPipe;
            if (TryGetPipePlacementAtCoordinate(
                    pipeCoordinate,
                    previewToIgnore,
                    out Pipe pipe,
                    out Quaternion pipeRotation)
                && pipe.HasConnectionTowards(pipeRotation, directionToEnergyInput))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetPipePlacementAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out Pipe pipe,
        out Quaternion pipeRotation)
    {
        pipe = null;
        pipeRotation = Quaternion.identity;

        if (TryGetInstallPreviewAtCoordinate(coordinate, out MapObject preview)
            && preview != null
            && preview != previewToIgnore)
        {
            MapObject previewSource = ResolveInstallPreviewFootprintSource(preview) ?? preview;
            pipe = preview as Pipe ?? previewSource as Pipe;
            if (pipe != null)
            {
                pipeRotation = preview.transform.rotation;
                return true;
            }
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null
            || !terrain.TryGetLoadedBlock(coordinate, out Block block)
            || block == null)
        {
            return false;
        }

        return TryGetPipePlacementAtBlock(
            block,
            GetOccupyingObjectForPlacement(block, previewToIgnore),
            out pipe,
            out pipeRotation);
    }

    private bool IsPipePlacementSource(MapObject mapObject)
    {
        MapObject source = ResolveInstallPreviewFootprintSource(mapObject) ?? mapObject;
        return source is Pipe;
    }

    private bool CoordinateHasNormalInputOutputAreaBlockForPlacement(
        Vector2Int coordinate,
        MapObject previewToIgnore)
    {
        if (InputOutputModuleEnergyAreaController.CoordinateIsEnergyArea(coordinate)
            || InputOutputModuleItemAreaController.CoordinateIsItemArea(coordinate)
            || InputOutputModuleOutputAreaController.CoordinateIsOutputArea(coordinate))
        {
            return true;
        }

        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out PlacementSnapshot previewSnapshot)
            && SnapshotHasNormalInputOutputAreaBlock(previewSnapshot, coordinate))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out PlacementSnapshot installedSnapshot)
            && SnapshotHasNormalInputOutputAreaBlock(installedSnapshot, coordinate))
        {
            return true;
        }

        runtimeGridModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeGridCoordinate(coordinate, runtimeGridModuleScratch))
        {
            for (int i = 0; i < runtimeGridModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeGridModuleScratch[i],
                        out PlacementSnapshot runtimeGridSnapshot)
                    && SnapshotHasNormalInputOutputAreaBlock(runtimeGridSnapshot, coordinate))
                {
                    runtimeGridModuleScratch.Clear();
                    return true;
                }
            }

            runtimeGridModuleScratch.Clear();
        }
        else if (TryGetRuntimeGridPlacementSnapshot(coordinate, out PlacementSnapshot runtimeGridSnapshot)
                 && SnapshotHasNormalInputOutputAreaBlock(runtimeGridSnapshot, coordinate))
        {
            return true;
        }

        runtimeAreaModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeAreaCoordinate(coordinate, runtimeAreaModuleScratch))
        {
            for (int i = 0; i < runtimeAreaModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeAreaModuleScratch[i],
                        out PlacementSnapshot runtimeAreaSnapshot)
                    && SnapshotHasNormalInputOutputAreaBlock(runtimeAreaSnapshot, coordinate))
                {
                    runtimeAreaModuleScratch.Clear();
                    return true;
                }
            }

            runtimeAreaModuleScratch.Clear();
        }
        else if (TryGetRuntimeAreaPlacementSnapshot(coordinate, out PlacementSnapshot runtimeAreaSnapshot)
                 && SnapshotHasNormalInputOutputAreaBlock(runtimeAreaSnapshot, coordinate))
        {
            return true;
        }

        return TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot)
               && SnapshotHasNormalInputOutputAreaBlock(savedSnapshot, coordinate);
    }

    private bool CoordinateHasBoilerEnergyInputBlockForPlacement(
        Vector2Int coordinate,
        MapObject previewToIgnore)
    {
        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out PlacementSnapshot previewSnapshot)
            && SnapshotHasBoilerEnergyInputBlock(previewSnapshot, coordinate))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out PlacementSnapshot installedSnapshot)
            && SnapshotHasBoilerEnergyInputBlock(installedSnapshot, coordinate))
        {
            return true;
        }

        runtimeGridModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeGridCoordinate(coordinate, runtimeGridModuleScratch))
        {
            for (int i = 0; i < runtimeGridModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeGridModuleScratch[i],
                        out PlacementSnapshot runtimeGridSnapshot)
                    && SnapshotHasBoilerEnergyInputBlock(runtimeGridSnapshot, coordinate))
                {
                    runtimeGridModuleScratch.Clear();
                    return true;
                }
            }

            runtimeGridModuleScratch.Clear();
        }
        else if (TryGetRuntimeGridPlacementSnapshot(coordinate, out PlacementSnapshot runtimeGridSnapshot)
                 && SnapshotHasBoilerEnergyInputBlock(runtimeGridSnapshot, coordinate))
        {
            return true;
        }

        runtimeAreaModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeAreaCoordinate(coordinate, runtimeAreaModuleScratch))
        {
            for (int i = 0; i < runtimeAreaModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeAreaModuleScratch[i],
                        out PlacementSnapshot runtimeAreaSnapshot)
                    && SnapshotHasBoilerEnergyInputBlock(runtimeAreaSnapshot, coordinate))
                {
                    runtimeAreaModuleScratch.Clear();
                    return true;
                }
            }

            runtimeAreaModuleScratch.Clear();
        }
        else if (TryGetRuntimeAreaPlacementSnapshot(coordinate, out PlacementSnapshot runtimeAreaSnapshot)
                 && SnapshotHasBoilerEnergyInputBlock(runtimeAreaSnapshot, coordinate))
        {
            return true;
        }

        return TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot)
               && SnapshotHasBoilerEnergyInputBlock(savedSnapshot, coordinate);
    }

    private bool SnapshotHasNormalInputOutputAreaBlock(PlacementSnapshot snapshot, Vector2Int coordinate)
    {
        if (snapshot == null || snapshot.mapObject == null)
        {
            return false;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(snapshot.mapObject) ?? snapshot.mapObject;
        return TryGetRectGridFootprintBlockType(
                   snapshot.anchorCoordinate,
                   footprintSource,
                   snapshot.quarterTurns,
                   coordinate,
                   out InputOutputModule.RectGridBlockType blockType)
               && IsNormalInputOutputAreaBlockType(blockType);
    }

    private bool SnapshotHasBoilerEnergyInputBlock(PlacementSnapshot snapshot, Vector2Int coordinate)
    {
        if (snapshot == null || !IsBoilerSource(snapshot.mapObject))
        {
            return false;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(snapshot.mapObject) ?? snapshot.mapObject;
        return TryGetRectGridFootprintBlockType(
                   snapshot.anchorCoordinate,
                   footprintSource,
                   snapshot.quarterTurns,
                   coordinate,
                   out InputOutputModule.RectGridBlockType blockType)
               && InputOutputModule.IsInputEnergyBlockType(blockType);
    }

    private static bool IsNormalInputOutputAreaBlockType(InputOutputModule.RectGridBlockType blockType)
    {
        return InputOutputModule.AllowsDirectAreaInteraction(blockType)
               && !InputOutputModule.AllowsPipeAreaInteraction(blockType);
    }

    private bool CoordinateHasInputOutputAreaForPlacement(Vector2Int coordinate, MapObject previewToIgnore)
    {
        if (InputOutputModuleEnergyAreaController.CoordinateIsEnergyArea(coordinate)
            || InputOutputModuleItemAreaController.CoordinateIsItemArea(coordinate)
            || InputOutputModuleOutputAreaController.CoordinateIsOutputArea(coordinate)
            || InputOutputModule.CoordinateIsRuntimeInputOutputAreaBlock(coordinate)
            || HasPipeAreaFluidStorageAtCoordinate(coordinate)
            || IsPumpOutputCoordinateForPlacement(coordinate))
        {
            return true;
        }

        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null
                || preview == previewToIgnore
                || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int previewAnchorCoordinate))
            {
                continue;
            }

            MapObject previewFootprintSource = ResolveInstallPreviewFootprintSource(preview);
            if (IsRectGridAreaBlockType(GetRectGridBlockTypeAtCoordinate(
                    previewAnchorCoordinate,
                    previewFootprintSource,
                    GetPreviewAreaQuarterTurns(preview),
                    coordinate)))
            {
                return true;
            }
        }

        return false;
    }

    private bool CanUseObjectPlacementForFluidStorageAreaOverlap(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType blockType,
        Vector2Int coordinate)
    {
        return blockType == InputOutputModule.RectGridBlockType.Object
               && TryResolveInstallationObject(footprintSource, out InstallationObject installationObject)
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump)
               && !IsSteamGeneratorSource(footprintSource)
               && !(IsBoilerSource(footprintSource) && IsPumpOutputCoordinateForPlacement(coordinate))
               && (IsPumpOutputCoordinateForPlacement(coordinate)
                   || HasPipeAreaFluidStorageAtCoordinate(coordinate));
    }

    private bool IsConveyorInstallPreview(MapObject previewToIgnore)
    {
        if (IsBelt2F(previewToIgnore)
            || (activeInstallDefinition != null && IsBelt2F(activeInstallDefinition.mapObject)))
        {
            return false;
        }

        if (previewToIgnore is ConveyorBelt)
        {
            return true;
        }

        return activeInstallDefinition != null && activeInstallDefinition.mapObject is ConveyorBelt;
    }

    private bool TryGetInstallPreviewAtCoordinate(Vector2Int coordinate, out MapObject preview)
    {
        preview = null;
        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject candidate = installPreviewInstances[i];
            if (candidate == null)
            {
                continue;
            }

            if (InstallPreviewContainsCoordinateNoAlloc(candidate, coordinate))
            {
                preview = candidate;
                return true;
            }
        }

        return false;
    }

    private bool InstallPreviewContainsCoordinateNoAlloc(MapObject preview, Vector2Int coordinate)
    {
        if (preview == null || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
        {
            return false;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(preview) ?? preview;
        int quarterTurns = GetPreviewAreaQuarterTurns(preview);
        if (TryGetRectGridFootprintSettings(
                footprintSource,
                out _,
                out _,
                out _))
        {
            return TryGetRectGridFootprintBlockType(
                       anchorCoordinate,
                       footprintSource,
                       quarterTurns,
                       coordinate,
                       out InputOutputModule.RectGridBlockType blockType)
                   && blockType != InputOutputModule.RectGridBlockType.None;
        }

        int sizeX = Mathf.Max(1, footprintSource != null ? footprintSource.Status.mapSizeX : 1);
        int sizeY = Mathf.Max(1, footprintSource != null ? footprintSource.Status.mapSizeY : 1);
        if (IsBelt2F(footprintSource))
        {
            Vector2Int belt2FSize = GetBelt2FFootprintSize(footprintSource);
            sizeX = belt2FSize.x;
            sizeY = belt2FSize.y;
        }

        Vector2Int centerCell = GetFootprintAnchorCell(footprintSource);
        for (int y = 0; y < sizeY; y++)
        {
            for (int x = 0; x < sizeX; x++)
            {
                Vector2Int localOffset = new Vector2Int(x - centerCell.x, y - centerCell.y);
                if (anchorCoordinate + RotateFootprintOffset(localOffset, quarterTurns) == coordinate)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryGetPreviewAnchorCoordinate(MapObject preview, out Vector2Int anchorCoordinate)
    {
        anchorCoordinate = Vector2Int.zero;
        return preview != null && installPreviewAnchorCoordinates.TryGetValue(preview, out anchorCoordinate);
    }

    private MapObject ResolveInstallPreviewFootprintSource(MapObject preview)
    {
        if (preview != null
            && installPreviewSourcePrefabsByPreview.TryGetValue(preview, out MapObject sourcePrefab)
            && sourcePrefab != null)
        {
            return sourcePrefab;
        }

        return preview;
    }

    private MapObject ResolveInstallPreviewPlacementSource(MapObject preview)
    {
        return ResolveInstallPreviewFootprintSource(preview) ?? preview;
    }

    private bool CanOverlapCompatibleInstallPreview(
        Vector2Int coordinate,
        MapObject candidateFootprintSource,
        InputOutputModule.RectGridBlockType candidateBlockType,
        Vector2Int candidateAnchorCoordinate,
        int candidateQuarterTurns,
        MapObject existingPreview)
    {
        if (existingPreview == null
            || !TryGetPreviewAnchorCoordinate(existingPreview, out Vector2Int existingAnchorCoordinate))
        {
            return false;
        }

        MapObject existingFootprintSource = ResolveInstallPreviewFootprintSource(existingPreview);
        int existingQuarterTurns = GetPreviewQuarterTurns(existingPreview);
        return CanOverlapCompatiblePlacementItemAreas(
            coordinate,
            candidateFootprintSource,
            candidateBlockType,
            candidateAnchorCoordinate,
            candidateQuarterTurns,
            existingFootprintSource,
            GetRectGridBlockTypeAtCoordinate(
                existingAnchorCoordinate,
                existingFootprintSource,
                existingQuarterTurns,
                coordinate),
            existingAnchorCoordinate,
            existingQuarterTurns);
    }

    private List<Vector2Int> GetFootprintCoordinates(Vector2Int anchorCoordinate, MapObject footprintSource, int quarterTurns)
    {
        List<Vector2Int> offsets = GetFootprintLocalOffsets(footprintSource, quarterTurns);
        List<Vector2Int> coordinates = new List<Vector2Int>(offsets.Count);
        for (int i = 0; i < offsets.Count; i++)
        {
            coordinates.Add(anchorCoordinate + offsets[i]);
        }

        return coordinates;
    }

    private List<Vector2Int> GetPlacementValidationCoordinates(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        List<Vector2Int> rectGridCoordinates = GetRectGridPlacementCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        return rectGridCoordinates.Count > 0
            ? rectGridCoordinates
            : GetFootprintCoordinates(anchorCoordinate, footprintSource, quarterTurns);
    }

    private List<Vector2Int> GetInstallPreviewAreaDisplayCoordinates(
        MapObject preview,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        MapObject footprintSource = ResolveInstallPreviewPlacementSource(preview);
        if (TryGetTransformBasedInstallPreviewAreaDisplayCoordinates(
                preview,
                footprintSource,
                quarterTurns,
                out List<Vector2Int> transformBasedCoordinates))
        {
            return transformBasedCoordinates;
        }

        List<Vector2Int> rectGridCoordinates = GetRectGridPlacementCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        return rectGridCoordinates.Count > 0
            ? rectGridCoordinates
            : GetFootprintCoordinates(anchorCoordinate, footprintSource, quarterTurns);
    }

    private bool TryGetTransformBasedInstallPreviewAreaDisplayCoordinates(
        MapObject preview,
        MapObject footprintSource,
        int fallbackQuarterTurns,
        out List<Vector2Int> coordinates)
    {
        coordinates = null;
        if (preview == null || footprintSource == null)
        {
            return false;
        }

        int quarterTurns = fallbackQuarterTurns;

        Vector2 averageObjectOffset = GetAverageLocalOffset(GetPlacementVisualLocalOffsets(footprintSource, quarterTurns));
        Vector2Int transformAnchorCoordinate = new Vector2Int(
            RoundGridCoordinate(preview.transform.position.x - averageObjectOffset.x),
            RoundGridCoordinate(preview.transform.position.z - averageObjectOffset.y));

        List<Vector2Int> rectGridCoordinates = GetRectGridPlacementCoordinates(
            transformAnchorCoordinate,
            footprintSource,
            quarterTurns);
        if (rectGridCoordinates.Count > 0)
        {
            coordinates = rectGridCoordinates;
            return true;
        }

        List<Vector2Int> footprintCoordinates = GetFootprintCoordinates(
            transformAnchorCoordinate,
            footprintSource,
            quarterTurns);
        if (footprintCoordinates.Count <= 0)
        {
            return false;
        }

        coordinates = footprintCoordinates;
        return true;
    }

    private List<Vector2Int> GetRectGridPlacementCoordinates(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        List<Vector2Int> coordinates = new List<Vector2Int>();
        List<RectGridPlacementCell> cells = new List<RectGridPlacementCell>();
        if (!TryBuildRectGridPlacementCells(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                null,
                cells))
        {
            return coordinates;
        }

        HashSet<Vector2Int> occupiedCoordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < cells.Count; i++)
        {
            Vector2Int coordinate = cells[i].coordinate;
            if (occupiedCoordinates.Add(coordinate))
            {
                coordinates.Add(coordinate);
            }
        }

        return coordinates;
    }

    private List<Vector2Int> GetFootprintLocalOffsets(MapObject footprintSource, int quarterTurns)
    {
        if (ShouldUseMapSizeFootprint(footprintSource))
        {
            return GetMapSizeFootprintLocalOffsets(footprintSource, quarterTurns);
        }

        List<RectGridPlacementCell> cells = new List<RectGridPlacementCell>();
        if (TryBuildRectGridPlacementCells(
                Vector2Int.zero,
                footprintSource,
                quarterTurns,
                null,
                cells))
        {
            List<Vector2Int> rectGridOffsets = new List<Vector2Int>(cells.Count);
            HashSet<Vector2Int> occupiedOffsets = new HashSet<Vector2Int>();

            for (int i = 0; i < cells.Count; i++)
            {
                Vector2Int rotatedOffset = cells[i].rotatedOffset;
                if (occupiedOffsets.Add(rotatedOffset))
                {
                    rectGridOffsets.Add(rotatedOffset);
                }
            }

            if (rectGridOffsets.Count > 0)
            {
                return rectGridOffsets;
            }
        }

        return GetMapSizeFootprintLocalOffsets(footprintSource, quarterTurns);
    }

    private static bool ShouldUseMapSizeFootprint(MapObject footprintSource)
    {
        return footprintSource is InstallationObject installationObject
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump);
    }

    private List<Vector2Int> GetMapSizeFootprintLocalOffsets(MapObject footprintSource, int quarterTurns)
    {
        int sizeX = 1;
        int sizeY = 1;
        if (footprintSource != null)
        {
            sizeX = Mathf.Max(1, footprintSource.Status.mapSizeX);
            sizeY = Mathf.Max(1, footprintSource.Status.mapSizeY);
            if (IsBelt2F(footprintSource))
            {
                Vector2Int belt2FSize = GetBelt2FFootprintSize(footprintSource);
                sizeX = belt2FSize.x;
                sizeY = belt2FSize.y;
            }
        }

        Vector2Int centerCell = GetFootprintAnchorCell(footprintSource);
        List<Vector2Int> offsets = new List<Vector2Int>(sizeX * sizeY);
        for (int y = 0; y < sizeY; y++)
        {
            for (int x = 0; x < sizeX; x++)
            {
                offsets.Add(RotateFootprintOffset(new Vector2Int(x - centerCell.x, y - centerCell.y), quarterTurns));
            }
        }

        return offsets;
    }

    private static bool HasMultiCellMapSize(MapObject footprintSource)
    {
        return footprintSource != null
            && (Mathf.Max(1, footprintSource.Status.mapSizeX) > 1
                || Mathf.Max(1, footprintSource.Status.mapSizeY) > 1);
    }

    private bool HasMultiCellPlacementFootprint(MapObject footprintSource)
    {
        if (HasMultiCellMapSize(footprintSource))
        {
            return true;
        }

        List<RectGridPlacementCell> cells = new List<RectGridPlacementCell>();
        if (!TryBuildRectGridPlacementCells(
                Vector2Int.zero,
                footprintSource,
                0,
                null,
                cells))
        {
            return false;
        }

        HashSet<Vector2Int> coordinates = new HashSet<Vector2Int>();
        for (int i = 0; i < cells.Count; i++)
        {
            coordinates.Add(cells[i].coordinate);
            if (coordinates.Count > 1)
            {
                return true;
            }
        }

        return false;
    }

    private static Vector2Int GetFootprintAnchorCell(MapObject footprintSource)
    {
        if (footprintSource == null)
        {
            return Vector2Int.zero;
        }

        return IsBelt2F(footprintSource)
            ? GetBelt2FAnchorCell(footprintSource)
            : footprintSource.PlacementCenterCell;
    }

    private static Vector2Int GetBelt2FAnchorCell(MapObject footprintSource)
    {
        Vector2Int size = GetBelt2FFootprintSize(footprintSource);
        Vector2Int centerCell = footprintSource != null
            ? footprintSource.PlacementCenterCell
            : Vector2Int.zero;
        return new Vector2Int(
            Mathf.Clamp(centerCell.x, 0, size.x - 1),
            Mathf.Clamp(centerCell.y, 0, size.y - 1));
    }

    private static Vector2Int GetBelt2FBridgeCenterCell(MapObject footprintSource)
    {
        return GetBelt2FAnchorCell(footprintSource);
    }

    private static Vector2Int GetBelt2FFootprintSize(MapObject footprintSource)
    {
        int sizeX = Mathf.Max(1, footprintSource != null ? footprintSource.Status.mapSizeX : 1);
        int sizeY = Mathf.Max(1, footprintSource != null ? footprintSource.Status.mapSizeY : 1);
        if (sizeX == 1 && sizeY == 1)
        {
            sizeX = Belt2FDefaultFootprintWidth;
            sizeY = Belt2FDefaultFootprintLength;
        }

        return new Vector2Int(sizeX, sizeY);
    }

    private static Vector2Int GetBelt2FBridgeCenterOffset(MapObject footprintSource, int quarterTurns)
    {
        return RotateFootprintOffset(
            GetBelt2FBridgeCenterCell(footprintSource) - GetBelt2FAnchorCell(footprintSource),
            quarterTurns);
    }

    private static Vector2Int GetBelt2FBridgeCenterCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        return anchorCoordinate + GetBelt2FBridgeCenterOffset(footprintSource, quarterTurns);
    }

    private bool TryGetRectGridFootprintSettings(
        MapObject footprintSource,
        out int rectGridWidth,
        out int rectGridHeight,
        out Vector2Int objectAnchorCell)
    {
        rectGridWidth = 0;
        rectGridHeight = 0;
        objectAnchorCell = Vector2Int.zero;

        if (footprintSource == null)
        {
            return false;
        }

        InputOutputModule inputOutputModule = footprintSource as InputOutputModule;
        if (inputOutputModule == null)
        {
            inputOutputModule = footprintSource.GetComponent<InputOutputModule>();
        }

        if (inputOutputModule == null)
        {
            inputOutputModule = footprintSource.GetComponentInChildren<InputOutputModule>(true);
        }

        if (inputOutputModule == null || inputOutputModule.LayoutType != InputOutputModule.SlotLayoutType.RectGrid)
        {
            return false;
        }

        rectGridWidth = Mathf.Max(1, inputOutputModule.RectGridWidth);
        rectGridHeight = Mathf.Max(1, inputOutputModule.RectGridHeight);
        return TryGetRectGridObjectAnchorCell(inputOutputModule, footprintSource, out objectAnchorCell);
    }

    private bool TryGetRectGridObjectAnchorCell(
        InputOutputModule inputOutputModule,
        MapObject footprintSource,
        out Vector2Int objectAnchorCell)
    {
        objectAnchorCell = Vector2Int.zero;
        return inputOutputModule != null
               && inputOutputModule.TryGetRectGridObjectAnchorCell(footprintSource, out objectAnchorCell);
    }

    private static Vector2Int RotateFootprintOffset(Vector2Int offset, int quarterTurns)
    {
        return InputOutputModule.RotateRectGridOffset(offset, quarterTurns);
    }

    public bool CanPlaceInstalledObjectAt(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore = null,
        bool ignoreOtherPreviews = false)
    {
        return TryGetFootprintBlocks(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            previewToIgnore,
            out _,
            ignoreOtherPreviews);
    }

    private bool TryGetFootprintBlocks(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore,
        out List<Block> footprintBlocks,
        bool ignoreOtherPreviews = false,
        bool includeIgnoredPreviewAsConnector = false)
    {
        footprintBlocks = new List<Block>();

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        if (PlacementHasNormalInputOutputAreaPipeOverlap(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                previewToIgnore))
        {
            return false;
        }

        List<Vector2Int> occupiedCoordinates = GetPlacementValidationCoordinates(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        for (int i = 0; i < occupiedCoordinates.Count; i++)
        {
            Vector2Int coordinate = occupiedCoordinates[i];
            if (!terrain.TryGetLoadedBlock(coordinate, out Block footprintBlock) || footprintBlock == null)
            {
                return false;
            }

            TryGetRectGridFootprintBlockType(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType rectGridBlockType);
            if (!CanPlacePreviewOnTargetBlockType(
                    footprintBlock,
                    footprintSource,
                    rectGridBlockType,
                    anchorCoordinate,
                    quarterTurns,
                    previewToIgnore,
                    includeIgnoredPreviewAsConnector))
            {
                return false;
            }

            if (!ignoreOtherPreviews
                && TryGetInstallPreviewAtCoordinate(coordinate, out MapObject existingPreview)
                && existingPreview != null
                && existingPreview != previewToIgnore)
            {
                if (IsBelt2F(footprintSource)
                    || !CanOverlapCompatibleInstallPreview(
                        coordinate,
                        footprintSource,
                        rectGridBlockType,
                        anchorCoordinate,
                        quarterTurns,
                        existingPreview))
                {
                    return false;
                }
            }

            footprintBlocks.Add(footprintBlock);
        }

        return footprintBlocks.Count > 0;
    }

    private bool TryGetRectGridFootprintBlockType(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        Vector2Int coordinate,
        out InputOutputModule.RectGridBlockType blockType)
    {
        blockType = InputOutputModule.RectGridBlockType.None;
        return TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
               && inputOutputModule.TryGetRectGridBlockTypeAtCoordinate(
                   footprintSource,
                   anchorCoordinate,
                   NormalizePlacementQuarterTurnsForObject(footprintSource, quarterTurns),
                   coordinate,
                   out blockType);
    }

    private InputOutputModule.RectGridBlockType GetRectGridBlockTypeAtCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        Vector2Int coordinate)
    {
        return TryGetRectGridFootprintBlockType(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType blockType)
            ? blockType
            : InputOutputModule.RectGridBlockType.None;
    }

    private bool ShouldBindInstalledObjectToBlock(
        Block block,
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        if (block == null)
        {
            return false;
        }

        if (IsTrainSource(footprintSource))
        {
            return false;
        }

        if (!TryGetRectGridFootprintSettings(footprintSource, out _, out _, out _)
            || !TryGetInputOutputModule(footprintSource, out _))
        {
            return !ShouldSkipBelt2FBridgeCenterBinding(block, anchorCoordinate, footprintSource, quarterTurns);
        }

        return TryGetRectGridFootprintBlockType(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                block.Coordinate,
                out InputOutputModule.RectGridBlockType blockType)
            && blockType == InputOutputModule.RectGridBlockType.Object;
    }

    private bool CanPlacePreviewOnTargetBlockType(
        Block block,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType = InputOutputModule.RectGridBlockType.None,
        Vector2Int? anchorCoordinate = null,
        int quarterTurns = 0,
        MapObject previewToIgnore = null,
        bool includeIgnoredPreviewAsConnector = false)
    {
        if (block == null)
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block);

        if (!TryResolveInstallationObject(footprintSource, out InstallationObject installationObject))
        {
            return CanPlaceOnTerrainBiome(block, InstallationMapFilter.Ground) && occupyingObject == null;
        }

        InstallationMapFilter allowedFilter = ResolvePlacementMapFilter(footprintSource, installationObject);
        InstallationMapFilter rectGridTerrainFilter =
            ResolveRectGridTerrainFilter(footprintSource, rectGridBlockType, allowedFilter);
        if (footprintSource is Pipe && IsFixedRectGridObjectBlockCoordinate(block.Coordinate))
        {
            return false;
        }

        bool isRectGridAreaBlock = IsRectGridAreaBlockType(rectGridBlockType);
        bool isInputOutputEnergyAreaBlock = InputOutputModuleEnergyAreaController.CoordinateIsEnergyArea(block.Coordinate)
            || InputOutputModule.CoordinateIsRuntimeInputEnergyBlock(block.Coordinate);
        bool isInputOutputItemAreaBlock = InputOutputModuleItemAreaController.CoordinateIsItemArea(block.Coordinate)
            || InputOutputModule.CoordinateIsRuntimeInputItemBlock(block.Coordinate);
        bool isPumpRuntimeOutputAreaBlock = IsPumpOutputCoordinateForPlacement(block.Coordinate);
        bool isInputOutputOutputAreaBlock = InputOutputModuleOutputAreaController.CoordinateIsOutputArea(block.Coordinate)
            || (InputOutputModule.CoordinateIsRuntimeOutputBlock(block.Coordinate)
                && !isPumpRuntimeOutputAreaBlock);
        bool isInputOutputAreaBlock = isInputOutputEnergyAreaBlock
            || isInputOutputItemAreaBlock
            || isInputOutputOutputAreaBlock
            || isPumpRuntimeOutputAreaBlock;
        bool isRuntimePipeAreaBlock = InputOutputModule.CoordinateAllowsRuntimePipeBlock(block.Coordinate);
        bool isFluidStoragePipeNodeBlock = HasPipeAreaFluidStorageAtCoordinate(block.Coordinate);
        bool canPlacePipeOnFixedConnectorArea = footprintSource is Pipe
            && CanPlacePipeOnFixedFluidConnectorArea(
                block,
                occupyingObject,
                footprintSource,
                quarterTurns);
        bool isCandidateNormalInputOutputAreaBlock = IsNormalInputOutputAreaBlockType(rectGridBlockType);
        bool isExistingDirectInputOutputAreaBlock = isInputOutputEnergyAreaBlock
            || isInputOutputItemAreaBlock
            || isInputOutputOutputAreaBlock;
        bool isExistingNormalInputOutputAreaBlock = isExistingDirectInputOutputAreaBlock
            && !isRuntimePipeAreaBlock
            && !isPumpRuntimeOutputAreaBlock
            && !isFluidStoragePipeNodeBlock;
        if (footprintSource is Pipe
            && (isExistingNormalInputOutputAreaBlock
                || CoordinateHasNormalInputOutputAreaBlockForPlacement(block.Coordinate, previewToIgnore)))
        {
            return false;
        }

        if ((isCandidateNormalInputOutputAreaBlock || isExistingNormalInputOutputAreaBlock)
            && TryGetPipePlacementAtBlock(block, occupyingObject, out _, out _))
        {
            return false;
        }

        if (rectGridBlockType != InputOutputModule.RectGridBlockType.None
            && !CanPlaceOnTerrainBiome(block, rectGridTerrainFilter))
        {
            return false;
        }

        MapObject boilerPipePassPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        if (CanPlaceBoilerConnectorOnPumpBody(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                anchorCoordinate,
                quarterTurns))
        {
            return true;
        }

        if (CanPlaceBoilerConnectorOnBoilerBody(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                anchorCoordinate,
                quarterTurns,
                boilerPipePassPreviewToIgnore))
        {
            return true;
        }

        if (CanPlaceBoilerObjectOnPumpOutputArea(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                isPumpRuntimeOutputAreaBlock,
                anchorCoordinate,
                quarterTurns))
        {
            return true;
        }

        if (CanPlaceBoilerObjectOnBoilerPipePassArea(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                allowedFilter,
                anchorCoordinate,
                quarterTurns,
                boilerPipePassPreviewToIgnore))
        {
            return true;
        }

        if (CanPlaceSteamGeneratorCenterOnBoilerPipeOutput(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                allowedFilter,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore))
        {
            return true;
        }

        if (CanPlaceBoilerCenterOnSteamGeneratorPipeInput(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                allowedFilter,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore))
        {
            return true;
        }

        if (CanPlaceBoilerOutputOnSteamGeneratorBodyForDirectInput(
                footprintSource,
                rectGridBlockType,
                block,
                occupyingObject,
                allowedFilter,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore))
        {
            return true;
        }

        if (CanPlaceSteamGeneratorStraightChainBlock(
                footprintSource,
                rectGridBlockType,
                block,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore,
                includeIgnoredPreviewAsConnector))
        {
            return true;
        }

        bool needsCompatibleRectGridOverlapCheck =
            (IsSteamGeneratorSource(footprintSource) || IsBoilerSource(footprintSource))
            && (occupyingObject != null
                || isInputOutputAreaBlock
                || isRuntimePipeAreaBlock
                || isFluidStoragePipeNodeBlock);
        if (needsCompatibleRectGridOverlapCheck
            && CanPlaceCompatibleRectGridOverlap(
                footprintSource,
                rectGridBlockType,
                block,
                anchorCoordinate,
                quarterTurns,
                previewToIgnore))
        {
            return true;
        }

        bool canPlaceFluidStorageObjectOnPipeNode = CanPlaceFluidStorageObjectOnPipeNode(
            footprintSource,
            rectGridBlockType,
            block,
            occupyingObject,
            anchorCoordinate,
            quarterTurns,
            isPumpRuntimeOutputAreaBlock,
            isFluidStoragePipeNodeBlock,
            previewToIgnore);
        if (!isRectGridAreaBlock
            && !canPlaceFluidStorageObjectOnPipeNode
            && !canPlacePipeOnFixedConnectorArea
            && !CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        if (IsWaterPumpSource(footprintSource)
            && !IsWaterPumpCardinalShoreCoordinate(anchorCoordinate ?? block.Coordinate))
        {
            return false;
        }

        if (canPlaceFluidStorageObjectOnPipeNode)
        {
            return true;
        }

        if (canPlacePipeOnFixedConnectorArea)
        {
            return true;
        }

        if (footprintSource is Pipe pipeOnRuntimeArea
            && isRuntimePipeAreaBlock
            && occupyingObject == null)
        {
            return CanResolvedPipePlacementMatchFixedFluidConnectors(
                block.Coordinate,
                pipeOnRuntimeArea,
                quarterTurns);
        }

        if (footprintSource is Pipe pipeFootprint
            && !CanResolvedPipePlacementMatchFixedFluidConnectors(
                block.Coordinate,
                pipeFootprint,
                quarterTurns))
        {
            return false;
        }

        if (IsResourceAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (IsRailloadAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (CanPlacePassthroughOnBelt2FBridgeCenter(
                block,
                footprintSource,
                occupyingObject,
                quarterTurns))
        {
            return true;
        }

        if (!isRectGridAreaBlock
            && IsPipeAllowedForPlacement(
                block,
                occupyingObject,
                footprintSource,
                anchorCoordinate,
                quarterTurns,
                allowedFilter))
        {
            return true;
        }

        if (IsBelt2F(footprintSource))
        {
            return CanPlaceBelt2FBlock(
                block,
                footprintSource,
                occupyingObject,
                anchorCoordinate,
                quarterTurns,
                isInputOutputAreaBlock,
                allowedFilter);
        }

        if (isRectGridAreaBlock)
        {
            if (CanPlaceBoilerOnPumpOutputArea(
                    footprintSource,
                    rectGridBlockType,
                    block,
                    occupyingObject,
                    isPumpRuntimeOutputAreaBlock,
                    allowedFilter,
                    anchorCoordinate,
                    quarterTurns))
            {
                return true;
            }

            if (CanPlaceBoilerAreaBesidePumpOutput(
                    footprintSource,
                    rectGridBlockType,
                    block,
                    occupyingObject,
                    anchorCoordinate,
                    quarterTurns))
            {
                return true;
            }

            if (CanPlaceFluidStorageAreaOnPipeNode(
                    installationObject,
                    rectGridBlockType,
                    block,
                    occupyingObject,
                    anchorCoordinate,
                    quarterTurns,
                    isPumpRuntimeOutputAreaBlock,
                    isFluidStoragePipeNodeBlock,
                    allowedFilter,
                    previewToIgnore))
            {
                return true;
            }

            if (CanPlaceSteamGeneratorInputOnBoilerBodyForDirectOutput(
                    footprintSource,
                    rectGridBlockType,
                    block,
                    occupyingObject,
                    rectGridTerrainFilter,
                    anchorCoordinate,
                    quarterTurns,
                    previewToIgnore))
            {
                return true;
            }

            return CanPlaceRectGridAreaBlock(
                block,
                occupyingObject,
                footprintSource,
                rectGridBlockType,
                anchorCoordinate ?? block.Coordinate,
                quarterTurns,
                isInputOutputEnergyAreaBlock,
                isInputOutputItemAreaBlock,
                isInputOutputOutputAreaBlock,
                rectGridTerrainFilter);
        }

        if (isInputOutputAreaBlock)
        {
            if ((isRuntimePipeAreaBlock || isPumpRuntimeOutputAreaBlock || isFluidStoragePipeNodeBlock)
                && CanPlaceFluidStorageOnRuntimePipeArea(
                    installationObject,
                    block,
                    occupyingObject,
                    isPumpRuntimeOutputAreaBlock,
                    isRuntimePipeAreaBlock,
                    isRectGridAreaBlock,
                    isFluidStoragePipeNodeBlock,
                    allowedFilter))
            {
                return true;
            }

            if (isRuntimePipeAreaBlock
                && CanPlacePipeOnFixedFluidConnectorArea(
                    block,
                    occupyingObject,
                    footprintSource,
                    quarterTurns))
            {
                return true;
            }

            if (CanPlaceBoilerOnPumpOutputArea(
                    footprintSource,
                    rectGridBlockType,
                    block,
                    occupyingObject,
                    isPumpRuntimeOutputAreaBlock,
                    allowedFilter,
                    anchorCoordinate,
                    quarterTurns))
            {
                return true;
            }

            return CanPlaceInstallationOnInputOutputAreaBlock(
                installationObject,
                block,
                occupyingObject,
                isInputOutputAreaBlock,
                isInputOutputItemAreaBlock,
                allowedFilter);
        }

        if (occupyingObject != null)
        {
            return false;
        }

        return block.Type switch
        {
            Block.BlockType.Ground => true,
            _ => false
        };
    }

    private bool CanPlaceFluidStorageOnRuntimePipeArea(
        InstallationObject installationObject,
        Block block,
        MapObject occupyingObject,
        bool isPumpRuntimeOutputAreaBlock,
        bool isRuntimePipeAreaBlock,
        bool isRectGridAreaBlock,
        bool isFluidStoragePipeNodeBlock,
        InstallationMapFilter allowedFilter)
    {
        if (installationObject is Boiler && isPumpRuntimeOutputAreaBlock && !isRectGridAreaBlock)
        {
            return false;
        }

        if (installationObject is Boiler && isRuntimePipeAreaBlock && !isRectGridAreaBlock)
        {
            return false;
        }

        return installationObject != null
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump)
               && block != null
               && CanPlaceOnTerrainBiome(block, allowedFilter)
               && (occupyingObject == null
                   || (isPumpRuntimeOutputAreaBlock && occupyingObject is Pump));
    }

    private bool CanPlaceFluidStorageObjectOnPipeNode(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        bool isPumpRuntimeOutputAreaBlock,
        bool isFluidStoragePipeNodeBlock,
        MapObject previewToIgnore)
    {
        if (IsBoilerSource(footprintSource)
            && isPumpRuntimeOutputAreaBlock
            && rectGridBlockType == InputOutputModule.RectGridBlockType.Object)
        {
            return anchorCoordinate.HasValue
                   && IsExactPumpOutputCoordinateForPlacement(block.Coordinate)
                   && TryGetExactPumpOutputDirectionForPlacement(
                       block.Coordinate,
                       out Vector2Int pumpOutputDirection)
                   && BoilerPumpSidePipePassMatchesOutputDirection(
                       footprintSource,
                       anchorCoordinate.Value,
                       block.Coordinate,
                       quarterTurns,
                       pumpOutputDirection);
        }

        if (IsBoilerSource(footprintSource)
            && block != null
            && isFluidStoragePipeNodeBlock
            && TryGetSteamGeneratorPipePassTailDirectionAtCoordinate(
                block.Coordinate,
                previewToIgnore,
                out _,
                out _))
        {
            return false;
        }

        return TryResolveInstallationObject(footprintSource, out InstallationObject installationObject)
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump)
               && !IsSteamGeneratorSource(footprintSource)
               && rectGridBlockType == InputOutputModule.RectGridBlockType.Object
               && block != null
                && block.Type == Block.BlockType.Ground
                && (occupyingObject == null
                    || (isPumpRuntimeOutputAreaBlock && occupyingObject is Pump))
                && (isPumpRuntimeOutputAreaBlock || isFluidStoragePipeNodeBlock);
    }

    private bool CanPlaceSteamGeneratorCenterOnBoilerPipeOutput(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        return rectGridBlockType == InputOutputModule.RectGridBlockType.Object
               && block != null
               && anchorCoordinate.HasValue
               && block.Coordinate == anchorCoordinate.Value
               && (occupyingObject == null || IsBoilerSource(occupyingObject))
               && CanPlaceOnTerrainBiome(block, allowedFilter)
               && TryGetSteamGeneratorDirectBoilerOutputPlacement(
                   anchorCoordinate.Value,
                   footprintSource,
                   quarterTurns,
                   previewToIgnore,
                   out _,
                   out _);
    }

    private bool CanPlaceSteamGeneratorInputOnBoilerBodyForDirectOutput(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!InputOutputModule.IsInputItemBlockType(rectGridBlockType)
            || block == null
            || !anchorCoordinate.HasValue
            || !IsBoilerSource(occupyingObject)
            || !CanPlaceOnTerrainBiome(block, allowedFilter)
            || !TryGetSteamGeneratorDirectBoilerOutputPlacement(
                anchorCoordinate.Value,
                footprintSource,
                quarterTurns,
                previewToIgnore,
                out _,
                out Vector2Int steamInputCoordinate)
            || block.Coordinate != steamInputCoordinate)
        {
            return false;
        }

        return true;
    }

    private bool CanPlaceBoilerCenterOnSteamGeneratorPipeInput(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || rectGridBlockType != InputOutputModule.RectGridBlockType.Object
            || block == null
            || !anchorCoordinate.HasValue
            || block.Coordinate != anchorCoordinate.Value
            || (occupyingObject != null && !IsSteamGeneratorSource(occupyingObject))
            || !CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        return CanBoilerDirectSteamGeneratorInputConnection(
            anchorCoordinate.Value,
            footprintSource,
            quarterTurns,
            previewToIgnore);
    }

    private bool CanPlaceBoilerOutputOnSteamGeneratorBodyForDirectInput(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        // Boiler -> SteamGenerator is a flush direct connection: the Boiler Object/body
        // sits on the SteamGenerator PipeInputArea, and the Boiler PipeOutput reaches
        // over the SteamGenerator body cell. Do not fall back to same-cell PipeOutput/
        // PipeInput overlap because that separates the machines by one tile.
        return IsBoilerSource(footprintSource)
               && InputOutputModule.IsOutputBlockType(rectGridBlockType)
               && block != null
               && anchorCoordinate.HasValue
               && (occupyingObject == null || IsSteamGeneratorSource(occupyingObject))
               && CanPlaceOnTerrainBiome(block, allowedFilter)
               && TryGetBoilerDirectSteamGeneratorInputPlacement(
                   anchorCoordinate.Value,
                   footprintSource,
                   quarterTurns,
                   previewToIgnore,
                   out Vector2Int boilerOutputCoordinate,
                   out _)
               && block.Coordinate == boilerOutputCoordinate;
    }

    private bool CanPlaceSteamGeneratorStraightChainBlock(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore,
        bool includeIgnoredPreviewAsConnector)
    {
        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        if (!IsSteamGeneratorSource(footprintSource)
            || block == null
            || block.Type != Block.BlockType.Ground
            || !anchorCoordinate.HasValue
            || !TryGetSteamGeneratorPipePassTailDirectionAtCoordinate(
                anchorCoordinate.Value,
                connectorPreviewToIgnore,
                out Vector2Int existingTailDirection,
                out PipeAreaBlockCandidate existingPipePassCandidate)
            || !TryGetSteamGeneratorBodyDirectionFromCenter(
                footprintSource,
                quarterTurns,
                out Vector2Int proposedTailDirection)
            || proposedTailDirection != existingTailDirection)
        {
            return false;
        }

        if (rectGridBlockType == InputOutputModule.RectGridBlockType.Object
            && block.Coordinate == anchorCoordinate.Value)
        {
            return true;
        }

        if (!InputOutputModule.IsInputItemBlockType(rectGridBlockType)
            || block.Coordinate != anchorCoordinate.Value - proposedTailDirection)
        {
            return false;
        }

        return existingPipePassCandidate.snapshot != null
               && TryGetRectGridFootprintBlockType(
                   existingPipePassCandidate.snapshot.anchorCoordinate,
                   existingPipePassCandidate.snapshot.mapObject,
                   existingPipePassCandidate.snapshot.quarterTurns,
                   block.Coordinate,
                   out InputOutputModule.RectGridBlockType existingBlockType)
               && existingBlockType == InputOutputModule.RectGridBlockType.Object;
    }

    private bool CanPlaceFluidStorageAreaOnPipeNode(
        InstallationObject installationObject,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        bool isPumpRuntimeOutputAreaBlock,
        bool isFluidStoragePipeNodeBlock,
        InstallationMapFilter allowedFilter,
        MapObject previewToIgnore)
    {
        if (installationObject is Boiler
            && block != null
            && isFluidStoragePipeNodeBlock
            && TryGetSteamGeneratorPipePassTailDirectionAtCoordinate(
                block.Coordinate,
                previewToIgnore,
                out _,
                out _))
        {
            return false;
        }

        if (installationObject is Boiler
            && isPumpRuntimeOutputAreaBlock
            && rectGridBlockType == InputOutputModule.RectGridBlockType.PipeInput
            && !BoilerPipePassMatchesPumpOutput(
                installationObject,
                block != null ? block.Coordinate : Vector2Int.zero,
                anchorCoordinate,
                quarterTurns))
        {
            return false;
        }

        if (isFluidStoragePipeNodeBlock
            && InputOutputModule.AllowsPipeAreaInteraction(rectGridBlockType)
            && !CanProposedPipeAreaBlockConnectExisting(
                block != null ? block.Coordinate : Vector2Int.zero,
                installationObject,
                rectGridBlockType,
                anchorCoordinate,
                quarterTurns))
        {
            return false;
        }

        return installationObject != null
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump)
               && IsRectGridAreaBlockType(rectGridBlockType)
               && block != null
               && CanPlaceOnTerrainBiome(block, allowedFilter)
               && (occupyingObject == null
                   || (isPumpRuntimeOutputAreaBlock && occupyingObject is Pump)
                   || (isFluidStoragePipeNodeBlock && IsFluidStoragePlacementObject(occupyingObject)))
               && (isPumpRuntimeOutputAreaBlock || isFluidStoragePipeNodeBlock);
    }

    private bool CanProposedPipeAreaBlockConnectExisting(
        Vector2Int coordinate,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Vector2Int? anchorCoordinate,
        int quarterTurns)
    {
        if (footprintSource == null
            || !anchorCoordinate.HasValue
            || !InputOutputModule.AllowsPipeAreaInteraction(rectGridBlockType))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate.Value,
            quarterTurns = quarterTurns
        };
        PipeAreaBlockCandidate proposedCandidate =
            new PipeAreaBlockCandidate(proposedSnapshot, rectGridBlockType);

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(coordinate, null, pipeAreaBlockCandidateScratchA);
        bool foundExistingCandidate = false;
        bool canConnect = false;
        for (int i = 0; i < pipeAreaBlockCandidateScratchA.Count; i++)
        {
            PipeAreaBlockCandidate existingCandidate = pipeAreaBlockCandidateScratchA[i];
            if (existingCandidate.snapshot == null
                || existingCandidate.snapshot.mapObject == footprintSource)
            {
                continue;
            }

            foundExistingCandidate = true;
            if (CanPipeAreaBlockCandidatesConnect(
                    coordinate,
                    proposedCandidate,
                    coordinate,
                    existingCandidate))
            {
                canConnect = true;
                break;
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        if (foundExistingCandidate && canConnect)
        {
            return true;
        }

        if (IsBoilerSource(footprintSource) && IsPipePassBlockType(rectGridBlockType))
        {
            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                Vector2Int existingPipePassCoordinate = coordinate + PipeCardinalDirections[directionIndex];
                if (BoilerPipePassConnectsExistingBoilerPipePassAtCoordinate(
                        coordinate,
                        proposedCandidate,
                        existingPipePassCoordinate,
                        null))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool CanProposedFluidStoragePipeAreaConnectionsMatchExisting(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore,
        bool includeIgnoredPreviewAsConnector = false)
    {
        if (!TryResolveInstallationObject(footprintSource, out InstallationObject installationObject)
            || installationObject is Pipe
            || installationObject is Pump
            || !installationObject.CanStoreFluid
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return true;
        }

        MapObject connectorPreviewToIgnore = includeIgnoredPreviewAsConnector ? null : previewToIgnore;
        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return true;
        }

        if (TryGetSteamGeneratorDirectBoilerOutputPlacement(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                connectorPreviewToIgnore,
                out _,
                out _))
        {
            return true;
        }

        if (CanSteamGeneratorDirectSteamGeneratorPipePassConnection(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                connectorPreviewToIgnore))
        {
            return true;
        }

        if (CanBoilerDirectSteamGeneratorInputConnection(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                connectorPreviewToIgnore))
        {
            return true;
        }

        if (CanBoilerObjectOnBoilerPipePassConnection(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                connectorPreviewToIgnore))
        {
            return true;
        }

        if (CanBoilerPipePassConnectExistingBoilerPipePass(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                connectorPreviewToIgnore))
        {
            return true;
        }

        if (IsSteamGeneratorSource(footprintSource)
            && !SteamGeneratorPlacementPipeOverlapsMatch(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                false))
        {
            return false;
        }

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int pipeAreaCoordinate))
            {
                continue;
            }

            PipeAreaBlockCandidate proposedCandidate =
                new PipeAreaBlockCandidate(proposedSnapshot, placement.blockType);
            if (!PipeAreaConnectionAtCoordinateIsCompatible(
                    pipeAreaCoordinate,
                    proposedCandidate,
                    pipeAreaCoordinate,
                    connectorPreviewToIgnore))
            {
                return false;
            }

            for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
            {
                Vector2Int connectorCoordinate = pipeAreaCoordinate + PipeCardinalDirections[directionIndex];
                if (!PipeAreaConnectionAtCoordinateIsCompatible(
                        pipeAreaCoordinate,
                        proposedCandidate,
                        connectorCoordinate,
                        connectorPreviewToIgnore))
                {
                    return false;
                }
            }
        }

        return true;
    }

    private bool TryGetSteamGeneratorDirectBoilerOutputPlacement(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore,
        out Vector2Int boilerOutputDirection,
        out Vector2Int steamInputCoordinate)
    {
        boilerOutputDirection = Vector2Int.zero;
        steamInputCoordinate = Vector2Int.zero;
        if (!TryResolveSteamGenerator(footprintSource, out SteamGenerator steamGenerator))
        {
            return false;
        }

        if (TryGetBoilerPipeOutputDirectionAtCoordinate(
                anchorCoordinate,
                previewToIgnore,
                out Vector2Int directBoilerOutputDirection)
            && steamGenerator.TryGetBodyDirectionFromCenter(
                footprintSource,
                quarterTurns,
                out Vector2Int adjacentBodyDirection)
            && adjacentBodyDirection == directBoilerOutputDirection)
        {
            Vector2Int directSteamInputCoordinate = anchorCoordinate - directBoilerOutputDirection;
            if (SteamGeneratorInputItemsMatchBoilerOutput(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    directSteamInputCoordinate,
                    previewToIgnore))
            {
                boilerOutputDirection = directBoilerOutputDirection;
                steamInputCoordinate = directSteamInputCoordinate;
                return true;
            }
        }

        if (!steamGenerator.TryGetInputCoordinateAndDirection(
                footprintSource,
                anchorCoordinate,
                quarterTurns,
                out Vector2Int candidateInputCoordinate,
                out Vector2Int inputDirection)
            || !TryGetBoilerPipeOutputDirectionAtCoordinate(
                candidateInputCoordinate,
                previewToIgnore,
                out Vector2Int candidateBoilerOutputDirection)
            || candidateBoilerOutputDirection != inputDirection
            || !SteamGeneratorInputItemsMatchBoilerOutput(
                candidateInputCoordinate,
                footprintSource,
                quarterTurns,
                candidateInputCoordinate,
                previewToIgnore))
        {
            return false;
        }

        boilerOutputDirection = candidateBoilerOutputDirection;
        steamInputCoordinate = candidateInputCoordinate;
        return true;
    }

    private bool SteamGeneratorInputItemsMatchBoilerOutput(
        Vector2Int boilerOutputCoordinate,
        MapObject steamGeneratorSource,
        int steamGeneratorQuarterTurns,
        Vector2Int steamInputCoordinate,
        MapObject previewToIgnore)
    {
        HashSet<int> outputItemIds = new HashSet<int>();
        if (!TryGetBoilerOutputItemIdsAtCoordinate(
                boilerOutputCoordinate,
                previewToIgnore,
                outputItemIds))
        {
            return false;
        }

        HashSet<int> inputItemIds = new HashSet<int>();
        return TryGetCandidateInputItemIdsAtCoordinate(
                boilerOutputCoordinate,
                steamGeneratorSource,
                steamGeneratorQuarterTurns,
                steamInputCoordinate,
                inputItemIds)
            && HasSharedItemId(outputItemIds, inputItemIds);
    }

    private bool CanSteamGeneratorDirectSteamGeneratorPipePassConnection(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!TryResolveSteamGenerator(footprintSource, out SteamGenerator steamGenerator)
            || !TryGetSteamGeneratorPipePassTailDirectionAtCoordinate(
                anchorCoordinate,
                previewToIgnore,
                out Vector2Int existingTailDirection,
                out PipeAreaBlockCandidate pipePassCandidate)
            || !steamGenerator.TryGetBodyDirectionFromCenter(
                footprintSource,
                quarterTurns,
                out Vector2Int proposedTailDirection)
            || proposedTailDirection != existingTailDirection)
        {
            return false;
        }

        Vector2Int proposedInputCoordinate = anchorCoordinate - proposedTailDirection;
        HashSet<int> pipePassItemIds = new HashSet<int>();
        HashSet<int> proposedInputItemIds = new HashSet<int>();
        bool hasPipePassItems = TryGetCandidatePipePassItemIds(pipePassCandidate, pipePassItemIds);
        bool hasInputItems = TryGetCandidateInputItemIdsAtCoordinate(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            proposedInputCoordinate,
            proposedInputItemIds);
        return !hasPipePassItems || !hasInputItems || HasSharedItemId(pipePassItemIds, proposedInputItemIds);
    }

    private bool CanBoilerDirectSteamGeneratorInputConnection(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        return TryGetBoilerDirectSteamGeneratorInputPlacement(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            previewToIgnore,
            out _,
            out _);
    }

    private bool TryGetBoilerDirectSteamGeneratorInputPlacement(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore,
        out Vector2Int boilerOutputCoordinate,
        out Vector2Int steamInputCoordinate)
    {
        boilerOutputCoordinate = Vector2Int.zero;
        steamInputCoordinate = Vector2Int.zero;
        if (!TryResolveBoiler(footprintSource, out Boiler boiler)
            || !boiler.TryGetOutputCoordinateAndDirection(
                footprintSource,
                anchorCoordinate,
                quarterTurns,
                out Vector2Int proposedOutputCoordinate,
                out Vector2Int boilerOutputFlowDirection))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            anchorCoordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);

        for (int existingIndex = 0; existingIndex < pipeAreaBlockCandidateScratchA.Count; existingIndex++)
        {
            PipeAreaBlockCandidate existingInputCandidate = pipeAreaBlockCandidateScratchA[existingIndex];
            if (existingInputCandidate.snapshot == null
                || !TryResolveSteamGenerator(existingInputCandidate.snapshot.mapObject, out SteamGenerator steamGenerator)
                || !InputOutputModule.IsInputItemBlockType(existingInputCandidate.blockType)
                || !steamGenerator.TryGetBodyDirectionFromCenter(
                    existingInputCandidate.snapshot.mapObject,
                    existingInputCandidate.snapshot.quarterTurns,
                    out Vector2Int steamBodyDirection)
                || steamBodyDirection == Vector2Int.zero
                || anchorCoordinate != existingInputCandidate.snapshot.anchorCoordinate - steamBodyDirection)
            {
                continue;
            }

            Vector2Int requiredOutputCoordinate = existingInputCandidate.snapshot.anchorCoordinate;
            if (proposedOutputCoordinate != requiredOutputCoordinate
                || boilerOutputFlowDirection != steamBodyDirection)
            {
                continue;
            }

            if (BoilerOutputItemsMatchSteamGeneratorInput(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    anchorCoordinate,
                    existingInputCandidate))
            {
                boilerOutputCoordinate = proposedOutputCoordinate;
                steamInputCoordinate = anchorCoordinate;
                pipeAreaBlockCandidateScratchA.Clear();
                return true;
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            proposedOutputCoordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);

        for (int existingIndex = 0; existingIndex < pipeAreaBlockCandidateScratchA.Count; existingIndex++)
        {
            PipeAreaBlockCandidate existingInputCandidate = pipeAreaBlockCandidateScratchA[existingIndex];
            if (existingInputCandidate.snapshot == null
                || !TryResolveSteamGenerator(existingInputCandidate.snapshot.mapObject, out SteamGenerator steamGenerator)
                || !InputOutputModule.IsInputItemBlockType(existingInputCandidate.blockType)
                || !steamGenerator.TryGetInputDirectionAtCoordinate(
                    existingInputCandidate.snapshot.mapObject,
                    existingInputCandidate.snapshot.anchorCoordinate,
                    existingInputCandidate.snapshot.quarterTurns,
                    proposedOutputCoordinate,
                    out Vector2Int steamInputDirection)
                || steamInputDirection != boilerOutputFlowDirection)
            {
                continue;
            }

            if (BoilerOutputItemsMatchSteamGeneratorInput(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    proposedOutputCoordinate,
                    existingInputCandidate))
            {
                boilerOutputCoordinate = proposedOutputCoordinate;
                steamInputCoordinate = proposedOutputCoordinate;
                pipeAreaBlockCandidateScratchA.Clear();
                return true;
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return false;
    }

    private bool CanBoilerObjectOnBoilerPipePassConnection(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || !TryGetRectGridBlockCoordinates(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                InputOutputModule.RectGridBlockType.Object,
                out List<Vector2Int> objectCoordinates))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };

        for (int i = 0; i < objectCoordinates.Count; i++)
        {
            if (BoilerObjectMatchesExistingBoilerPipePassDirection(
                    objectCoordinates[i],
                    proposedSnapshot,
                    previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private bool CanBoilerPipePassConnectExistingBoilerPipePass(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (placements == null || placements.Count <= 0)
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };

        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!IsPipePassBlockType(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int proposedPipePassCoordinate))
            {
                continue;
            }

            PipeAreaBlockCandidate proposedCandidate =
                new PipeAreaBlockCandidate(proposedSnapshot, placement.blockType);
            if (BoilerPipePassConnectsExistingBoilerPipePassAtOrAdjacentCoordinate(
                    proposedPipePassCoordinate,
                    proposedCandidate,
                    previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private bool BoilerPipePassConnectsExistingBoilerPipePassAtOrAdjacentCoordinate(
        Vector2Int proposedPipePassCoordinate,
        PipeAreaBlockCandidate proposedCandidate,
        MapObject previewToIgnore)
    {
        if (BoilerPipePassConnectsExistingBoilerPipePassAtCoordinate(
                proposedPipePassCoordinate,
                proposedCandidate,
                proposedPipePassCoordinate,
                previewToIgnore))
        {
            return true;
        }

        for (int directionIndex = 0; directionIndex < PipeCardinalDirections.Length; directionIndex++)
        {
            Vector2Int existingPipePassCoordinate =
                proposedPipePassCoordinate + PipeCardinalDirections[directionIndex];
            if (BoilerPipePassConnectsExistingBoilerPipePassAtCoordinate(
                    proposedPipePassCoordinate,
                    proposedCandidate,
                    existingPipePassCoordinate,
                    previewToIgnore))
            {
                return true;
            }
        }

        return false;
    }

    private bool BoilerPipePassConnectsExistingBoilerPipePassAtCoordinate(
        Vector2Int proposedPipePassCoordinate,
        PipeAreaBlockCandidate proposedCandidate,
        Vector2Int existingPipePassCoordinate,
        MapObject previewToIgnore)
    {
        if (proposedCandidate.snapshot == null || !IsPipePassBlockType(proposedCandidate.blockType))
        {
            return false;
        }

        List<PipeAreaBlockCandidate> existingPipePassCandidates =
            CollectPipePassCandidatesAtCoordinate(existingPipePassCoordinate, previewToIgnore);
        for (int i = 0; i < existingPipePassCandidates.Count; i++)
        {
            PipeAreaBlockCandidate existingCandidate = existingPipePassCandidates[i];
            if (existingCandidate.snapshot == null
                || !IsBoilerSource(existingCandidate.snapshot.mapObject))
            {
                continue;
            }

            if (CanPipeAreaBlockCandidatesConnect(
                    proposedPipePassCoordinate,
                    proposedCandidate,
                    existingPipePassCoordinate,
                    existingCandidate))
            {
                return true;
            }
        }

        return false;
    }

    private bool BoilerObjectMatchesExistingBoilerPipePassDirection(
        Vector2Int objectCoordinate,
        PlacementSnapshot proposedSnapshot,
        MapObject previewToIgnore)
    {
        return BoilerObjectMatchesExistingBoilerPipePassDirection(
            objectCoordinate,
            proposedSnapshot,
            previewToIgnore,
            null);
    }

    private bool BoilerObjectMatchesExistingBoilerPipePassDirection(
        Vector2Int objectCoordinate,
        PlacementSnapshot proposedSnapshot,
        MapObject previewToIgnore,
        Vector2Int? requiredProposedPipePassCoordinate)
    {
        if (proposedSnapshot == null || !IsBoilerSource(proposedSnapshot.mapObject))
        {
            return false;
        }

        List<PipeAreaBlockCandidate> pipePassCandidates = CollectPipePassCandidatesAtCoordinate(
            objectCoordinate,
            previewToIgnore);
        for (int i = 0; i < pipePassCandidates.Count; i++)
        {
            PipeAreaBlockCandidate existingCandidate = pipePassCandidates[i];
            if (existingCandidate.snapshot == null
                || !IsBoilerSource(existingCandidate.snapshot.mapObject)
                || !TryGetPipeAreaObjectDirection(
                    objectCoordinate,
                    existingCandidate,
                    out Vector2Int existingPipePassDirection))
            {
                continue;
            }

            Vector2Int proposedPipePassCoordinate = objectCoordinate + existingPipePassDirection;
            if (requiredProposedPipePassCoordinate.HasValue
                && proposedPipePassCoordinate != requiredProposedPipePassCoordinate.Value)
            {
                continue;
            }

            if (!TryGetBoilerPipePassDirectionAtCoordinate(
                    proposedSnapshot.mapObject,
                    proposedSnapshot.anchorCoordinate,
                    proposedSnapshot.quarterTurns,
                    proposedPipePassCoordinate,
                    out Vector2Int proposedPipePassDirection)
                || proposedPipePassDirection != -existingPipePassDirection)
            {
                continue;
            }

            PipeAreaBlockCandidate proposedCandidate = new PipeAreaBlockCandidate(
                proposedSnapshot,
                InputOutputModule.RectGridBlockType.PipeInput);
            if (PipePassItemsMatchPipePass(existingCandidate, proposedCandidate))
            {
                return true;
            }
        }

        return false;
    }

    private bool BoilerOutputItemsMatchSteamGeneratorInput(
        Vector2Int boilerAnchorCoordinate,
        MapObject boilerSource,
        int boilerQuarterTurns,
        Vector2Int steamInputCoordinate,
        PipeAreaBlockCandidate steamInputCandidate)
    {
        HashSet<int> outputItemIds = new HashSet<int>();
        HashSet<int> inputItemIds = new HashSet<int>();
        return TryGetCandidateOutputItemIds(
                boilerAnchorCoordinate,
                boilerSource,
                boilerQuarterTurns,
                outputItemIds)
            && steamInputCandidate.snapshot != null
            && TryGetCandidateInputItemIdsAtCoordinate(
                steamInputCandidate.snapshot.anchorCoordinate,
                steamInputCandidate.snapshot.mapObject,
                steamInputCandidate.snapshot.quarterTurns,
                steamInputCoordinate,
                inputItemIds)
            && HasSharedItemId(outputItemIds, inputItemIds);
    }

    private bool TryGetBoilerOutputItemIdsAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        ISet<int> outputItemIds)
    {
        if (outputItemIds == null)
        {
            return false;
        }

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);

        for (int i = 0; i < pipeAreaBlockCandidateScratchA.Count; i++)
        {
            PipeAreaBlockCandidate candidate = pipeAreaBlockCandidateScratchA[i];
            if (candidate.snapshot == null
                || !IsBoilerSource(candidate.snapshot.mapObject)
                || !InputOutputModule.IsOutputBlockType(candidate.blockType))
            {
                continue;
            }

            bool foundOutput = TryGetCandidateOutputItemIds(
                candidate.snapshot.anchorCoordinate,
                candidate.snapshot.mapObject,
                candidate.snapshot.quarterTurns,
                outputItemIds);
            pipeAreaBlockCandidateScratchA.Clear();
            return foundOutput;
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return false;
    }

    private bool PipeAreaConnectionAtCoordinateIsCompatible(
        Vector2Int proposedCoordinate,
        PipeAreaBlockCandidate proposedCandidate,
        Vector2Int connectorCoordinate,
        MapObject previewToIgnore)
    {
        bool hasConnector = false;
        bool hasCompatibleConnector = false;
        List<Vector2Int> pipeConnectionDirections = new List<Vector2Int>(4);
        if (TryGetPipePlacementAtCoordinate(
                connectorCoordinate,
                previewToIgnore,
                out Pipe connectorPipe,
                out Quaternion connectorPipeRotation)
            && TryGetProposedPipeAreaPipeConnectionDirections(
                proposedCoordinate,
                proposedCandidate,
                connectorCoordinate,
                pipeConnectionDirections))
        {
            hasConnector = true;
            for (int i = 0; i < pipeConnectionDirections.Count; i++)
            {
                Vector2Int pipeConnectionDirection = pipeConnectionDirections[i];
                if (pipeConnectionDirection == Vector2Int.zero)
                {
                    continue;
                }

                if (TryResolvePipeVariantForForcedConnection(
                        connectorCoordinate,
                        connectorPipe,
                        connectorPipeRotation,
                        pipeConnectionDirection,
                        out Pipe resolvedPipe,
                        out Quaternion resolvedPipeRotation)
                    && PipeAreaCandidateFluidMatchesPipeNetwork(
                        connectorCoordinate,
                        resolvedPipe,
                        resolvedPipeRotation,
                        proposedCoordinate,
                        proposedCandidate,
                        previewToIgnore))
                {
                    hasCompatibleConnector = true;
                    break;
                }
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            connectorCoordinate,
            previewToIgnore,
            pipeAreaBlockCandidateScratchA);

        for (int i = 0; i < pipeAreaBlockCandidateScratchA.Count; i++)
        {
            PipeAreaBlockCandidate connectorCandidate = pipeAreaBlockCandidateScratchA[i];
            if (connectorCandidate.snapshot == null
                || connectorCandidate.snapshot.mapObject == proposedCandidate.snapshot.mapObject)
            {
                continue;
            }

            if (!PipeAreaBlockCandidatesWouldConnect(
                    proposedCoordinate,
                    proposedCandidate,
                    connectorCoordinate,
                    connectorCandidate))
            {
                continue;
            }

            hasConnector = true;
            if (CanPipeAreaBlockCandidatesConnect(
                    proposedCoordinate,
                    proposedCandidate,
                    connectorCoordinate,
                    connectorCandidate))
            {
                hasCompatibleConnector = true;
                break;
            }
        }

        pipeAreaBlockCandidateScratchA.Clear();
        return !hasConnector || hasCompatibleConnector;
    }

    private bool TryGetProposedPipeAreaPipeConnectionDirections(
        Vector2Int proposedCoordinate,
        PipeAreaBlockCandidate proposedCandidate,
        Vector2Int pipeCoordinate,
        List<Vector2Int> pipeConnectionDirections)
    {
        if (pipeConnectionDirections == null || proposedCandidate.snapshot == null)
        {
            return false;
        }

        int beforeCount = pipeConnectionDirections.Count;
        if (pipeCoordinate == proposedCoordinate)
        {
            TryGetPipeAreaCandidateConnectionDirections(
                proposedCoordinate,
                proposedCandidate,
                pipeConnectionDirections);
            return pipeConnectionDirections.Count > beforeCount;
        }

        Vector2Int directionFromAreaToPipe = pipeCoordinate - proposedCoordinate;
        if (!IsCardinalPipeDirection(directionFromAreaToPipe)
            || !TryResolveFixedFluidConnectorCompatibility(
                proposedCandidate.snapshot,
                proposedCoordinate,
                directionFromAreaToPipe,
                out bool connectorCanConnect)
            || !connectorCanConnect)
        {
            return false;
        }

        AddPipeDirection(pipeConnectionDirections, -directionFromAreaToPipe);
        return pipeConnectionDirections.Count > beforeCount;
    }

    private static bool IsFluidStoragePlacementObject(MapObject mapObject)
    {
        return mapObject is InstallationObject installationObject
               && installationObject.CanStoreFluid
               && !(installationObject is Pipe)
               && !(installationObject is Pump);
    }

    private bool CanPlacePipeNearFixedFluidConnectors(
        Vector2Int pipeCoordinate,
        Pipe pipePrefab,
        int quarterTurns)
    {
        if (pipePrefab == null)
        {
            return true;
        }

        Quaternion pipeRotation = GetPlacementObjectRotation(pipePrefab, quarterTurns);
        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionToConnector = PipeCardinalDirections[i];
            Vector2Int connectorCoordinate = pipeCoordinate + directionToConnector;
            Vector2Int directionToPipe = -directionToConnector;

            if (!TryGetFixedFluidConnectorCompatibilityAtCoordinate(
                    connectorCoordinate,
                    directionToPipe,
                    out bool connectorCanConnect))
            {
                continue;
            }

            if (connectorCanConnect
                && !CanPipeAreaBlocksConnect(pipeCoordinate, connectorCoordinate))
            {
                return false;
            }

            if (connectorCanConnect
                && !pipePrefab.HasConnectionTowards(pipeRotation, directionToConnector))
            {
                return false;
            }
        }

        return CanPipePlacementFluidConnectionsMatch(
            pipeCoordinate,
            pipePrefab,
            pipeRotation,
            null);
    }

    private bool CanResolvedPipePlacementMatchFixedFluidConnectors(
        Vector2Int pipeCoordinate,
        Pipe pipePrefab,
        int quarterTurns)
    {
        if (pipePrefab == null)
        {
            return true;
        }

        if (TryGetFixedFluidPipeConnectionDirectionsAtCoordinate(pipeCoordinate, null, out _))
        {
            return CanPlacePipeOnFixedFluidConnectorCoordinate(
                pipeCoordinate,
                pipePrefab,
                quarterTurns);
        }

        return CanPlacePipeNearFixedFluidConnectors(
            pipeCoordinate,
            pipePrefab,
            quarterTurns);
    }

    private bool CanPlacePipeOnFixedFluidConnectorCoordinate(
        Vector2Int pipeCoordinate,
        Pipe pipePrefab,
        int quarterTurns)
    {
        if (pipePrefab == null)
        {
            return true;
        }

        if (!TryGetFixedFluidPipeConnectionDirectionsAtCoordinate(
                pipeCoordinate,
                null,
                out List<Vector2Int> pipeConnectionDirections))
        {
            return CanPipePlacementFluidConnectionsMatch(
                pipeCoordinate,
                pipePrefab,
                quarterTurns,
                null);
        }

        Quaternion pipeRotation = GetPlacementObjectRotation(pipePrefab, quarterTurns);
        return PipeHasConnectionTowardsAnyDirection(pipePrefab, pipeRotation, pipeConnectionDirections)
               && CanPipePlacementFluidConnectionsMatch(
                   pipeCoordinate,
                   pipePrefab,
                   pipeRotation,
                   null);
    }

    private bool CanPlacePipeOnFixedFluidConnectorArea(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        int quarterTurns)
    {
        if (block == null
            || block.Type != Block.BlockType.Ground
            || !(footprintSource is Pipe pipePrefab))
        {
            return false;
        }

        if (IsFixedRectGridObjectBlockCoordinate(block.Coordinate))
        {
            return false;
        }

        if (occupyingObject != null && !IsPipePlacementAreaCoordinate(block.Coordinate))
        {
            return false;
        }

        if (TryGetFixedFluidPipeConnectionDirectionsAtCoordinate(
                block.Coordinate,
                null,
                out List<Vector2Int> pipeConnectionDirections))
        {
            Quaternion pipeRotation = GetPlacementObjectRotation(pipePrefab, quarterTurns);
            return PipeHasConnectionTowardsAnyDirection(pipePrefab, pipeRotation, pipeConnectionDirections)
                   && CanPipePlacementFluidConnectionsMatch(
                       block.Coordinate,
                       pipePrefab,
                       pipeRotation,
                       null);
        }

        return HasCompatibleFixedFluidConnectorAdjacentToPipe(
                   block.Coordinate,
                   pipePrefab,
                   quarterTurns)
               && CanPipePlacementFluidConnectionsMatch(
                   block.Coordinate,
                   pipePrefab,
                   quarterTurns,
                   null);
    }

    private bool IsFixedRectGridObjectBlockCoordinate(Vector2Int coordinate)
    {
        if (InputOutputModule.CoordinateIsRuntimeRectGridBlockType(
                coordinate,
                InputOutputModule.RectGridBlockType.Object))
        {
            return true;
        }

        if (TryGetPreviewPlacementSnapshot(coordinate, null, out PlacementSnapshot previewSnapshot)
            && SnapshotHasRectGridObjectBlock(previewSnapshot, coordinate))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out PlacementSnapshot installedSnapshot)
            && SnapshotHasRectGridObjectBlock(installedSnapshot, coordinate))
        {
            return true;
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot)
            && SnapshotHasRectGridObjectBlock(savedSnapshot, coordinate))
        {
            return true;
        }

        return false;
    }

    private bool SnapshotHasRectGridObjectBlock(PlacementSnapshot snapshot, Vector2Int coordinate)
    {
        if (snapshot == null || snapshot.mapObject == null)
        {
            return false;
        }

        MapObject footprintSource = ResolveInstallPreviewFootprintSource(snapshot.mapObject) ?? snapshot.mapObject;
        return TryGetRectGridFootprintBlockType(
                   snapshot.anchorCoordinate,
                   footprintSource,
                   snapshot.quarterTurns,
                   coordinate,
                   out InputOutputModule.RectGridBlockType blockType)
               && blockType == InputOutputModule.RectGridBlockType.Object;
    }

    private bool IsPipePlacementAreaCoordinate(Vector2Int coordinate)
    {
        if (InputOutputModule.CoordinateAllowsRuntimePipeBlock(coordinate)
            || IsPumpOutputCoordinateForPlacement(coordinate)
            || HasPipeAreaFluidStorageAtCoordinate(coordinate))
        {
            return true;
        }

        pipeAreaBlockCandidateScratchC.Clear();
        CollectRectGridPipeAreaBlockCandidatesAtCoordinate(
            coordinate,
            null,
            pipeAreaBlockCandidateScratchC);
        bool hasPipeArea = pipeAreaBlockCandidateScratchC.Count > 0;
        pipeAreaBlockCandidateScratchC.Clear();
        return hasPipeArea;
    }

    private bool HasCompatibleFixedFluidConnectorAdjacentToPipe(
        Vector2Int pipeCoordinate,
        Pipe pipePrefab,
        int quarterTurns)
    {
        if (pipePrefab == null)
        {
            return false;
        }

        Quaternion pipeRotation = GetPlacementObjectRotation(pipePrefab, quarterTurns);
        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionToConnector = PipeCardinalDirections[i];
            Vector2Int connectorCoordinate = pipeCoordinate + directionToConnector;
            Vector2Int directionToPipe = -directionToConnector;

            if (TryGetFixedFluidConnectorCompatibilityAtCoordinate(
                    connectorCoordinate,
                    directionToPipe,
                    out bool connectorCanConnect)
                && connectorCanConnect
                && CanPipeAreaBlocksConnect(pipeCoordinate, connectorCoordinate)
                && pipePrefab.HasConnectionTowards(pipeRotation, directionToConnector))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetFixedFluidPipeConnectionDirectionsAtCoordinate(
        Vector2Int coordinate,
        MapObject previewToIgnore,
        out List<Vector2Int> pipeConnectionDirections)
    {
        pipeConnectionDirections = new List<Vector2Int>(4);
        AppendFixedFluidPipeConnectionDirections(coordinate, previewToIgnore, pipeConnectionDirections);
        return pipeConnectionDirections.Count > 0;
    }

    private static bool PipeHasConnectionTowardsAnyDirection(
        Pipe pipePrefab,
        Quaternion pipeRotation,
        IReadOnlyList<Vector2Int> directions)
    {
        if (pipePrefab == null || directions == null || directions.Count <= 0)
        {
            return true;
        }

        for (int i = 0; i < directions.Count; i++)
        {
            Vector2Int direction = directions[i];
            if (direction == Vector2Int.zero)
            {
                continue;
            }

            if (pipePrefab.HasConnectionTowards(pipeRotation, direction))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetBoilerFixedFluidConnectorCompatibilityAtCoordinate(
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (directionToPipe == Vector2Int.zero)
        {
            return false;
        }

        if (TryGetPreviewPlacementSnapshot(connectorCoordinate, null, out PlacementSnapshot previewSnapshot)
            && TryResolveBoilerFixedFluidConnectorCompatibility(
                previewSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(connectorCoordinate, out PlacementSnapshot installedSnapshot)
            && TryResolveBoilerFixedFluidConnectorCompatibility(
                installedSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetRuntimeGridPlacementSnapshot(connectorCoordinate, out PlacementSnapshot runtimeGridSnapshot)
            && TryResolveBoilerFixedFluidConnectorCompatibility(
                runtimeGridSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetRuntimeAreaPlacementSnapshot(connectorCoordinate, out PlacementSnapshot runtimeAreaSnapshot)
            && TryResolveBoilerFixedFluidConnectorCompatibility(
                runtimeAreaSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        return TryGetSavedPlacementSnapshot(connectorCoordinate, out PlacementSnapshot savedSnapshot)
               && TryResolveBoilerFixedFluidConnectorCompatibility(
                   savedSnapshot,
                   connectorCoordinate,
                   directionToPipe,
                   out connectorCanConnect);
    }

    private bool TryResolveBoilerFixedFluidConnectorCompatibility(
        PlacementSnapshot connectorSnapshot,
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (!(connectorSnapshot?.mapObject is Boiler))
        {
            return false;
        }

        if (TryResolveFixedFluidConnectorCompatibility(
            connectorSnapshot,
            connectorCoordinate,
            directionToPipe,
            out connectorCanConnect))
        {
            return true;
        }

        if (!SnapshotHasRectGridObjectBlock(connectorSnapshot, connectorCoordinate))
        {
            return false;
        }

        connectorCanConnect = BoilerHasPipePassFacingDirection(
            connectorSnapshot.mapObject,
            connectorSnapshot.anchorCoordinate,
            connectorSnapshot.quarterTurns,
            -directionToPipe);
        return connectorCanConnect;
    }

    private bool TryGetFixedFluidConnectorCompatibilityAtCoordinate(
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (directionToPipe == Vector2Int.zero)
        {
            return false;
        }

        if (TryGetPreviewPlacementSnapshot(connectorCoordinate, null, out PlacementSnapshot previewSnapshot)
            && TryResolveFixedFluidConnectorCompatibility(
                previewSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetInstalledPlacementSnapshot(connectorCoordinate, out PlacementSnapshot installedSnapshot)
            && TryResolveFixedFluidConnectorCompatibility(
                installedSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetRuntimeGridPlacementSnapshot(connectorCoordinate, out PlacementSnapshot runtimeGridSnapshot)
            && TryResolveFixedFluidConnectorCompatibility(
                runtimeGridSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        if (TryGetRuntimeAreaPlacementSnapshot(connectorCoordinate, out PlacementSnapshot runtimeAreaSnapshot)
            && TryResolveFixedFluidConnectorCompatibility(
                runtimeAreaSnapshot,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect))
        {
            return true;
        }

        return TryGetSavedPlacementSnapshot(connectorCoordinate, out PlacementSnapshot savedSnapshot)
               && TryResolveFixedFluidConnectorCompatibility(
                   savedSnapshot,
                   connectorCoordinate,
                   directionToPipe,
                   out connectorCanConnect);
    }

    private bool TryResolveFixedFluidConnectorCompatibility(
        PlacementSnapshot connectorSnapshot,
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (connectorSnapshot == null)
        {
            return false;
        }

        return TryResolveFixedFluidConnectorCompatibility(
            connectorSnapshot.mapObject,
            connectorSnapshot.rotation,
            connectorSnapshot.anchorCoordinate,
            connectorSnapshot.quarterTurns,
            connectorCoordinate,
            directionToPipe,
            out connectorCanConnect);
    }

    private bool TryResolveFixedFluidConnectorCompatibility(
        MapObject connector,
        Quaternion connectorRotation,
        Vector2Int connectorAnchorCoordinate,
        int connectorQuarterTurns,
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (connector == null || directionToPipe == Vector2Int.zero)
        {
            return false;
        }

        if (connector is Pump pump)
        {
            return TryResolvePumpFixedFluidConnectorCompatibility(
                pump,
                connectorRotation,
                connectorAnchorCoordinate,
                connectorQuarterTurns,
                connectorCoordinate,
                directionToPipe,
                out connectorCanConnect);
        }

        if (connector is Boiler boiler)
        {
            connectorCanConnect = CanBoilerConnectorBlockConnectPipeTowards(
                boiler,
                connectorAnchorCoordinate,
                connectorQuarterTurns,
                connectorCoordinate,
                directionToPipe);
            return connectorCanConnect;
        }

        if (TryGetInputOutputModule(connector, out InputOutputModule inputOutputModule))
        {
            if (!TryGetRectGridFootprintBlockType(
                    connectorAnchorCoordinate,
                    connector,
                    connectorQuarterTurns,
                    connectorCoordinate,
                    out InputOutputModule.RectGridBlockType blockType)
                || !InputOutputModule.AllowsPipeAreaInteraction(blockType)
                || !TryGetRectGridPipeAreaConnectionDirection(
                    connector,
                    inputOutputModule,
                    connectorAnchorCoordinate,
                    connectorQuarterTurns,
                    connectorCoordinate,
                    out Vector2Int connectionDirection))
            {
                return false;
            }

            connectorCanConnect = directionToPipe == connectionDirection;
            return true;
        }

        if (connector is InstallationObject fluidStorage
            && !(connector is Pipe)
            && !(connector is InputOutputModule)
            && fluidStorage.CanStoreFluid)
        {
            connectorCanConnect = IsCardinalPipeDirection(directionToPipe);
            return connectorCanConnect;
        }

        return false;
    }

    private bool TryResolvePumpFixedFluidConnectorCompatibility(
        Pump pump,
        Quaternion pumpRotation,
        Vector2Int pumpAnchorCoordinate,
        int pumpQuarterTurns,
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe,
        out bool connectorCanConnect)
    {
        connectorCanConnect = false;
        if (pump == null || directionToPipe == Vector2Int.zero)
        {
            return false;
        }

        if (TryGetRectGridFootprintBlockType(
                pumpAnchorCoordinate,
                pump,
                pumpQuarterTurns,
                connectorCoordinate,
                out InputOutputModule.RectGridBlockType blockType))
        {
            if (blockType != InputOutputModule.RectGridBlockType.PipeOutputItem)
            {
                return false;
            }

            connectorCanConnect = pump.TryGetPipeConnectionDirection(
                pumpRotation,
                out Vector2Int pumpOutputDirection)
                && directionToPipe == pumpOutputDirection;
            return connectorCanConnect;
        }

        connectorCanConnect = pump.HasPipeConnectionTowards(pumpRotation, directionToPipe);
        return connectorCanConnect;
    }

    private bool CanBoilerConnectorBlockConnectPipeTowards(
        Boiler boiler,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        Vector2Int connectorCoordinate,
        Vector2Int directionToPipe)
    {
        // Boiler PipePass is the actual pipe tile. Allowing an adjacent pipe here
        // creates the recurring invalid layout: Pipe - empty PipePass tile - Boiler body.
        // Same-cell pipe overlap is handled by CanBoilerPipePassOverlapPipe.
        return false;
    }

    private bool TryAppendBoilerPipeAxisDirectionsAtCoordinate(
        Boiler boiler,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        Vector2Int coordinate,
        List<Vector2Int> directions)
    {
        if (boiler == null || directions == null)
        {
            return false;
        }

        if (!TryGetRectGridFootprintBlockType(
                boilerAnchorCoordinate,
                boiler,
                boilerQuarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType blockType)
            || blockType == InputOutputModule.RectGridBlockType.None)
        {
            return false;
        }

        if (blockType == InputOutputModule.RectGridBlockType.Object)
        {
            return false;
        }

        if (TryGetBoilerPipePassDirectionAtCoordinate(
                boiler,
                boilerAnchorCoordinate,
                boilerQuarterTurns,
                coordinate,
                out Vector2Int pipePassDirection))
        {
            // A pipe placed directly on a boiler PipePass cell connects to the boiler body only.
            // The opposite side must be counted only when an actual neighboring pipe exists;
            // otherwise a single side branch is incorrectly promoted from corner to tee.
            AddPipeDirection(directions, pipePassDirection);
            return true;
        }

        return false;
    }

    private bool CanBoilerPipePassOverlapPipe(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (block == null
            || !IsPipePassBlockType(rectGridBlockType)
            || !TryGetPipePlacementAtBlock(block, occupyingObject, out Pipe pipe, out Quaternion pipeRotation)
            || !TryGetBoilerPipePassDirectionAtCoordinate(
                footprintSource,
                anchorCoordinate,
                quarterTurns,
                block.Coordinate,
                out Vector2Int pipePassDirection))
        {
            return false;
        }

        if (!TryResolvePipeVariantForForcedConnection(
                block.Coordinate,
                pipe,
                pipeRotation,
                pipePassDirection,
                out Pipe resolvedPipe,
                out Quaternion resolvedPipeRotation))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };
        return PipeAreaCandidateFluidMatchesPipeNetwork(
            block.Coordinate,
            resolvedPipe,
            resolvedPipeRotation,
            block.Coordinate,
            new PipeAreaBlockCandidate(proposedSnapshot, rectGridBlockType),
            null);
    }

    private bool CanBoilerPipeOutputOverlapPipe(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        if (block == null
            || !IsBoilerSource(footprintSource)
            || !InputOutputModule.IsOutputBlockType(rectGridBlockType)
            || !TryGetPipePlacementAtBlock(block, occupyingObject, out Pipe pipe, out Quaternion pipeRotation)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetRectGridPipeAreaConnectionDirection(
                footprintSource,
                inputOutputModule,
                anchorCoordinate,
                quarterTurns,
                block.Coordinate,
                out Vector2Int outputObjectDirection))
        {
            return false;
        }

        if (!TryResolvePipeVariantForForcedConnection(
                block.Coordinate,
                pipe,
                pipeRotation,
                outputObjectDirection,
                out Pipe resolvedPipe,
                out Quaternion resolvedPipeRotation))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };
        return PipeAreaCandidateFluidMatchesPipeNetwork(
            block.Coordinate,
            resolvedPipe,
            resolvedPipeRotation,
            block.Coordinate,
            new PipeAreaBlockCandidate(proposedSnapshot, rectGridBlockType),
            null);
    }

    private bool TryGetBoilerPipePassDirectionAtCoordinate(
        MapObject boilerSource,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        Vector2Int coordinate,
        out Vector2Int pipePassDirection)
    {
        pipePassDirection = Vector2Int.zero;
        return TryResolveBoiler(boilerSource, out Boiler boiler)
               && boiler.TryGetPipePassDirectionAtCoordinate(
                   boilerSource,
                   boilerAnchorCoordinate,
                   boilerQuarterTurns,
                   coordinate,
                   out pipePassDirection)
               && pipePassDirection != Vector2Int.zero;
    }

    private static bool IsCardinalPipeDirection(Vector2Int direction)
    {
        return PipeDirectionsContain(PipeCardinalDirections, direction);
    }

    private void PrepareBelt2FBridgeCenterForPassthroughPlacement(Block block, MapObject passthroughSource)
    {
        if (!IsBelt2FPassthroughPlacementSource(passthroughSource)
            || block == null
            || !(block.MapObject is ConvayorBelt2F belt2F)
            || !belt2F.IsBridgeCenterCoordinate(block.Coordinate)
            || !belt2F.TryGetPlacementRuntime(out Vector2Int anchorCoordinate, out int quarterTurns))
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        terrain?.RemoveInstallationPersistence(belt2F);

        List<Vector2Int> blockingCoordinates = GetFootprintCoordinates(anchorCoordinate, belt2F, quarterTurns);
        blockingCoordinates.Remove(block.Coordinate);
        belt2F.ConfigurePlacementRuntime(
            anchorCoordinate,
            quarterTurns,
            blockingCoordinates,
            belt2F.RuntimePlacementSequence);

        ConvayorBelt2F.MarkCoverageDirty();
        belt2F.RefreshCoveredConveyorTopology();
        terrain?.RegisterLiveInstallationObject(belt2F);
    }

    private bool CanPlacePassthroughOnBelt2FBridgeCenter(
        Block block,
        MapObject footprintSource,
        MapObject occupyingObject,
        int quarterTurns)
    {
        if (!IsBelt2FPassthroughPlacementSource(footprintSource)
            || block == null
            || block.Type != Block.BlockType.Ground
            || !(occupyingObject is ConvayorBelt2F belt2F)
            || !belt2F.IsBridgeCenterCoordinate(block.Coordinate))
        {
            return false;
        }

        if (footprintSource is Pipe pipeFootprint)
        {
            return CanResolvedPipePlacementMatchFixedFluidConnectors(
                block.Coordinate,
                pipeFootprint,
                quarterTurns);
        }

        return true;
    }

    private static bool IsBelt2FPassthroughPlacementSource(MapObject mapObject)
    {
        return mapObject is Pipe || IsBaseConveyorBelt(mapObject);
    }

    private bool CanPlaceBelt2FBlock(
        Block block,
        MapObject footprintSource,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        bool isInputOutputAreaBlock,
        InstallationMapFilter allowedFilter)
    {
        if (block == null
            || !anchorCoordinate.HasValue
            || block.Type != Block.BlockType.Ground
            || !CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        bool isBridgeCenter = block.Coordinate == GetBelt2FBridgeCenterCoordinate(
            anchorCoordinate.Value,
            footprintSource,
            quarterTurns);
        if (IsResourceAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (isBridgeCenter)
        {
            if (isInputOutputAreaBlock)
            {
                return false;
            }

            if (occupyingObject == null || IsBaseConveyorBelt(occupyingObject))
            {
                return true;
            }

            return TryGetPipePlacementAtBlock(block, occupyingObject, out Pipe pipe, out Quaternion pipeRotation)
                   && IsBelt2FCrossingPipeDirectionAllowed(footprintSource, quarterTurns, pipe, pipeRotation);
        }

        return occupyingObject == null && !isInputOutputAreaBlock;
    }

    private bool CanPlaceBelt2FGridTargetBlock(Block block, MapObject footprintSource)
    {
        if (block == null || block.Type != Block.BlockType.Ground)
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block);

        InstallationMapFilter allowedFilter = TryResolveInstallationObject(footprintSource, out InstallationObject installationObject)
            ? ResolvePlacementMapFilter(footprintSource, installationObject)
            : InstallationMapFilter.Ground;
        if (!CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        if (TryResolveInstallationObject(footprintSource, out installationObject)
            && IsResourceAllowedForPlacement(
                block,
                occupyingObject,
                allowedFilter))
        {
            return true;
        }

        if (IsRailloadAllowedForPlacement(block, occupyingObject, allowedFilter))
        {
            return true;
        }

        if (IsPipeAllowedForAnyBelt2FPlacementRotation(
                block,
                occupyingObject,
                footprintSource,
                allowedFilter))
        {
            return true;
        }

        bool isInputOutputAreaBlock =
            InputOutputModuleEnergyAreaController.CoordinateIsEnergyArea(block.Coordinate)
            || InputOutputModuleItemAreaController.CoordinateIsItemArea(block.Coordinate)
            || InputOutputModuleOutputAreaController.CoordinateIsOutputArea(block.Coordinate)
            || InputOutputModule.CoordinateIsRuntimeInputOutputAreaBlock(block.Coordinate);
        if (isInputOutputAreaBlock)
        {
            return false;
        }

        return occupyingObject == null
               || IsBaseConveyorBelt(occupyingObject)
               || (TryGetPipePlacementAtBlock(block, occupyingObject, out Pipe pipe, out Quaternion pipeRotation)
                   && IsBelt2FCrossingPipeDirectionAllowed(footprintSource, 0, pipe, pipeRotation));
    }

    private bool ShouldSkipBelt2FBridgeCenterBinding(
        Block block,
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        if (block == null
            || !IsBelt2F(footprintSource)
            || block.Coordinate != GetBelt2FBridgeCenterCoordinate(anchorCoordinate, footprintSource, quarterTurns))
        {
            return false;
        }

        return IsBelt2FBridgeCenterBlockedByPassthroughObject(block);
    }

    private bool ShouldSkipBelt2FBridgeCenterBinding(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        out Vector2Int bridgeCenterCoordinate)
    {
        bridgeCenterCoordinate = Vector2Int.zero;
        if (!IsBelt2F(footprintSource))
        {
            return false;
        }

        bridgeCenterCoordinate = GetBelt2FBridgeCenterCoordinate(anchorCoordinate, footprintSource, quarterTurns);
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        return terrain != null
               && terrain.TryGetLoadedBlock(bridgeCenterCoordinate, out Block bridgeCenterBlock)
               && bridgeCenterBlock != null
               && IsBelt2FBridgeCenterBlockedByPassthroughObject(bridgeCenterBlock);
    }

    private bool IsBelt2FBridgeCenterBlockedByPassthroughObject(Block block)
    {
        if (block == null)
        {
            return false;
        }

        MapObject occupyingObject = GetOccupyingObjectForPlacement(block);
        return IsBaseConveyorBelt(occupyingObject) || occupyingObject is Pipe;
    }

    private static bool IsBaseConveyorBelt(MapObject mapObject)
    {
        return mapObject is ConveyorBelt && !IsBelt2F(mapObject);
    }

    private static bool IsBelt2F(MapObject mapObject)
    {
        return mapObject is ConvayorBelt2F;
    }

    private bool CanPlaceOnTerrainBiome(Block block, InstallationMapFilter allowedFilter)
    {
        if (block == null || block.Type != Block.BlockType.Ground)
        {
            return false;
        }

        if (IsWaterBiomeBlock(block))
        {
            return (allowedFilter & InstallationMapFilter.Water) != 0;
        }

        if (IsWaterOutlineBiomeBlock(block))
        {
            return (allowedFilter & InstallationMapFilter.WaterOutline) != 0;
        }

        return (allowedFilter & InstallationMapFilter.Ground) != 0;
    }

    private bool IsWaterBiomeBlock(Block block)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        return terrain != null
               && block != null
               && terrain.IsWaterBiomeAt(block.Coordinate);
    }

    private bool IsWaterOutlineBiomeBlock(Block block)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || block == null || terrain.IsWaterBiomeAt(block.Coordinate))
        {
            return false;
        }

        Vector2Int coordinate = block.Coordinate;
        for (int y = -1; y <= 1; y++)
        {
            for (int x = -1; x <= 1; x++)
            {
                if (x == 0 && y == 0)
                {
                    continue;
                }

                if (terrain.IsWaterBiomeAt(coordinate + new Vector2Int(x, y)))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool IsWaterPumpCardinalShoreCoordinate(Vector2Int coordinate)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        return terrain != null
               && !terrain.IsWaterBiomeAt(coordinate)
               && HasCardinalWaterNeighbor(coordinate, terrain);
    }

    private bool TryResolveWaterPumpOutwardQuarterTurns(
        Vector2Int coordinate,
        MapObject sourcePrefab,
        int fallbackQuarterTurns,
        out int quarterTurns)
    {
        quarterTurns = NormalizePlacementQuarterTurnsForObject(sourcePrefab, fallbackQuarterTurns);
        if (!IsWaterPumpSource(sourcePrefab))
        {
            return false;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null || terrain.IsWaterBiomeAt(coordinate))
        {
            return false;
        }

        List<int> candidateQuarterTurns = GetWaterPumpOutwardQuarterTurnCandidates(coordinate, terrain);
        if (candidateQuarterTurns.Count <= 0)
        {
            return false;
        }

        quarterTurns = ResolvePreferredWaterPumpOutwardQuarterTurns(
            candidateQuarterTurns,
            quarterTurns);
        return true;
    }

    private static List<int> GetWaterPumpOutwardQuarterTurnCandidates(
        Vector2Int coordinate,
        TerrainGenerator terrain)
    {
        List<int> candidates = new List<int>();
        if (terrain == null)
        {
            return candidates;
        }

        AppendWaterPumpCardinalOutwardQuarterTurnCandidates(coordinate, terrain, candidates);
        return candidates;
    }

    private static bool HasCardinalWaterNeighbor(Vector2Int coordinate, TerrainGenerator terrain)
    {
        if (terrain == null)
        {
            return false;
        }

        for (int i = 0; i < WaterPumpCardinalProbeDirections.Length; i++)
        {
            Vector2Int waterDirection = WaterPumpCardinalProbeDirections[i];
            if (terrain.IsWaterBiomeAt(coordinate + waterDirection))
            {
                return true;
            }
        }

        return false;
    }

    private static void AppendWaterPumpCardinalOutwardQuarterTurnCandidates(
        Vector2Int coordinate,
        TerrainGenerator terrain,
        List<int> candidates)
    {
        if (terrain == null || candidates == null)
        {
            return;
        }

        for (int i = 0; i < WaterPumpCardinalProbeDirections.Length; i++)
        {
            Vector2Int waterDirection = WaterPumpCardinalProbeDirections[i];
            if (!terrain.IsWaterBiomeAt(coordinate + waterDirection))
            {
                continue;
            }

            AddWaterPumpQuarterTurnCandidate(candidates, -waterDirection);
        }
    }

    private static void AddWaterPumpQuarterTurnCandidate(List<int> candidates, Vector2Int outwardDirection)
    {
        if (candidates == null || !TryGetQuarterTurnsForCardinalDirection(outwardDirection, out int quarterTurns))
        {
            return;
        }

        if (!candidates.Contains(quarterTurns))
        {
            candidates.Add(quarterTurns);
        }
    }

    private static int ResolvePreferredWaterPumpOutwardQuarterTurns(
        IReadOnlyList<int> candidates,
        int preferredQuarterTurns)
    {
        int normalizedPreferred = NormalizePlacementQuarterTurns(preferredQuarterTurns);
        int bestQuarterTurns = normalizedPreferred;
        int bestClockwiseDelta = 4;
        for (int i = 0; i < candidates.Count; i++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurns(candidates[i]);
            int clockwiseDelta = NormalizePlacementQuarterTurns(candidateQuarterTurns - normalizedPreferred);
            if (clockwiseDelta >= bestClockwiseDelta)
            {
                continue;
            }

            bestClockwiseDelta = clockwiseDelta;
            bestQuarterTurns = candidateQuarterTurns;
        }

        return bestQuarterTurns;
    }

    private static bool IsWaterPumpSource(MapObject sourcePrefab)
    {
        if (sourcePrefab == null)
        {
            return false;
        }

        return sourcePrefab is Pump
               || sourcePrefab.GetComponent<Pump>() != null
               || sourcePrefab.GetComponentInChildren<Pump>(true) != null;
    }

    private static bool TryGetQuarterTurnsForCardinalDirection(
        Vector2Int direction,
        out int quarterTurns)
    {
        quarterTurns = 0;
        if (direction == Vector2Int.zero)
        {
            return false;
        }

        if (direction == Vector2Int.up)
        {
            quarterTurns = 0;
            return true;
        }

        if (direction == Vector2Int.right)
        {
            quarterTurns = 1;
            return true;
        }

        if (direction == Vector2Int.down)
        {
            quarterTurns = 2;
            return true;
        }

        if (direction == Vector2Int.left)
        {
            quarterTurns = 3;
            return true;
        }

        return false;
    }

    public static InstallationMapFilter ResolvePlacementMapFilter(
        MapObject footprintSource,
        InstallationObject installationObject)
    {
        if (footprintSource is ConveyorBelt conveyorBelt && conveyorBelt.IsCornerVariant)
        {
            ConveyorBelt straightPrefab = conveyorBelt.StraightVariantPrefab;
            if (straightPrefab != null)
            {
                return straightPrefab.MapFilter;
            }
        }

        if (footprintSource is Wall wall && wall.StraightVariantPrefab != null && wall.StraightVariantPrefab != wall)
        {
            return wall.StraightVariantPrefab.MapFilter;
        }

        if (footprintSource is Pipe pipe && pipe.StraightVariantPrefab != null && pipe.StraightVariantPrefab != pipe)
        {
            return pipe.StraightVariantPrefab.MapFilter;
        }

        return installationObject != null
            ? installationObject.MapFilter
            : InstallationMapFilter.Ground;
    }

    private static InstallationMapFilter ResolveRectGridTerrainFilter(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        InstallationMapFilter fallbackFilter)
    {
        if (!IsWaterPumpSource(footprintSource))
        {
            return fallbackFilter;
        }

        if (IsWaterPumpPipeInputBlockType(rectGridBlockType))
        {
            return InstallationMapFilter.Water;
        }

        if (rectGridBlockType == InputOutputModule.RectGridBlockType.PipeOutputItem)
        {
            return InstallationMapFilter.Ground | InstallationMapFilter.WaterOutline;
        }

        return fallbackFilter;
    }

    private static bool IsWaterPumpPipeInputBlockType(InputOutputModule.RectGridBlockType blockType)
    {
        return blockType == InputOutputModule.RectGridBlockType.PipeInput
               || blockType == InputOutputModule.RectGridBlockType.PipeInputItem
               || blockType == InputOutputModule.RectGridBlockType.PipeInputEnergy;
    }

    private bool CanPlaceRectGridAreaBlock(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        bool hasExistingInputOutputEnergyAreaBlock,
        bool hasExistingInputOutputItemAreaBlock,
        bool hasExistingInputOutputOutputAreaBlock,
        InstallationMapFilter allowedFilter)
    {
        if (!CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        bool hasExistingInputOutputAreaBlock =
            hasExistingInputOutputEnergyAreaBlock
            || hasExistingInputOutputItemAreaBlock
            || hasExistingInputOutputOutputAreaBlock;
        if (hasExistingInputOutputAreaBlock
            && !CanOverlapCompatibleItemArea(
                block.Coordinate,
                footprintSource,
                rectGridBlockType,
                anchorCoordinate,
                quarterTurns,
                hasExistingInputOutputEnergyAreaBlock,
                hasExistingInputOutputItemAreaBlock,
                hasExistingInputOutputOutputAreaBlock))
        {
            return false;
        }

        if (occupyingObject == null || occupyingObject is BoxObject)
        {
            return true;
        }

        if (occupyingObject is Pipe
            && InputOutputModule.AllowsPipeAreaInteraction(rectGridBlockType))
        {
            if (IsSteamGeneratorSource(footprintSource))
            {
                return SteamGeneratorPipeAreaOverlapsPipeDirection(
                    block,
                    footprintSource,
                    occupyingObject,
                    anchorCoordinate,
                    quarterTurns);
            }

            return !IsBoilerSource(footprintSource)
                   || CanBoilerPipePassOverlapPipe(
                       block,
                       occupyingObject,
                       footprintSource,
                       rectGridBlockType,
                       anchorCoordinate,
                       quarterTurns)
                   || CanBoilerPipeOutputOverlapPipe(
                       block,
                       occupyingObject,
                       footprintSource,
                       rectGridBlockType,
                       anchorCoordinate,
                       quarterTurns);
        }

        return occupyingObject is Resource resource
            && IsResourceAllowedByMapFilter(resource, allowedFilter);
    }

    private bool CanPlaceCompatibleRectGridOverlap(
        MapObject candidateFootprintSource,
        InputOutputModule.RectGridBlockType candidateBlockType,
        Block block,
        Vector2Int? candidateAnchorCoordinate,
        int candidateQuarterTurns,
        MapObject previewToIgnore)
    {
        if (candidateFootprintSource == null
            || candidateBlockType == InputOutputModule.RectGridBlockType.None
            || block == null
            || !candidateAnchorCoordinate.HasValue)
        {
            return false;
        }

        bool foundExistingRectGridBlock = false;
        bool foundCompatibleOverlap = false;
        bool hasIncompatibleOverlap = false;

        EvaluateCompatibleRectGridOverlap(
            block.Coordinate,
            candidateFootprintSource,
            candidateBlockType,
            candidateAnchorCoordinate.Value,
            candidateQuarterTurns,
            previewToIgnore,
            ref foundExistingRectGridBlock,
            ref foundCompatibleOverlap,
            ref hasIncompatibleOverlap);

        return foundExistingRectGridBlock && foundCompatibleOverlap && !hasIncompatibleOverlap;
    }

    private void EvaluateCompatibleRectGridOverlap(
        Vector2Int coordinate,
        MapObject candidateFootprintSource,
        InputOutputModule.RectGridBlockType candidateBlockType,
        Vector2Int candidateAnchorCoordinate,
        int candidateQuarterTurns,
        MapObject previewToIgnore,
        ref bool foundExistingRectGridBlock,
        ref bool foundCompatibleOverlap,
        ref bool hasIncompatibleOverlap)
    {
        if (TryGetPreviewPlacementSnapshot(coordinate, previewToIgnore, out PlacementSnapshot previewSnapshot))
        {
            EvaluateCompatibleRectGridOverlap(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                previewSnapshot,
                ref foundExistingRectGridBlock,
                ref foundCompatibleOverlap,
                ref hasIncompatibleOverlap);
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }

        if (TryGetInstalledPlacementSnapshot(coordinate, out PlacementSnapshot installedSnapshot))
        {
            EvaluateCompatibleRectGridOverlap(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                installedSnapshot,
                ref foundExistingRectGridBlock,
                ref foundCompatibleOverlap,
                ref hasIncompatibleOverlap);
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }

        runtimeGridModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeGridCoordinate(coordinate, runtimeGridModuleScratch))
        {
            for (int i = 0; i < runtimeGridModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeGridModuleScratch[i],
                        out PlacementSnapshot runtimeGridSnapshot))
                {
                    EvaluateCompatibleRectGridOverlap(
                        coordinate,
                        candidateFootprintSource,
                        candidateBlockType,
                        candidateAnchorCoordinate,
                        candidateQuarterTurns,
                        runtimeGridSnapshot,
                        ref foundExistingRectGridBlock,
                        ref foundCompatibleOverlap,
                        ref hasIncompatibleOverlap);
                    if (hasIncompatibleOverlap)
                    {
                        break;
                    }
                }
            }

            runtimeGridModuleScratch.Clear();
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }
        else if (TryGetRuntimeGridPlacementSnapshot(coordinate, out PlacementSnapshot runtimeGridSnapshot))
        {
            EvaluateCompatibleRectGridOverlap(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                runtimeGridSnapshot,
                ref foundExistingRectGridBlock,
                ref foundCompatibleOverlap,
                ref hasIncompatibleOverlap);
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }

        runtimeAreaModuleScratch.Clear();
        if (InputOutputModule.CollectModulesAtRuntimeAreaCoordinate(coordinate, runtimeAreaModuleScratch))
        {
            for (int i = 0; i < runtimeAreaModuleScratch.Count; i++)
            {
                if (TryGetRuntimeModulePlacementSnapshot(
                        runtimeAreaModuleScratch[i],
                        out PlacementSnapshot runtimeAreaSnapshot))
                {
                    EvaluateCompatibleRectGridOverlap(
                        coordinate,
                        candidateFootprintSource,
                        candidateBlockType,
                        candidateAnchorCoordinate,
                        candidateQuarterTurns,
                        runtimeAreaSnapshot,
                        ref foundExistingRectGridBlock,
                        ref foundCompatibleOverlap,
                        ref hasIncompatibleOverlap);
                    if (hasIncompatibleOverlap)
                    {
                        break;
                    }
                }
            }

            runtimeAreaModuleScratch.Clear();
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }
        else if (TryGetRuntimeAreaPlacementSnapshot(coordinate, out PlacementSnapshot runtimeAreaSnapshot))
        {
            EvaluateCompatibleRectGridOverlap(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                runtimeAreaSnapshot,
                ref foundExistingRectGridBlock,
                ref foundCompatibleOverlap,
                ref hasIncompatibleOverlap);
            if (hasIncompatibleOverlap)
            {
                return;
            }
        }

        if (TryGetSavedPlacementSnapshot(coordinate, out PlacementSnapshot savedSnapshot))
        {
            EvaluateCompatibleRectGridOverlap(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                savedSnapshot,
                ref foundExistingRectGridBlock,
                ref foundCompatibleOverlap,
                ref hasIncompatibleOverlap);
        }
    }

    private void EvaluateCompatibleRectGridOverlap(
        Vector2Int coordinate,
        MapObject candidateFootprintSource,
        InputOutputModule.RectGridBlockType candidateBlockType,
        Vector2Int candidateAnchorCoordinate,
        int candidateQuarterTurns,
        PlacementSnapshot existingSnapshot,
        ref bool foundExistingRectGridBlock,
        ref bool foundCompatibleOverlap,
        ref bool hasIncompatibleOverlap)
    {
        if (existingSnapshot == null
            || existingSnapshot.mapObject == null
            || !TryGetRectGridFootprintBlockType(
                existingSnapshot.anchorCoordinate,
                existingSnapshot.mapObject,
                existingSnapshot.quarterTurns,
                coordinate,
                out InputOutputModule.RectGridBlockType existingBlockType)
            || existingBlockType == InputOutputModule.RectGridBlockType.None)
        {
            return;
        }

        foundExistingRectGridBlock = true;
        if (CanOverlapCompatiblePlacementItemAreas(
                coordinate,
                candidateFootprintSource,
                candidateBlockType,
                candidateAnchorCoordinate,
                candidateQuarterTurns,
                existingSnapshot.mapObject,
                existingBlockType,
                existingSnapshot.anchorCoordinate,
                existingSnapshot.quarterTurns))
        {
            foundCompatibleOverlap = true;
        }
        else
        {
            hasIncompatibleOverlap = true;
        }
    }

    private bool CanOverlapCompatibleItemArea(
        Vector2Int coordinate,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        bool hasExistingInputOutputEnergyAreaBlock,
        bool hasExistingInputOutputItemAreaBlock,
        bool hasExistingInputOutputOutputAreaBlock)
    {
        if (IsBoilerSource(footprintSource)
            && IsExactPumpOutputCoordinateForPlacement(coordinate)
            && IsBoilerPumpInputBlockType(rectGridBlockType))
        {
            return BoilerPipePassMatchesPumpOutput(
                footprintSource,
                coordinate,
                anchorCoordinate,
                quarterTurns);
        }

        if (InputOutputModule.IsInputItemBlockType(rectGridBlockType))
        {
            return hasExistingInputOutputOutputAreaBlock
                && CandidateInputItemsMatchExistingOutput(
                    coordinate,
                    footprintSource,
                    anchorCoordinate,
                    quarterTurns);
        }

        if (InputOutputModule.IsInputEnergyBlockType(rectGridBlockType))
        {
            return hasExistingInputOutputOutputAreaBlock
                && CandidateInputEnergyMatchesExistingOutput(coordinate, footprintSource);
        }

        if (InputOutputModule.IsOutputBlockType(rectGridBlockType))
        {
            return CandidateOutputMatchesExistingInputAreas(
                coordinate,
                footprintSource,
                anchorCoordinate,
                quarterTurns,
                hasExistingInputOutputItemAreaBlock,
                hasExistingInputOutputEnergyAreaBlock);
        }

        return false;
    }

    private bool CandidateInputItemsMatchExistingOutput(
        Vector2Int coordinate,
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        HashSet<int> candidateInputItemIds = new HashSet<int>();
        HashSet<int> existingOutputItemIds = new HashSet<int>();
        return TryGetCandidateInputItemIdsAtCoordinate(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                coordinate,
                candidateInputItemIds)
            && TryGetExistingOutputItemIdsAtCoordinate(coordinate, existingOutputItemIds)
            && HasSharedItemId(candidateInputItemIds, existingOutputItemIds);
    }

    private bool CandidateInputEnergyMatchesExistingOutput(Vector2Int coordinate, MapObject footprintSource)
    {
        HashSet<ItemDefinition.EnergyType> candidateInputEnergyTypes = new HashSet<ItemDefinition.EnergyType>();
        HashSet<int> existingOutputItemIds = new HashSet<int>();
        return TryGetCandidateInputEnergyTypes(footprintSource, candidateInputEnergyTypes)
            && TryGetExistingOutputItemIdsAtCoordinate(coordinate, existingOutputItemIds)
            && HasOutputItemWithEnergyType(existingOutputItemIds, candidateInputEnergyTypes);
    }

    private bool CandidateOutputMatchesExistingInputAreas(
        Vector2Int coordinate,
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        bool hasExistingInputOutputItemAreaBlock,
        bool hasExistingInputOutputEnergyAreaBlock)
    {
        if (!hasExistingInputOutputItemAreaBlock && !hasExistingInputOutputEnergyAreaBlock)
        {
            return false;
        }

        HashSet<int> candidateOutputItemIds = new HashSet<int>();
        if (!TryGetCandidateOutputItemIds(anchorCoordinate, footprintSource, quarterTurns, candidateOutputItemIds))
        {
            return false;
        }

        return (hasExistingInputOutputItemAreaBlock
                && ExistingInputItemsMatchOutput(coordinate, candidateOutputItemIds))
            || (hasExistingInputOutputEnergyAreaBlock
                && ExistingInputEnergyMatchesOutput(coordinate, candidateOutputItemIds));
    }

    private static bool ExistingInputItemsMatchOutput(Vector2Int coordinate, ISet<int> outputItemIds)
    {
        HashSet<int> existingInputItemIds = new HashSet<int>();
        return TryGetExistingInputItemIdsAtCoordinate(coordinate, existingInputItemIds)
            && HasSharedItemId(outputItemIds, existingInputItemIds);
    }

    private static bool ExistingInputEnergyMatchesOutput(Vector2Int coordinate, ISet<int> outputItemIds)
    {
        HashSet<ItemDefinition.EnergyType> existingInputEnergyTypes = new HashSet<ItemDefinition.EnergyType>();
        return TryGetExistingInputEnergyTypesAtCoordinate(coordinate, existingInputEnergyTypes)
            && HasOutputItemWithEnergyType(outputItemIds, existingInputEnergyTypes);
    }

    private bool CanOverlapCompatiblePlacementItemAreas(
        Vector2Int coordinate,
        MapObject candidateFootprintSource,
        InputOutputModule.RectGridBlockType candidateBlockType,
        Vector2Int candidateAnchorCoordinate,
        int candidateQuarterTurns,
        MapObject existingFootprintSource,
        InputOutputModule.RectGridBlockType existingBlockType,
        Vector2Int existingAnchorCoordinate,
        int existingQuarterTurns)
    {
        PlacementSnapshot candidateSnapshot = new PlacementSnapshot
        {
            mapObject = candidateFootprintSource,
            rotation = GetPlacementObjectRotation(candidateFootprintSource, candidateQuarterTurns),
            anchorCoordinate = candidateAnchorCoordinate,
            quarterTurns = candidateQuarterTurns
        };
        PlacementSnapshot existingSnapshot = new PlacementSnapshot
        {
            mapObject = existingFootprintSource,
            rotation = GetPlacementObjectRotation(existingFootprintSource, existingQuarterTurns),
            anchorCoordinate = existingAnchorCoordinate,
            quarterTurns = existingQuarterTurns
        };

        if (BoilerObjectPipePassOverlapCanConnect(
                coordinate,
                candidateSnapshot,
                candidateBlockType,
                existingSnapshot,
                existingBlockType))
        {
            return true;
        }

        if (SteamGeneratorObjectPipePassOverlapCanConnect(
                coordinate,
                candidateSnapshot,
                candidateBlockType,
                existingSnapshot,
                existingBlockType))
        {
            return true;
        }

        if (SteamGeneratorInputObjectOverlapCanConnect(
                coordinate,
                candidateSnapshot,
                candidateBlockType,
                existingSnapshot,
                existingBlockType))
        {
            return true;
        }

        if (InputOutputModule.AllowsPipeAreaInteraction(candidateBlockType)
            && InputOutputModule.AllowsPipeAreaInteraction(existingBlockType))
        {
            return CanPipeAreaBlockCandidatesConnect(
                coordinate,
                new PipeAreaBlockCandidate(candidateSnapshot, candidateBlockType),
                coordinate,
                new PipeAreaBlockCandidate(existingSnapshot, existingBlockType));
        }

        if (IsPipePassBlockType(candidateBlockType) && IsPipePassBlockType(existingBlockType))
        {
            return true;
        }

        if (InputOutputModule.IsOutputBlockType(candidateBlockType))
        {
            HashSet<int> candidateOutputItemIds = new HashSet<int>();
            if (!TryGetCandidateOutputItemIds(
                    candidateAnchorCoordinate,
                    candidateFootprintSource,
                    candidateQuarterTurns,
                    candidateOutputItemIds))
            {
                return false;
            }

            return PlacementInputAreaMatchesOutput(
                coordinate,
                existingFootprintSource,
                existingBlockType,
                existingAnchorCoordinate,
                existingQuarterTurns,
                candidateOutputItemIds);
        }

        if (!InputOutputModule.IsOutputBlockType(existingBlockType))
        {
            return false;
        }

        HashSet<int> existingOutputItemIds = new HashSet<int>();
        if (!TryGetCandidateOutputItemIds(
                existingAnchorCoordinate,
                existingFootprintSource,
                existingQuarterTurns,
                existingOutputItemIds))
        {
            return false;
        }

        return PlacementInputAreaMatchesOutput(
            coordinate,
            candidateFootprintSource,
            candidateBlockType,
            candidateAnchorCoordinate,
            candidateQuarterTurns,
            existingOutputItemIds);
    }

    private bool BoilerObjectPipePassOverlapCanConnect(
        Vector2Int coordinate,
        PlacementSnapshot candidateSnapshot,
        InputOutputModule.RectGridBlockType candidateBlockType,
        PlacementSnapshot existingSnapshot,
        InputOutputModule.RectGridBlockType existingBlockType)
    {
        if (candidateSnapshot == null
            || existingSnapshot == null
            || !IsBoilerSource(candidateSnapshot.mapObject)
            || !IsBoilerSource(existingSnapshot.mapObject))
        {
            return false;
        }

        if (candidateBlockType == InputOutputModule.RectGridBlockType.Object
            && IsPipePassBlockType(existingBlockType))
        {
            return BoilerObjectMatchesPipePassDirection(
                coordinate,
                candidateSnapshot,
                new PipeAreaBlockCandidate(existingSnapshot, existingBlockType));
        }

        if (existingBlockType == InputOutputModule.RectGridBlockType.Object
            && IsPipePassBlockType(candidateBlockType))
        {
            return BoilerObjectMatchesPipePassDirection(
                coordinate,
                existingSnapshot,
                new PipeAreaBlockCandidate(candidateSnapshot, candidateBlockType));
        }

        return false;
    }

    private bool BoilerObjectMatchesPipePassDirection(
        Vector2Int objectCoordinate,
        PlacementSnapshot objectSnapshot,
        PipeAreaBlockCandidate pipePassCandidate)
    {
        if (objectSnapshot == null
            || !IsBoilerSource(objectSnapshot.mapObject)
            || pipePassCandidate.snapshot == null
            || !IsBoilerSource(pipePassCandidate.snapshot.mapObject)
            || !IsPipePassBlockType(pipePassCandidate.blockType)
            || !TryGetPipeAreaObjectDirection(
                objectCoordinate,
                pipePassCandidate,
                out Vector2Int pipePassDirection))
        {
            return false;
        }

        Vector2Int objectPipePassCoordinate = objectCoordinate + pipePassDirection;
        if (!TryGetBoilerPipePassDirectionAtCoordinate(
                objectSnapshot.mapObject,
                objectSnapshot.anchorCoordinate,
                objectSnapshot.quarterTurns,
                objectPipePassCoordinate,
                out Vector2Int objectPipePassDirection)
            || objectPipePassDirection != -pipePassDirection)
        {
            return false;
        }

        return PipePassItemsMatchPipePass(
            pipePassCandidate,
            new PipeAreaBlockCandidate(objectSnapshot, InputOutputModule.RectGridBlockType.PipeInput));
    }

    private bool SteamGeneratorObjectPipePassOverlapCanConnect(
        Vector2Int coordinate,
        PlacementSnapshot candidateSnapshot,
        InputOutputModule.RectGridBlockType candidateBlockType,
        PlacementSnapshot existingSnapshot,
        InputOutputModule.RectGridBlockType existingBlockType)
    {
        if (candidateSnapshot == null
            || existingSnapshot == null
            || !IsSteamGeneratorSource(candidateSnapshot.mapObject)
            || !IsSteamGeneratorSource(existingSnapshot.mapObject))
        {
            return false;
        }

        if (candidateBlockType == InputOutputModule.RectGridBlockType.Object
            && IsPipePassBlockType(existingBlockType))
        {
            return SteamGeneratorObjectMatchesPipePassDirection(
                coordinate,
                candidateSnapshot,
                new PipeAreaBlockCandidate(existingSnapshot, existingBlockType));
        }

        if (existingBlockType == InputOutputModule.RectGridBlockType.Object
            && IsPipePassBlockType(candidateBlockType))
        {
            return SteamGeneratorObjectMatchesPipePassDirection(
                coordinate,
                existingSnapshot,
                new PipeAreaBlockCandidate(candidateSnapshot, candidateBlockType));
        }

        return false;
    }

    private bool SteamGeneratorInputObjectOverlapCanConnect(
        Vector2Int coordinate,
        PlacementSnapshot candidateSnapshot,
        InputOutputModule.RectGridBlockType candidateBlockType,
        PlacementSnapshot existingSnapshot,
        InputOutputModule.RectGridBlockType existingBlockType)
    {
        if (candidateSnapshot == null
            || existingSnapshot == null
            || !IsSteamGeneratorSource(candidateSnapshot.mapObject)
            || !IsSteamGeneratorSource(existingSnapshot.mapObject))
        {
            return false;
        }

        if (InputOutputModule.IsInputItemBlockType(candidateBlockType)
            && existingBlockType == InputOutputModule.RectGridBlockType.Object)
        {
            return SteamGeneratorInputMatchesExistingTailObject(
                coordinate,
                candidateSnapshot,
                candidateBlockType,
                existingSnapshot);
        }

        if (InputOutputModule.IsInputItemBlockType(existingBlockType)
            && candidateBlockType == InputOutputModule.RectGridBlockType.Object)
        {
            return SteamGeneratorInputMatchesExistingTailObject(
                coordinate,
                existingSnapshot,
                existingBlockType,
                candidateSnapshot);
        }

        return false;
    }

    private bool SteamGeneratorInputMatchesExistingTailObject(
        Vector2Int inputCoordinate,
        PlacementSnapshot inputSnapshot,
        InputOutputModule.RectGridBlockType inputBlockType,
        PlacementSnapshot existingSnapshot)
    {
        if (inputSnapshot == null
            || existingSnapshot == null
            || !IsSteamGeneratorSource(inputSnapshot.mapObject)
            || !IsSteamGeneratorSource(existingSnapshot.mapObject)
            || !InputOutputModule.IsInputItemBlockType(inputBlockType)
            || !SnapshotHasRectGridObjectBlock(existingSnapshot, inputCoordinate)
            || !TryGetSteamGeneratorBodyDirectionFromCenter(
                inputSnapshot.mapObject,
                inputSnapshot.quarterTurns,
                out Vector2Int proposedTailDirection))
        {
            return false;
        }

        Vector2Int pipePassCoordinate = inputSnapshot.anchorCoordinate;
        if (inputCoordinate != pipePassCoordinate - proposedTailDirection
            || !TryGetRectGridFootprintBlockType(
                existingSnapshot.anchorCoordinate,
                existingSnapshot.mapObject,
                existingSnapshot.quarterTurns,
                pipePassCoordinate,
                out InputOutputModule.RectGridBlockType existingPipePassBlockType)
            || !IsPipePassBlockType(existingPipePassBlockType))
        {
            return false;
        }

        PipeAreaBlockCandidate existingPipePassCandidate =
            new PipeAreaBlockCandidate(existingSnapshot, existingPipePassBlockType);
        if (!TryGetSteamGeneratorPipePassTailDirection(
                pipePassCoordinate,
                existingPipePassCandidate,
                out Vector2Int existingTailDirection)
            || existingTailDirection != proposedTailDirection)
        {
            return false;
        }

        return PipePassItemsMatchInput(
            existingPipePassCandidate,
            new PipeAreaBlockCandidate(inputSnapshot, inputBlockType),
            inputCoordinate);
    }

    private bool SteamGeneratorObjectMatchesPipePassDirection(
        Vector2Int objectCoordinate,
        PlacementSnapshot objectSnapshot,
        PipeAreaBlockCandidate pipePassCandidate)
    {
        if (objectSnapshot == null
            || !IsSteamGeneratorSource(objectSnapshot.mapObject)
            || objectCoordinate != objectSnapshot.anchorCoordinate
            || pipePassCandidate.snapshot == null
            || !IsSteamGeneratorSource(pipePassCandidate.snapshot.mapObject)
            || !TryGetSteamGeneratorPipePassTailDirection(
                objectCoordinate,
                pipePassCandidate,
                out Vector2Int existingTailDirection)
            || !TryGetSteamGeneratorBodyDirectionFromCenter(
                objectSnapshot.mapObject,
                objectSnapshot.quarterTurns,
                out Vector2Int proposedTailDirection)
            || proposedTailDirection != existingTailDirection)
        {
            return false;
        }

        Vector2Int proposedInputCoordinate = objectCoordinate - proposedTailDirection;
        if (!SnapshotHasRectGridObjectBlock(pipePassCandidate.snapshot, proposedInputCoordinate)
            || !TryGetRectGridFootprintBlockType(
                objectSnapshot.anchorCoordinate,
                objectSnapshot.mapObject,
                objectSnapshot.quarterTurns,
                proposedInputCoordinate,
                out InputOutputModule.RectGridBlockType proposedInputBlockType)
            || !InputOutputModule.IsInputItemBlockType(proposedInputBlockType))
        {
            return false;
        }

        return PipePassItemsMatchInput(
            pipePassCandidate,
            new PipeAreaBlockCandidate(objectSnapshot, proposedInputBlockType),
            proposedInputCoordinate);
    }

    private bool PlacementInputAreaMatchesOutput(
        Vector2Int coordinate,
        MapObject inputFootprintSource,
        InputOutputModule.RectGridBlockType inputBlockType,
        Vector2Int inputAnchorCoordinate,
        int inputQuarterTurns,
        ISet<int> outputItemIds)
    {
        if (InputOutputModule.IsInputItemBlockType(inputBlockType))
        {
            HashSet<int> inputItemIds = new HashSet<int>();
            return TryGetCandidateInputItemIdsAtCoordinate(
                    inputAnchorCoordinate,
                    inputFootprintSource,
                    inputQuarterTurns,
                    coordinate,
                    inputItemIds)
                && HasSharedItemId(outputItemIds, inputItemIds);
        }

        if (InputOutputModule.IsInputEnergyBlockType(inputBlockType))
        {
            HashSet<ItemDefinition.EnergyType> inputEnergyTypes = new HashSet<ItemDefinition.EnergyType>();
            return TryGetCandidateInputEnergyTypes(inputFootprintSource, inputEnergyTypes)
                && HasOutputItemWithEnergyType(outputItemIds, inputEnergyTypes);
        }

        return false;
    }

    private bool CanPlaceBoilerOnPumpOutputArea(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        bool isPumpRuntimeOutputAreaBlock,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns)
    {
        return IsBoilerSource(footprintSource)
               && IsBoilerPumpInputBlockType(rectGridBlockType)
               && block != null
               && CanPlaceOnTerrainBiome(block, allowedFilter)
               && (occupyingObject == null || occupyingObject is Pump)
               && isPumpRuntimeOutputAreaBlock
               && IsExactPumpOutputCoordinateForPlacement(block.Coordinate)
               && BoilerPipePassMatchesPumpOutput(
                   footprintSource,
                   block.Coordinate,
                   anchorCoordinate,
                   quarterTurns);
    }

    private bool CanPlaceBoilerObjectOnPumpOutputArea(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        bool isPumpRuntimeOutputAreaBlock,
        Vector2Int? anchorCoordinate,
        int quarterTurns)
    {
        // CRITICAL: Boiler may sit directly on the pump OutputArea. Do not require
        // Pump PipeOutput and Boiler PipePass to overlap the same cell; this is an
        // adjacent fluid-direction connection. Do not move the Boiler one cell away.
        // The only hard rule here is that the pump-side Boiler PipePass faces the
        // pump output flow direction.
        return IsBoilerSource(footprintSource)
               && rectGridBlockType == InputOutputModule.RectGridBlockType.Object
               && block != null
               && block.Type == Block.BlockType.Ground
               && (occupyingObject == null || occupyingObject is Pump)
               && isPumpRuntimeOutputAreaBlock
               && IsExactPumpOutputCoordinateForPlacement(block.Coordinate)
               && anchorCoordinate.HasValue
               && TryGetExactPumpOutputDirectionForPlacement(
                   block.Coordinate,
                   out Vector2Int pumpOutputDirection)
               && BoilerPumpSidePipePassMatchesOutputDirection(
                   footprintSource,
                   anchorCoordinate.Value,
                   block.Coordinate,
                   quarterTurns,
                   pumpOutputDirection);
    }

    private bool CanPlaceBoilerObjectOnBoilerPipePassArea(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || rectGridBlockType != InputOutputModule.RectGridBlockType.Object
            || block == null
            || block.Type != Block.BlockType.Ground
            || occupyingObject != null
            || !CanPlaceOnTerrainBiome(block, allowedFilter))
        {
            return false;
        }

        if (!anchorCoordinate.HasValue)
        {
            return HasBoilerPipePassAtCoordinate(block.Coordinate, previewToIgnore);
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate.Value,
            quarterTurns = quarterTurns
        };
        return BoilerObjectMatchesExistingBoilerPipePassDirection(
            block.Coordinate,
            proposedSnapshot,
            previewToIgnore);
    }

    private bool CanPlaceBoilerConnectorOnPumpBody(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns)
    {
        if (!IsBoilerSource(footprintSource)
            || rectGridBlockType != InputOutputModule.RectGridBlockType.PipeInput
            || block == null
            || !(occupyingObject is Pump)
            || !anchorCoordinate.HasValue
            || !TryGetExactPumpOutputDirectionForPlacement(
                anchorCoordinate.Value,
                out Vector2Int pumpOutputDirection))
        {
            return false;
        }

        // When Boiler Object is anchored on Pump OutputArea, its PipeInput marker can
        // geometrically fall over the pump body. Treat that marker as a virtual port,
        // not a placement blocker, as long as the boiler's pipe direction faces the pump flow.
        return BoilerPumpSidePipePassMatchesOutputDirection(
            footprintSource,
            anchorCoordinate.Value,
            anchorCoordinate.Value,
            quarterTurns,
            pumpOutputDirection);
    }

    private bool CanPlaceBoilerConnectorOnBoilerBody(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        MapObject previewToIgnore)
    {
        if (!IsBoilerSource(footprintSource)
            || rectGridBlockType != InputOutputModule.RectGridBlockType.PipeInput
            || block == null
            || !anchorCoordinate.HasValue
            || !IsBoilerSource(occupyingObject)
            || !TryGetRectGridBlockCoordinates(
                anchorCoordinate.Value,
                footprintSource,
                quarterTurns,
                InputOutputModule.RectGridBlockType.Object,
                out List<Vector2Int> objectCoordinates))
        {
            return false;
        }

        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate.Value,
            quarterTurns = quarterTurns
        };

        // CRITICAL: Boiler -> Boiler is the same flush-adjacent rule as Pump -> Boiler.
        // The new Boiler Object may sit on the existing Boiler PipePass cell, while the
        // new Boiler PipePass marker may fall over the existing Boiler body. Do not
        // separate the machines by one tile; only allow this when the two PipePass
        // directions face each other.
        for (int i = 0; i < objectCoordinates.Count; i++)
        {
            if (BoilerObjectMatchesExistingBoilerPipePassDirection(
                    objectCoordinates[i],
                    proposedSnapshot,
                    previewToIgnore,
                    block.Coordinate))
            {
                return true;
            }
        }

        return false;
    }

    private bool CanPlaceBoilerAreaBesidePumpOutput(
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType rectGridBlockType,
        Block block,
        MapObject occupyingObject,
        Vector2Int? anchorCoordinate,
        int quarterTurns)
    {
        // Same rule as above: pump body cells are not boiler connection cells.
        return false;
    }

    private static bool IsBoilerSource(MapObject footprintSource)
    {
        return footprintSource is Boiler
               || (footprintSource != null
                   && (footprintSource.GetComponent<Boiler>() != null
                       || footprintSource.GetComponentInChildren<Boiler>(true) != null));
    }

    private static bool IsSteamGeneratorSource(MapObject footprintSource)
    {
        return footprintSource is SteamGenerator
               || (footprintSource != null
                   && (footprintSource.GetComponent<SteamGenerator>() != null
                       || footprintSource.GetComponentInChildren<SteamGenerator>(true) != null));
    }

    private static bool TryResolveBoiler(MapObject footprintSource, out Boiler boiler)
    {
        boiler = footprintSource as Boiler;
        if (boiler != null)
        {
            return true;
        }

        if (footprintSource == null)
        {
            return false;
        }

        boiler = footprintSource.GetComponent<Boiler>();
        if (boiler != null)
        {
            return true;
        }

        boiler = footprintSource.GetComponentInChildren<Boiler>(true);
        return boiler != null;
    }

    private static bool TryResolveSteamGenerator(MapObject footprintSource, out SteamGenerator steamGenerator)
    {
        steamGenerator = footprintSource as SteamGenerator;
        if (steamGenerator != null)
        {
            return true;
        }

        if (footprintSource == null)
        {
            return false;
        }

        steamGenerator = footprintSource.GetComponent<SteamGenerator>();
        if (steamGenerator != null)
        {
            return true;
        }

        steamGenerator = footprintSource.GetComponentInChildren<SteamGenerator>(true);
        return steamGenerator != null;
    }

    private static bool TryGetSteamGeneratorBodyDirectionFromCenter(
        MapObject footprintSource,
        int quarterTurns,
        out Vector2Int direction)
    {
        direction = Vector2Int.zero;
        return TryResolveSteamGenerator(footprintSource, out SteamGenerator steamGenerator)
               && steamGenerator.TryGetBodyDirectionFromCenter(footprintSource, quarterTurns, out direction);
    }

    private bool TryResolveSteamGeneratorPipeAlignedQuarterTurns(
        Block anchorBlock,
        MapObject previewToIgnore,
        int preferredQuarterTurns,
        out int resolvedQuarterTurns)
    {
        resolvedQuarterTurns = NormalizeInstallPreviewQuarterTurns(previewToIgnore, preferredQuarterTurns);
        if (anchorBlock == null
            || !TryResolveInstallPreviewFootprintSourceForPlacement(previewToIgnore, out MapObject footprintSource)
            || !IsSteamGeneratorSource(footprintSource))
        {
            return false;
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int offset = 0; offset < candidateCount; offset++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(
                footprintSource,
                preferredQuarterTurns + offset);
            if (!SteamGeneratorPlacementHasMatchingPipeOverlap(
                    anchorBlock.Coordinate,
                    footprintSource,
                    candidateQuarterTurns)
                || !CanPlacePreviewOnBlock(anchorBlock, previewToIgnore, candidateQuarterTurns))
            {
                continue;
            }

            resolvedQuarterTurns = candidateQuarterTurns;
            return true;
        }

        return false;
    }

    private bool SteamGeneratorPlacementHasMatchingPipeOverlap(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        return SteamGeneratorPlacementPipeOverlapsMatch(
            anchorCoordinate,
            footprintSource,
            quarterTurns,
            true);
    }

    private bool SteamGeneratorPlacementPipeOverlapsMatch(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        bool requirePipeOverlap)
    {
        if (!IsSteamGeneratorSource(footprintSource)
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return !requirePipeOverlap;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        if (terrain == null || placements == null || placements.Count <= 0)
        {
            return !requirePipeOverlap;
        }

        bool foundPipeOverlap = false;
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (!InputOutputModule.AllowsPipeAreaInteraction(placement.blockType)
                || !TryGetRectGridCoordinate(
                    anchorCoordinate,
                    footprintSource,
                    quarterTurns,
                    placement,
                    out Vector2Int pipeAreaCoordinate)
                || !terrain.TryGetLoadedBlock(pipeAreaCoordinate, out Block pipeAreaBlock)
                || pipeAreaBlock == null)
            {
                continue;
            }

            if (!TryGetRectGridPipeAreaConnectionDirection(
                    footprintSource,
                    inputOutputModule,
                    anchorCoordinate,
                    quarterTurns,
                    pipeAreaCoordinate,
                    out Vector2Int pipeAreaDirection))
            {
                continue;
            }

            if (!SteamGeneratorPipeAreaPipeConnectionsMatch(
                    pipeAreaCoordinate,
                    pipeAreaDirection,
                    out bool hasPipeConnection))
            {
                return false;
            }

            foundPipeOverlap |= hasPipeConnection;
        }

        return requirePipeOverlap ? foundPipeOverlap : true;
    }

    private bool SteamGeneratorPipeAreaOverlapsPipeDirection(
        Block block,
        MapObject footprintSource,
        MapObject occupyingObject,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        return block != null
               && IsSteamGeneratorSource(footprintSource)
               && TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
               && TryGetRectGridFootprintBlockType(
                   anchorCoordinate,
                   footprintSource,
                   quarterTurns,
                   block.Coordinate,
                   out InputOutputModule.RectGridBlockType blockType)
               && TryGetRectGridPipeAreaConnectionDirection(
                   footprintSource,
                   inputOutputModule,
                   anchorCoordinate,
                   quarterTurns,
                   block.Coordinate,
                   out Vector2Int pipeAreaDirection)
               && SteamGeneratorPipeAreaPipeConnectionsMatch(
                   block.Coordinate,
                   pipeAreaDirection,
                   out bool hasPipeConnection)
               && hasPipeConnection
               && SteamGeneratorPipeAreaFluidMatchesPipeNetwork(
                   block.Coordinate,
                   footprintSource,
                   blockType,
                   anchorCoordinate,
                   quarterTurns);
    }

    private bool SteamGeneratorPipeAreaFluidMatchesPipeNetwork(
        Vector2Int pipeAreaCoordinate,
        MapObject footprintSource,
        InputOutputModule.RectGridBlockType blockType,
        Vector2Int anchorCoordinate,
        int quarterTurns)
    {
        PlacementSnapshot proposedSnapshot = new PlacementSnapshot
        {
            mapObject = footprintSource,
            rotation = GetPlacementObjectRotation(footprintSource, quarterTurns),
            anchorCoordinate = anchorCoordinate,
            quarterTurns = quarterTurns
        };
        PipeAreaBlockCandidate proposedCandidate = new PipeAreaBlockCandidate(proposedSnapshot, blockType);

        if (!TryGetPipePlacementAtCoordinate(
                pipeAreaCoordinate,
                out Pipe pipe,
                out Quaternion pipeRotation))
        {
            for (int i = 0; i < PipeCardinalDirections.Length; i++)
            {
                Vector2Int directionToPipe = PipeCardinalDirections[i];
                Vector2Int pipeCoordinate = pipeAreaCoordinate + directionToPipe;
                Vector2Int directionFromPipeToArea = -directionToPipe;
                if (!TryGetPipePlacementAtCoordinate(
                        pipeCoordinate,
                        out Pipe adjacentPipe,
                        out Quaternion adjacentPipeRotation)
                    || !TryResolvePipeVariantForForcedConnection(
                        pipeCoordinate,
                        adjacentPipe,
                        adjacentPipeRotation,
                        directionFromPipeToArea,
                        out Pipe resolvedAdjacentPipe,
                        out Quaternion resolvedAdjacentPipeRotation))
                {
                    continue;
                }

                if (!PipeAreaCandidateFluidMatchesPipeNetwork(
                        pipeCoordinate,
                        resolvedAdjacentPipe,
                        resolvedAdjacentPipeRotation,
                        pipeAreaCoordinate,
                        proposedCandidate,
                        null))
                {
                    return false;
                }
            }

            return true;
        }

        Pipe pipeForFluidMatch = pipe;
        Quaternion pipeRotationForFluidMatch = pipeRotation;
        List<Vector2Int> requiredDirections = new List<Vector2Int>(4);
        if (TryGetPipeAreaCandidateConnectionDirections(
                pipeAreaCoordinate,
                proposedCandidate,
                requiredDirections)
            && requiredDirections.Count > 0)
        {
            bool resolvedPipeForArea = false;
            for (int i = 0; i < requiredDirections.Count; i++)
            {
                Vector2Int requiredDirection = requiredDirections[i];
                if (requiredDirection == Vector2Int.zero)
                {
                    continue;
                }

                if (TryResolvePipeVariantForForcedConnection(
                        pipeAreaCoordinate,
                        pipe,
                        pipeRotation,
                        requiredDirection,
                        out Pipe resolvedPipe,
                        out Quaternion resolvedPipeRotation))
                {
                    pipeForFluidMatch = resolvedPipe;
                    pipeRotationForFluidMatch = resolvedPipeRotation;
                    resolvedPipeForArea = true;
                    break;
                }
            }

            if (!resolvedPipeForArea)
            {
                return false;
            }
        }

        return PipeAreaCandidateFluidMatchesPipeNetwork(
            pipeAreaCoordinate,
            pipeForFluidMatch,
            pipeRotationForFluidMatch,
            pipeAreaCoordinate,
            proposedCandidate,
            null);
    }

    private bool SteamGeneratorPipeAreaPipeConnectionsMatch(
        Vector2Int pipeAreaCoordinate,
        Vector2Int pipeAreaDirection,
        out bool hasPipeConnection)
    {
        hasPipeConnection = false;
        if (pipeAreaDirection == Vector2Int.zero)
        {
            return true;
        }

        if (TryGetPipePlacementAtCoordinate(
                pipeAreaCoordinate,
                out Pipe overlappingPipe,
                out Quaternion overlappingPipeRotation))
        {
            hasPipeConnection = true;
            if (!TryResolvePipeVariantForForcedConnection(
                    pipeAreaCoordinate,
                    overlappingPipe,
                    overlappingPipeRotation,
                    pipeAreaDirection,
                    out _,
                    out _))
            {
                return false;
            }
        }

        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionToPipe = PipeCardinalDirections[i];
            Vector2Int pipeCoordinate = pipeAreaCoordinate + directionToPipe;
            if (!TryGetPipePlacementAtCoordinate(
                    pipeCoordinate,
                    out Pipe pipe,
                    out Quaternion pipeRotation))
            {
                continue;
            }

            Vector2Int directionFromPipeToArea = -directionToPipe;
            if (!TryResolvePipeVariantForForcedConnection(
                    pipeCoordinate,
                    pipe,
                    pipeRotation,
                    directionFromPipeToArea,
                    out _,
                    out _))
            {
                continue;
            }

            if (directionFromPipeToArea != pipeAreaDirection)
            {
                return false;
            }

            hasPipeConnection = true;
        }

        return true;
    }

    private bool TryGetPipePlacementAtCoordinate(
        Vector2Int coordinate,
        out Pipe pipe,
        out Quaternion pipeRotation)
    {
        pipe = null;
        pipeRotation = Quaternion.identity;

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        Block block = null;
        if (terrain != null)
        {
            terrain.TryGetLoadedBlock(coordinate, out block);
        }

        MapObject occupyingObject = null;
        if (block != null)
        {
            occupyingObject = GetBlockingMapObject(block);
        }

        if (TryGetPipePlacementAtBlock(block, occupyingObject, out pipe, out pipeRotation))
        {
            return true;
        }

        if (TryGetSavedInstallationPlacementAtCoordinate(
                coordinate,
                out MapObject savedSourcePrefab,
                out Quaternion savedRotation,
                out _)
            && savedSourcePrefab is Pipe savedPipe)
        {
            pipe = savedPipe;
            pipeRotation = savedRotation;
            return true;
        }

        return false;
    }

    private bool SteamGeneratorPipeAreaDirectionMatchesPipe(
        MapObject footprintSource,
        InputOutputModule inputOutputModule,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector2Int pipeAreaCoordinate,
        Vector2Int pipeAxisDirection)
    {
        return TryGetRectGridPipeAreaConnectionDirection(
                   footprintSource,
                   inputOutputModule,
                   anchorCoordinate,
                   quarterTurns,
                   pipeAreaCoordinate,
                   out Vector2Int pipeAreaDirection)
               && DirectionsShareAxis(pipeAxisDirection, pipeAreaDirection);
    }

    private static bool TryGetStraightPipeAxis(Pipe pipe, Quaternion pipeRotation, out Vector2Int axisDirection)
    {
        axisDirection = Vector2Int.zero;
        if (pipe == null
            || pipe.IsCornerVariant
            || pipe.IsTeeVariant
            || pipe.IsCrossVariant)
        {
            return false;
        }

        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int direction = PipeCardinalDirections[i];
            if (!pipe.HasConnectionTowards(pipeRotation, direction)
                || !pipe.HasConnectionTowards(pipeRotation, -direction))
            {
                continue;
            }

            axisDirection = NormalizeCardinalAxis(direction);
            return axisDirection != Vector2Int.zero;
        }

        return false;
    }

    private static bool DirectionsShareAxis(Vector2Int firstDirection, Vector2Int secondDirection)
    {
        return firstDirection != Vector2Int.zero
               && secondDirection != Vector2Int.zero
               && NormalizeCardinalAxis(firstDirection) == NormalizeCardinalAxis(secondDirection);
    }

    private static Vector2Int NormalizeCardinalAxis(Vector2Int direction)
    {
        if (direction.x != 0)
        {
            return Vector2Int.right;
        }

        if (direction.y != 0)
        {
            return Vector2Int.up;
        }

        return Vector2Int.zero;
    }

    private static bool IsBoilerPumpInputBlockType(InputOutputModule.RectGridBlockType blockType)
    {
        return blockType == InputOutputModule.RectGridBlockType.PipeInput;
    }

    private bool BoilerPipePassMatchesPumpOutput(
        MapObject boilerSource,
        Vector2Int coordinate,
        Vector2Int? boilerAnchorCoordinate,
        int boilerQuarterTurns)
    {
        // Same-cell PipePass/PipeOutput overlap is still valid, but it is not required
        // for pump-to-boiler attachment. Direct flush placement is handled by the
        // Boiler Object-on-OutputArea path above.
        if (boilerSource == null
            || !boilerAnchorCoordinate.HasValue
            || !TryGetExactPumpOutputDirectionForPlacement(coordinate, out Vector2Int pumpOutputDirection)
            || !BoilerPipePassAtCoordinateMatchesDirection(
                boilerSource,
                boilerAnchorCoordinate.Value,
                boilerQuarterTurns,
                coordinate,
                pumpOutputDirection))
        {
            return false;
        }

        return true;
    }

    private bool PlacementHasBoilerPumpOutputDirectionMismatch(
        Vector2Int boilerAnchorCoordinate,
        MapObject boilerSource,
        int boilerQuarterTurns)
    {
        return TryGetExactPumpOutputDirectionForPlacement(
                   boilerAnchorCoordinate,
                   out Vector2Int pumpOutputDirection)
               && !BoilerPumpSidePipePassMatchesOutputDirection(
                   boilerSource,
                   boilerAnchorCoordinate,
                   boilerAnchorCoordinate,
                   boilerQuarterTurns,
                   pumpOutputDirection);
    }

    private bool BoilerPumpSidePipePassMatchesOutputDirection(
        MapObject boilerSource,
        Vector2Int boilerAnchorCoordinate,
        Vector2Int pumpOutputCoordinate,
        int boilerQuarterTurns,
        Vector2Int pumpOutputDirection)
    {
        if (pumpOutputDirection == Vector2Int.zero)
        {
            return false;
        }

        Vector2Int pumpSidePipePassCoordinate = pumpOutputCoordinate - pumpOutputDirection;
        return BoilerPipePassAtCoordinateMatchesDirection(
            boilerSource,
            boilerAnchorCoordinate,
            boilerQuarterTurns,
            pumpSidePipePassCoordinate,
            pumpOutputDirection);
    }

    private bool BoilerPipePassAtCoordinateMatchesDirection(
        MapObject boilerSource,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        Vector2Int pipePassCoordinate,
        Vector2Int targetDirection)
    {
        return TryResolveBoiler(boilerSource, out Boiler boiler)
               && boiler.PipePassAtCoordinateMatchesDirection(
                   boilerSource,
                   boilerAnchorCoordinate,
                   boilerQuarterTurns,
                   pipePassCoordinate,
                   targetDirection);
    }

    private bool BoilerHasPipePassFacingDirection(
        MapObject boilerSource,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        Vector2Int targetDirection)
    {
        return TryResolveBoiler(boilerSource, out Boiler boiler)
               && boiler.HasPipePassFacingDirection(
                   boilerSource,
                   boilerAnchorCoordinate,
                   boilerQuarterTurns,
                   targetDirection);
    }

    private bool TryGetBoilerPumpOutputDirectionMatch(
        MapObject boilerSource,
        Vector2Int boilerAnchorCoordinate,
        int boilerQuarterTurns,
        out bool matches)
    {
        matches = false;
        if (!IsBoilerSource(boilerSource)
            || !TryGetInputOutputModule(boilerSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        if (TryGetExactPumpOutputDirectionForPlacement(
                boilerAnchorCoordinate,
                out Vector2Int directPumpOutputDirection))
        {
            matches = BoilerPumpSidePipePassMatchesOutputDirection(
                boilerSource,
                boilerAnchorCoordinate,
                boilerAnchorCoordinate,
                boilerQuarterTurns,
                directPumpOutputDirection);
            return true;
        }

        bool foundPumpOutput = false;
        IReadOnlyList<InputOutputModule.RectGridBlockPlacement> placements = inputOutputModule.RectGridPlacements;
        for (int i = 0; i < placements.Count; i++)
        {
            InputOutputModule.RectGridBlockPlacement placement = placements[i];
            if (placement.blockType != InputOutputModule.RectGridBlockType.PipeInput
                || !TryGetRectGridCoordinate(
                    boilerAnchorCoordinate,
                    boilerSource,
                    boilerQuarterTurns,
                    placement,
                    out Vector2Int pipePassCoordinate)
                || !TryGetPumpOutputDirectionForBoilerPipePass(
                    pipePassCoordinate,
                    out Vector2Int pumpOutputDirection))
            {
                continue;
            }

            if (!TryGetRectGridPipeAreaConnectionDirection(
                    boilerSource,
                    inputOutputModule,
                    boilerAnchorCoordinate,
                    boilerQuarterTurns,
                    pipePassCoordinate,
                    out Vector2Int pipePassDirection))
            {
                continue;
            }

            foundPumpOutput = true;
            if (pipePassDirection == pumpOutputDirection)
            {
                matches = true;
                return true;
            }
        }

        return foundPumpOutput;
    }

    private bool TryGetPumpOutputDirectionForBoilerPipePass(Vector2Int pipePassCoordinate, out Vector2Int direction)
    {
        direction = Vector2Int.zero;
        if (TryGetExactPumpOutputDirectionForPlacement(pipePassCoordinate, out direction))
        {
            return direction != Vector2Int.zero;
        }

        // Pump/boiler fluid connectors may be adjacent. Do not require PipeOutput and
        // PipePass to occupy the same cell; only the flow direction has to line up.
        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionFromPumpOutput = PipeCardinalDirections[i];
            Vector2Int pumpOutputCoordinate = pipePassCoordinate - directionFromPumpOutput;
            if (!TryGetExactPumpOutputDirectionForPlacement(
                    pumpOutputCoordinate,
                    out Vector2Int pumpOutputDirection)
                || pumpOutputDirection != directionFromPumpOutput)
            {
                continue;
            }

            direction = pumpOutputDirection;
            return true;
        }

        return false;
    }

    private bool TryGetRectGridCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        InputOutputModule.RectGridBlockPlacement placement,
        out Vector2Int coordinate)
    {
        coordinate = Vector2Int.zero;
        return TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
               && inputOutputModule.TryGetRectGridPlacementCoordinate(
                   footprintSource,
                   anchorCoordinate,
                   NormalizePlacementQuarterTurnsForObject(footprintSource, quarterTurns),
                   placement,
                   out coordinate);
    }

    private static bool IsPumpRuntimeOutputCoordinate(Vector2Int coordinate)
    {
        if (InputOutputModule.TryGetRuntimePipeSourceAtCoordinate(coordinate, out _))
        {
            return true;
        }

        return InputOutputModule.TryGetModuleAtRuntimeRectGridBlockType(
                   coordinate,
                   InputOutputModule.RectGridBlockType.PipeOutputItem,
                   out InputOutputModule pipeOutputModule)
               && pipeOutputModule is Pump;
    }

    private bool IsExactPumpOutputCoordinateForPlacement(Vector2Int coordinate)
    {
        return IsPumpRuntimeOutputCoordinate(coordinate)
               || IsPumpRectGridOutputCoordinateForPlacement(coordinate);
    }

    private bool IsPumpOutputCoordinateForPlacement(Vector2Int coordinate)
    {
        return IsPumpRuntimeOutputCoordinate(coordinate)
               || IsPumpRectGridOutputCoordinateForPlacement(coordinate)
               || IsAdjacentPumpOutputCoordinate(coordinate);
    }

    private bool TryGetExactPumpOutputDirectionForPlacement(Vector2Int coordinate, out Vector2Int direction)
    {
        direction = Vector2Int.zero;
        if (InputOutputModule.TryGetRuntimePipeSourceAtCoordinate(coordinate, out Pump runtimePump)
            && runtimePump != null
            && runtimePump.TryGetPipeConnectionDirection(runtimePump.transform.rotation, out direction))
        {
            return true;
        }

        return TryGetPumpRectGridOutputDirectionForPlacement(coordinate, out direction);
    }

    private bool IsPumpRectGridOutputCoordinateForPlacement(Vector2Int coordinate)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        for (int x = -2; x <= 2; x++)
        {
            for (int y = -2; y <= 2; y++)
            {
                Vector2Int pumpCoordinate = coordinate + new Vector2Int(x, y);
                if (!terrain.TryGetLoadedBlock(pumpCoordinate, out Block pumpBlock)
                    || pumpBlock == null)
                {
                    continue;
                }

                MapObject pumpObject = GetBlockingMapObject(pumpBlock);
                bool hasSavedPumpPlacement = false;
                Vector2Int savedPumpAnchorCoordinate = Vector2Int.zero;
                int savedPumpQuarterTurns = 0;
                if (pumpObject == null
                    && TryGetSavedInstallationPlacementAtCoordinate(
                        pumpCoordinate,
                        out pumpObject,
                        out _,
                        out BlockStateStore.InstallationSaveState savedPumpState)
                    && savedPumpState != null)
                {
                    hasSavedPumpPlacement = true;
                    savedPumpAnchorCoordinate = savedPumpState.anchorCoordinate;
                    savedPumpQuarterTurns = savedPumpState.quarterTurns;
                }

                if (pumpObject == null)
                {
                    continue;
                }

                Vector2Int pumpAnchorCoordinate;
                int pumpQuarterTurns;
                if (hasSavedPumpPlacement)
                {
                    pumpAnchorCoordinate = savedPumpAnchorCoordinate;
                    pumpQuarterTurns = savedPumpQuarterTurns;
                }
                else if (!TryGetPumpPlacementRuntime(
                             pumpObject,
                             out pumpAnchorCoordinate,
                             out pumpQuarterTurns))
                {
                    continue;
                }

                if (TryGetRectGridFootprintBlockType(
                        pumpAnchorCoordinate,
                        pumpObject,
                        pumpQuarterTurns,
                        coordinate,
                        out InputOutputModule.RectGridBlockType blockType)
                    && blockType == InputOutputModule.RectGridBlockType.PipeOutputItem)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryGetPumpRectGridOutputDirectionForPlacement(Vector2Int coordinate, out Vector2Int direction)
    {
        direction = Vector2Int.zero;
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        for (int x = -2; x <= 2; x++)
        {
            for (int y = -2; y <= 2; y++)
            {
                Vector2Int pumpCoordinate = coordinate + new Vector2Int(x, y);
                if (!terrain.TryGetLoadedBlock(pumpCoordinate, out Block pumpBlock)
                    || pumpBlock == null)
                {
                    continue;
                }

                MapObject pumpObject = GetBlockingMapObject(pumpBlock);
                Quaternion pumpRotation = pumpObject != null ? pumpObject.transform.rotation : Quaternion.identity;
                bool hasSavedPumpPlacement = false;
                Vector2Int savedPumpAnchorCoordinate = Vector2Int.zero;
                int savedPumpQuarterTurns = 0;
                if (pumpObject == null
                    && TryGetSavedInstallationPlacementAtCoordinate(
                        pumpCoordinate,
                        out pumpObject,
                        out pumpRotation,
                        out BlockStateStore.InstallationSaveState savedPumpState)
                    && savedPumpState != null)
                {
                    hasSavedPumpPlacement = true;
                    savedPumpAnchorCoordinate = savedPumpState.anchorCoordinate;
                    savedPumpQuarterTurns = savedPumpState.quarterTurns;
                }

                if (!(pumpObject is Pump pump))
                {
                    continue;
                }

                Vector2Int pumpAnchorCoordinate;
                int pumpQuarterTurns;
                if (hasSavedPumpPlacement)
                {
                    pumpAnchorCoordinate = savedPumpAnchorCoordinate;
                    pumpQuarterTurns = savedPumpQuarterTurns;
                }
                else if (!TryGetPumpPlacementRuntime(
                             pumpObject,
                             out pumpAnchorCoordinate,
                             out pumpQuarterTurns))
                {
                    continue;
                }

                if (TryGetRectGridFootprintBlockType(
                        pumpAnchorCoordinate,
                        pumpObject,
                        pumpQuarterTurns,
                        coordinate,
                        out InputOutputModule.RectGridBlockType blockType)
                    && blockType == InputOutputModule.RectGridBlockType.PipeOutputItem
                    && pump.TryGetPipeConnectionDirection(pumpRotation, out direction))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool TryGetPumpPlacementRuntime(
        MapObject pumpObject,
        out Vector2Int anchorCoordinate,
        out int quarterTurns)
    {
        anchorCoordinate = Vector2Int.zero;
        quarterTurns = 0;
        if (!(pumpObject is Pump pump))
        {
            return false;
        }

        if (pump.TryGetPlacementRuntime(out anchorCoordinate, out quarterTurns))
        {
            return true;
        }

        return false;
    }

    private bool IsAdjacentPumpOutputCoordinate(Vector2Int coordinate)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        if (terrain == null)
        {
            return false;
        }

        for (int i = 0; i < PipeCardinalDirections.Length; i++)
        {
            Vector2Int directionFromPump = PipeCardinalDirections[i];
            Vector2Int pumpCoordinate = coordinate - directionFromPump;
            if (!terrain.TryGetLoadedBlock(pumpCoordinate, out Block pumpBlock)
                || pumpBlock == null)
            {
                continue;
            }

            MapObject pumpObject = GetBlockingMapObject(pumpBlock);
            Quaternion pumpRotation = pumpObject != null ? pumpObject.transform.rotation : Quaternion.identity;
            if (pumpObject == null
                && !TryGetSavedInstallationPlacementAtCoordinate(
                    pumpCoordinate,
                    out pumpObject,
                    out pumpRotation,
                    out _))
            {
                pumpObject = null;
            }

            if (pumpObject is Pump pump
                && pump.TryGetPipeConnectionDirection(
                    pumpRotation,
                    out Vector2Int pumpOutputDirection)
                && pumpOutputDirection == directionFromPump)
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetCandidateInputItemIdsAtCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        Vector2Int coordinate,
        ISet<int> inputItemIds)
    {
        if (inputItemIds == null
            || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule)
            || !TryGetOrderedInputItemAreaBindings(
                anchorCoordinate,
                footprintSource,
                quarterTurns,
                inputOutputModule,
                out List<InputOutputModuleItemAreaBinding> bindings))
        {
            return false;
        }

        bool foundAny = false;
        for (int i = 0; i < bindings.Count; i++)
        {
            InputOutputModuleItemAreaBinding binding = bindings[i];
            if (binding.Coordinate != coordinate || binding.ItemId < 0)
            {
                continue;
            }

            inputItemIds.Add(binding.ItemId);
            foundAny = true;
        }

        return foundAny;
    }

    private bool TryGetCandidateOutputItemIds(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        ISet<int> outputItemIds)
    {
        if (outputItemIds == null || !TryGetInputOutputModule(footprintSource, out InputOutputModule inputOutputModule))
        {
            return false;
        }

        bool foundAny = false;
        IReadOnlyList<InputOutputModule.ItemIoEntry> outputList = inputOutputModule.OutputList;
        if (outputList != null)
        {
            for (int i = 0; i < outputList.Count; i++)
            {
                ItemDefinition itemDefinition = outputList[i].itemDefinition;
                if (itemDefinition == null || itemDefinition.id < 0)
                {
                    continue;
                }

                outputItemIds.Add(itemDefinition.id);
                foundAny = true;
            }
        }

        if (TryGetMiningMachine(footprintSource, out MiningMachine miningMachine))
        {
            List<Vector2Int> miningCoordinates = GetInstalledObjectBlockingCoordinates(
                anchorCoordinate,
                footprintSource,
                quarterTurns);
            foundAny |= miningMachine.TryAppendPlacementOutputItemIds(
                ResolveInstallPreviewTerrain(),
                miningCoordinates,
                outputItemIds);
        }

        return foundAny;
    }

    private bool TryGetCandidateInputEnergyTypes(
        MapObject footprintSource,
        ISet<ItemDefinition.EnergyType> energyTypes)
    {
        if (energyTypes == null)
        {
            return false;
        }

        ItemDefinition installationDefinition = ResolveItemDefinition(footprintSource);
        if (installationDefinition == null
            || installationDefinition.useEnergyType == ItemDefinition.EnergyType.None)
        {
            return false;
        }

        energyTypes.Add(installationDefinition.useEnergyType);
        return true;
    }

    private static bool TryGetExistingOutputItemIdsAtCoordinate(Vector2Int coordinate, ISet<int> outputItemIds)
    {
        if (IsPumpRuntimeOutputCoordinate(coordinate))
        {
            return false;
        }

        return InputOutputModule.TryGetOutputItemIdsAtRuntimeGridCoordinate(coordinate, outputItemIds);
    }

    private static bool TryGetExistingInputItemIdsAtCoordinate(Vector2Int coordinate, ISet<int> inputItemIds)
    {
        if (inputItemIds == null)
        {
            return false;
        }

        bool foundAny = InputOutputModuleItemAreaController.TryGetAcceptedItemIds(coordinate, inputItemIds);
        foundAny |= InputOutputModule.TryGetInputItemIdsAtRuntimeGridCoordinate(coordinate, inputItemIds);
        return foundAny;
    }

    private static bool TryGetExistingInputEnergyTypesAtCoordinate(
        Vector2Int coordinate,
        ISet<ItemDefinition.EnergyType> energyTypes)
    {
        if (energyTypes == null)
        {
            return false;
        }

        bool foundAny = InputOutputModuleEnergyAreaController.TryGetAcceptedEnergyTypes(coordinate, energyTypes);
        foundAny |= InputOutputModule.TryGetInputEnergyTypesAtRuntimeGridCoordinate(coordinate, energyTypes);
        return foundAny;
    }

    private static bool HasSharedItemId(ISet<int> leftItemIds, ISet<int> rightItemIds)
    {
        if (leftItemIds == null || rightItemIds == null || leftItemIds.Count <= 0 || rightItemIds.Count <= 0)
        {
            return false;
        }

        foreach (int itemId in leftItemIds)
        {
            if (itemId >= 0 && rightItemIds.Contains(itemId))
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasOutputItemWithEnergyType(
        ISet<int> outputItemIds,
        ISet<ItemDefinition.EnergyType> acceptedEnergyTypes)
    {
        if (outputItemIds == null
            || acceptedEnergyTypes == null
            || outputItemIds.Count <= 0
            || acceptedEnergyTypes.Count <= 0)
        {
            return false;
        }

        foreach (int outputItemId in outputItemIds)
        {
            ItemDefinition outputDefinition = ResolveItemDefinition(outputItemId);
            if (outputDefinition == null
                || outputDefinition.energyType == ItemDefinition.EnergyType.None
                || outputDefinition.energyAmount <= 0)
            {
                continue;
            }

            if (acceptedEnergyTypes.Contains(outputDefinition.energyType))
            {
                return true;
            }
        }

        return false;
    }

    private static ItemDefinition ResolveItemDefinition(int itemId)
    {
        if (itemId < 0 || GameManager.Instance == null || GameManager.Instance.ItemManger == null)
        {
            return null;
        }

        List<ItemDefinition> definitions = GameManager.Instance.ItemManger.ItemDefinitions;
        if (definitions == null)
        {
            return null;
        }

        for (int i = 0; i < definitions.Count; i++)
        {
            ItemDefinition definition = definitions[i];
            if (definition != null && definition.id == itemId)
            {
                return definition;
            }
        }

        return null;
    }

    private static bool CanPlaceInstallationOnInputOutputAreaBlock(
        InstallationObject installationObject,
        Block block,
        MapObject occupyingObject,
        bool isInputOutputAreaBlock,
        bool isInputOutputItemAreaBlock,
        InstallationMapFilter allowedFilter)
    {
        if (installationObject == null || block == null || block.Type != Block.BlockType.Ground)
        {
            return false;
        }

        if (isInputOutputAreaBlock
            && occupyingObject is Resource occupyingResource
            && IsResourceAllowedByMapFilter(occupyingResource, allowedFilter))
        {
            return true;
        }

        if (!(installationObject is BoxObject))
        {
            return false;
        }

        if (occupyingObject == null || occupyingObject is InputOutputModule)
        {
            return true;
        }

        return isInputOutputItemAreaBlock
            && occupyingObject is Resource resource
            && IsResourceAllowedByMapFilter(resource, InstallationMapFilter.Ore);
    }

    public static bool IsResourceAllowedByMapFilter(Resource resource, InstallationMapFilter allowedFilter)
    {
        if (resource == null || !resource.CanHarvest)
        {
            return false;
        }

        InstallationMapFilter resourceFilter;
        switch (resource.ResolvedHarvestMode)
        {
            case Resource.HarvestMode.Logging:
            case Resource.HarvestMode.Cut:
                resourceFilter = InstallationMapFilter.Tree;
                break;
            default:
                resourceFilter = InstallationMapFilter.Ore;
                break;
        }

        return (allowedFilter & resourceFilter) != 0;
    }

    private static bool IsResourceAllowedForPlacement(
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter)
    {
        Resource resource = occupyingObject as Resource;
        if (resource == null && occupyingObject == null && block != null)
        {
            resource = block.Resource;
        }

        return IsResourceAllowedByMapFilter(resource, allowedFilter);
    }

    private bool IsRailloadAllowedForPlacement(
        Block block,
        MapObject occupyingObject,
        InstallationMapFilter allowedFilter)
    {
        if ((allowedFilter & InstallationMapFilter.Railload) == 0)
        {
            return false;
        }

        if (occupyingObject is Railload)
        {
            return true;
        }

        if (block != null && block.MapObject is Railload)
        {
            return true;
        }

        return block != null
               && TryGetSavedInstallationPlacementAtCoordinate(
                   block.Coordinate,
                   out MapObject savedSourcePrefab,
                   out _,
                   out _)
               && savedSourcePrefab is Railload;
    }

    private bool IsPipeAllowedForPlacement(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        Vector2Int? anchorCoordinate,
        int quarterTurns,
        InstallationMapFilter allowedFilter)
    {
        if ((allowedFilter & InstallationMapFilter.Pipe) == 0
            || !TryGetPipePlacementAtBlock(block, occupyingObject, out Pipe pipe, out Quaternion pipeRotation))
        {
            return false;
        }

        if (!IsBelt2F(footprintSource))
        {
            return true;
        }

        return anchorCoordinate.HasValue
               && block != null
               && block.Coordinate == GetBelt2FBridgeCenterCoordinate(
                   anchorCoordinate.Value,
                   footprintSource,
                   quarterTurns)
               && IsBelt2FCrossingPipeDirectionAllowed(footprintSource, quarterTurns, pipe, pipeRotation);
    }

    private bool IsPipeAllowedForPlacement(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        Vector2Int anchorCoordinate,
        InstallationMapFilter allowedFilter)
    {
        return IsPipeAllowedForPlacement(
            block,
            occupyingObject,
            footprintSource,
            anchorCoordinate,
            0,
            allowedFilter);
    }

    private bool IsPipeAllowedForAnyBelt2FPlacementRotation(
        Block block,
        MapObject occupyingObject,
        MapObject footprintSource,
        InstallationMapFilter allowedFilter)
    {
        if (!IsBelt2F(footprintSource) || block == null)
        {
            return IsPipeAllowedForPlacement(
                block,
                occupyingObject,
                footprintSource,
                block != null ? block.Coordinate : Vector2Int.zero,
                0,
                allowedFilter);
        }

        int candidateCount = GetPlacementRotationCandidateCount(footprintSource);
        for (int i = 0; i < candidateCount; i++)
        {
            int candidateQuarterTurns = NormalizePlacementQuarterTurnsForObject(footprintSource, i);
            if (IsPipeAllowedForPlacement(
                    block,
                    occupyingObject,
                    footprintSource,
                    block.Coordinate,
                    candidateQuarterTurns,
                    allowedFilter))
            {
                return true;
            }
        }

        return false;
    }

    private bool TryGetPipePlacementAtBlock(
        Block block,
        MapObject occupyingObject,
        out Pipe pipe,
        out Quaternion pipeRotation)
    {
        pipe = null;
        pipeRotation = Quaternion.identity;

        if (block != null && block.MapObject is Pipe activePipe)
        {
            if (TryGetInstalledPipeVariantPreview(
                    activePipe,
                    out Pipe previewPipe,
                    out Quaternion previewRotation))
            {
                pipe = previewPipe;
                pipeRotation = previewRotation;
                return true;
            }

            pipe = activePipe;
            pipeRotation = activePipe.transform.rotation;
            return true;
        }

        if (block != null
            && TryGetSavedInstallationPlacementAtCoordinate(
                block.Coordinate,
                out MapObject savedSourcePrefab,
                out Quaternion savedRotation,
                out _)
            && savedSourcePrefab is Pipe savedPipe)
        {
            pipe = savedPipe;
            pipeRotation = savedRotation;
            return true;
        }

        if (occupyingObject is Pipe occupyingPipe)
        {
            if (TryGetInstalledPipeVariantPreview(
                    occupyingPipe,
                    out Pipe previewPipe,
                    out Quaternion previewRotation))
            {
                pipe = previewPipe;
                pipeRotation = previewRotation;
                return true;
            }

            pipe = occupyingPipe;
            pipeRotation = occupyingPipe.transform.rotation;
            return true;
        }

        return false;
    }

    private bool IsBelt2FCrossingPipeDirectionAllowed(
        MapObject footprintSource,
        int quarterTurns,
        Pipe pipe,
        Quaternion pipeRotation)
    {
        if (!(footprintSource is ConveyorBelt belt2F)
            || pipe == null)
        {
            return false;
        }

        Quaternion beltRotation = GetPlacementObjectRotation(footprintSource, quarterTurns);
        if (!belt2F.TryGetOutputDirection(beltRotation, out Vector2Int beltDirection)
            || beltDirection == Vector2Int.zero)
        {
            return false;
        }

        if (pipe.HasConnectionTowards(pipeRotation, beltDirection)
            || pipe.HasConnectionTowards(pipeRotation, -beltDirection))
        {
            return false;
        }

        Vector2Int crossingDirection = ConveyorBelt.RotateDirectionClockwise(beltDirection);
        return pipe.HasConnectionTowards(pipeRotation, crossingDirection)
               || pipe.HasConnectionTowards(pipeRotation, -crossingDirection);
    }

    private static bool IsRectGridAreaBlockType(InputOutputModule.RectGridBlockType blockType)
    {
        return InputOutputModule.IsInputOutputAreaBlockType(blockType);
    }

    private MapObject GetOccupyingObjectForPlacement(Block block, MapObject previewToIgnore = null)
    {
        if (block == null)
        {
            return null;
        }

        MapObject occupyingObject = GetBlockingMapObject(block);
        if (occupyingObject == previewToIgnore)
        {
            occupyingObject = null;
        }

        if (occupyingObject == null
            && TryGetSavedInstallationPlacementAtCoordinate(
                block.Coordinate,
                out MapObject savedOccupyingObject,
                out _,
                out _)
            && savedOccupyingObject != previewToIgnore)
        {
            occupyingObject = savedOccupyingObject;
        }

        return occupyingObject;
    }

    private MapObject GetBlockingMapObject(Block block)
    {
        if (block == null)
        {
            return null;
        }

        MapObject occupyingObject = block.MapObject;
        if (occupyingObject == null)
        {
            return null;
        }

        if (!occupyingObject.gameObject.activeInHierarchy)
        {
            block.SetMapObject(null);
            return null;
        }

        if (occupyingObject is Resource resource && !resource.CanHarvest)
        {
            block.SetMapObject(null);
            return null;
        }

        return occupyingObject;
    }

    private Vector3 GetPreviewWorldPosition(Block anchorBlock, MapObject footprintSource, int quarterTurns)
    {
        Vector3 position = anchorBlock.transform.position;
        Vector2 positionOffset = GetPlacementWorldPositionOffset(footprintSource, quarterTurns);
        position.x += positionOffset.x;
        position.z += positionOffset.y;
        return position;
    }

    private Vector3 ResolvePlacementWorldPosition(
        Block anchorBlock,
        MapObject footprintSource,
        int quarterTurns,
        Vector3? railReferenceWorldPosition = null)
    {
        if (anchorBlock == null)
        {
            return Vector3.zero;
        }

        Vector3 position = GetPreviewWorldPosition(anchorBlock, footprintSource, quarterTurns);
        return ResolveRailAlignedPlacementWorldPosition(
            footprintSource,
            anchorBlock.Coordinate,
            quarterTurns,
            position,
            railReferenceWorldPosition);
    }

    private Vector3 ResolvePlacementWorldPosition(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns,
        Vector3? railReferenceWorldPosition = null)
    {
        Vector3 position = GetPlacementWorldPositionFromAnchorCoordinate(
            anchorCoordinate,
            footprintSource,
            quarterTurns);
        return ResolveRailAlignedPlacementWorldPosition(
            footprintSource,
            anchorCoordinate,
            quarterTurns,
            position,
            railReferenceWorldPosition);
    }

    private Vector3 ResolveRailAlignedPlacementWorldPosition(
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector3 fallbackPosition,
        Vector3? railReferenceWorldPosition)
    {
        Vector3 referencePosition = railReferenceWorldPosition ?? fallbackPosition;
        if (TryResolveTrainRailPlacementPose(
                sourcePrefab,
                anchorCoordinate,
                quarterTurns,
                referencePosition,
                out Vector3 trainPosition,
                out _))
        {
            return trainPosition;
        }

        if (!IsTrainSource(sourcePrefab)
            || !TryFindNearestRailPathAtCoordinate(
                anchorCoordinate,
                new Vector2(referencePosition.x, referencePosition.z),
                out _,
                out Vector2 railPoint,
                out _,
                out float railSqrDistance)
            || railSqrDistance > ResolveRailAlignedPlacementMaxSqrDistance())
        {
            return fallbackPosition;
        }

        Vector2 positionOffset = GetPlacementWorldPositionOffset(sourcePrefab, quarterTurns);
        fallbackPosition.x = railPoint.x + positionOffset.x;
        fallbackPosition.z = railPoint.y + positionOffset.y;
        return fallbackPosition;
    }

    private bool TryResolveTrainRailPlacementPose(
        MapObject sourcePrefab,
        Vector2Int anchorCoordinate,
        int quarterTurns,
        Vector3 referencePosition,
        out Vector3 position,
        out Quaternion rotation)
    {
        position = referencePosition;
        rotation = sourcePrefab != null ? sourcePrefab.transform.rotation : Quaternion.identity;
        Train train = ResolveTrainSource(sourcePrefab);
        if (train == null)
        {
            return false;
        }

        Quaternion baseRotation = sourcePrefab != null
            ? sourcePrefab.transform.rotation
            : Quaternion.identity;
        Vector2 referencePoint = new Vector2(referencePosition.x, referencePosition.z);
        int searchCells = Mathf.CeilToInt(Mathf.Max(1f, TrainPlacementRailSearchRadius));
        if (!TryFindNearestRailPathAroundCoordinate(
                anchorCoordinate,
                referencePoint,
                searchCells,
                out _,
                out Vector2 railPoint,
                out Vector2 railTangent,
                out float railSqrDistance))
        {
            return false;
        }

        float maxRailDistance = RailAlignedPlacementMaxDistance;
        if (railSqrDistance > maxRailDistance * maxRailDistance)
        {
            return false;
        }

        Vector3 railForward = FlattenHorizontalDirection(new Vector3(railTangent.x, 0f, railTangent.y));
        if (railForward.sqrMagnitude <= 0.0001f)
        {
            return false;
        }

        Quaternion preferredRotation = GetPlacementObjectRotation(baseRotation, sourcePrefab, quarterTurns);
        Vector3 preferredForward = FlattenHorizontalDirection(preferredRotation * Vector3.forward);
        if (preferredForward.sqrMagnitude > 0.0001f
            && Vector3.Dot(railForward, preferredForward) < 0f)
        {
            railForward = -railForward;
        }

        Vector2 positionOffset = GetPlacementWorldPositionOffset(sourcePrefab, quarterTurns);
        position.x = railPoint.x + positionOffset.x;
        position.z = railPoint.y + positionOffset.y;
        rotation = AlignBaseRotationForwardToDirection(baseRotation, railForward);
        return true;
    }

    private Vector3 GetPlacementWorldPositionFromAnchorCoordinate(
        Vector2Int anchorCoordinate,
        MapObject footprintSource,
        int quarterTurns)
    {
        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        float baseHeight = terrain != null ? terrain.transform.position.y : 0f;
        Vector3 position = new Vector3(anchorCoordinate.x, baseHeight, anchorCoordinate.y);
        if (terrain != null && terrain.TryGetLoadedBlock(anchorCoordinate, out Block anchorBlock) && anchorBlock != null)
        {
            position = anchorBlock.transform.position;
        }

        Vector2 positionOffset = GetPlacementWorldPositionOffset(footprintSource, quarterTurns);
        position.x += positionOffset.x;
        position.z += positionOffset.y;
        return position;
    }

    private Vector2 GetPlacementWorldPositionOffset(MapObject footprintSource, int quarterTurns)
    {
        if (ShouldUseAnchorCellWorldPosition(footprintSource))
        {
            return Vector2.zero;
        }

        List<Vector2Int> offsets = GetPlacementVisualLocalOffsets(footprintSource, quarterTurns);
        if (offsets.Count <= 0)
        {
            return Vector2.zero;
        }

        Vector2 averageOffset = Vector2.zero;
        for (int i = 0; i < offsets.Count; i++)
        {
            averageOffset += offsets[i];
        }

        return averageOffset / offsets.Count;
    }

    private static bool ShouldUseAnchorCellWorldPosition(MapObject footprintSource)
    {
        // SteamGenerator placement uses one RectGrid Object cell as the user-visible
        // Center. Using the average of its two body cells puts the preview on the grid
        // line between them after rotation.
        return IsSteamGeneratorSource(footprintSource);
    }

    private List<Vector2Int> GetPlacementVisualLocalOffsets(MapObject footprintSource, int quarterTurns)
    {
        if (ShouldUseMapSizeFootprint(footprintSource))
        {
            return GetMapSizeFootprintLocalOffsets(footprintSource, quarterTurns);
        }

        if (TryGetRectGridObjectLocalOffsets(footprintSource, quarterTurns, out List<Vector2Int> objectOffsets)
            && objectOffsets.Count > 0)
        {
            return objectOffsets;
        }

        return GetFootprintLocalOffsets(footprintSource, quarterTurns);
    }

    private bool TryGetRectGridObjectLocalOffsets(MapObject footprintSource, int quarterTurns, out List<Vector2Int> objectOffsets)
    {
        objectOffsets = null;
        return TryGetRectGridBlockLocalOffsets(
            footprintSource,
            quarterTurns,
            InputOutputModule.RectGridBlockType.Object,
            out objectOffsets);
    }

    private bool IsPreviewObjectCell(MapObject preview, Block block)
    {
        if (preview == null || block == null || !TryGetPreviewAnchorCoordinate(preview, out Vector2Int anchorCoordinate))
        {
            return false;
        }

        List<Vector2Int> visualCoordinates = GetPlacementVisualCoordinates(
            anchorCoordinate,
            ResolveInstallPreviewPlacementSource(preview),
            GetPreviewAreaQuarterTurns(preview));
        for (int i = 0; i < visualCoordinates.Count; i++)
        {
            if (visualCoordinates[i] == block.Coordinate)
            {
                return true;
            }
        }

        return false;
    }

    private List<Vector2Int> GetPlacementVisualCoordinates(Vector2Int anchorCoordinate, MapObject footprintSource, int quarterTurns)
    {
        List<Vector2Int> offsets = GetPlacementVisualLocalOffsets(footprintSource, quarterTurns);
        List<Vector2Int> coordinates = new List<Vector2Int>(offsets.Count);
        for (int i = 0; i < offsets.Count; i++)
        {
            coordinates.Add(anchorCoordinate + offsets[i]);
        }

        return coordinates;
    }

    private void RegisterInstalledObjectPersistence(MapObject installedObject)
    {
        if (!(installedObject is InstallationObject installationObject))
        {
            return;
        }

        TerrainGenerator terrain = ResolveInstallPreviewTerrain();
        terrain?.RegisterLiveInstallationObject(installationObject);
    }

    private MapObject CreateInstalledObjectInstance(MapObject sourcePrefab, Transform parent, TerrainGenerator terrain)
    {
        if (sourcePrefab == null)
        {
            return null;
        }

        InstallationObject pooledObject = terrain != null
            ? terrain.CreateInstallationObject(sourcePrefab, parent)
            : null;
        return pooledObject != null ? pooledObject : Instantiate(sourcePrefab, parent);
    }

    private void ReleaseInstalledObjectInstance(InstallationObject installationObject, MapObject sourcePrefab, TerrainGenerator terrain)
    {
        if (installationObject == null)
        {
            return;
        }

        if (installationObject is Wall installedFence)
        {
            RemoveInstalledFenceVariantPreview(installedFence);
        }

        if (installationObject is Pipe installedPipe)
        {
            RemoveInstalledPipeVariantPreview(installedPipe);
        }

        if (terrain != null)
        {
            terrain.ReleaseInstallationObject(installationObject, sourcePrefab);
            return;
        }

        if (Application.isPlaying)
        {
            Destroy(installationObject.gameObject);
        }
        else
        {
            DestroyImmediate(installationObject.gameObject);
        }
    }

    private static MapObject ResolveInstallationSourcePrefab(ItemDefinition definition, int conveyorVariantKind)
    {
        MapObject sourcePrefab = definition != null ? definition.mapObject : null;
        if (sourcePrefab is Wall fencePrototype && conveyorVariantKind >= 0)
        {
            sourcePrefab = ResolveFenceVariantPrefab(fencePrototype, conveyorVariantKind)
                ?? sourcePrefab;
        }
        else if (sourcePrefab is Pipe pipePrototype && conveyorVariantKind >= 0)
        {
            sourcePrefab = ResolvePipeVariantPrefab(pipePrototype, conveyorVariantKind)
                ?? sourcePrefab;
        }
        else if (!IsBelt2F(sourcePrefab) && sourcePrefab is ConveyorBelt conveyorPrototype && conveyorVariantKind >= 0)
        {
            sourcePrefab = ResolveConveyorVariantPrefab(conveyorPrototype, conveyorVariantKind)
                ?? sourcePrefab;
        }

        return sourcePrefab;
    }

    private void PlayInstallPlacementAnimation(MapObject installedObject, PortableObject sourcePortableObject, int itemId, float delay)
    {
        if (installedObject == null)
        {
            return;
        }

        Transform installedTransform = installedObject.transform;
        Vector3 originalScale = installedTransform.localScale;
        SetConveyorBeltVirtualRendering(installedObject, false);
        installedTransform.DOKill();
        installedTransform.localScale = Vector3.zero;
        SetInstalledObjectVisualVisible(installedObject, false);

        if (sourcePortableObject == null || itemId < 0)
        {
            RevealInstalledObjectAfterPlacement(installedObject, installedTransform, originalScale, delay);
            return;
        }

        PortableObject movingPortableObject = Instantiate(
            sourcePortableObject,
            sourcePortableObject.transform.position,
            sourcePortableObject.transform.rotation);
        if (movingPortableObject == null)
        {
            RevealInstalledObjectAfterPlacement(installedObject, installedTransform, originalScale, delay);
            return;
        }

        movingPortableObject.name = $"{sourcePortableObject.name}_InstallMove";
        movingPortableObject.transform.SetParent(null, true);
        movingPortableObject.transform.position = sourcePortableObject.transform.position;
        movingPortableObject.transform.localScale = sourcePortableObject.transform.lossyScale;
        if (!movingPortableObject.gameObject.activeSelf)
        {
            movingPortableObject.gameObject.SetActive(true);
        }

        if (!movingPortableObject.SetItem(itemId))
        {
            Destroy(movingPortableObject.gameObject);
            RevealInstalledObjectAfterPlacement(installedObject, installedTransform, originalScale, delay);
            return;
        }

        Vector3 startPosition = sourcePortableObject.transform.position;
        Vector3 targetPosition = installedTransform != null ? installedTransform.position : movingPortableObject.transform.position;
        movingPortableObject.MoveTo(
            () => installedTransform != null ? installedTransform.position : targetPosition,
            Mathf.Max(0f, delay),
            () => sourcePortableObject != null ? sourcePortableObject.transform.position : startPosition,
            () =>
            {
                if (movingPortableObject != null)
                {
                    Destroy(movingPortableObject.gameObject);
                }

                if (installedObject != null && installedTransform != null)
                {
                    RevealInstalledObjectAfterPlacement(installedObject, installedTransform, originalScale, 0f);
                }
            },
            false);
    }

    private void RevealInstalledObjectAfterPlacement(
        MapObject installedObject,
        Transform installedTransform,
        Vector3 originalScale,
        float delay)
    {
        if (installedObject == null || installedTransform == null)
        {
            return;
        }

        SetInstalledObjectVisualVisible(installedObject, true);

        bool restoredVirtualRendering = false;
        TweenCallback restoreVirtualRendering = () =>
        {
            if (restoredVirtualRendering || installedObject == null)
            {
                return;
            }

            restoredVirtualRendering = true;
            SetConveyorBeltVirtualRendering(installedObject, true);
            if (installedObject is UtilityPole)
            {
                UtilityPole.RefreshPoleTopologyNow();
            }
        };

        Tween revealTween = installedTransform
            .DOScale(originalScale, installPlacementScaleDuration)
            .SetDelay(Mathf.Max(0f, delay))
            .SetEase(installPlacementScaleEase)
            .SetLink(installedObject.gameObject);
        revealTween.OnComplete(restoreVirtualRendering);
        revealTween.OnKill(restoreVirtualRendering);
    }

    private static void SetConveyorBeltVirtualRendering(MapObject installedObject, bool isEnabled)
    {
        if (installedObject is ConveyorBelt conveyorBelt)
        {
            conveyorBelt.SetVirtualRuntimeRenderingEnabled(isEnabled);
        }
    }

    private void PlayInstallationEditCompleteAnimation(MapObject restoredObject, InstallationEditSession editSession)
    {
        if (restoredObject == null)
        {
            return;
        }

        int itemId = editSession?.definition != null
            ? editSession.definition.id
            : restoredObject.ResolveItemId();
        PortableObject sourcePortableObject = null;
        List<PortableObject> handPortableSources = GetPlayerHandPortableSources(itemId, 1);
        if (handPortableSources.Count > 0)
        {
            sourcePortableObject = handPortableSources[0];
        }

        PlayInstallPlacementAnimation(restoredObject, sourcePortableObject, itemId, 0f);
    }

    private void SetInstalledObjectVisualVisible(MapObject installedObject, bool isVisible)
    {
        if (installedObject == null)
        {
            return;
        }

        Renderer[] renderers = installedObject.GetComponentsInChildren<Renderer>(true);
        for (int i = 0; i < renderers.Length; i++)
        {
            if (renderers[i] != null)
            {
                renderers[i].enabled = isVisible;
            }
        }
    }

    private bool TryGetPrimaryPointerPosition(out Vector2 pointerPosition)
    {
        pointerPosition = Vector2.zero;

        if (Input.touchCount > 0)
        {
            pointerPosition = Input.GetTouch(0).position;
            return true;
        }

        pointerPosition = Input.mousePosition;
        return true;
    }

    private bool TryGetPrimaryPointerDown(out Vector2 pointerPosition)
    {
        pointerPosition = Vector2.zero;

        if (Input.touchCount > 0)
        {
            Touch touch = Input.GetTouch(0);
            if (touch.phase == TouchPhase.Began)
            {
                pointerPosition = touch.position;
                return true;
            }
        }

        if (Input.GetMouseButtonDown(0))
        {
            pointerPosition = Input.mousePosition;
            return true;
        }

        return false;
    }

    private bool IsPrimaryPointerHeld()
    {
        if (Input.touchCount > 0)
        {
            Touch touch = Input.GetTouch(0);
            return touch.phase != TouchPhase.Ended && touch.phase != TouchPhase.Canceled;
        }

        return Input.GetMouseButton(0);
    }

    public bool IsPlacementPointerOverBlockingUi(Vector2 pointerPosition)
    {
        return IsPointerOverBlockingUi(pointerPosition);
    }

    private bool IsPointerOverBlockingUi(Vector2 pointerPosition)
    {
        EventSystem currentEventSystem = EventSystem.current;
        if (currentEventSystem == null)
        {
            return false;
        }

        if (pointerRaycastEventData == null || pointerRaycastEventSystem != currentEventSystem)
        {
            pointerRaycastEventSystem = currentEventSystem;
            pointerRaycastEventData = new PointerEventData(currentEventSystem);
        }

        pointerRaycastEventData.Reset();
        pointerRaycastEventData.position = pointerPosition;
        pointerRaycastResults.Clear();
        currentEventSystem.RaycastAll(pointerRaycastEventData, pointerRaycastResults);
        for (int i = 0; i < pointerRaycastResults.Count; i++)
        {
            GameObject hitObject = pointerRaycastResults[i].gameObject;
            if (IsBlockingButtonObject(hitObject))
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsBlockingButtonObject(GameObject targetObject)
    {
        if (targetObject == null)
        {
            return false;
        }

        return targetObject.GetComponentInParent<Button>() != null;
    }

    private void ClearInstallPreview()
    {
        ClearTrainInstallPreviewConnectionHighlights();
        InvalidateInstallPreviewMoveCache();
        railloadInstallationController?.Cancel();
        RefundAllInstallPreviewReservations();
        RemoveInstalledFenceVariantPreviews(null);
        RemoveInstalledPipeVariantPreviews(null);
        UtilityPole.ClearBlueprintPreviews();
        activeInstallDefinition = null;
        activeInstallBaseRotation = Quaternion.identity;
        waitForPointerReleaseAfterPreviewSpawn = false;
        installPreviewQuarterTurns = 0;
        installPreviewConveyorVariantMode = ConveyorPreviewVariantMode.Straight;
        ResetPreviewPointerTracking();
        ResetInstallPreviewVisualSyncState();
        GameManager.Instance?.SetInstallationPlacementActive(false);
        if (IsInstallGridModeActive())
        {
            InvalidateInstallGrid();
            SetInstallGridVisible(true);
        }
        else
        {
            SetInstallGridVisible(false);
            ResetInstallGridRefreshState();
        }

        CleanupInstallPreviewReferences();
        for (int i = 0; i < installPreviewInstances.Count; i++)
        {
            MapObject preview = installPreviewInstances[i];
            if (preview == null)
            {
                continue;
            }

            DestroyInstallPreviewObject(preview);
        }

        installPreviewInstances.Clear();
        installPreviewQuarterTurnsByPreview.Clear();
        installPreviewFenceDoorStandaloneQuarterTurnsByPreview.Clear();
        installPreviewBaseRotationsByPreview.Clear();
        installPreviewAnchorCoordinates.Clear();
        installPreviewSourcePrefabsByPreview.Clear();
        installPreviewRailReferenceWorldPositions.Clear();
        installPreviewPlacementSequencesByPreview.Clear();
        installPreviewConveyorRotationSequenceIndexesByPreview.Clear();
        installPreviewItemReservationsByPreview.Clear();
        straightFirstConveyorPreviews.Clear();
        activeInstallPreview = null;
        RefreshInstallOrEditWorkableRangeVisualRequest();
    }

    private void SetInstallButtonVisible(bool isVisible)
    {
        if (installButton == null)
        {
            return;
        }

        if (installButton.gameObject.activeSelf != isVisible)
        {
            installButton.gameObject.SetActive(isVisible);
        }

        installButton.interactable = isVisible;
    }
}
